-- dbo.ACV_CAP source

ALTER VIEW [dbo].[ACV_CAP] AS
select cap Codice,
		cap + ' ' + ISNULL(Descrizione,' ') descrizione 
from cap;


-- dbo.ACV_LOCALITA source

ALTER VIEW [dbo].[ACV_LOCALITA] AS
select Localita + ';' + provincia + ';' + Nazione + ';' + ISNULL(Cap,' ') Codice,
		Localita + ' (' + provincia + ') ('+ Nazione + ')' descrizione 
from localita
where CAP is not null
and Nazione is not null
and Regione is not null
and Provincia is not null;


-- dbo.CBO_ANA_ADR source

ALTER VIEW [dbo].[CBO_ANA_ADR] AS
SELECT 'NONE' AS Codice
     , 'NONE' AS Descrizione
	 , 0 AS OrderField
 UNION
SELECT 'HAZARDOUS' AS Codice
     , 'HAZARDOUS' AS Descrizione
	 , 1 AS OrderField
UNION
SELECT 'HAZARDOUS_TO_WATER' AS Codice
     , 'HAZARDOUS_TO_WATER' AS Descrizione
	 , 2 AS OrderField
UNION
SELECT 'COMBUSTIBLES' AS Codice
     , 'COMBUSTIBLES' AS Descrizione
	 , 3 AS OrderField
UNION
SELECT 'COMBUSTIBLES_HAZARDOUS_TO_WATER' AS Codice
     , 'COMBUSTIBLES_HAZARDOUS_TO_WATER' AS Descrizione
	 , 4 AS OrderField;


-- dbo.CBO_ANA_Autisti source

ALTER VIEW [dbo].[CBO_ANA_Autisti] AS
    SELECT Codice, 			
	       RTRIM(LTRIM(RagioneSociale)) + ' (' + isNull(Matricola,'')+ ')' AS Descrizione, 
		   RagioneSociale,
		   Attivo,
		   RagioneSociale as Orderfield
      FROM Autisti;


-- dbo.CBO_ANA_Autisti_TipiAttivita source

ALTER VIEW [dbo].[CBO_ANA_Autisti_TipiAttivita] as
SELECT	Codice, 
		RTRIM(LTRIM(Descrizione)) AS Descrizione, 
		Descrizione AS Orderfield
FROM	Autisti_TipiAttivita;


-- dbo.CBO_ANA_BancaliCausali source

ALTER VIEW [dbo].[CBO_ANA_BancaliCausali] AS
SELECT codice,
          descrizione + ' (' + codice + ')' Descrizione,
          tipocausale, segno1, segno2, tiposoggetto1, tiposoggetto2,
          descrizione AS orderfield, attivo
     FROM bancalicausali
    WHERE attivo = 'S';


-- dbo.CBO_ANA_CAMPICALCOLO source

ALTER VIEW [dbo].[CBO_ANA_CAMPICALCOLO] 
AS
   SELECT nomecampo AS codice, descrizione, descrizione AS orderfield,
          campoviaggio, campospedizione, campogiacenza,CampoContrassegno 
     FROM tabcampicalcolo;


-- dbo.CBO_ANA_CLIENTI_FATTURAZIONE source

ALTER VIEW [dbo].[CBO_ANA_CLIENTI_FATTURAZIONE] AS 
SELECT DISTINCT C1.CODICE AS CODICE, 				
				Case When C1.Attivo = 'N' Then '*** ATTENZIONE: BLOCCO AMMINISTRATIVO *** ' Else '' End + RTRIM(LTRIM(C1.RagioneSociale)) + ' (' + C1.CODICE + ')' as descrizione, 
				C1.RAGIONESOCIALE, 
				C1.Localita,
				C1.Indirizzo,
				C1.Provincia,
				C1.Nazione,
				C1.Cap,
				C1.RAGIONESOCIALE as orderfield
FROM			CLIENTI C1 
				INNER JOIN CLIENTI C2 ON C1.CODICE = C2.FATTURAA
WHERE			C1.CODICE <> '*ALL';


-- dbo.CBO_ANA_CODICIIVA source

ALTER VIEW [dbo].[CBO_ANA_CODICIIVA] as
select	Codice, 
		RTRIM(LTRIM(Descrizione)) + ' (' + CODICE + ')' as descrizione, 
		Codice as orderfield
from	CodiciIva;


-- dbo.CBO_ANA_CONTESTAZIONI_SOGGETTI source

ALTER VIEW [dbo].[CBO_ANA_CONTESTAZIONI_SOGGETTI]  AS
SELECT T.*, T.ragionesociale + ' (' + codice + ')' Descrizione, ragionesociale ORDERFIELD  
from VW_ANA_CONTESTAZIONI_SOGGETTI T;


-- dbo.CBO_ANA_Caricatori source

ALTER VIEW [dbo].[CBO_ANA_Caricatori] AS
    SELECT Codice, 			
	       RTRIM(LTRIM(RagioneSociale)) + ' (' + Codice+ ')' AS Descrizione, 
		   RagioneSociale, 
		   Localita,
		   Indirizzo,
		   Provincia,
		   Nazione,
		   Cap,
		   RagioneSociale as Orderfield
      FROM Caricatori;


-- dbo.CBO_ANA_CausaliMezziAnomalie source

ALTER VIEW [dbo].[CBO_ANA_CausaliMezziAnomalie]
AS
SELECT	CODICE,
		DESCRIZIONE,
		CODICE AS ORDERFIELD
FROM	CAUSALIMEZZIANOMALIE;


-- dbo.CBO_ANA_ClienteTSpedTMerce source

ALTER VIEW [dbo].[CBO_ANA_ClienteTSpedTMerce] as
SELECT	TM.Codice, 
		RTRIM(LTRIM(TM.Descrizione)) + ' (' + TM.Codice + ')' AS Descrizione, 
		TM.Codice AS Orderfield,
		CSM.Cliente,
		CSM.TipoSpedizione
FROM	ClientiTipiSpedizioneTipiMerce CSM
		INNER JOIN TipiSpedizione TS ON CSM.TipoSpedizione = TS.Codice
		INNER JOIN TipiMerce TM ON CSM.TipoMerce = TM.Codice;


-- dbo.CBO_ANA_ClienteTipiSpedizione source

ALTER VIEW [dbo].[CBO_ANA_ClienteTipiSpedizione] as
SELECT	Codice, 
		RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ')' AS Descrizione, 
		Codice AS Orderfield,
		Cliente
FROM	ClientiTipiSpedizione C 
		INNER JOIN TipiSpedizione TS ON C.TipoSpedizione = TS.Codice;


-- dbo.CBO_ANA_Clienti source

ALTER VIEW [dbo].[CBO_ANA_Clienti] AS
    SELECT Codice, 			
	       RTRIM(LTRIM(RagioneSociale)) + ' (' + Codice+ ')' AS Descrizione, 
		   RagioneSociale, 
		   Localita,
		   Indirizzo,
		   Provincia,
		   Nazione,
		   Cap,
		   RagioneSociale as Orderfield,
		   ClienteMittente,
		   Attivo
      FROM Clienti
     WHERE ClienteMittente='C';


-- dbo.CBO_ANA_Clienti_ALL source

ALTER VIEW [dbo].[CBO_ANA_Clienti_ALL] as
select		codice, 			
			Case When Attivo = 'N' Then '*** ATTENZIONE: BLOCCO AMMINISTRATIVO *** ' Else '' End + RTRIM(LTRIM(RAGIONESOCIALE)) + ' (' + CODICE + ')' as descrizione, 
			RAGIONESOCIALE, 
			Localita,
			Indirizzo,
			Provincia,
			Nazione,
			Cap,
			RAGIONESOCIALE as orderfield
from		Clienti;


-- dbo.CBO_ANA_CodiciIvaEsenzione source

ALTER VIEW [dbo].[CBO_ANA_CodiciIvaEsenzione] AS
SELECT Codice, 
	   RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ')' AS Descrizione, 
	   Codice AS Orderfield
  FROM CodiciIva
 WHERE PercentualeIva = 0;


-- dbo.CBO_ANA_CodiciPagamento source

ALTER VIEW [dbo].[CBO_ANA_CodiciPagamento] AS
SELECT Codice, 
	   RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ')' AS Descrizione, 
