-- dbo.CBO_ANA_Mezzi_Motrici source

ALTER VIEW [dbo].[CBO_ANA_Mezzi_Motrici] as
SELECT	M.Codice, 
		M.CODICE + ' - '  +RTRIM(LTRIM(M.Descrizione)) + ' (' + M.Targa + ')' AS Descrizione, 
		M.Codice AS Orderfield,
		ISNULL(ISNULL(M.TipoMerce,TM.TipoMerce), '') TipoMerce, 				
		CASE WHEN PUOTRAINARE = 'S' AND CONTENITORE = 'N' THEN 'S' 
			 ELSE 'N' END AS Rimorchio, 	
		CASE WHEN ACCETTACONTENITORE = 'S' AND CONTENITORE = 'N' THEN 'S'
			 ELSE 'N' END AS Tank, 
		M.Trasportatore,
		M.Trasportatore as Trasportatore1,
		M.Attivo
FROM	Mezzi M	
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
	    INNER JOIN MEZZICATEGORIE C ON C.CODICE = TM.CATEGORIA
WHERE	CONMOTORE = 'S';


-- dbo.CBO_ANA_Mezzi_Rimorchi source

ALTER VIEW [dbo].[CBO_ANA_Mezzi_Rimorchi] as
SELECT	M.Codice, 
		M.CODICE + ' - '  +RTRIM(LTRIM(M.Descrizione)) + ' (' + M.Targa + ')' AS Descrizione, 
		M.Codice AS Orderfield,
		ISNULL(ISNULL(M.TipoMerce,TM.TipoMerce), '') TipoMerce, 				
		CASE WHEN PUOTRAINARE = 'S' AND CONTENITORE = 'N' THEN 'S' 
			 ELSE 'N' END AS Rimorchio, 	
		CASE WHEN ACCETTACONTENITORE = 'S' AND CONTENITORE = 'N' THEN 'S'
			 ELSE 'N' END AS Tank,
		M.Attivo
FROM	Mezzi M	
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
	    INNER JOIN MEZZICATEGORIE C ON C.CODICE = TM.CATEGORIA
WHERE	CONMOTORE = 'N' AND TARGATO = 'S';


-- dbo.CBO_ANA_Mezzi_Tank source

/*
	MODIFICA VISTA CBO_ANA_Mezzi_Tank 
*/
ALTER VIEW [dbo].[CBO_ANA_Mezzi_Tank] as
SELECT	M.Codice, 
		M.CODICE + ' - '  +RTRIM(LTRIM(M.Descrizione)) + ' (' + M.Targa + ')' AS Descrizione, 
		M.Codice AS Orderfield,
		ISNULL(ISNULL(M.TipoMerce,TM.TipoMerce), '') TipoMerce, 				
		CASE WHEN PUOTRAINARE = 'S' AND CONTENITORE = 'N' THEN 'S' 
			 ELSE 'N' END AS Rimorchio, 	
		CASE WHEN ACCETTACONTENITORE = 'S' AND CONTENITORE = 'N' THEN 'S'
			 ELSE 'N' END AS Tank,
		M.Attivo
FROM	Mezzi M	
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
	    INNER JOIN MEZZICATEGORIE C ON C.CODICE = TM.CATEGORIA
WHERE	c.Contenitore='S';


