-- dbo.CBO_ANA_OPERATORI source

ALTER VIEW [dbo].[CBO_ANA_OPERATORI] as
select	'=' as codice,
		'UGUALE' as descrizione,
		1 as orderfield
UNION
select	'>' as codice,
		'MAGGIORE' as descrizione,
		2 as orderfield
UNION
select	'>=' as codice,
		'MAGGIORE O UGUALE' as descrizione,
		3 as orderfield
UNION
select	'<' as codice,
		'MINORE' as descrizione,
		4 as orderfield
UNION
select	'<=' as codice,
		'MINORE O UGUALE' as descrizione,
		5 as orderfield
UNION
select	'<>' as codice,
		'DIVERSO' as descrizione,
		6 as orderfield
UNION
select	'IN' as codice,
		'INCLUSO' as descrizione,
		7 as orderfield
UNION
select	'NOT IN' as codice,
		'NON INCLUSO' as descrizione,
		8 as orderfield
UNION
select	'IS NULL' as codice,
		'E'' NULLO' as descrizione,
		9 as orderfield
UNION
select	'IS NOT NULL' as codice,
		'NON E'' NULLO' as descrizione,
		10 as orderfield
UNION
select	'LIKE' as codice,
		'CONTIENE' as descrizione,
		11 as orderfield
UNION
select	'NOT LIKE' as codice,
		'NON CONTIENE' as descrizione,
		12 as orderfield;


