-- dbo.CBO_ANA_TRASPORTATORI_FATT source

ALTER VIEW [dbo].[CBO_ANA_TRASPORTATORI_FATT] as
select DISTINCT	T1.codice, 			
				Case When T1.Attivo = 'N' Then '*** ATTENZIONE: BLOCCO AMMINISTRATIVO *** ' Else '' End + RTRIM(LTRIM(T1.RAGIONESOCIALE)) + ' (' + T1.CODICE + ')' as descrizione, 
				T1.RAGIONESOCIALE, 
				T1.Localita,
				T1.Indirizzo,
				T1.Provincia,
				T1.Nazione,
				T1.Cap,
				T1.RAGIONESOCIALE as orderfield
from			Trasportatori T1 
				INNER JOIN Trasportatori T2 ON T1.CODICE = T2.FATTURAA
WHERE			T1.CODICE <> '*ALL';


