-- dbo.CBO_GMB_SOGGETTI source

ALTER VIEW [dbo].[CBO_GMB_SOGGETTI]  AS
	SELECT  codice, 
			ragionesociale + ' (' + Codice + ')' AS descrizione, 
			'D' AS tipoanagrafica, 
			ragionesociale AS orderfield
    FROM Destinatari  
    WHERE Attivo='S'
	
	UNION
	
	SELECT  codice, 
			ragionesociale + ' (' + Codice + ')' AS descrizione, 
			'F' AS tipoanagrafica, 
			ragionesociale AS orderfield          
    FROM Filiali 
    WHERE Attivo='S'
     
	UNION
	
	SELECT codice, 
			ragionesociale + ' (' + Codice + ')' AS descrizione, 
			'H' AS tipoanagrafica, 
			ragionesociale AS orderfield
    FROM Corrispondenti 
    WHERE Attivo='S'
     
	UNION
	
	SELECT  codice, 
			ragionesociale + ' (' + Codice + ')' AS descrizione, 
			'C' AS tipoanagrafica, 
			RagioneSociale  AS orderfield
     FROM clienti
	 WHERE Attivo='S' 
	 
   UNION
   
   SELECT	codice, 
			ragionesociale + ' (' + Codice + ')' AS descrizione, 
			'V' AS tipoanagrafica, 
			RagioneSociale AS orderfield
     FROM trasportatori;


