-- dbo.CBO_VIAGGI source

ALTER VIEW [dbo].[CBO_VIAGGI]
AS
SELECT V.IDVIAGGIO CODICE,
             '<b>Id:</b>'
          + CAST(V.IDVIAGGIO AS VARCHAR)
          + ' <b>Data:</b>'
          + ISNULL (dbo.FORMATDATE(V.DataPartenzaPianificata,'DDMMYY','/') + ' ' + dbo.FORMATTIME (V.DataPartenzaPianificata,'HHMM',':'), ' ')
          + ' <b>Vett:</b>'
          + LEFT(ISNULL (T.RAGIONESOCIALE, 'NON DEF.'),30)
          + ' <b>Part:</b>'
          + ISNULL(V.PCSPARTENZA, 'NON DEF.') 
          + ' <b>Arr:</b>'
          + ISNULL(V.PCSARRIVO,'NON DEF.') DESCRIZIONEHTML,
          'Id:'
          + CAST(V.IDVIAGGIO AS VARCHAR)
          + ' Data:'
          + ISNULL (dbo.FORMATDATE(V.DataPartenzaPianificata,'DDMMYY','/') + ' ' + dbo.FORMATTIME (V.DataPartenzaPianificata,'HHMM',':'), ' ')
          + ' Vettore:'
          + ISNULL (T.RAGIONESOCIALE, ' ')
          + ' Partenza:'
          + ISNULL(V.PCSPARTENZA,' ') 
          + ' Arrivo:'
          + ISNULL(V.PCSARRIVO,' ') DESCRIZIONE,
          V.IDVIAGGIO ORDERFIELD, 
          V.IDVIAGGIO,
          ISNULL (dbo.FORMATDATE(V.DataPartenzaPianificata,'DDMMYY','/') + ' ' + dbo.FORMATTIME (V.DataPartenzaPianificata,'HHMM',':'), '-') Data,
          ISNULL(T.RAGIONESOCIALE, '-') Vettore_RagioneSociale,
          V.STATO,
          ISNULL(V.PCSPARTENZA,'-') PCSPARTENZA,
          ISNULL(V.PCSARRIVO,'-') PCSARRIVO
     FROM VIAGGI V LEFT JOIN TRASPORTATORI T ON V.VETTORE = T.CODICE
    WHERE STATO = 10;


