		Codice AS Orderfield
   FROM FTPAgentFilegroup T;


-- dbo.CBO_WFI_FTP_FOLDERS source

ALTER VIEW [dbo].[CBO_WFI_FTP_FOLDERS] AS
 SELECT	Codice, 
		RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ')' AS Descrizione, 
		Codice AS Orderfield,
		CASE Tipo
			WHEN 'F' THEN RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ') - <strong>Server: </strong>' + FTPServer +  ' - <strong>Path: </strong>' + FTPPath
			WHEN 'R' THEN RTRIM(LTRIM(Descrizione)) + ' (' + Codice + ') - <strong>Path: </strong>' + LOCALPATH
		END AS DescrizioneCompleta
   FROM FTPAgentFolders T;


