-- dbo.CHK_ANA_Autisti_Classi source

ALTER VIEW [dbo].[CHK_ANA_Autisti_Classi] AS
SELECT		Codice, 
			Descrizione, 
			Autista, 
			MAX(SELECTED) SELECTED, 
			DESCRIZIONE ORDERBYFIELD
FROM
(
	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			AC.Autista,
			CASE WHEN AC.Autista IS NULL THEN 'N' ELSE 'S' END SELECTED
	FROM	CLASSI C INNER JOIN AutistiClassi AC ON AC.Classe=C.COdice
	WHERE	Tipo='AUT'

UNION

	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			NULL Autista,
			'N' SELECTED
	FROM	CLASSI C 
	WHERE	Tipo='AUT'

UNION 

	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			A.Codice Autista,
			'N' AS SELECTED
	FROM	CLASSI C CROSS JOIN AUTISTI A
	WHERE	Tipo='AUT'
) T 
GROUP BY	CODICE, 
			DESCRIZIONE, 
			AUTISTA;


-- dbo.CHK_ANA_Clienti_Classi source

ALTER VIEW [dbo].[CHK_ANA_Clienti_Classi] AS
SELECT		Codice, 
			Descrizione, 
			Cliente, 
			MAX(SELECTED) SELECTED, 
			DESCRIZIONE ORDERBYFIELD
FROM
(
	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			CC.Cliente,
			CASE WHEN CC.Cliente IS NULL THEN 'N' ELSE 'S' END SELECTED
	FROM	CLASSI C INNER JOIN ClientiClassi CC ON CC.Classe=C.COdice
	WHERE	Tipo='CLI'

UNION

	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			NULL Cliente,
			'N' SELECTED
	FROM	CLASSI C 
	WHERE	Tipo='CLI'

UNION 

	SELECT	C.CODICE,
			C.DESCRIZIONE Descrizione,
			CL.Codice Cliente,
			'N' AS SELECTED
	FROM	CLASSI C CROSS JOIN CLIENTI CL
	WHERE	Tipo='CLI'
) T 
GROUP BY	CODICE, 
			DESCRIZIONE, 
			CLIENTE;


-- dbo.CHK_ANA_Mezzi_Classi source

ALTER VIEW [dbo].[CHK_ANA_Mezzi_Classi] AS
SELECT		Codice, 
			Descrizione, 
			Mezzo, 
			MAX(Selected) Selected, 
			Descrizione OrderByField
FROM
(
	SELECT	C.Codice,
			C.Descrizione Descrizione,
			MC.Mezzo,
			CASE WHEN MC.Mezzo IS NULL THEN 'N' ELSE 'S' END Selected
	FROM	Classi C INNER JOIN MezziClassi MC ON MC.Classe=C.Codice
	WHERE	Tipo='MEZ'

UNION

	SELECT	C.Codice,
			C.Descrizione Descrizione,
			NULL Mezzo,
			'N' Selected
	FROM	CLASSI C 
	WHERE	Tipo='MEZ'

UNION 

	SELECT	C.Codice,
			C.Descrizione Descrizione,
			M.Codice Mezzo,
			'N' AS Selected
	FROM	Classi C CROSS JOIN Mezzi M
	WHERE	Tipo='MEZ'
) T 
GROUP BY	Codice, 
			Descrizione, 
			Mezzo;


-- dbo.CHK_ANA_PCS_Classi source

ALTER VIEW [dbo].[CHK_ANA_PCS_Classi] AS
SELECT		Codice, 
			Descrizione, 
			PCS, 
			MAX(Selected) Selected, 
			Descrizione OrderByField
FROM
(
	SELECT	C.Codice,
			C.Descrizione Descrizione,
			PC.PCS,
			CASE WHEN PC.PCS IS NULL THEN 'N' ELSE 'S' END Selected
	FROM	Classi C INNER JOIN PCS_Classi PC ON PC.Classe=C.Codice
	WHERE	Tipo='PCS'

UNION

	SELECT	C.Codice,
			C.Descrizione Descrizione,
			NULL PCS,
			'N' Selected
	FROM	CLASSI C 
	WHERE	Tipo='PCS'

UNION 

	SELECT	C.Codice,
			C.Descrizione Descrizione,
			P.Codice PCS,
			'N' AS Selected
	FROM	Classi C CROSS JOIN PCS P
	WHERE	Tipo='PCS'
) T 
GROUP BY	Codice, 
			Descrizione, 
			PCS;


-- dbo.CHK_ANA_Trasportatori_Classi source

ALTER VIEW [dbo].[CHK_ANA_Trasportatori_Classi] AS
SELECT Codice, 
	   Descrizione, 
	   Trasportatore, 
	   MAX(Selected) Selected, 
	   Descrizione OrderByField
FROM
(
	SELECT C.Codice,
		   C.Descrizione Descrizione,
		   TC.Trasportatore,
		   CASE WHEN TC.Trasportatore IS NULL THEN 'N' ELSE 'S' END SELECTED
	  FROM Classi C 
     INNER JOIN TrasportatoriClassi TC ON TC.Classe=C.COdice
	 WHERE C.Tipo='TRA'
UNION
	SELECT C.Codice,
		   C.Descrizione Descrizione,
		   NULL Trasportatore,
		   'N' Selected
	  FROM Classi C 
	 WHERE C.Tipo='TRA'
UNION 
	SELECT C.Codice,
		   C.Descrizione Descrizione,
		   T.Codice Trasportatore,
		   'N' AS SELECTED
	  FROM Classi C
	 CROSS JOIN Trasportatori T
	 WHERE C.Tipo='TRA'
) T 
GROUP BY Codice, Descrizione, Trasportatore;


