-- dbo.CST_ControlloFattureJDE source

ALTER View CST_ControlloFattureJDE
As
Select F4311.IdFattura, F4311.Importo_F43, F4311.Importo2, F56VIAGG.Importo_F56, Fattura.Importo_FT, Importo_F43 - Importo_F56 Delta_F43_F56, Importo_FT - Importo_F43 Delta_FT_F43, Importo_FT - Importo_F56 Delta_FT_F56
From 
	(Select IdFattura, Sum(SZAEXP) Importo_F43, Sum(SZAOPN) Importo2
	From CST_JDE_ESF4311Z1
	Group By IdFattura) F4311
Left Join 
	(Select IdFattura, Sum(VIY56CSVG) Importo_F56
	From CST_JDE_ESF56VIAGG
	Group By IdFattura) F56VIAGG On F4311.IdFattura = F56VIAGG.IdFattura
Left Join 
	(Select IdFattura, Sum(ImportoArrotondato) Importo_FT
	From Fatture_Passive_Dettaglio
	Group By IdFattura) Fattura On F4311.IdFattura = Fattura.IdFattura;


-- dbo.CST_DaSostituire_CBO_VIAGGI source

ALTER VIEW [dbo].[CST_CBO_VIAGGI] AS
SELECT  V.IdViaggio Codice,
        '<b>Id:</b>' + CAST(V.IdViaggio AS VARCHAR) + ' <b>Dt:</b>' + ISNULL(dbo.FORMATDATE(V.DataPartenzaPianificata, 'DDMMYY', '/'),' ') + ' <b>Tipo:</b>' + ISNULL(V.MotricePianificata,' ') + ' <b>Vett:</b>' + Left(ISNULL(T.RAGIONESOCIALE,' '), 60) + ' <b>Plt:</b>' + Convert(varchar, ISNULL(V.PalletPassivo, 0)) DescrizioneHtml,   
        'Id:' + CAST(V.IdViaggio AS VARCHAR) + ' Data: ' + ISNULL(dbo.FORMATDATE(V.DataPartenzaPianificata, 'DDMMYY', '/'),' ') + ' Tipo:' + ISNULL(V.MotricePianificata,' ') + ' Vettore:' + ISNULL(T.RAGIONESOCIALE,' ') + ' Plt:' + Convert(varchar, ISNULL(VT.Pallet, 0)) Descrizione,   
        V.IdViaggio OrderField,
        V.Stato
FROM Viaggi V 
LEFT JOIN TRASPORTATORI T ON V.VETTORE=T.Codice
Left Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
WHERE stato=10;


