-- dbo.CST_DaSostituire_VW_DOC_Viaggi_Stati source

ALTER VIEW [dbo].[CST_DaSostituire_VW_DOC_Viaggi_Stati] 
AS

--		  ' 10 - In Pianificazione

--        ' 20 - Pianificato (Chiusura viaggio)

--        ' 30 - Inviato a OBC

--        ' 40 - Terminato

--        ' 50 - Certificato

--        ' 60 - Storicizzato

SELECT Codice,Descrizione,OrderField 
FROM
(
	SELECT '10' Codice, 
		   'IN PIANIFICAZIONE' Descrizione, 
		   10 
		   AS Orderfield
	UNION 
	SELECT '20' Codice, 
		   'CHIUSO' Descrizione, 
		   20 AS Orderfield
	UNION 
	SELECT '30' Codice, 
		   'PARTITO' Descrizione, 
		   30 AS Orderfield
	UNION 
	SELECT '40' Codice, 
		   'TERMINATO' Descrizione, 
		   40 AS Orderfield
	UNION 
	SELECT '50' Codice, 
		   'CERTIFICATO' Descrizione, 
		   50 AS Orderfield
	UNION 
	SELECT '60' Codice, 
		   'STORICIZZATO' Descrizione, 
		   60 AS Orderfield
) T;


-- dbo.CST_DaSostituire_VW_PIA_Zone_Spedizioni source

ALTER VIEW [dbo].[CST_DaSostituire_VW_PIA_Zone_Spedizioni] 
AS
   SELECT S.unibol, unibolparent, unibolmaster, progressivoconsegna, barcode,
          prebolla, tiposervizio, cliente,
          c.ragionesociale AS clienteragionesociale, mittente,
          m.ragionesociale AS mittenteragionesociale2, mittenteragionesociale,
          numerobolla, databolla, numeroordine, dataordine,
          numeroordinecliente, dataordinecliente, tipospedizione,
          ts.descrizione AS iipospedizionidescrizione, tipomerce,
          tm.descrizione AS tipomercedescrizione, pcspartenza,
          pcspartenza_ragsoc, pcspartenza_indirizzo, pcspartenza_cap,
          pcspartenza_localita, pcspartenza_provincia, pcspartenza_nazione,
          pcsdestinazione, pcsdestinazione_ragsoc, pcsdestinazione_indirizzo,
          pcsdestinazione_cap, pcsdestinazione_localita,
          pcsdestinazione_provincia, pcsdestinazione_nazione,
          s.zonaspedizione, z.descrizione AS zonaspedizionedescrizione,
          dataconsegnaprevista1, dataconsegnaprevista2,
          dataconsegnaconcordata, oraconsegnaconcordata1,
          oraconsegnaconcordata2, dataritiroprevista1, dataritiroprevista2,
          oraritiroconcordata1, oraritiroconcordata2, corrispondente,
          co.ragionesociale AS corrispondenteragionesociale, trasportatore,
          t.ragionesociale AS trasportatoreragionesociale, s.peso, s.colli,
          s.pallet, s.volume, s.campocalcolo1, s.campocalcolo2,
          s.campocalcolo3, s.campocalcolo4, s.campocalcolo5, s.campocalcolo6,
          s.campocalcolo7, s.campocalcolo8, s.campocalcolo9, s.campocalcolo10,
          contrassegno, s.note, datacompetenzaattiva, batchid, dataspedizione,
          ISNULL (zm.codice, '*XXX*') AS macrozonaspedizione,
          ISNULL (zm.descrizione,
               'NON DEFINITA'
              ) AS macrozonaspedizionedescrizione, 
		  s.FillerAlfa1,s.FillerAlfa2,s.FillerAlfa3,
		  s.FillerAlfa4,s.FillerAlfa5,s.FillerAlfa6,
		  s.FillerAlfa7,s.FillerAlfa8,s.FillerAlfa9,s.FillerAlfa10,
		  s.FillerAlfa1 BusinessUnit,
		  s.NoteConsegnaPrevista,
		  s.NoteConsegnaConcordata,
		  CST_Sped.LinkPDF, 
		  CST_Sped.StatoEs
     FROM spedizioni s INNER JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN clienti m ON m.codice = s.mittente
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN corrispondenti co ON co.codice = s.corrispondente
          LEFT JOIN trasportatori t ON t.codice = s.trasportatore
          INNER JOIN zonespedizione z ON z.codice = s.zonaspedizione
          LEFT JOIN zonemacro zm ON zm.codice = z.codicezonamacro
		  Left Join CST_VW_Spedizioni CST_Sped On CST_Sped.UniBol = s.UniBol
    WHERE s.stato = 20 AND idviaggio IS NULL;


-- dbo.CST_DaSostiuire_GRD_DOC_Spedizioni_Eventi source

ALTER  VIEW [dbo].[CST_DaSostiuire_GRD_DOC_Spedizioni_Eventi]
AS
SELECT	Id, 
		Unibol, 
		CodiceEvento, 
		E.Descrizione as DescrizioneEvento,
		DataOraEvento, 
		NoteInterne, 
		NoteEsterne, 
		Importato, 
		Annullato, 
		EsportatoCliente, 
		DataEsportazioneCliente, 
		EsportatoFornitore, 
        DataEsportazioneFornitore, 
        DataConsegnaConcordata, 
        OraConsegnaConcordata1, 
        OraConsegnaConcordata2, 
        Riferimento, 
        SE.Autista, 
        A.RagioneSociale as AutistaDescrizione,
        Terminale, 
        Motrice, 
        MM.Descrizione as MotriceDescrizione,
        Rimorchio1, 
        MR1.Descrizione as Rimorchio1Descrizione,
        Contenitore1, 
        MC1.Descrizione as Contenitore1Descrizione,
        Rimorchio2, 
        MR2.Descrizione as Rimorchio2Descrizione,
        Contenitore2, 
        MC2.Descrizione as Contenitore2Descrizione,
        DatiAggiuntivi, 
        Latitudine, 
        Longitudine, 
        DataValiditaGPS, 
        KmGPS, 
        KmManuali, 
        SE.Localita, 
        SE.Indirizzo, 
        SE.Cap, 
        SE.Provincia, 
        SE.Nazione,
		SE.UteIns
FROM	SPEDIZIONI_EVENTI SE
		INNER JOIN EVENTI E ON E.CODICE = SE.CODICEEVENTO
		LEFT JOIN AUTISTI A ON A.CODICE = SE.AUTISTA
		LEFT JOIN MEZZI MM ON MM.CODICE = SE.MOTRICE
		LEFT JOIN MEZZI MR1 ON MR1.CODICE = SE.RIMORCHIO1
		LEFT JOIN MEZZI MR2 ON MR1.CODICE = SE.RIMORCHIO2
		LEFT JOIN MEZZI MC1 ON MC1.CODICE = SE.CONTENITORE1
		LEFT JOIN MEZZI MC2 ON MC2.CODICE = SE.CONTENITORE2;


-- dbo.CST_ES_RigheOrdine source

ALTER View [dbo].[CST_ES_RigheOrdine]
As
Select TSNORD Ordine, RGNRIG Riga, Art_Codice Articolo, Art_Descrizione Descrizione, RGQRIC QtaRichiesta, RGQMOD QtaModificata, RGQPRE QtaPrenotata, RGQEVA QtaEvasa
