-- dbo.CST_EXP_FAT_FattPassive_Dett source

ALTER View [dbo].[CST_EXP_FAT_FattPassive_Dett]
As

Select det.idfattura as [IdFattura],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.DataPartenzaPianificata
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			VS.DataPartenzaPianificata
		Else Null
	End  [Data Viaggio],

Det.unibol as [Spedizione], 
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			dbo.CST_DDTViaggio(Det.IdViaggio)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			dbo.CST_DDTViaggioSpedizione(Det.Unibol)
		Else Null
	End [Elenco DDT],
det.importoarrotondato as [Importo],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.IdViaggio
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.IdViaggio
		Else Null
	End Viaggio,
VX.MiocPrenotazione as [Booking],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.PCSPartenza
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.PCSPartenza
		Else Null
	End [Stab. Partenza],
		Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.RagioneSociale + ' (' + PCSV.Localita + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_RagSoc + ' (' + S.PCSDestinazione_Localita + ')'
		Else Null
	End [Destinazione],
		Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Cap
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Cap
		Else Null
	End  [Cap],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Provincia
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Provincia
		Else Null
	End [Prov.],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Nazione
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Nazione
		Else Null
	End [Naz.],
		Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			ZV.Descrizione + ' (' + V.ZonaArrivo + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			ZS.Descrizione + ' (' + S.ZonaArrivoTariffaPassiva + ')'
		Else Null
	End [Zona],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			ZMV.Descrizione + ' (' + ZV.CodiceZonaMacro + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			ZMS.Descrizione + ' (' + ZS.CodiceZonaMacro + ')'
		Else Null
	End [Zona Macro],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(VT.Colli, 0)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(S.Colli, 0)
		Else 0
	End Colli,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(VT.Pallet, 0)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(S.Pallet, 0)
		Else 0
	End Pallet,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(VT.Peso, 0)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(S.Peso, 0)
		Else 0
	End Peso,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(VT.Volume, 0)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(S.Volume, 0)
		Else 0
	End Volume,
det.descrizione as [Descrizione], det.quantitaOriginale as [Quantità], det.importounitario as [Unitario],
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			dbo.CST_NOCViaggio(Det.IdViaggio)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			dbo.CST_NOCViaggioSpedizione(Det.Unibol)
		Else Null
	End NumeroOrdineCliente,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(V.FillerAlfa9, '')
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(V.FillerAlfa9, '')
		Else Null
	End SubVettore

From Fatture_Passive_Dettaglio Det
Left Join Spedizioni S On S.UniBol = Det.Unibol
Left Join Viaggi V On V.IdViaggio = Det.IdViaggio
Left Join Viaggi VS On VS.IdViaggio = S.IdViaggio
Left Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
Left Join Zone ZS On ZS.Codice = S.ZonaArrivoTariffaPassiva
Left Join Zone ZV On ZV.Codice = V.ZonaArrivo
Left Join ZoneMacro ZMS On ZMS.Codice = ZS.CodiceZonaMacro
Left Join ZoneMacro ZMV On ZMV.Codice = ZV.CodiceZonaMacro
Left Join PCS PCSV On PCSV.Codice = v.PCSArrivo
Left Join CST_Viaggi VX On VX.Idviaggio = V.IdViaggio
Left Join Voci On Voci.Codice = Det.Voce;


