-- dbo.CST_GRD_ANA_Trasportatori source

ALTER VIEW CST_GRD_ANA_Trasportatori
AS
SELECT T.Codice,
       T.Tipo,
	   T.CodiceContabile,
       T.RagioneSociale,
	  T.Indirizzo,
	   T.Cap, 
	   T.Localita, 
	   T.Provincia,
	   T.ZonaPartenza,
	   T.Nazione,
	   T.Telefono, 
	   T.Fax,
	   T.Riferimento,
	   T.EMail,
	   T.PartitaIva,
	   T.CodicePagamento,
	   T.CodiceIva,
	   T.Note,
	   T.ReportBordero,
	   T.Attivo,
	   T.FatturaA,	
	   T.ReportFattura,
	   T.DataPerFatturazione,
	   T.EsportazioneBolle,
	   T.CodiceFiscale,
	   T.AlboTrasportatori,	  
	   T.ZonaSpedizione,
	   T.IsDefault,
	   '<B>Ragione Sociale: </B>'+ISNULL(T.RagioneSociale,'') + '</br>' +
	   '<B>Indirizzo: </B>'+ISNULL(T.Indirizzo,'') + '</br>' +
	   '<B>CAP: </B>'+ISNULL(T.Cap,'') + '</br>' +
