-- dbo.CST_GRD_CHECK_DETERM_CONT source

ALTER view [dbo].[CST_GRD_CHECK_DETERM_CONT] as 
SELECT Tipologia, Chk.Unibol, Voce, V.Descrizione as VoceDesc, Cdc, C.Descrizione as cdcdesc, ClasseCoge, Errore,
	  dbo.TRUNC(Vg.DataPartenzaEffettiva) DataViaggio, Chk.DatIns, 
	  S.TipoSpedizione, S.PCSPartenza, S.PCSDestinazione, S.TipoMerce, S.IdViaggio,
	  T.RagioneSociale Trasportatore
  FROM [dbo].[CST_CHECK_DETERM_CONT] Chk
  inner join voci v on (voce = v.codice)
  Left join CST_CentriDiCosto c on (cdc = c.codice) 
  Left Join Spedizioni S On S.UniBol = Chk.Unibol
  Left Join Viaggi Vg On Vg.IdViaggio = S.IdViaggio
  Left Join Trasportatori T On T.Codice = Vg.Vettore;


-- dbo.CST_GRD_CHK_ConfermeMancantiTransporeon source

ALTER View [dbo].[CST_GRD_CHK_ConfermeMancantiTransporeon]
As
Select Top 100 percent Convert(Varchar, V.DataPartenzaPianificata, 103) [Data Viaggio], T.RagioneSociale Vettore, V.IdViaggio Viaggio, S.NumeroOrdine, S.PCSPartenza_RagSoc Magazzino,
	 EsT.TSSTAT Stato, S.PCSDestinazione_RagSoc Cliente, S.PCSDestinazione_Provincia Prov, VC.MiocPrenotazione MIOC, C.RagioneSociale [Transit Point],
	 S.FillerAlfa1 BU, S.Pallet Colonne, V.PCSPartenza Par, VT.StatoTrasmissione, VT.StatoAccettazione
From Spedizioni S
Left Join CST_ES_TestateOrdine EsT On EsT.TSNORD = S.NumeroOrdine
Left Join Corrispondenti C On C.Codice = S.Corrispondente
Join Viaggi V On V.IdViaggio = S.IdViaggio
Join CST_Viaggi_Transporeon VT On VT.Idviaggio = V.IdViaggio
Left Join CST_Viaggi VC On VC.Idviaggio = V.IdViaggio
Left Join Trasportatori T On T.Codice = V.Vettore
Where VT.StatoAccettazione <> 'A'
	And V.Stato < 30
	And V.DataPartenzaPianificata >= dbo.TRUNC(GetDate())
Order By V.DataPartenzaPianificata, T.RagioneSociale;


-- dbo.CST_GRD_CHK_PartenzeSospese source

ALTER View [dbo].[CST_GRD_CHK_PartenzeSospese]
As
Select Top 100 percent Convert(Varchar, V.DataPartenzaPianificata, 103) [Data Viaggio], T.RagioneSociale Vettore, V.IdViaggio Viaggio, S.NumeroOrdine, S.NumeroBolla NumeroDDT, S.PCSPartenza_RagSoc Magazzino,
	 EsT.TSSTAT Stato, S.PCSDestinazione_RagSoc Cliente, S.PCSDestinazione_Provincia Prov, VC.MiocPrenotazione MIOC, C.RagioneSociale [Transit Point],
	 S.FillerAlfa1 BU, S.Pallet Colonne, V.PCSPartenza Par, Convert(Varchar, V.DataPartenzaPianificata, 102) DataPartenzaPianificata
From Spedizioni S
Left Join CST_ES_TestateOrdine EsT On EsT.TSNORD = S.NumeroOrdine
Left Join Corrispondenti C On C.Codice = S.Corrispondente
Join Viaggi V On V.IdViaggio = S.IdViaggio
Left Join CST_Viaggi VC On VC.Idviaggio = V.IdViaggio
Left Join Trasportatori T On T.Codice = V.Vettore
--Where V.DataPartenzaPianificata = dbo.TRUNC(GETDATE())
Where isnull(EsT.TSSTAT,110)= 110
	And V.Stato < 30
Order By V.DataPartenzaPianificata Desc, Par;


-- dbo.CST_GRD_CHK_SpedizioniNonPianificate source

ALTER View [dbo].[CST_GRD_CHK_SpedizioniNonPianificate]
As
Select Top 100 percent S.NumeroOrdine, S.PCSPartenza_RagSoc Magazzino,
	 EsT.TSSTAT Stato, S.PCSDestinazione_RagSoc Cliente, S.PCSDestinazione_Provincia Prov, C.RagioneSociale [Transit Point],
	 S.FillerAlfa1 BU, S.Pallet Colonne, S.PCSPartenza Par
From Spedizioni S
Left Join CST_ES_TestateOrdine EsT On EsT.TSNORD = S.NumeroOrdine
Left Join Corrispondenti C On C.Codice = S.Corrispondente
Where S.IdViaggio Is Null
	And S.Stato < 30
	And PCSPartenza <> 'P'
Order By S.UniBol;


-- dbo.CST_GRD_DOC_Spedizioni source

ALTER VIEW [dbo].[CST_GRD_DOC_Spedizioni] AS
   SELECT tb.descrizione AS tipobolladescrizione,
          c.ragionesociale AS clienteragionesociale,
          ts.descrizione AS tipospedizionedescrizione,
          tm.descrizione AS tipomercedescrizione,
          ISNULL(S.DATACONSEGNACONCORDATA, s.DATACONSEGNAPREVISTA1)
                                                        DATACONSEGNAPREVISTA1,
          CASE
             WHEN S.DATACONSEGNACONCORDATA IS NOT NULL
                THEN NULL
             ELSE s.DATACONSEGNAPREVISTA2
          END DATACONSEGNAPREVISTA2,
          S.UNIBOL,
          S.UNIBOLPARENT,
          S.UNIBOLMASTER,
          S.UNIBOLOBC,
          S.PROGRESSIVOCONSEGNA,
          S.BARCODE,
          S.STATO,
