						HOrdTes_DataOrdine = S.DataOrdine

          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
		  Left Join CST_VW_Spedizioni CST_Sped On CST_Sped.UniBol = s.UniBol
		  Left Join Viaggi On Viaggi.IdViaggio = S.IdViaggio
		  Left Join Trasportatori On Trasportatori.Codice = Viaggi.Vettore
	Where s.Stato In (20, 30);


-- dbo.CST_GRD_DOC_Spedizioni_CheckCosti source

ALTER View CST_GRD_DOC_Spedizioni_CheckCosti
As
With CTE_Costi As (
  Select *
	From Spedizioni_Costi
	)
Select S.UniBol,
		Stato,
		IdViaggio,
		SS.Descrizione AS DescrizioneStato,
		NumeroOrdine,
		DataOrdine,
		NumeroBolla,
		DataBolla,
		Corrispondente,
		C.RagioneSociale CorrispondenteRagioneSociale,
		TipoSpedizione,
		TS.Descrizione AS TipoSpedizioneDescrizione,
		TipoMerce,
		TM.Descrizione AS TipoMerceDescrizione,
		PCSPartenza,
		PCSDestinazione,
		PCSDestinazione_RagSoc,
		PCSDestinazione_Indirizzo,
		PCSDestinazione_Localita,
		PCSDestinazione_Provincia, 
		PCSDestinazione_Nazione,
		Peso,
		Volume,
		Colli,
		Pallet,
		StatoEs,
		ErroreTariffaPassiva,
		(
		Select IsNull(Sum(IsNull(ImportoArrotondato, 0)), 0) From CTE_Costi C Where C.Unibol = S.UniBol
		) CostoTotale
From Spedizioni S
Join CST_VW_Spedizioni CS On CS.UniBol = S.UniBol
Join VW_DOC_Spedizioni_Stati SS ON S.Stato = SS.Codice
Join Corrispondenti C On C.Codice = S.Corrispondente
Left Join TIPISPEDIZIONE TS ON TS.Codice = S.TipoSpedizione
Left Join TIPIMERCE TM ON TM.Codice = S.TipoMerce
Where IdFatturaPassiva Is Null;


-- dbo.CST_GRD_DOC_Spedizioni_DaAtt source

ALTER VIEW [dbo].[CST_GRD_DOC_Spedizioni_DaAtt] AS
   SELECT tb.descrizione AS tipobolladescrizione,
          c.ragionesociale AS clienteragionesociale,
          ts.descrizione AS tipospedizionedescrizione,
          tm.descrizione AS tipomercedescrizione,
          ISNULL(S.DATACONSEGNACONCORDATA, s.DATACONSEGNAPREVISTA1)
                                                        DATACONSEGNAPREVISTA1,
          CASE
             WHEN S.DATACONSEGNACONCORDATA IS NOT NULL
                THEN NULL
             ELSE s.DATACONSEGNAPREVISTA2
          END DATACONSEGNAPREVISTA2,
          S.UNIBOL,
          S.UNIBOLPARENT,
          S.UNIBOLMASTER,
          S.UNIBOLOBC,
          S.PROGRESSIVOCONSEGNA,
          S.BARCODE,
          S.STATO,
          S.PREBOLLA,
          S.TIPOSERVIZIO,
          S.CLIENTE,
          S.MITTENTE,
