          S.PCSDESTINAZIONE_CAP,
          S.PCSDESTINAZIONE_LOCALITA,
          S.PCSDESTINAZIONE_PROVINCIA,
          S.PCSDESTINAZIONE_NAZIONE,
          S.DESTINAZIONECLIENTE,
          S.DESTINATARIO,
          S.DESTINATARIOCLIENTE,
          S.ZONASPEDIZIONE,
          S.ZONAPARTENZATARIFFAATTIVA,
          S.ZONAARRIVOTARIFFAATTIVA,
          S.ZONAPARTENZATARIFFAPASSIVA,
          S.ZONAARRIVOTARIFFAPASSIVA,
          S.NOTECONSEGNAPREVISTA,
          S.DATACONSEGNACONCORDATA,
          S.ORACONSEGNACONCORDATA1,
          S.ORACONSEGNACONCORDATA2,
          S.NOTECONSEGNACONCORDATA,
          S.RIFERIMENTOCONSEGNACONCORDATA,
          S.CAUSALECONSEGNACONCORDATA,
          S.DATARITIROPREVISTA1,
          S.DATARITIROPREVISTA2,
          S.NOTERITIROPREVISTO,
          S.ORARITIROCONCORDATA1,
          S.ORARITIROCONCORDATA2,
          S.NOTERITIROCONCORDATA,
          S.RIFERIMENTORITIROCONCORDATA,
          S.CAUSALERITIROCONCORDATA,
          S.CORRISPONDENTE,
          S.TRASPORTATORE,
          S.PESO,
          S.COLLI,
          S.PALLET,
          S.VOLUME,
          S.CAMPOCALCOLO1,
          S.CAMPOCALCOLO2,
          S.CAMPOCALCOLO3,
          S.CAMPOCALCOLO4,
          S.CAMPOCALCOLO5,
          S.CAMPOCALCOLO6,
          S.CAMPOCALCOLO7,
          S.CAMPOCALCOLO8,
          S.CAMPOCALCOLO9,
          S.CAMPOCALCOLO10,
          S.FLAG1,
          S.FLAG2,
          S.FLAG3,
          S.FLAG4,
          S.FLAG5,
          S.FLAG6,
          S.FLAG7,
          S.FLAG8,
          S.FLAG9,
          S.FLAG10,
          S.CONTRASSEGNO,
          S.TASSATOATTIVO,
          S.TASSATOPASSIVO,
          S.NOTE,
          S.DATAORAPARTENZAPIANIFICATA,
          S.DATAORAPARTENZAEFFETTIVA,
          S.DATAORAARRIVOPIANIFICATA,
          S.DATAORAARRIVOEFFETTIVA,
          S.KMPIANIFICATI,
          S.KMGPS,
          S.KMMANUALI,
          S.KMRICALCOLATI,
          S.DATACOMPETENZAATTIVA,
          S.DATACOMPETENZAPASSIVA,
          S.IDFATTURAATTIVA,
          S.IDFATTURAPASSIVA,
          S.IDVIAGGIO,
          S.SEQUENZAPIANIFICATA,
          S.SEQUENZAEFFETTIVA,
          S.SEQUENZAORIGINALE,
          S.FILLERALFA1,
          S.FILLERALFA2,
          S.FILLERALFA3,
          S.FILLERALFA4,
          S.FILLERALFA5,
          S.FILLERALFA6,
          S.FILLERALFA7,
          S.FILLERALFA8,
          S.FILLERALFA9,
          S.FILLERALFA10,
          S.FILLERDATA1,
          S.FILLERDATA2,
          S.FILLERDATA3,
          S.FILLERDATA4,
          S.FILLERDATA5,
          S.BATCHID,
          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
		  CO.RagioneSociale AS RagSocCorrispondente,
		  CO.Localita AS LocalitaCorrispondente,
		  VL.Giro,
		  VL.RiferimentoEsterno AS RiferimentoEsternoGiro,
		  CST_Sped.LinkPDF,
		  CST_Sped.StatoEs

		  --'<a href="' +  Convert(varchar, dbo.CST_LinkPDF(s.UniBol)) + '" target="_blank">View</a>' LinkPDF
		  --CASE WHEN S.TipoServizio = 'CONSDP' THEN
		  --'<a href="../../pdfcdv/' + 
		  --CAST(DATEPART(YYYY , DataOrdine) AS VARCHAR) + '-' +
		  --SUBSTRING(NumeroOrdine, 9, 2) + '-' +
		  --Cliente + '-' +
		  --SUBSTRING(NumeroOrdine, 1, 8) + '-' +
		  --PCSDestinazione +
		  --'.pdf' + '" target="_blank">View</a>' ELSE NULL END LinkPDF
			
     FROM Spedizioni S INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  Left Join CST_VW_Spedizioni CST_Sped On CST_Sped.UniBol = s.UniBol
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
		  LEFT JOIN CST_Spedizioni_Ext X ON X.UniBol = S.UniBol 
    WHERE s.stato = 20 AND ISNULL(X.Attenzionata, 'N') = 'N' and IdViaggio is null;


-- dbo.CST_GRD_DOC_Spedizioni_Eventi source

ALTER VIEW [dbo].[CST_GRD_DOC_Spedizioni_Eventi]
AS
SELECT	Id, 
		Unibol, 
		CodiceEvento, 
		E.Descrizione as DescrizioneEvento,
		DataOraEvento, 
		NoteInterne, 
		NoteEsterne, 
		Importato, 
		Annullato, 
		EsportatoCliente, 
		DataEsportazioneCliente, 
		EsportatoFornitore, 
        DataEsportazioneFornitore, 
        DataConsegnaConcordata, 
        OraConsegnaConcordata1, 
        OraConsegnaConcordata2, 
        Riferimento, 
        SE.Autista, 
        A.RagioneSociale as AutistaDescrizione,
        Terminale, 
        Motrice, 
        MM.Descrizione as MotriceDescrizione,
        Rimorchio1, 
        MR1.Descrizione as Rimorchio1Descrizione,
        Contenitore1, 
        MC1.Descrizione as Contenitore1Descrizione,
        Rimorchio2, 
        MR2.Descrizione as Rimorchio2Descrizione,
        Contenitore2, 
        MC2.Descrizione as Contenitore2Descrizione,
        DatiAggiuntivi, 
        Latitudine, 
        Longitudine, 
        DataValiditaGPS, 
        KmGPS, 
        KmManuali, 
        SE.Localita, 
        SE.Indirizzo, 
        SE.Cap, 
        SE.Provincia, 
        SE.Nazione,
		SE.UteIns
FROM	SPEDIZIONI_EVENTI SE
		INNER JOIN EVENTI E ON E.CODICE = SE.CODICEEVENTO
		LEFT JOIN AUTISTI A ON A.CODICE = SE.AUTISTA
		LEFT JOIN MEZZI MM ON MM.CODICE = SE.MOTRICE
		LEFT JOIN MEZZI MR1 ON MR1.CODICE = SE.RIMORCHIO1
		LEFT JOIN MEZZI MR2 ON MR1.CODICE = SE.RIMORCHIO2
		LEFT JOIN MEZZI MC1 ON MC1.CODICE = SE.CONTENITORE1
		LEFT JOIN MEZZI MC2 ON MC2.CODICE = SE.CONTENITORE2;


