          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
		  Left Join CST_ES_TestateOrdine EsTes On EsTes.TSNORD = s.NumeroOrdine
WHERE IDVIAGGIO IS NULL And
	S.STATO = 20 And
	(NumeroOrdine <> ISNULL(NumeroBolla, NumeroOrdine) Or S.UteIns <> 'DSI');


-- dbo.CST_GRD_DOC_Spedizioni_Libere source

ALTER VIEW [dbo].[CST_GRD_DOC_Spedizioni_Libere] AS
SELECT S.Unibol,
       S.Barcode,
       S.NumeroOrdine,
       S.NumeroBolla,
       S.NUMEROORDINECLIENTE,
       S.TipoSERVIZIO,
       TB.Descrizione AS TipoBollaDescrizione,          
       S.PCSPartenza,
       S.PCSPartenza_RagSoc,
       S.PCSPartenza_Localita,
       S.PCSPartenza_Indirizzo,
       S.PCSPartenza_Provincia,
       S.PCSPartenza_Nazione,
       S.PCSDestinazione,
       S.PCSDestinazione_RagSoc,
       S.PCSDestinazione_Localita,
       S.PCSDestinazione_Indirizzo,
       S.PCSDestinazione_Provincia,
       S.PCSDestinazione_Nazione,
       S.Corrispondente,
       S.Colli,
       S.Pallet,
       S.Peso,
       S.Volume,
       S.TipoSpedizione,
       S.TipoMerce,
       S.Cliente,
       S.ZonaSpedizione,
       S.DataBolla,
       S.DataOrdine,
       S.DATAORDINECLIENTE,
       S.DATACONSEGNAPREVISTA1,
       S.DATACONSEGNAPREVISTA2,
       ISNULL(S.DATACONSEGNACONCORDATA, s.DATACONSEGNAPREVISTA1) DATACONSEGNA1,
       CASE
          WHEN S.DATACONSEGNACONCORDATA IS NOT NULL
             THEN NULL
          ELSE s.DATACONSEGNAPREVISTA2
       END DATACONSEGNA2,
       DATACONSEGNACONCORDATA, 
       S.BatchId,
       S.DataSpedizione,
	   S.DestinazioneCliente,
	   CO.RagioneSociale AS RagSocCorrispondente,
	   CO.Localita AS LocalitaCorrispondente,
	   VL.Giro,
	   VL.RiferimentoEsterno AS RiferimentoEsternoGiro,
       S.FILLERALFA1,
       S.FILLERALFA2,
       S.FILLERALFA3,
       S.FILLERALFA4,
       S.FILLERALFA5,
       S.FILLERALFA6,
       S.FILLERALFA7,
       S.FILLERALFA8,
       S.FILLERALFA9,
       S.FILLERALFA10,
       S.FILLERDATA1,
       S.FILLERDATA2,
       S.FILLERDATA3,
       S.FILLERDATA4,
       S.FILLERDATA5,
	   EsTes.TSNORD StatoEs
  FROM Spedizioni S
 INNER JOIN TIPISERVIZI TB ON TB.CODICE = S.TIPOSERVIZIO
 INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
  LEFT JOIN CLIENTI C ON C.CODICE = S.CLIENTE    
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE  
  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
  Left Join CST_ES_TestateOrdine EsTes On EsTes.TSNORD = s.NumeroOrdine
WHERE IDVIAGGIO IS NULL AND s.STATO = 20;


-- dbo.CST_GRD_DOC_Spedizioni_Statistiche source

ALTER VIEW [dbo].[CST_GRD_DOC_Spedizioni_Statistiche] AS
SELECT S.UniBol,
		S.IdViaggio,
		V.DataPartenzaPianificata,
		S.Stato,
		SS.Descrizione AS DescrizioneStato,
		Corrispondente,
		C.RagioneSociale AS CorrispondenteDescrizione,
		S.TipoSpedizione,
		TS.Descrizione AS TipoSpedizioneDescrizione,
		S.TipoMerce,
		TM.Descrizione AS TipoMerceDescrizione,
		S.Cliente,
		C.RagioneSociale AS ClienteDescrizione,
		S.PCSPartenza,
		PCSDestinazione,
		S.Peso,
		S.Volume,
		S.Colli,
		S.Pallet,
		S.FILLERALFA1 AS BU,
		S.FILLERALFA2,
		S.FILLERALFA3,
		S.FILLERALFA4,
		S.FILLERALFA5,
		S.FILLERALFA6,
		S.FILLERALFA7,
		S.FILLERALFA8,
		S.FILLERALFA9,
		S.FILLERALFA10,
		S.FILLERDATA1,
		S.FILLERDATA2,
		S.FILLERDATA3,
		S.FILLERDATA4,
		S.FILLERDATA5,
		S.ZonaArrivoTariffaPassiva,
		ZA.CodiceZonaMacro MacroZonaArrivo,
		S.Note, 
		PcsP.RagioneSociale Partenza,
		PcsA.RagioneSociale + IsNull(' (' + PcsA.Provincia + ')', '') Arrivo,
		SCT.ImportoTotale,
		PcsA.Provincia,
		Pr.Regione,
		PcsA.Nazione
FROM Spedizioni S 
Left Join Viaggi V On V.IdViaggio = S.IdViaggio
INNER JOIN VW_DOC_Spedizioni_Stati SS ON S.Stato = SS.Codice
LEFT JOIN Corrispondenti C ON C.CODICE = S.Corrispondente
LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TipoMerce
Left Join PCS PcsP On PcsP.Codice = S.PCSPartenza
Left Join PCS PcsA On PcsA.Codice = S.PCSDestinazione
Left Join CST_SpedizioniCostoTotale SCT On SCT.Unibol = S.UniBol
Left Join Zone ZA On ZA.Codice = S.ZonaArrivoTariffaAttiva
Left Join Province Pr On Pr.Provincia = PcsA.Provincia;


