          S.FILLERDATA5,
          S.BATCHID,
          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
		  CO.RagioneSociale AS RagSocCorrispondente,
		  CO.Localita AS LocalitaCorrispondente,
		  VL.Giro,
		  VL.RiferimentoEsterno AS RiferimentoEsternoGiro,
		  --'<a href="' +  Convert(varchar, dbo.CST_LinkPDF(s.UniBol)) + '" target="_blank">View</a>' LinkPDF
		  CST_Sped.LinkPDF,
		  CST_Sped.StatoEs,
		  Convert(Varchar, S.IdViaggio) + ' (' + ISNULL(Trasportatori.RagioneSociale, '') + ')' ViaggioVettore,
		  IsNull(Convert(Varchar, Viaggi.DataArrivoPianificata, 1) + '*', Convert(Varchar, S.DataConsegnaPrevista1, 1)) DataConsegna,
		  ZS.CodiceZonaMacro,
		  P.Regione
     FROM Spedizioni S INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
		  Left Join CST_VW_Spedizioni CST_Sped On CST_Sped.UniBol = s.UniBol
		  Left Join Viaggi On Viaggi.IdViaggio = S.IdViaggio
		  Left Join Trasportatori On Trasportatori.Codice = Viaggi.Vettore
		  Left Join ZoneSpedizione ZS On ZS.Codice = S.ZonaSpedizione
		  Left Join Province P On P.Provincia = S.PCSDestinazione_Provincia
	Where S.Stato >= 30
		And S.Stato < 90
		And S.Corrispondente Is Not Null;


-- dbo.CST_GRD_DOC_TariffePassive source

ALTER VIEW [dbo].[CST_GRD_DOC_TariffePassive] AS
SELECT TC.Codice
     , TC.Trasportatore
     , T.RagioneSociale AS RagioneSocialeTrasportatore
	 , TC.Descrizione
	 , TC.DataInizioValidita
	 , TC.DataFineValidita
	 , TC.Raggruppamento
	 , TT.TipoSpedizione
	 , TT.TipoMerce
	 , TT.TipoMezzo
	 , TT.Cliente
	 , C.RagioneSociale AS RagioneSocialeCliente
	 , TT.GruppoTariffarioPartenza
	 , GT.Descrizione AS DescrizioneGruppoTarifPartenza
	 , TT.PCSPartenza
	 , PCS.RagioneSociale AS RagSocPCSPartenza
	 , TT.MacroZonaArrivo
	 , ZM.Descrizione AS DescrizioneZMArrivo
	 , TT.ZonaArrivo + ' (' + Z.Descrizione + ')' ZonaArrivo
	 , Z.Descrizione AS DescrizioneZonaArrivo
	 , TT.GruppoTariffarioArrivo
	 , GT1.Descrizione AS DescrizioneGruppoTarifArrivo
	 , TT.PCSArrivo
	 , PCS1.RagioneSociale AS RagSocPCSArrivo
	 , TT.TipoDocumento
	 , TV.Voce
	 , V.Descrizione AS DescrizioneVoce
	 , TV.CampoCalcolo
	 , TV.ArrCampoCalcolo
	 , TV.ArrCampoCalcoloLimite
	 , TV.ArrCampoCalcoloOltre
	 , TV.ArrImporto
	 , TV.flgEccedenza
	 , TF.FasciaInferiore
	 , TF.FasciaSuperiore
	 , TF.Fisso
	 , TF.Variabile
	 , TF.Percentuale
	 , TT.IdTariffa
	 , TV.IdVoce
	 , TF.IdFascia
	 , CAST(TT.IdTariffa AS VARCHAR) + ' ' + CAST(TV.IdVoce AS VARCHAR) + ' ' + CAST(TF.IdFascia AS VARCHAR) AS Id
  FROM TariffeContratti TC
 INNER JOIN TariffePassiveTestata TT ON TC.Codice=TT.Contratto
 INNER JOIN Trasportatori T ON TC.Trasportatore=T.Codice
 INNER JOIN Clienti C ON TT.Cliente=C.Codice
 INNER JOIN PCS_GruppiTariffari GT ON GT.Codice=TT.GruppoTariffarioPartenza
 INNER JOIN PCS PCS ON PCS.Codice=TT.PCSPartenza
 INNER JOIN ZoneMacro ZM ON TT.MacroZonaArrivo=ZM.Codice
 INNER JOIN Zone Z ON Z.Codice=TT.ZonaArrivo
 INNER JOIN PCS_GruppiTariffari GT1 ON GT1.Codice=TT.GruppoTariffarioArrivo
 INNER JOIN PCS PCS1 ON PCS1.Codice=TT.PCSArrivo
 INNER JOIN TariffePassiveVoci TV ON TV.IdTariffa=TT.IdTariffa
 INNER JOIN Voci V ON V.Codice=TV.Voce
 INNER JOIN TariffePassiveFasce TF ON TF.IdVoce=TV.IdVoce 
 WHERE TC.AttivaPassiva='P' AND TC.Attivo='S';


-- dbo.CST_GRD_DOC_TariffePassive_Por source

ALTER VIEW [dbo].[CST_GRD_DOC_TariffePassive_Por] AS
SELECT TC.Codice
     , TC.Trasportatore
     , T.RagioneSociale AS RagioneSocialeTrasportatore
	 , TC.Descrizione
	 , TC.DataInizioValidita
	 , TC.DataFineValidita
	 , TC.Raggruppamento
	 , TT.TipoSpedizione
	 , TT.TipoMerce
	 , TT.TipoMezzo
	 , TT.Cliente
	 , C.RagioneSociale AS RagioneSocialeCliente
	 , TT.GruppoTariffarioPartenza
	 , GT.Descrizione AS DescrizioneGruppoTarifPartenza
	 , TT.PCSPartenza
	 , PCS.RagioneSociale AS RagSocPCSPartenza
	 , TT.MacroZonaArrivo
	 , ZM.Descrizione AS DescrizioneZMArrivo
	 , TT.ZonaArrivo
	 , Z.Descrizione AS DescrizioneZonaArrivo
	 , TT.GruppoTariffarioArrivo
	 , GT1.Descrizione AS DescrizioneGruppoTarifArrivo
	 , TT.PCSArrivo
	 , PCS1.RagioneSociale AS RagSocPCSArrivo
	 , TT.TipoDocumento
	 , TV.Voce
	 , V.Descrizione AS DescrizioneVoce
	 , TV.CampoCalcolo
	 , TV.ArrCampoCalcolo
	 , TV.ArrCampoCalcoloLimite
	 , TV.ArrCampoCalcoloOltre
	 , TV.ArrImporto
	 , TV.flgEccedenza
	 , TF.FasciaInferiore
	 , TF.FasciaSuperiore
	 , TF.Fisso
	 , TF.Variabile
	 , TF.Percentuale
	 , TT.IdTariffa
	 , TV.IdVoce
	 , TF.IdFascia
	 , CAST(TT.IdTariffa AS VARCHAR) + ' ' + CAST(TV.IdVoce AS VARCHAR) + ' ' + CAST(TF.IdFascia AS VARCHAR) AS Id
  FROM TariffeContratti TC
 INNER JOIN TariffePassiveTestata TT ON TC.Codice=TT.Contratto
 INNER JOIN Trasportatori T ON TC.Trasportatore=T.Codice
 INNER JOIN Clienti C ON TT.Cliente=C.Codice
 INNER JOIN PCS_GruppiTariffari GT ON GT.Codice=TT.GruppoTariffarioPartenza
 INNER JOIN PCS PCS ON PCS.Codice=TT.PCSPartenza
 INNER JOIN ZoneMacro ZM ON TT.MacroZonaArrivo=ZM.Codice
 INNER JOIN Zone Z ON Z.Codice=TT.ZonaArrivo
 INNER JOIN PCS_GruppiTariffari GT1 ON GT1.Codice=TT.GruppoTariffarioArrivo
 INNER JOIN PCS PCS1 ON PCS1.Codice=TT.PCSArrivo
 INNER JOIN TariffePassiveVoci TV ON TV.IdTariffa=TT.IdTariffa
 INNER JOIN Voci V ON V.Codice=TV.Voce
 INNER JOIN TariffePassiveFasce TF ON TF.IdVoce=TV.IdVoce 
 WHERE TC.AttivaPassiva='P'
	AND TC.Attivo='S'
	And PCSPartenza In ('*ALL', 'P')
	And GETDATE() Between TC.DataInizioValidita And TC.DataFineValidita;


-- dbo.CST_GRD_DOC_Viaggi_All source

ALTER                 VIEW [dbo].[CST_GRD_DOC_Viaggi_All] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT V.IdViaggio,
		Stato,
		VS.Descrizione AS DescrizioneStato,
		DataPartenzaPianificata,
		DataArrivoPianificata,
		DataPartenzaEffettiva,
		DataArrivoEffettiva,
		MotriceEffettiva AS Motrice,
		MM.Targa AS MotriceDescrizione,
		Rimorchio1Effettivo AS Rimorchio1,
		MR.Targa AS Rimorchio1Descrizione,
		Contenitore1Effettivo AS Contenitore1,
		MC.Targa AS Contenitore1Descrizione,
		Vettore,
		T.RagioneSociale AS VettoreDescrizione,
		Autista1Pianificato,
		A.RagioneSociale AS Autista1PianificatoDescrizione,
		Autista1Effettivo,
		A1.RagioneSociale AS Autista1EffettivoDescrizione,
		TipoSpedizione,
		TS.Descrizione AS TipoSpedizioneDescrizione,
		V.TipoMerce,
		TM.Descrizione AS TipoMerceDescrizione,
		V.Cliente,
		C.RagioneSociale AS ClienteDescrizione,
		PCSPartenza,
		PCSArrivo,
		KmPianificati,
		KmManuali,
		KmGPS,
		A1.Trasportatore,
		MM.Trasportatore AS Trasportatore1,
		V.Terminale,
		(
			SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
			) Peso,
			(
			SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
			) Volume,
			(
			SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
			) Colli,
			(
			SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
			) Pallet,
			(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
			) Numero_Spedizioni,
			V.Sagome,
			V.PalletPassivo,
			V.VolumePassivo,
			V.PALLETEFFETTIVI,
			V.SAGOMEEFFETTIVE,
			V.VolumeEffettivo,
			V.TipoViaggio,
			(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
			) Num_Spedizioni_Diretta,
			(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
			) Num_Spedizioni_Distribuzione,
		V.FILLERALFA1,
		V.FILLERALFA2,
		V.FILLERALFA3,
		V.FILLERALFA4,
		V.FILLERALFA5,
		V.FILLERALFA6,
		V.FILLERALFA7,
		V.FILLERALFA8,
		V.FILLERALFA9,
		V.FILLERALFA10,
		V.FILLERDATA1,
		V.FILLERDATA2,
		V.FILLERDATA3,
		V.FILLERDATA4,
		V.FILLERDATA5,
		V.ZonaArrivo,
		V.Note1, 
		V.Note2, 
		CASE VT.StatoTrasmissione
    WHEN 'S' THEN
        'Inviato' +
        ISNULL(
            ' (' +
            CASE
                WHEN VT.StatoAccettazione = 'A'
                     AND VT.DeclineReason = 'Non esistono slot liberi nella data indicata'
                    THEN 'Rifiutato'
                -- Ramo spostato PRIMA del generico 'A' -> 'Accettato',
                -- altrimenti non verrebbe mai raggiunto
                WHEN VT.StatoAccettazione = 'A'
                     AND VT.StatoTesi = 'D'
                    THEN 'Cancellato tramite Delsy'
                WHEN VT.StatoAccettazione = 'A'
                    THEN 'Accettato'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.StatoTesi = 'D'
                     AND VT.DeclineReason IS NULL
                    THEN 'Cancellato tramite Delsy'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.DeclineReason IS NULL
                    THEN 'In attesa vettore'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.DeclineReason = 'Viaggio rifiutato da trasportatore'
                    THEN 'Rifiutato'
                WHEN VT.StatoAccettazione = 'X'
                AND VT.DeclineReason IS NULL
                    THEN 'Anomalia'
                WHEN VT.StatoAccettazione = 'R'
                     AND LEFT(VT.DeclineReason, 44) = 'Impossibile creare appuntamento per delivery'
                    THEN 'Anomalia'
                ELSE NULL
            END +
            ')',
            ''
        )
    WHEN 'E' THEN 'Errore di sistema'
    WHEN 'X' THEN 'In trasmissione'
    ELSE NULL
END AS StatoTesi, 
VT.DeclineReason ErroreTesi,
		VTR.StatoTrasmissione + IsNull('-' + VTR.StatoTransporeon, '') + IsNull(' (' + Case VTR.StatoAccettazione When 'A' Then 'Acc' When 'D' Then 'Dec' Else Null End + ')', '') StatoTransporeon,
		VC.MiocPrenotazione,
		CASE 
        WHEN V.Stato in ('30','40') THEN 'PARTITO'
		WHEN V.PCSPartenza NOT IN ('G', 'D','AD') THEN ''
        WHEN VC.PrenotazioneVettore = 'OK' THEN 'ARRIVATO'
        WHEN VC.PrenotazioneVettore = 'Entrato' THEN 'ENTRATO'
        ELSE 'NON ARRIVATO'
        END AS StatoCamion,
        CST_Sped.AvanzaStatoCamion as AvanzaStato,
        CST_Reset.ResetStatoCamion as ResetStato,
        --CST_Sped.AvanzaStato AS AvanzaStato,
        /*CASE WHEN V.PCSPartenza IN ('G', 'D') THEN
		  '<a href="http://dtscartotecnica/schede/schedenam.exe/Avanza?IDViaggio=' + 
		  CAST(V.IdViaggio AS VARCHAR) +
		  '&amp;NuovoStato=Entrato' +
		  '" target="_blank">View</a>' ELSE NULL END AvanzaStato,
        
        
        
        
        'http://dtscartotecnica/schede/schedenam.exe/Avanza?IDViaggio=' 
+ CAST(V.IdViaggio AS VARCHAR) + 
'&amp;NuovoStato=Entrato' AS AvanzaStato,*/
		dbo.CST_SpedizioniViaggio(V.IdViaggio) ElencoSpedizioni,
		(
			SELECT Convert(Varchar, Min(StatoEs)) + Case When Min(StatoEs) <> Max(StatoEs) Then '-' + Convert(Varchar, Max(StatoEs)) Else '' End FROM Spedizioni S Join CST_VW_Spedizioni CS On CS.UniBol = S.UniBol WHERE S.IdViaggio = V.IdViaggio
		) StatoEs,
		PcsA.RagioneSociale + IsNull(' (' + PcsA.Provincia + ')', '') Arrivo,
		'X' temp, dbo.CST_OrdCliSpedxViaggio(V.IdViaggio) ElencoOrdiniClienteSpedizioniViaggio, VEC.ExtraCosti, V.Flag8,
		isnull((
			SELECT isnull(AltMaxMezzo, 0) AltMaxMezzo FROM CST_VW_Altezza_Max_Viaggio WHERE ViaggioId = V.IdViaggio
			), 0) AltMaxMezzo
FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato 
LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato 
LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
Left Join CST_Viaggi VC On VC.Idviaggio = V.IdViaggio
Left Join CST_Viaggi_Tesi VT On VT.Idviaggio = V.IdViaggio
Left Join CST_Viaggi_Transporeon VTR On VTR.Idviaggio = V.IdViaggio
Left Join PCS PcsA On PcsA.Codice = V.PCSArrivo
Left Join CST_Viaggi_ExtraCosti VEC On VEC.IdViaggio = V.IdViaggio
Join CST_VW_EntraCamion CST_Sped On CST_Sped.IdViaggio = V.IdViaggio
Join CST_VW_ResetStatoCamion CST_Reset On CST_Reset.IdViaggio = V.IdViaggio
Where IsNull(DataPartenzaEffettiva, DataPartenzaPianificata) > GetDate() - 30;


-- dbo.CST_GRD_DOC_Viaggi_Attivi source

ALTER VIEW [dbo].[CST_GRD_DOC_Viaggi_Attivi] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT V.IdViaggio,
		VS.Descrizione AS Stato,
		DataPartenzaPianificata,
		DataArrivoPianificata,
		DataPartenzaEffettiva,
		DataArrivoEffettiva,
		MotriceEffettiva AS Motrice,
		MM.Targa AS MotriceDescrizione,
		Rimorchio1Effettivo AS Rimorchio1,
		MR.Targa AS Rimorchio1Descrizione,
		Contenitore1Effettivo AS Contenitore1,
		MC.Targa AS Contenitore1Descrizione,
		Vettore,
		T.RagioneSociale AS VettoreDescrizione,
		Autista1Pianificato,
		A.RagioneSociale AS Autista1PianificatoDescrizione,
		Autista1Effettivo,
		A1.RagioneSociale AS Autista1EffettivoDescrizione,
		TipoSpedizione,
		TS.Descrizione AS TipoSpedizioneDescrizione,
		V.TipoMerce,
		TM.Descrizione AS TipoMerceDescrizione,
		V.Cliente,
		C.RagioneSociale AS ClienteDescrizione,
		PCSPartenza,
		PCSArrivo,
		KmPianificati,
		KmManuali,
		KmGPS,
		V.Note1, 
		V.Note2,
		A1.Trasportatore,
		MM.Trasportatore AS Trasportatore1,
		V.Terminale,
		(
		SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
		) Peso,
		(
		SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
		) Volume,
		(
		SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
		) Colli,
		(
		SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
		) Pallet,
		(
		SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
		) Numero_Spedizioni    ,
		V.Sagome,
		V.PalletPassivo,
		V.VolumePassivo,
		V.PALLETEFFETTIVI,
		V.SAGOMEEFFETTIVE,
		V.VolumeEffettivo,
		V.TipoViaggio,
		(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
		) Num_Spedizioni_Diretta,
		(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
		) Num_Spedizioni_Distribuzione,
		V.FILLERALFA1,
		V.FILLERALFA2,
		V.FILLERALFA3,
		V.FILLERALFA4,
		V.FILLERALFA5,
		V.FILLERALFA6,
		V.FILLERALFA7,
		V.FILLERALFA8,
		V.FILLERALFA9,
		V.FILLERALFA10,
		V.FILLERDATA1,
		V.FILLERDATA2,
		V.FILLERDATA3,
		V.FILLERDATA4,
		V.FILLERDATA5,
		V.ZonaArrivo, 
		VTR.StatoTrasmissione + IsNull('-' + VTR.StatoTransporeon, '') + IsNull(' (' + Case VTR.StatoAccettazione When 'A' Then 'Acc' When 'D' Then 'Dec' Else Null End + ')', '') StatoTransporeon,
		CASE VT.StatoTrasmissione
    WHEN 'S' THEN
        'Inviato' +
        ISNULL(
            ' (' +
            CASE
                WHEN VT.StatoAccettazione = 'A'
                     AND VT.DeclineReason = 'Non esistono slot liberi nella data indicata'
                    THEN 'Rifiutato'
                -- Ramo spostato PRIMA del generico 'A' -> 'Accettato',
                -- altrimenti non verrebbe mai raggiunto
                WHEN VT.StatoAccettazione = 'A'
                     AND VT.StatoTesi = 'D'
                    THEN 'Cancellato tramite Delsy'
                WHEN VT.StatoAccettazione = 'A'
                    THEN 'Accettato'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.StatoTesi = 'D'
                     AND VT.DeclineReason IS NULL
                    THEN 'Cancellato tramite Delsy'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.DeclineReason IS NULL
                    THEN 'In attesa vettore'
                WHEN VT.StatoAccettazione = 'R'
                     AND VT.DeclineReason = 'Viaggio rifiutato da trasportatore'
                    THEN 'Rifiutato'
                WHEN VT.StatoAccettazione = 'X'
                AND VT.DeclineReason IS NULL
                    THEN 'Anomalia'
                WHEN VT.StatoAccettazione = 'R'
                     AND LEFT(VT.DeclineReason, 44) = 'Impossibile creare appuntamento per delivery'
                    THEN 'Anomalia'
                ELSE NULL
            END +
            ')',
            ''
        )
    WHEN 'E' THEN 'Errore di sistema'
    WHEN 'X' THEN 'In trasmissione'
    ELSE NULL
END AS StatoTesi,
 VT.DeclineReason ErroreTesi,
		VC.MiocPrenotazione,
		dbo.CST_SpedizioniViaggio(V.IdViaggio) ElencoSpedizioni,
		(
			SELECT Convert(Varchar, Min(StatoEs)) + Case When Min(StatoEs) <> Max(StatoEs) Then '-' + Convert(Varchar, Max(StatoEs)) Else '' End FROM Spedizioni S Join CST_VW_Spedizioni CS On CS.UniBol = S.UniBol WHERE S.IdViaggio = V.IdViaggio
		) StatoEs,
		PcsA.RagioneSociale + IsNull(' (' + PcsA.Provincia + ')', '') Arrivo,
		(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL AND S.Flag1 = 'N'
		) ConsegneDaPrenotare, dbo.CST_OrdCliSpedxViaggio(V.IdViaggio) ElencoOrdiniClienteSpedizioniViaggio, VEC.ExtraCosti, V.Flag8,
		isnull((
			SELECT isnull(AltMaxMezzo, 0) AltMaxMezzo FROM CST_VW_Altezza_Max_Viaggio WHERE ViaggioId = V.IdViaggio
			), 0) AltMaxMezzo
FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato
LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato
LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
Left Join CST_Viaggi VC On VC.Idviaggio = V.IdViaggio
Left Join CST_Viaggi_Tesi VT On VT.Idviaggio = V.IdViaggio
Left Join CST_Viaggi_Transporeon VTR On VTR.Idviaggio = V.IdViaggio
Left Join PCS PcsA On PcsA.Codice = V.PCSArrivo
Left Join CST_Viaggi_ExtraCosti VEC On VEC.IdViaggio = V.IdViaggio
WHERE V.Stato<20;


