			) Num_Spedizioni_Diretta,
			(
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
			) Num_Spedizioni_Distribuzione,
		V.FILLERALFA1,
