--Left Join CST_Viaggi VC On VC.Idviaggio = V.IdViaggio
Left Join PCS PcsP On PcsP.Codice = V.PCSPartenza
Left Join PCS PcsA On PcsA.Codice = V.PCSArrivo
--Left Join CST_Viaggi_ExtraCosti VEC On VEC.IdViaggio = V.IdViaggio
Left Join CST_ViaggiCostoTotale VCT On VCT.IdViaggio = V.IdViaggio
Left Join Zone ZA On ZA.Codice = V.ZonaArrivo
Left Join Province Pr On (Pr.Provincia = PcsA.Provincia And Pr.Nazione = PcsA.Nazione);


-- dbo.CST_GRD_FAT_FattPassExpRip source

ALTER VIEW [dbo].[CST_GRD_FAT_FattPassExpRip] AS
SELECT a.*,
    b.Descrizione   AS DescCdc,
    d.descrizione   AS DescVoce,
    c.PCSDestinazione_RagSoc AS DestRagSoc,
    c.idviaggio     AS IdViaggioSped,
    FT.Data,
    c.NumeroOrdine,
    c.NumeroBolla,
    c.TipoSpedizione,
    c.PCSDestinazione,
    c.PCSPartenza,
    c.PCSPartenza_RagSoc,
    v.FillerAlfa9   AS SubVettore,
    c.NumeroOrdineCliente,
    -- 🔑 Vettore condizionale
    CASE
        WHEN a.Tipologia = 'S' THEN c.Trasportatore    -- dalla tabella spedizioni
        ELSE v.Vettore                           -- altrimenti dai viaggi
    END AS Vettore,
    T.RagioneSociale AS VettoreDescrizione
FROM [dbo].[CST_FattPassExpRipartizione] a
INNER JOIN cst_centridicosto b ON (a.centrodicosto = b.codice)
INNER JOIN spedizioni c ON (c.unibol = a.unibol)
INNER JOIN voci d ON (d.codice = a.voce)
JOIN viaggi v ON (v.IdViaggio = c.idviaggio)
JOIN Fatture_Passive_Testata FT ON FT.IdFattura = a.IdFattura
LEFT JOIN TRASPORTATORI T ON T.CODICE = 
    CASE WHEN a.Tipologia = 'S' THEN c.Trasportatore ELSE v.Vettore END;


-- dbo.CST_GRD_FAT_FattPassive_Dett source

ALTER View [dbo].[CST_GRD_FAT_FattPassive_Dett]
As
Select Det.*,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			dbo.CST_DDTViaggio(Det.IdViaggio)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			dbo.CST_DDTViaggioSpedizione(Det.Unibol)
		Else Null
	End NumeroBolla,
	VX.MiocPrenotazione Prenotazione,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			'Viaggio ' + Convert(varchar, V.IdViaggio) + ' del ' + Convert(varchar, V.DataPartenzaPianificata, 103) + IsNull(' - ' + VX.MiocPrenotazione, '')
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			'Spedizione ' + Convert(varchar, S.UniBol) + ', Ordine ' + Convert(varchar, S.NumeroOrdine) + ', Ddt ' + Convert(varchar, S.NumeroBolla)
		Else Null
	End DescrizioneServizio,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.DataPartenzaPianificata
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			VS.DataPartenzaPianificata
		Else Null
	End DataPartenza,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.PCSPartenza
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.PCSPartenza
		Else Null
	End PCSPartenza,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.RagioneSociale + ' (' + PCSV.Localita + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_RagSoc + ' (' + S.PCSDestinazione_Localita + ')'
		Else Null
	End PCSArrivo,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Cap
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Cap
		Else Null
	End PCSArrivoCap,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Provincia
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Provincia
		Else Null
	End PCSArrivoProvincia,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			PCSV.Nazione
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			s.PCSDestinazione_Nazione
		Else Null
	End PCSArrivoNazione,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			ZV.Descrizione + ' (' + V.ZonaArrivo + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			ZS.Descrizione + ' (' + S.ZonaArrivoTariffaPassiva + ')'
		Else Null
	End ZonaArrivo,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			ZMV.Descrizione + ' (' + ZV.CodiceZonaMacro + ')'
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			ZMS.Descrizione + ' (' + ZS.CodiceZonaMacro + ')'
		Else Null
	End MacroZonaArrivo,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			dbo.CST_SpedizioniViaggio(V.IdViaggio)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			Null
		Else Null
	End ElencoSpedizioni,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			VT.Colli
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.Colli
		Else Null
	End Colli,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			VT.Pallet
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.Pallet
		Else Null
	End Pallet,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			VT.Peso
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.Peso
		Else Null
	End Peso,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			VT.Volume
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.Volume
		Else Null
	End Volume,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			V.IdViaggio
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			S.IdViaggio
		Else Null
	End Viaggio,
	Voci.FlagNolo,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			dbo.CST_NOCViaggio(Det.IdViaggio)
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			dbo.CST_NOCViaggioSpedizione(Det.Unibol)
		Else Null
	End NumeroOrdineCliente,
	Case
		When (Det.TipoRiga = 'V') Or (Det.IdViaggio Is Not Null) Then
			isnull(V.FillerAlfa9, '')
		When (Det.TipoRiga = 'S') Or (Det.UniBol Is Not Null) Then
			isnull(V.FillerAlfa9, '')
		Else Null
	End SubVettore
	
From Fatture_Passive_Dettaglio Det
Left Join Spedizioni S On S.UniBol = Det.Unibol
Left Join Viaggi V On V.IdViaggio = Det.IdViaggio
Left Join Viaggi VS On VS.IdViaggio = S.IdViaggio
Left Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
Left Join Zone ZS On ZS.Codice = S.ZonaArrivoTariffaPassiva
Left Join Zone ZV On ZV.Codice = V.ZonaArrivo
Left Join ZoneMacro ZMS On ZMS.Codice = ZS.CodiceZonaMacro
Left Join ZoneMacro ZMV On ZMV.Codice = ZV.CodiceZonaMacro
Left Join PCS PCSV On PCSV.Codice = v.PCSArrivo
Left Join CST_Viaggi VX On VX.Idviaggio = V.IdViaggio
Left Join Voci On Voci.Codice = Det.Voce;


-- dbo.CST_GRD_FAT_FattPassive_Dett_20180503 source

ALTER View [dbo].[CST_GRD_FAT_FattPassive_Dett_20180503]
As
Select Det.*,
	Case Det.TipoRiga
		When 'V' Then
			dbo.CST_DDTViaggio(Det.IdViaggio)
		When 'S' Then
			dbo.CST_DDTViaggioSpedizione(Det.Unibol)
		Else Null
	End NumeroBolla,
	VX.MiocPrenotazione Prenotazione,
	Case Det.TipoRiga
		When 'V' Then
			'Viaggio ' + Convert(varchar, V.IdViaggio) + ' del ' + Convert(varchar, V.DataPartenzaPianificata, 103) + IsNull(' - ' + VX.MiocPrenotazione, '')
		When 'S' Then
			'Spedizione ' + Convert(varchar, S.UniBol) + ', Ordine ' + Convert(varchar, S.NumeroOrdine) + ', Ddt ' + Convert(varchar, S.NumeroBolla)
		Else Null
	End DescrizioneServizio,
	Case Det.TipoRiga
		When 'V' Then
			V.DataPartenzaPianificata
		When 'S' Then
			VS.DataPartenzaPianificata
		Else Null
	End DataPartenza,
	Case Det.TipoRiga
		When 'V' Then
			V.PCSPartenza
		When 'S' Then
			S.PCSPartenza
		Else Null
	End PCSPartenza,
	Case Det.TipoRiga
		When 'V' Then
			PCSV.RagioneSociale + ' (' + PCSV.Localita + ')'
		When 'S' Then
			s.PCSDestinazione_RagSoc + ' (' + S.PCSDestinazione_Localita + ')'
		Else Null
	End PCSArrivo,
	Case Det.TipoRiga
		When 'V' Then
			PCSV.Cap
		When 'S' Then
			s.PCSDestinazione_Cap
		Else Null
	End PCSArrivoCap,
	Case Det.TipoRiga
		When 'V' Then
			PCSV.Provincia
		When 'S' Then
			s.PCSDestinazione_Provincia
		Else Null
	End PCSArrivoProvincia,
	Case Det.TipoRiga
		When 'V' Then
			PCSV.Nazione
		When 'S' Then
			s.PCSDestinazione_Nazione
		Else Null
	End PCSArrivoNazione,
	Case Det.TipoRiga
		When 'V' Then
			ZV.Descrizione + ' (' + V.ZonaArrivo + ')'
		When 'S' Then
			ZS.Descrizione + ' (' + S.ZonaArrivoTariffaPassiva + ')'
		Else Null
	End ZonaArrivo,
	Case Det.TipoRiga
		When 'V' Then
			ZMV.Descrizione + ' (' + ZV.CodiceZonaMacro + ')'
		When 'S' Then
			ZMS.Descrizione + ' (' + ZS.CodiceZonaMacro + ')'
		Else Null
	End MacroZonaArrivo,
	Case Det.TipoRiga
		When 'V' Then
			dbo.CST_SpedizioniViaggio(V.IdViaggio)
		When 'S' Then
			Null
		Else Null
	End ElencoSpedizioni,
	Case Det.TipoRiga
		When 'V' Then
			VT.Colli
		When 'S' Then
			S.Colli
		Else Null
	End Colli,
	Case Det.TipoRiga
		When 'V' Then
			VT.Pallet
		When 'S' Then
			S.Pallet
		Else Null
	End Pallet,
	Case Det.TipoRiga
		When 'V' Then
			VT.Peso
		When 'S' Then
			S.Peso
		Else Null
	End Peso,
	Case Det.TipoRiga
		When 'V' Then
			VT.Volume
		When 'S' Then
			S.Volume
		Else Null
	End Volume,
	Case Det.TipoRiga
		When 'V' Then
			V.IdViaggio
		When 'S' Then
			S.IdViaggio
		Else Null
	End Viaggio,
	Voci.FlagNolo
From Fatture_Passive_Dettaglio Det
Left Join Spedizioni S On S.UniBol = Det.Unibol
Left Join Viaggi V On V.IdViaggio = Det.IdViaggio
Left Join Viaggi VS On VS.IdViaggio = S.IdViaggio
Left Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
Left Join Zone ZS On ZS.Codice = S.ZonaArrivoTariffaPassiva
Left Join Zone ZV On ZV.Codice = V.ZonaArrivo
Left Join ZoneMacro ZMS On ZMS.Codice = ZS.CodiceZonaMacro
Left Join ZoneMacro ZMV On ZMV.Codice = ZV.CodiceZonaMacro
Left Join PCS PCSV On PCSV.Codice = v.PCSArrivo
Left Join CST_Viaggi VX On VX.Idviaggio = V.IdViaggio
Left Join Voci On Voci.Codice = Det.Voce;


-- dbo.CST_GRD_FAT_FattPassive_Testata source

ALTER VIEW [dbo].[CST_GRD_FAT_FattPassive_Testata]
AS
SELECT  F.IdFattura, 
		TipoDocumento,		
		Sezionale, 
		S.Descrizione as SezionaleDescrizione,
		Numero, 
		Data, 
		Trasportatore, 
		T.RagioneSociale,
		F.TipoPagamento,
		CP.Descrizione as TipoPagamentoDescrizione,  
		DataScadenza1, 
		DataScadenza2, 
		DataScadenza3, 
		Contabilizzata, 
        DataContabilizzazione, 
        ErroreContabilizzazione,
        FT.Imponibile,
        FT.Imposta,
        FT.Totale
FROM    Fatture_Passive_Testata F
		INNER JOIN Sezionali S ON S.Codice = F.Sezionale
		INNER JOIN Trasportatori T ON T.Codice = F.Trasportatore
		INNER JOIN CodiciPagamento CP ON CP.Codice = F.TipoPagamento
		Join CST_FatturePassive_Totali FT On FT.IdFattura = F.IdFattura;


