-- dbo.CST_GRD_VIAGGI_CHIUSI_EXPORT_XML source

/*
Vista per l'esportazione dei viaggi chiusi: CST_GRD_VIAGGI_CHIUSI_EXPORT_XML
I campi che iniziano per DNE_ (do not export) non vengono esportati
Il parametro CST.VIA.CHI.EXPXML.FILEPATH indica il percorso di esportazione del file ("\\Clogicway\prenotazioni")
Il parametro CST.VIA.CHI.EXPXML.FILENAME indica il nome del file: l'asterisco viene sostituito da IdViaggio & "_" & Now.ToString("yyyyMMddHHmmssfff")
*/


ALTER VIEW CST_GRD_VIAGGI_CHIUSI_EXPORT_XML AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE WHEN TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_Ritiro = 'S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT JOIN TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )

SELECT V.IdViaggio,
		DataPartenzaPianificata,
		MM.Targa AS MotriceDescrizione,
		MR.Targa AS Rimorchio1Descrizione,
		MC.Targa AS Contenitore1Descrizione,
		T.RagioneSociale AS VettoreDescrizione,
		TS.Descrizione AS TipoSpedizioneDescrizione,
		S.PCSDestinazione_RagSoc + 
		' (' + S.PCSDestinazione_Provincia + ')' + 
		IsNull('; TP:' + COR.RagioneSociale, '') + 
		' [' + Convert(Varchar, S.NumeroOrdine) + '-' + Convert(Varchar, S.NumeroBolla) + '] *** ' + '<br />' AS DNE_Spedizione,
		S.PCSDestinazione_RagSoc AS SpedizioneDestinazioneRagioneSociale,
		S.PCSDestinazione_Provincia AS SpedizioneDestinazioneProvincia,
		IsNull(Cor.RagioneSociale, '') AS SpedizioneTransitPoint,
		S.NumeroOrdine AS SpedizioneNumeroOrdine,
		S.NumeroBolla AS SpedizioneNumeroBolla,
		S.PCSPartenza,
		PcsA.RagioneSociale + IsNull(' (' + PcsA.Provincia + ')', '') Arrivo,
		ISNULL(S.Peso * S.Segno, 0) AS Peso,
		ISNULL(S.Volume * S.Segno, 0) AS Volume,
		ISNULL(S.Colli * S.Segno, 0) AS Colli,
		ISNULL(S.Pallet * S.Segno, 0) AS Pallet
FROM 
	Viaggi V 
	INNER JOIN CTE_Spedizioni S ON S.IdViaggio = V.IdViaggio 
	LEFT JOIN Corrispondenti COR On S.Corrispondente = COR.Codice
	LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
	LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato 
	LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato 
	LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
	LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
	Left Join PCS PcsA On PcsA.Codice = V.PCSArrivo
	
WHERE	
	V.STATO = 20;


-- dbo.CST_GRD_VOCI_CENTRIDICOSTO source

ALTER VIEW [dbo].[CST_GRD_VOCI_CENTRIDICOSTO] 
AS
SELECT	TipoSpedizione,
		TS.DESCRIZIONE AS TipoSpedizioneDescrizione,
		TipoMerce,
		TM.DESCRIZIONE AS TipoMerceDescrizione,
		PCSPartenza,
		PP.RagioneSociale AS PCSPartenzaRagioneSociale,
		PCSArrivo,
		PA.RagioneSociale AS PCSArrivoRagioneSociale,
		Voce,
		V.DESCRIZIONE AS VoceDescrizione,
		CentroDiCosto,
		Convert(Varchar, CentroDiCosto) + ' - ' + C.DESCRIZIONE AS CentroDiCostoDescrizione,
		ClasseCoge as VoceDiCosto
FROM	CST_VOCI_CENTRIDICOSTO VC
		INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = VC.TIPOSPEDIZIONE
		INNER JOIN TIPIMERCE TM ON TM.CODICE = VC.TIPOMERCE
		INNER JOIN PCS PP ON PP.CODICE = VC.PCSPARTENZA
		INNER JOIN PCS PA ON PA.CODICE = VC.PCSARRIVO
		INNER JOIN VOCI V ON V.CODICE = VC.VOCE
		INNER JOIN CST_CENTRIDICOSTO C ON C.CODICE = VC.CENTRODICOSTO;


-- dbo.CST_GRD_ViaggiXStato source

ALTER View CST_GRD_ViaggiXStato
As
Select V.PCSPartenza, P.RagioneSociale,
	Sum(Case When V.Stato = '10' Then 1 Else 0 End) ViaggiAperti,
	Sum(Case When V.Stato = '20' Then 1 Else 0 End) ViaggiChiusi,
	Sum(Case When V.Stato = '30' Then 1 Else 0 End) ViaggiPartiti,
	Sum(Case When V.Stato = '40' Then 1 Else 0 End) ViaggiTerminati,
	Sum(Case When V.Stato = '50' Then 1 Else 0 End) ViaggiCertificati,
	Sum(Case When V.IdFatturaPassiva Is Not Null Then 1 Else 0 End) ViaggiPrefatturati,
	Sum(Case When V.IdFatturaPassiva Is Null Then 1 Else 0 End) ViaggiNonPrefatturati
From Viaggi V
Left Join PCS P On P.Codice = V.PCSPartenza
--Where Stato In (10, 20)
Group By V.PCSPartenza, P.RagioneSociale;


