-- dbo.CST_ImpTariffe source

ALTER View CST_ImpTariffe As
Select Con.Codice Contratto, IdTestata, Tmp.RagioneSociale,
	Case
		When IsNull(Piattaforma, '') <> '' Then 'SPEDIZ'
		Else 'VIAGGIO'
	End TipoDocumento,
	Case 
		When Tmp.Piattaforma <> '' Then '*ALL'
		When Tmp.TipoMezzo = 'FH22' Then 'FH22' -- Solo TOPRAIL
		When Tmp.TipoMezzo = 'FRILS' Then 'FRILS' -- Solo TOPRAIL	*** TOGLIERE ***
		When Tmp.TipoMezzo = 'C20BOX' Then 'CONT20'
		When Tmp.TipoMezzo = 'C40BOX' Then 'CON40B'
		When Tmp.TipoMezzo = 'GENERICO' Then '*ALL'
		When Tmp.TipoMezzo = 'FHABINS' Then 'FHABIN' -- Solo TOPRAIL
		When Tmp.TipoMezzo = 'C40PWHC' Then 'CON40W'
		When Tmp.TipoMezzo = 'GMOTRICE' Then 'MOT'
		When Tmp.TipoMezzo = 'FLAAIS' Then 'FLAAIS' -- Solo TOPRAIL
		When Tmp.TipoMezzo = 'FG20' Then 'FG20' -- Solo TOPRAIL		*** TOGLIERE ***
		When Tmp.TipoMezzo = 'GBILICO' Then 'BIL'
		When Tmp.TipoMezzo = 'GMAXVOLUME' Then 'MAX'
		When Tmp.TipoMezzo = 'FG1' Then 'VAGFG1' --					*** TOGLIERE ***
		When Tmp.TipoMezzo = 'VAGONE' Then 'VAGONE'
		When Tmp.TipoMezzo = 'C40HC' Then 'CONT40'
	End TipoMezzo,
	Case 
		When Tmp.Piattaforma = 'CAB' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-BO' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-CE' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-GE' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-PV' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-TO' Then '*ALL'
		When Tmp.Piattaforma = 'CAB-VE' Then '*ALL'
		When Tmp.Piattaforma = 'CHIGGIATO' Then '*ALL'
		When Tmp.Piattaforma = 'I03' Then '*ALL'
		When Tmp.Piattaforma = 'I99' Then '*ALL'
		When Tmp.Piattaforma = 'IBA' Then '*ALL'
		When Tmp.Piattaforma = 'ICS' Then '*ALL'
		When Tmp.Piattaforma = 'ICT' Then '*ALL'
		When Tmp.Piattaforma = 'INA' Then '*ALL'
		When Tmp.Piattaforma = 'IOR' Then '*ALL'
		When Tmp.Piattaforma = 'IPA' Then '*ALL'
		When Tmp.Piattaforma = 'IPD' Then '*ALL'
		When Tmp.Piattaforma = 'IPE' Then '*ALL'
		When Tmp.Piattaforma = 'ISA' Then '*ALL'
		When Tmp.Piattaforma = 'TOP RAIL' Then '*ALL'
		When Tmp.Magazzino = '' Then '*ALL'
		Else Tmp.Magazzino
	End PCSPartenza,
	Case Tmp.TipoDestinazione
		When '01' -- PCS Arrivo
			Then '*ALL'
		When '02' -- Cap
			Then '*ALL'
		When '03' -- AreaCap (prime 2 cifre ZIP)
			Then Case
				When Nazione = 'IT' Then 
					Case Provincia
						When 'FO' Then 'FC'
						When 'PS' Then 'PU'
						Else Provincia
					End
				Else Replace(Case Nazione When 'EL' Then 'GR' Else Nazione End + Right(Convert(Varchar, '00') + Convert(Varchar, AreaCap), 2), ' ', '')
			End
		When '04' -- Zona CAP (raggruppamento) --> solo 2 tariffe
			Then '*ALL'
		When '05' -- Città
			Then '*ALL'
		When '06' -- Provincia
			Then
				Case Provincia
					When 'FO' Then 'FC'
					When 'PS' Then 'PU'
					Else Provincia
				End
		When '07' -- Nazione
			Then Nazione
		When '08' -- Piattaforma
			Then '*ALL'
	End MacroZonaArrivo,
	Case Tmp.TipoDestinazione
		When '01' -- PCS Arrivo
			Then '*ALL'
		When '02' -- Cap
			Then Case
				When Nazione = 'IT' Then 'I' + Tmp.Cap
				Else (Select Zona 
					From TEMP_Tariffe_Cap
					Where Cap = Tmp.Cap 
						And Nazione = Tmp.Nazione)
			End
		When '03' -- AreaCap (prime 2 cifre ZIP)
			Then '*ALL' -- 20180115 SPOSTATO SU MACROZONA
		When '04' -- Zona CAP (raggruppamento) --> ???
			Then '???'
		When '05' -- Città --???
			Then (Select Zona 
					From TEMP_Tariffe_Localita 
					Where Localita = Tmp.Citta 
						And Provincia = Tmp.Provincia 
						And Cap = Tmp.Cap 
						And Nazione = Tmp.Nazione)
		When '06' -- Provincia
			Then '*ALL' -- 20180115 SPOSTATO SU MACROZONA
		When '07' -- Nazione
			Then '*ALL'
		When '08' -- Piattaforma
			Then '*ALL'
	End ZonaArrivo,
	Case Tmp.TipoDestinazione
		When '01' -- PCS Arrivo
			Then Tmp.Destinazione
		When '02' -- Cap
			Then '*ALL'
		When '03' -- AreaCap (prime 2 cifre ZIP)
			Then '*ALL'
		When '04' -- Zona CAP (raggruppamento) --> solo 2 tariffe
			Then '*ALL'
		When '05' -- Città
			Then '*ALL'
		When '06' -- Provincia
			Then '*ALL'
		When '07' -- Nazione
			Then '*ALL'
		When '08' -- Piattaforma
			Then Piattaforma2
	End PCSArrivo,
	Case Tmp.BaseCalcolo
		When 'K' Then 'PALLET'
		When 'V' Then 'VOLUME'
		Else 'FORFAIT'
	End CampoCalcolo,
	ROW_NUMBER() Over (Order By IdTestata, SogliaQta) IdFascia,
	Case
		When SogliaQta = 1 
			And (Select IsNull(Max(SogliaQta), 1)
				From TEMP_Tariffe
				Where SogliaQta < Tmp.SogliaQta
					And IdTestata = Tmp.IdTestata) = 1 Then 0 
		Else SogliaQta End FasciaInferiore,
	(Select IsNull(Min(SogliaQta), 999999999)
	From TEMP_Tariffe
	Where SogliaQta > Tmp.SogliaQta
		And IdTestata = Tmp.IdTestata) FasciaSuperiore,
	Case 
		When (Tmp.TipoTariffa2 = 'F' Or (RTrim(Tmp.TipoTariffa2) In ('', '-') And RTrim(IsNull(Tmp.BaseCalcolo, '')) In ('', '-'))) And Tmp.Tariffa > 0 Then Tmp.Tariffa
		Else 0
	End ImportoFisso,
	Case 
		When Tmp.TipoTariffa2 = 'F' Or (RTrim(Tmp.TipoTariffa2) In ('', '-') And RTrim(IsNull(Tmp.BaseCalcolo, '')) In ('', '-')) And Tmp.Tariffa > 0 Then 0
		Else Tmp.Tariffa
	End ImportoVariabile,
	Tmp.ConsegnaExtra1,
	Tmp.ConsegnaExtra2, 
	Tmp.TipoDestinazione, Tmp.Soglia, Tmp.TipoTariffa, Tmp.TipoTariffa2, Tmp.BaseCalcolo
From TEMP_Tariffe Tmp
Left Join TariffeContratti Con On Tmp.Vettore = Con.Trasportatore
Where Tmp.Magazzino Not In ('E', 'H', 'O', 'V')
	And Tmp.Piattaforma Not In ('I99', 'TOP RAIL')
	And Tmp.Piattaforma2 Not In ('I99', 'TOP RAIL')
	And Tmp.TipoMezzo Not In ('FG1', 'FG20', 'FRILS')
	And Con.Codice Is Not Null
	And Tmp.TipoDestinazione <> '04' -- SOLO 2 TARIFFE;


