-- dbo.CST_RPT_FATT_PAS_01 source

ALTER VIEW [dbo].[CST_RPT_FATT_PAS_01] AS
SELECT	T.IDFATTURA,
		T.NUMERO,
		T.DATA,
		T.DataScadenza1,
		T.DataScadenza2,
		T.DataScadenza3,
		TD.DESCRIZIONE AS TIPODOCUMENTO,
		CP.CODICE AS CODICEPAGAMENTO,
		CP.DESCRIZIONE AS TIPOPAGAMENTO,
		CP.GIORNI1 AS SCADENZE1,
		CP.GIORNI2 AS SCADENZE2,
		CP.GIORNI3 AS SCADENZE3,
		TIA.INFO AS RIFERIMENTOBANCARIO,
		'LUCART S.P.A.' AS SOCIETARGS,
		'VIA CIARPI, 77' AS SOCIETAIND,
		'PORCARI' AS SOCIETALOC,
		'55016' AS SOCIETACAP,
		'LU' AS SOCIETAPRV,
		'' AS SOCIETAPIVA,
		'' AS SOCIETACODFIS,		
		TR.RAGIONESOCIALE AS SOGGETTORGS,
		TR.INDIRIZZO AS SOGGETTOIND,
		ISNULL(TR.LOCALITA,'') AS SOGGETTOLOC,
		TR.CAP AS SOGGETTOCAP,
		ISNULL(TR.PROVINCIA,'') AS SOGGETTOPRV,
		TR.PARTITAIVA AS SOGGETTOPIVA,
		TR.CODICEFISCALE AS SOGGETTOCODFIS,		
		ISNULL(TC.DESCRIZIONE,TR.RAGIONESOCIALE) AS INVIARGS,
		ISNULL(TC.INDIRIZZO,TR.INDIRIZZO) AS INVIAIND,
		ISNULL(ISNULL(TC.LOCALITA,TR.LOCALITA),'') AS INVIALOC,
		ISNULL(TC.CAP,TR.CAP) AS INVIACAP,
		ISNULL(ISNULL(TC.PROVINCIA,TR.PROVINCIA),'') AS INVIAPRV,
		D.TIPORIGA,		
		D.RIGA,
		ISNULL(D.IDVIAGGIO,D.UNIBOL) AS RIFINTERNO,		
		CASE WHEN D.UNIBOL IS NOT NULL THEN ISNULL(S.DATACOMPETENZAATTIVA,ISNULL(S.DATABOLLA,S.DATINS))
			 WHEN D.IDVIAGGIO IS NOT NULL THEN ISNULL(VI.DATAPARTENZAEFFETTIVA,VI.DATAPARTENZAPIANIFICATA)			 
			 ELSE NULL END  AS DATADETTAGLIO,
		CASE WHEN D.IdViaggio Is Not Null THEN 'DDT: ' + dbo.CST_DDTViaggio(D.IdViaggio) 
			 WHEN D.UniBol Is Not Null THEN 'Riconsegna da deposito DDT:' + Convert(varchar, S.NumeroBolla)
			 WHEN D.TIPORIGA ='C' THEN 'CONTRASSEGNO' 
			 WHEN D.TIPORIGA = 'N' THEN 'NOTA' 		 
			 ELSE '' END 
		AS DESCRIZIONEDETTAGLIO,
		V.DESCRIZIONE AS VOCE,
		TCC.UnitaDiMisura AS UM,
		QUANTITATASSATA AS QUANTITADETT,
		IMPORTOUNITARIO AS UNITARIODETT,
		IMPORTOARROTONDATO AS IMPORTODETT,
		CI.CODICE AS CODICEIVADETT,
		CI.DESCRIZIONE AS DESCRIZIONEIVADETT,
		(SELECT ISNULL(SUM(IMPONIBILE + IMPOSTA),0) FROM FATTURE_PASSIVE_IVA WHERE FATTURE_PASSIVE_IVA.IDFATTURA = T.IDFATTURA) AS TOTALEDOCUMENTO
FROM	FATTURE_PASSIVE_TESTATA T 
		INNER JOIN FATTURE_PASSIVE_DETTAGLIO D ON D.IDFATTURA = T.IDFATTURA
		INNER JOIN TRASPORTATORI TR ON TR.CODICE = T.TRASPORTATORE
		LEFT JOIN 
		(
		SELECT TIA2.*, IA.Info 
		FROM TRASPORTATORIINFOAGGIUNTIVE TIA2 
		INNER JOIN INFOAGGIUNTIVEANAGRAFICHE IA ON IA.ID = TIA2.IDINFO AND IA.TIPOINFO = 'RIFBAN'
		WHERE IA.TIPOINFO = 'RIFBAN'
		) TIA ON TIA.TRASPORTATORE = T.TRASPORTATORE		
		INNER JOIN CODICIPAGAMENTO CP ON CP.CODICE = T.TIPOPAGAMENTO
		INNER JOIN VW_FATTUREPASSIVE_TIPIDOC TD ON TD.CODICE = T.TIPODOCUMENTO
		LEFT JOIN 
		(
		SELECT  CO.*, TC2.Trasportatore 
		FROM TRASPORTATORICONTATTI TC2 
		INNER JOIN CONTATTI CO ON CO.ID = TC2.IDCONTATTO AND TIPOCONTATTO = 'INVFAT'
		WHERE TIPOCONTATTO = 'INVFAT'
		) TC ON TC.TRASPORTATORE = T.TRASPORTATORE		
		LEFT JOIN VOCI V ON V.CODICE = D.VOCE
		LEFT JOIN TABCAMPICALCOLO TCC ON TCC.NOMECAMPO = D.CAMPOCALCOLO
		LEFT JOIN CODICIIVA CI ON CI.CODICE = D.CODICEIVA 
		LEFT JOIN SPEDIZIONI S ON S.UNIBOL = D.UNIBOL
		LEFT JOIN VIAGGI VI ON VI.IDVIAGGIO = D.IDVIAGGIO;


-- dbo.CST_SPEDCORR_NO_PREFATT source

ALTER VIEW [dbo].[CST_SPEDCORR_NO_PREFATT] as 
select sc.*, v.descrizione
from spedizioni s inner join spedizioni_costi sc on (s.unibol = sc.unibol)
inner join voci v on (sc.voce = v.codice)
where s.idfatturapassiva is null
and dataorapartenzaeffettiva >= GETDATE() - 70
--and dataorapartenzaeffettiva >= '20180501';


-- dbo.CST_SPEDIZIONI_VIAGGI_PIATTAFORMA source

ALTER VIEW CST_SPEDIZIONI_VIAGGI_PIATTAFORMA
AS
SELECT S.* 
FROM Spedizioni S 
INNER JOIN Corrispondenti C ON C.CODICE = S.PCSPARTENZA 
WHERE Stato in (10,20);


-- dbo.CST_SpedizioniCostoTotale source

ALTER View CST_SpedizioniCostoTotale
As
Select Unibol, Sum(ImportoArrotondato) ImportoTotale, Sum(Case When Voci.FlagNolo = 'S' Then ImportoArrotondato Else 0 End) ImportoNolo
From Spedizioni_Costi
Join Voci On Voci.Codice = Spedizioni_Costi.Voce
Group By Unibol;


-- dbo.CST_SpedizioniViaggio1 source

ALTER VIEW CST_SpedizioniViaggio1
As
select s.IdViaggio, CAST(v.DataPartenzaEffettiva as date) DataPartenza, t.RagioneSociale, s.NumeroOrdine, s.PCSDestinazione, s.PCSDestinazione_RagSoc, s.PCSDestinazione_Indirizzo, s.PCSDestinazione_Localita, s.PCSDestinazione_Cap, s.PCSDestinazione_Provincia,s.Pallet as Colonne, s.Peso as Peso, s.Volume as Volume, s.NumeroBolla as DDT, s.CampoCalcolo1 as Pallet
from DELSYLOG91_LUCART.dbo.Spedizioni s 
left join DELSYLOG91_LUCART.dbo.viaggi v on v.IdViaggio=s.IdViaggio 
left JOIN DELSYLOG91_LUCART.dbo.Trasportatori t on v.vettore= t.CodiceContabile
where YEAR(v.DataPartenzaEffettiva) = YEAR(getdate());


-- dbo.CST_SpedizioniVoci_CentriDiCosto source

ALTER View CST_SpedizioniVoci_CentriDiCosto
As
Select S.UniBol, S.IdViaggio, S.TipoSpedizione, S.PCSPartenza, S.PCSDestinazione, VC.Voce, V.IdFatturaPassiva,
	(Select Top 1 CentroDiCosto
	From CST_VW_Voci_CentroDiCosto_Peso 
	Where TipoSpedizione IN ('*ALL', S.TipoSpedizione) 
		AND TipoMerce IN ('*ALL', S.TipoMerce) 
		AND PCSPartenza IN ('*ALL', S.PCSPartenza) 
		AND PCSArrivo IN ('*ALL', S.PCSDestinazione) 
		AND Voce IN ('*ALL', VC.Voce) 
	Order By Peso Desc) CentroDiCosto,
	CS.CentroDiCosto CentroDiCosto_JDE
From Spedizioni S
Join CST_Spedizioni CS On CS.Unibol = S.UniBol
Join Viaggi V On S.IdViaggio = V.IdViaggio
Join Viaggi_Costi VC On VC.IdViaggio = V.IdViaggio
Union
Select S.UniBol, S.IdViaggio, S.TipoSpedizione, S.PCSPartenza, S.PCSDestinazione, SC.Voce, S.IdFatturaPassiva,
	(Select Top 1 CentroDiCosto
	From CST_VW_Voci_CentroDiCosto_Peso 
	Where TipoSpedizione IN ('*ALL', S.TipoSpedizione) 
		AND TipoMerce IN ('*ALL', S.TipoMerce) 
		AND PCSPartenza IN ('*ALL', S.PCSPartenza) 
		AND PCSArrivo IN ('*ALL', S.PCSDestinazione) 
		AND Voce IN ('*ALL', SC.Voce) 
	Order By Peso Desc) CentroDiCosto,
	CS.CentroDiCosto CentroDiCosto_JDE
From Spedizioni S
Join CST_Spedizioni CS On CS.Unibol = S.UniBol
Join Spedizioni_Costi SC On SC.Unibol = S.UniBol;


-- dbo.CST_Tariffe_ConfrontoSpedizioni source

ALTER View CST_Tariffe_ConfrontoSpedizioni
As
Select Tmp.ViaggioPiattaforma VP, Tmp.Viaggio JDE_Id, Spd.UniBol DSY_Id, Tmp.DataViaggio JDE_Data, Vg.DataPartenzaPianificata DSY_Data, 
	Tmp.Vettore JDE_Vettore, Tmp.RagioneSociale JDE_RagSoc, Spd.Corrispondente DSY_Vettore, Tr.RagioneSociale DSY_RagSoc, 
	Tmp.TipoMezzo JDE_Mezzo, Vg.MotricePianificata DSY_Mezzo, Tmp.CostoTotale /*+ IsNull(Tmp.TariffaConsegna2, 0) + IsNull(Tmp.TariffaConsegna3, 0)*/ JDE_Costo, IsNull(SC.ImportoTotale, 0) DSY_Costo, 
	Abs(IsNull(Tmp.CostoTotale, 0) /*+ IsNull(Tmp.TariffaConsegna2, 0) + IsNull(Tmp.TariffaConsegna3, 0)*/ - IsNull(SC.ImportoTotale, 0)) Diff,
	Tmp.PesoLordo JDE_Peso, Spd.Peso DSY_Peso, Tmp.NumeroColonne JDE_Plt, Spd.Pallet DSY_Plt, Tmp.VolumeUnitario JDE_Volume, Spd.Volume DSY_Volume
From TEMP_ViaggiValori Tmp
Join Spedizioni Spd On (Convert(varchar, Tmp.Ordine) + Tmp.TipoOrdine = Left(Spd.NumeroOrdine, 10))
Join Viaggi Vg On Spd.IdViaggio = Vg.IdViaggio
Join Corrispondenti Cor On Cor.Codice = Spd.Corrispondente
Join Trasportatori Tr On Tr.Codice = Cor.CodiceTrasportatore
Left Join CST_SpedizioniCostoTotale SC On SC.UniBol = Spd.UniBol
Where Tmp.ViaggioPiattaforma = 'Y';


-- dbo.CST_Tariffe_ConfrontoViaggi source

ALTER View CST_Tariffe_ConfrontoViaggi
As
Select Tmp.ViaggioPiattaforma VP, Tmp.Viaggio JDE_Id, Vg.IdViaggio DSY_Id, Tmp.DataViaggio JDE_Data, Vg.DataPartenzaPianificata DSY_Data, 
	Tmp.Vettore JDE_Vettore, Tmp.RagioneSociale JDE_RagSoc, Vg.Vettore DSY_Vettore, Tr.RagioneSociale DSY_RagSoc, Tmp.TipoMezzo JDE_Mezzo_Orig,
	Case Tmp.TipoMezzo
		When 'GENERICO' Then '*GEN*'
		When 'GBILICO' Then 'BIL33'
		When 'GMOTRICE' Then 'MOT23'
		When 'GMAXVOLUME' Then 'GMAX'
		When 'C40BOX' Then 'CONT40'
		When 'C40HC' Then 'CONTHC'
		When 'C40PWHC' Then 'CONTPW'
		When 'FH22' Then 'FH22'
		When 'FHABINS' Then 'FHABIN'
		When 'FLAAIS' Then 'FLAAIS'
		Else TipoMezzo
	End JDE_Mezzo, Vg.MotricePianificata DSY_Mezzo, Convert(Int, Tmp.CostoTotale) /*+ IsNull(Tmp.TariffaConsegna2, 0) + IsNull(Tmp.TariffaConsegna3, 0)*/ JDE_Costo, Convert(Int, IsNull(VC.ImportoTotale, 0)) DSY_Costo, 
	Abs(IsNull(Tmp.CostoTotale, 0) /*+ IsNull(Tmp.TariffaConsegna2, 0) + IsNull(Tmp.TariffaConsegna3, 0)*/ - IsNull(VC.ImportoTotale, 0)) Diff,
	Convert(Int, Tmp.PesoLordo) JDE_Peso, Convert(Int, VT.Peso) DSY_Peso, Tmp.NumeroColonne JDE_Plt, VT.Pallet DSY_Plt, Convert(Int, Tmp.VolumeUnitario) JDE_Volume, Convert(Int, VT.Volume) DSY_Volume
From TEMP_ViaggiValori_Gen Tmp
Join Spedizioni Spd On (Convert(varchar, Tmp.Ordine) + Tmp.TipoOrdine = Left(Spd.NumeroOrdine, 10))
Join Viaggi Vg On Vg.IdViaggio = Spd.IdViaggio
Join Trasportatori Tr On Tr.Codice = Vg.Vettore
Join CST_Viaggi_Totali VT On VT.IdViaggio = Vg.IdViaggio
Join CST_ViaggiCostoTotale VC On VC.IdViaggio = Vg.IdViaggio
Where Tmp.ViaggioPiattaforma = 'N';


-- dbo.CST_VIAGGIINEVADIBILI source

ALTER view CST_VIAGGIINEVADIBILI as 
select v.IdViaggio, o.TSNORD 
from Eslucart74..TSORD o inner join Viaggi v ON (o.spedizione = v.idviaggio)
where o.TSSTAT = 1000;


-- dbo.CST_VIAGGI_NO_PREFATT source

ALTER VIEW [dbo].[CST_VIAGGI_NO_PREFATT] as 
select vc.*, c.descrizione
from viaggi v inner join viaggi_costi vc on (v.idviaggio = vc.idviaggio)
inner join voci c on (vc.voce = c.codice)
where v.idfatturapassiva is null 
and datapartenzaeffettiva >= GETDATE() - 70
--and datapartenzaeffettiva >= '20180501';


-- dbo.CST_VW_Altezza_Max_Viaggio source

-- dbo.CST_VW_Altezza_Max_Viaggio source
ALTER   VIEW [dbo].[CST_VW_Altezza_Max_Viaggio] AS
SELECT 
    FORMAT(
        MAX(
            CASE
                WHEN UPPER(ISNULL(articoli.Art_LUC_Sovrapponibile, 'N')) IN ('S','Y') 
                     AND ISNULL(articoli.Art_LUC_Altezza, 0) <= 150
                    THEN ISNULL(articoli.Art_LUC_Altezza, 0) * 2
                ELSE ISNULL(articoli.Art_LUC_Altezza, 0)
            END
        ) / 100.0,  -- conversione da cm a metri
        'N2',
        'it-IT'
    ) AS AltMaxMezzo,
    spedizioni.IdViaggio AS ViaggioId
FROM 
    eslucart74..tsord 
    INNER JOIN eslucart74..rgord ON ordtes_skid = OrdRig_Skid_Ordine 
    INNER JOIN eslucart74..articoli ON art_skid = OrdRig_Skid_Articolo 
    INNER JOIN spedizioni ON NumeroOrdine = Tsnord 
    INNER JOIN viaggi ON viaggi.IdViaggio = spedizioni.IdViaggio 
WHERE 
    spedizioni.Stato <> '99'
GROUP BY 
    spedizioni.IdViaggio;


