-- dbo.CST_VW_Altezza_Max_Viaggio_BOB source

ALTER VIEW [dbo].[CST_VW_Altezza_Max_Viaggio_BOB] as
select max(isnull(art_luc_altezza, 0)) AltMaxMezzo, spedizioni.IdViaggio ViaggioId
from eslucart74..HSTORDTESRX 
inner join eslucart74..HSTORDRIGRX on HOrdTes_Ordine=HOrdRig_Ordine 
inner join eslucart74..articoli on art_codice=HOrdRig_Articolo 
inner join spedizioni on NumeroOrdine = concat(HOrdTes_Ordine,'/',HOrdTes_NumeroVersione) inner join viaggi on viaggi.IdViaggio=Spedizioni.IdViaggio 
where spedizioni.Stato <> '99' --and Spedizioni.idviaggio='317808'
group by spedizioni.idviaggio;


