-- dbo.CST_VW_PIA_SPEDIZIONI_CANCELLARE source

ALTER VIEW [dbo].[CST_VW_PIA_SPEDIZIONI]
AS
SELECT UniBol,
          UnibolParent,
          UnibolMaster,
          ProgressivoConsegna,
          Barcode,
          Prebolla,
          TipoServizio,
          Cliente,
          C.RagioneSociale AS ClienteRagioneSociale,
          Mittente,
          M.RagioneSociale AS MittenteRagioneSociale2,
          MittenteRagioneSociale,
          NumeroBolla,
          DataBolla,
          NumeroOrdine,
          DataOrdine,
          NumeroOrdineCliente,
          DataOrdineCliente,
          TipoSpedizione,
          TS.Descrizione AS IipoSpedizioniDescrizione,
          TipoMerce,
          TM.Descrizione AS TipoMerceDescrizione,
          PCSPartenza,
          PCSPartenza_RagSoc,
          PCSPartenza_Indirizzo,
          PCSPartenza_Cap,
          PCSPartenza_Localita,
          PCSPartenza_Provincia,
          PCSPartenza_Nazione,
          PCSDestinazione,
          PCSDestinazione_RagSoc,
          PCSDestinazione_Indirizzo,
          PCSDestinazione_Cap,
          PCSDestinazione_Localita,
          PCSDestinazione_Provincia,
          PCSDestinazione_Nazione,
          S.ZonaSpedizione,
          Z.Descrizione AS ZonaSpedizioneDescrizione,
          DataConsegnaPrevista1,
          DataConsegnaPrevista2,
          DataConsegnaConcordata,
          OraConsegnaConcordata1,
          OraConsegnaConcordata2,
		  NoteConsegnaPrevista,
		  NoteConsegnaConcordata,
          DataRitiroPrevista1,
          DataRitiroPrevista2,
          OraRitiroConcordata1,
          OraRitiroConcordata2,
          Corrispondente,
          CO.RagioneSociale AS CorrispondenteRagioneSociale,
          Trasportatore,
          T.RagioneSociale AS TrasportatoreRagioneSociale,
          S.Peso,
          S.Colli,
          S.Pallet,
          S.Volume,
          S.CampoCalcolo1,
          S.CampoCalcolo2,
          S.CampoCalcolo3,
          S.CampoCalcolo4,
          S.CampoCalcolo5,
          S.CampoCalcolo6,
          S.CampoCalcolo7,
          S.CampoCalcolo8,
          S.CampoCalcolo9,
          S.CampoCalcolo10,
          Contrassegno,
          S.Note,
          DataCompetenzaAttiva,
          BatchId,
          DataSpedizione,
		  S.FillerAlfa1 BusinessUnit
     FROM SPEDIZIONI S INNER JOIN CLIENTI C ON C.CODICE = S.CLIENTE
          LEFT JOIN CLIENTI M ON M.CODICE = S.MITTENTE
          INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE
          LEFT JOIN CORRISPONDENTI CO ON CO.CODICE = S.CORRISPONDENTE
          LEFT JOIN TRASPORTATORI T ON T.CODICE = S.TRASPORTATORE
          INNER JOIN SPEDIZIONI_BATCH B ON B.ID = S.BATCHID
          INNER JOIN ZONESPEDIZIONE Z ON Z.CODICE = S.ZONASPEDIZIONE
    WHERE S.STATO = 20
      AND IDVIAGGIO IS NULL
      AND BATCHID IS NOT NULL
      AND B.STATO IN (10, 20, 25);


-- dbo.CST_VW_PIA_Zone_Spedizioni source

ALTER VIEW [dbo].[CST_VW_PIA_Zone_Spedizioni] 
AS
   SELECT s.unibol, unibolparent, unibolmaster, progressivoconsegna, barcode,
          prebolla, tiposervizio, cliente,
          c.ragionesociale AS clienteragionesociale, mittente,
          m.ragionesociale AS mittenteragionesociale2, mittenteragionesociale,
          numerobolla, databolla, 
		  --numeroordine, 
		  ISNULL(S.NUMEROORDINE + ' - ('+EsTes.TS_LUC_QUADRO+')',S.NUMEROORDINE) AS NUMEROORDINE,
		  dataordine,
          numeroordinecliente, dataordinecliente, tipospedizione,
          ts.descrizione AS iipospedizionidescrizione, tipomerce,
          tm.descrizione AS tipomercedescrizione, pcspartenza,
          pcspartenza_ragsoc, pcspartenza_indirizzo, pcspartenza_cap,
          pcspartenza_localita, pcspartenza_provincia, pcspartenza_nazione,
          pcsdestinazione, pcsdestinazione_ragsoc, pcsdestinazione_indirizzo,
          pcsdestinazione_cap, pcsdestinazione_localita,
          pcsdestinazione_provincia, pcsdestinazione_nazione,
          s.zonaspedizione, z.descrizione AS zonaspedizionedescrizione,
          dataconsegnaprevista1, dataconsegnaprevista2,
          dataconsegnaconcordata, oraconsegnaconcordata1,
          oraconsegnaconcordata2, dataritiroprevista1, dataritiroprevista2,
          oraritiroconcordata1, oraritiroconcordata2, corrispondente,
          co.ragionesociale AS corrispondenteragionesociale, trasportatore,
          t.ragionesociale AS trasportatoreragionesociale, s.peso, s.colli,
          s.pallet, s.volume, s.campocalcolo1, s.campocalcolo2,
          s.campocalcolo3, s.campocalcolo4, s.campocalcolo5, s.campocalcolo6,
          s.campocalcolo7, s.campocalcolo8, s.campocalcolo9, s.campocalcolo10,
          contrassegno, s.note, datacompetenzaattiva, batchid, dataspedizione,
          ISNULL (zm.codice, '*XXX*') AS macrozonaspedizione,
          ISNULL (zm.descrizione,
               'NON DEFINITA'
              ) AS macrozonaspedizionedescrizione,
		  s.FillerAlfa1 BusinessUnit,
		  s.NoteConsegnaPrevista,
		  s.NoteConsegnaConcordata,
		  CST_Sped.LinkPDF, 
		  CST_Sped.StatoEs,
		  s.FillerAlfa1
     FROM spedizioni s INNER JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN clienti m ON m.codice = s.mittente
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN corrispondenti co ON co.codice = s.corrispondente
          LEFT JOIN trasportatori t ON t.codice = s.trasportatore
          INNER JOIN zonespedizione z ON z.codice = s.zonaspedizione
          LEFT JOIN zonemacro zm ON zm.codice = z.codicezonamacro
		  Left Join CST_VW_Spedizioni CST_Sped On CST_Sped.UniBol = s.UniBol
		  Left Join CST_ES_TestateOrdine EsTes On EsTes.TSNORD = s.NumeroOrdine
    WHERE s.stato = 20 AND idviaggio IS NULL;


-- dbo.CST_VW_ResetStatoCamion source

ALTER VIEW [dbo].[CST_VW_ResetStatoCamion] AS
   SELECT IdViaggio, 
		  CASE WHEN V.PCSPartenza IN ('G', 'D','AD') THEN
		  '<a href="http://dtscartotecnica/schede/schedenam.exe/Avanza?IDViaggio=' + 
		  CAST(V.IdViaggio AS VARCHAR) +
