-- dbo.CST_VW_Spedizioni source

ALTER   VIEW [dbo].[CST_VW_Spedizioni] AS
   SELECT Unibol, 
		  CASE WHEN S.TipoServizio = 'CONSDP' Or 1=1 THEN
		  '<a href="../../pdfcdv/' + 
		  CAST(DATEPART(YYYY , DataOrdine) AS VARCHAR) + '-' +
		  SUBSTRING(NumeroOrdine, 9, 2) + '-' +
		  Cliente + '-' +
		  SUBSTRING(NumeroOrdine, 1, 8) +
		  '.pdf' + '" target="_blank">View</a>' ELSE NULL END LinkPDF,
		  TSSTAT StatoEs,
		  TSNORD NumeroOrdine
     FROM Spedizioni S INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
		  Left Join CST_ES_TestateOrdine EsTes On EsTes.TSNORD = s.NumeroOrdine;


-- dbo.CST_VW_VIAGGICUSTOM source

ALTER   VIEW [dbo].[CST_VW_VIAGGICUSTOM] as
select	c.IdViaggio, c.MiocPrenotazione, c.MiocRichiesta,
		V.TIPOMERCE ,
		V.PCSPartenza ,
		V.VETTORE ,
		IsNull(M.Marca, '*') as PrenotazioneMezzo,
-- 		IsNull(TM.ADR, '*') AS PrenotazioneMerce,
		Case
			When V.TipoMerce = 'BOB'
				Then '5'
			When V.PCSPartenza = 'D' And V.TipoMerce = 'PF'
				Then '4'
			When V.PCSPartenza = 'G' And V.TipoMerce = 'PF'
				Then '17'
			When V.PCSPartenza = 'A' And V.TipoMerce = 'PF'
				Then '4'
			When V.PCSPartenza = 'C' And V.TipoMerce = 'PF'
				Then '16'
			Else V.TipoMerce 
		End PrenotazioneMerce, 
		T.Codice AS PrenotazioneVettore,		
		Case PCSPartenza
			When 'P' Then '1'
			When 'D' Then '2'
			When 'G' Then '3'
			When 'A' Then '4'
			When 'C' Then '12'
			When 'AD' Then '2'
			Else '*'
		End as PrenotazioneStabilimento,		
		V.DataPartenzaPianificata as PrenotazioneData,
		C.DataArrivoTP as DataArrivoTP
from	CST_VIAGGI C
		INNER JOIN VIAGGI V  ON V.IDVIAGGIO = C.IDVIAGGIO
		LEFT JOIN PCS P ON P.CODICE = V.PCSPartenza
		LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TIPOMERCE
		LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
		Left Join Mezzi M On M.Codice = V.MotricePianificata;


-- dbo.CST_VW_Voci_CentroDiCosto_Peso source

ALTER VIEW CST_VW_Voci_CentroDiCosto_Peso AS
SELECT		T.Id,
			T.TipoSpedizione, 
			T.TipoMerce, 			
			T.PCSPartenza,			
			T.PCSArrivo,
			T.Voce,			
			T.CentroDiCosto,
			T.ClasseCOGE,
			(CASE WHEN T.Voce='*ALL' THEN 0 ELSE 1 END )*10000 +
			(CASE WHEN T.PCSArrivo='*ALL' THEN 0 ELSE 1 END )*1000 +			
			(CASE WHEN T.PCSPartenza='*ALL' THEN 0 ELSE 1 END )*100 +			
			(CASE WHEN T.TipoMerce='*ALL' THEN 0 ELSE 1 END )*10 +
			(CASE WHEN T.TipoSpedizione='*ALL' THEN 0 ELSE 1 END )*1 Peso
FROM		CST_Voci_CentriDiCosto T;


