-- dbo.CST_VW_XML_SPEDIZIONI source

-- dbo.CST_VW_XML_SPEDIZIONI source

ALTER     VIEW [dbo].[CST_VW_XML_SPEDIZIONI] AS
SELECT	--S.Corrispondente, IsNull(P4.CodiceTrasportatore, 'XXX'), V.Vettore, P4.RagioneSociale, P2.RagioneSociale,
		S.IdViaggio,
		S.UNIBOL,
		S.NumeroOrdine,
-- S.NumeroOrdineCliente,
		case when S.NumeroOrdineCliente is null then OP.TBNBOL else S.NumeroOrdineCliente end NumeroOrdineCliente,
		dbo.CST_XML_ReplaceChar(P3.FILLERALFA2) as Filler1,
		dbo.CST_XML_ReplaceChar(M.Descrizione) as MOTRICE,
		S.Peso as peso,
		S.Volume as Volume,
		S.Pallet,
		P1.FillerAlfa1 as PCSPARFiller1,
		case when P1.Codice = 'AD' then 'D' else dbo.CST_XML_ReplaceChar(P1.Codice) end as PCSPARCode,
		dbo.CST_XML_ReplaceChar(P1.RagioneSociale) as PCSPARRagSoc,
		isnull(dbo.CST_XML_ReplaceChar(P1.Telefono),'.') as PCSPARTel,
		dbo.CST_XML_ReplaceChar(P1.Indirizzo) as PCSPARInd,
		dbo.CST_XML_ReplaceChar(P1.Cap) as PCSPARCap,
		dbo.CST_XML_ReplaceChar(P1.Localita) as PCSPARLoc,
		dbo.CST_XML_ReplaceChar(dbo.CST_NazioneTransporeon(P1.Nazione)) as PCSPARNaz,
		S.dataRitiroPrevista1,
		V.DataPartenzaPianificata  dataRitiro1,
		V.DataPartenzaPianificata  dataRitiro2,
		dbo.CST_XML_ReplaceChar(
    CASE 
        WHEN S.PCSPARTENZA = 'Q' 
             THEN 'Orario di apertura Magazzino: 08:00 - 18:00 | Eventuali ritardi dovranno essere comunicati a Trasporti.AFH@lucartgroup.com entro le ore 17:00 | Warehouse opening hours: 08:00 AM - 06:00 TABLE PM | In case of delay, please write to Trasporti.AFH@lucartgroup.com within 5:00 PM' + ISNULL(NoteRitiroPrevisto, '')
        WHEN S.PCSPARTENZA = 'D' 
             THEN ISNULL(NoteRitiroPrevisto, '') + ' | IT: Parcheggiare nell’area designata, prenotarsi con TESI, attendere la chiamata dall ufficio accettazione. È vietato transitare lungo la strada.____EN: Park in the designated area, check in with TESI, and wait for the call from the acceptance office. It is forbidden to drive along the road.____DE: Im dafür vorgesehenen Bereich parken, mit TESI einchecken und auf den Anruf des Annahmebüros warten. Es ist verboten, auf der Straße zu fahren.'
        ELSE ISNULL(NoteRitiroPrevisto, '')
    END
) as NoteRitiro,
-- dbo.CST_XML_ReplaceChar(NoteRitiroPrevisto) as NoteRitiro,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.FillerAlfa1 Else P2.FillerAlfa1 End) as PCSDESFiller1,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.RagioneSociale Else P2.RagioneSociale End) as PCSDESRagSoc,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.Telefono Else P2.Telefono End) as PCSDESTel,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.Indirizzo Else P2.Indirizzo End) as PCSDESInd,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.Cap Else P2.Cap End) as PCSDESCap,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.Localita Else P2.Localita End) as PCSDESLoc,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null And IsNull(P4.CodiceTrasportatore, 'XXX') <> V.Vettore Then P4.Nazione Else P2.Nazione End) as PCSDESNaz,
dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.FillerAlfa1 Else P2.FillerAlfa1 End) as PCSDESFiller1,
-- dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.Codice Else P2.Codice End) as PCSDESCode,	    
        CASE WHEN LEFT(P2.Codice, 3) = '999' THEN P2.FillerAlfa3 ELSE P2.Codice END as PCSDESCode,
       /*dbo.CST_XML_ReplaceChar(
    CASE 
        WHEN S.Corrispondente IS NOT NULL TABLE 
            THEN 
                CASE 
                    WHEN ISNULL(P2.RagioneSociale, '') <> '' 
                     AND ISNULL(P2.RagioneSociale, '') <> ''
                        THEN S.Corrispondente + '_' + P2.RagioneSociale
                    ELSE 
                        ISNULL(NULLIF(P2.RagioneSociale, ''), P2.RagioneSociale)
                END
        ELSE 
            P2.RagioneSociale 
    END
) AS PCSDESRagSoc,*/
CASE 
    WHEN S.Corrispondente IS NOT NULL 
        THEN 
            CASE 
                WHEN ISNULL(P2.RagioneSociale, '') <> '' 
                    THEN P4.RagioneSociale + '_' + P2.RagioneSociale
                ELSE 
                    ISNULL(NULLIF(P4.RagioneSociale, ''), P2.RagioneSociale)
            END
    ELSE 
        P2.RagioneSociale 
END AS PCSDESRagSoc,
		--dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.RagioneSociale Else P2.RagioneSociale End) as PCSDESRagSoc,
		dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.Telefono Else isnull(P2.Telefono, '.') End) as PCSDESTel,
		dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.Indirizzo Else P2.Indirizzo End) as PCSDESInd,
		dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.Cap Else P2.Cap End) as PCSDESCap,
		dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then P4.Localita Else P2.Localita End) as PCSDESLoc,
		dbo.CST_XML_ReplaceChar(Case When S.Corrispondente Is Not Null Then dbo.CST_NazioneTransporeon(P4.Nazione) Else dbo.CST_NazioneTransporeon(P2.Nazione) End) as PCSDESNaz,
		Case When IsNull(V.DataArrivoPianificata, ISNULL(S.DataConsegnaConcordata, S.DataConsegnaPrevista1)) >= V.DataPartenzaPianificata Then IsNull(V.DataArrivoPianificata, ISNULL(S.DataConsegnaConcordata, S.DataConsegnaPrevista1)) Else V.DataPartenzaPianificata End dataConsegna1,
		Case When IsNull(V.DataArrivoPianificata, ISNULL(S.DataConsegnaConcordata, S.DataConsegnaPrevista2)) >= V.DataPartenzaPianificata Then IsNull(V.DataArrivoPianificata, ISNULL(S.DataConsegnaConcordata, S.DataConsegnaPrevista2)) Else V.DataPartenzaPianificata End dataConsegna2,
		--dbo.CST_XML_ReplaceChar(IsNull(Case When S.Corrispondente Is Not Null And P4.CodiceTrasportatore = V.Vettore Then '*** Consegna: ' + Convert(Varchar(60), S.PCSDestinazione_RagSoc) + ' - ' + Convert(Varchar(60), S.PCSDestinazione_Indirizzo) + '-' + Convert(Varchar(10), PCSDestinazione_Cap) + ' ' + Convert(Varchar(60), PCSDestinazione_Localita) + ' (' + Convert(Varchar(5), PCSDestinazione_Provincia) + ')' Else Null End + ' *** ', '') + Convert(Varchar(255), IsNull(NoteConsegnaPrevista + ' ', '')) + Convert(Varchar(1000), IsNull(S.Note, ''))) as NoteConsegna,
	    dbo.CST_XML_ReplaceChar(IsNull(dbo.CST_InfoSpedizioneTransporeon(S.UniBol), '') + Char(10) + Char(10) + IsNull(Case When S.Corrispondente Is Not Null And P4.CodiceTrasportatore = V.Vettore Then '*** Consegna: ' + Convert(Varchar(60), S.PCSDestinazione_RagSoc) + ' - ' + Convert(Varchar(60), S.PCSDestinazione_Indirizzo) + '-' + Convert(Varchar(10), PCSDestinazione_Cap) + ' ' + Convert(Varchar(60), PCSDestinazione_Localita) + ' (' + Convert(Varchar(5), PCSDestinazione_Provincia) + ')' Else Null End + ' *** ', '') + Convert(Varchar(255), IsNull(NoteConsegnaPrevista + ' ', '')) + Convert(Varchar(1000), IsNull(S.Note, ''))) as NoteConsegna,
		P2.RagioneSociale RagioneSocialeDestinazione,
		P4.RagioneSociale RagioneSocialeCorrispondente,
		S.Corrispondente,
		C.DataArrivoTP, S.cliente
FROM	SPEDIZIONI S 
		INNER JOIN VIAGGI V ON V.IDVIAGGIO = S.IDVIAGGIO
        INNER JOIN PCS P1 ON P1.CODICE = S.PCSPARTENZA --20171023 - su richiesta Sonia sostituiamo con partenza viaggio
-- INNER JOIN PCS P1 ON P1.CODICE = V.PCSPARTENZA
		INNER JOIN PCS P2 ON P2.CODICE = S.PCSDESTINAZIONE		
		INNER JOIN PCS P3 ON P3.CODICE = V.PCSPartenza
		Left Join PCS P4 On P4.Codice = S.Corrispondente
		INNER JOIN MEZZI M ON M.CODICE = V.MOTRICEPIANIFICATA
		INNER JOIN CST_Viaggi C ON C.IdViaggio = V.IdViaggio
		left join VW_LUC_OP_Easystor_all OP on OP.TSNORD =left(S.NumeroOrdine,12)
WHERE	S.IDVIAGGIO IS NOT NULL and P1.Codice <>'F';


-- dbo.CST_VW_XML_SPEDIZIONIUDS source

ALTER VIEW [dbo].[CST_VW_XML_SPEDIZIONIUDS]
AS
SELECT	S.IDVIAGGIO,
		S.UNIBOL,
		u.descrizione,
		U.CODICE,
		ID AS Progressivo,
		U.PesoLordo as Peso,
		U.Volume,
		U.Colli
FROM	SPEDIZIONIUDS U 
		INNER JOIN SPEDIZIONI S ON S.UNIBOL = U.UNIBOL
WHERE	IDVIAGGIO IS NOT NULL;


-- dbo.CST_VW_XML_VIAGGI source

ALTER VIEW [dbo].[CST_VW_XML_VIAGGI] AS
SELECT	V.IdViaggio,
		T.StatoTransporeon,
		dbo.CST_XML_ReplaceChar(P.Filleralfa2) as Filler1,
		dbo.CST_XML_ReplaceChar(M.Descrizione) as Motrice,
		dbo.CST_XML_ReplaceChar(IsNull(Tra.CodiceContabile, V.Vettore)) Vettore,
		dateadd(hh,2,getdate()) as Data,
		isnull(VT.Peso, 0) / 1000 as Peso,
		isnull(VT.Volume, 0) / 1000 as Volume,
		isnull(VT.Pallet, 0) as Pallet,
		V.KmPianificati,
		CV.MIOCPRENOTAZIONE,
		V.Note1 AS Note,
		C1.Descrizione ContactPerson,
		Case V.TipoMerce When 'PF' Then 'F' Else 'B' End GateType
FROM	VIAGGI V 
		INNER JOIN CST_Viaggi_Transporeon T on T.IdViaggio = V.idViaggio
		INNER JOIN CST_Viaggi CV on CV.IdViaggio = V.IdViaggio
		INNER JOIN PCS P on P.Codice = V.PCSPartenza
		INNER JOIN Mezzi M on M.Codice = V.MotricePianificata
		Inner Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
		Left Join Mezzi C1 On C1.Codice = V.Contenitore1Pianificato
		Join Trasportatori Tra On Tra.Codice = V.Vettore;


-- dbo.CST_VW_XML_VIAGGICOSTI source

ALTER VIEW CST_VW_XML_VIAGGICOSTI
AS
SELECT	IDVIAGGIO,'NOLO' VOCE, 'NOLO' DESCRIZIONE,ISNULL(SUM(IMPORTOARROTONDATO),0) AS IMPORTO , 1 as SEQ
FROM	VIAGGI_COSTI VC
		INNER JOIN VOCI V ON V.CODICE = VC.VOCE
WHERE	FLAGNOLO ='S'
GROUP BY IDVIAGGIO
UNION 
SELECT	IDVIAGGIO,VOCE,DESCRIZIONE,IMPORTOARROTONDATO , 2 AS SEQ
FROM	VIAGGI_COSTI VC
		INNER JOIN VOCI V ON V.CODICE = VC.VOCE
WHERE	FLAGNOLO ='N';


-- dbo.CST_VW_XML_VIAGGI_TESI source

ALTER VIEW [dbo].[CST_VW_XML_VIAGGI_TESI] AS
SELECT	V.IdViaggio,
		T.StatoTesi,
		dbo.CST_XML_ReplaceChar(P.Filleralfa2) as Filler1,
		--dbo.CST_XML_ReplaceChar(M.Descrizione) as Motrice,
		V.MotricePianificata as Motrice,
		dbo.CST_XML_ReplaceChar(IsNull(Tra.CodiceContabile, V.Vettore)) Vettore,
		dateadd(hh,2,getdate()) as Data,
		isnull(VT.Peso, 0) as Peso,
		isnull(VT.Volume, 0) as Volume,
		isnull(VT.Pallet, 0) as Pallet,
		V.KmPianificati,
		CV.MIOCPRENOTAZIONE,
		V.Note1 AS Note,
		C1.Descrizione ContactPerson,
		Case V.TipoMerce When 'PF' Then 'F' Else 'B' End GateType, 
		isnull(C1.Note, '') as PlannerEMail,
		V.TipoSpedizione as Incoterms, v.TipoViaggio, '' as targa, 
		isnull(isnull(v.Autista1Effettivo, v.Autista1Pianificato), tra.RagioneSociale) as Autista, V.pcspartenza
FROM	VIAGGI V 
		INNER JOIN CST_Viaggi_Tesi T on T.IdViaggio = V.idViaggio
		INNER JOIN CST_Viaggi CV on CV.IdViaggio = V.IdViaggio
		INNER JOIN PCS P on P.Codice = V.PCSPartenza
		--Inner JOIN Mezzi M on M.Codice = V.TipoViaggio
		Inner Join CST_Viaggi_Totali VT On VT.IdViaggio = V.IdViaggio
		Left Join Mezzi C1 On C1.Codice = V.Contenitore1Pianificato
		Join Trasportatori Tra On Tra.Codice = V.Vettore;


-- dbo.CST_VW_XML_VIAGGI_TESI_RESPONSE source

ALTER VIEW [dbo].[CST_VW_XML_VIAGGI_TESI_RESPONSE] AS
SELECT	CST_Viaggi_Tesi.IdViaggio as IdViaggio,
		V.Vettore as VettoreViaggio,
		StatoTrasmissione, 
		StatoTesi,
		StatoAccettazione,
		DataRichiesta,
		DataTrasmissione,
		SelectedCarrier,
		Price,
		Currency
FROM	CST_Viaggi_Tesi inner join Viaggi V on CST_Viaggi_Tesi.Idviaggio = V.IdViaggio
where StatoTrasmissione = 'S' 
and DataTrasmissione is not null
and StatoAccettazione in ('X','R');


-- dbo.CST_ViaggiCostoTotale source

ALTER View CST_ViaggiCostoTotale
As
Select IdViaggio, Sum(ImportoArrotondato) ImportoTotale, Sum(Case When Voci.FlagNolo = 'S' Then ImportoArrotondato Else 0 End) ImportoNolo
From Viaggi_Costi
Join Voci On Voci.Codice = Viaggi_Costi.Voce
Group By IdViaggio;


-- dbo.CST_Viaggi_ExtraCosti source

ALTER View CST_Viaggi_ExtraCosti
As
Select IdViaggio, Case When Count(1) > 0 Then '*' Else Null End ExtraCosti
From Viaggi_Costi
Where UtenteForzatura Is Not Null
Group By IdViaggio;


-- dbo.CST_Viaggi_Totali source

ALTER View CST_Viaggi_Totali
As
Select IdViaggio, Count(1) NumeroSpedizioni, Sum(Peso) Peso, Sum(Volume) Volume, Sum(Pallet) Pallet, Sum(Colli) Colli
From Spedizioni
Group By IdViaggio;


