-- dbo.ElencoCampiTabella source

ALTER VIEW [dbo].[ElencoCampiTabella]
AS
SELECT     CAST(C.TABLE_SCHEMA AS VARCHAR) AS TABLE_SCHEMA, 
		   CAST(C.TABLE_NAME AS VARCHAR) AS TABLE_NAME, 
		   CAST(C.COLUMN_NAME AS VARCHAR) AS COLUMN_NAME, 
		   CAST(C.ORDINAL_POSITION AS INT) AS ORDINAL_POSITION, 
		   LEFT(CAST(C.COLUMN_DEFAULT AS VARCHAR),255) AS COLUMN_DEFAULT, 
		   C.IS_NULLABLE, 
		   CAST(C.DATA_TYPE AS VARCHAR) AS DATA_TYPE , 
           C.CHARACTER_MAXIMUM_LENGTH, 
		   C.NUMERIC_PRECISION, 
		   C.NUMERIC_SCALE,
			CASE CAST(C.DATA_TYPE AS VARCHAR) 
			when 'bigint' THEN 'NUMERIC'
			when 'char' THEN 'STRING'
			when 'datetime' THEN 'DATETIME'
			when 'decimal' THEN 'NUMERIC'
			when 'float' THEN 'NUMERIC'
			when 'int' THEN 'NUMERIC'
			when 'numeric' THEN 'NUMERIC'
			when 'nvarchar' THEN 'STRING' 
			when 'smallint' THEN 'NUMERIC'
			when 'tinyint' THEN 'NUMERIC'
			when 'varchar' THEN 'STRING'
			else 'NOT_MANAGED' END AS WFI_DATA_TYPE,
			isnull(NULL, C.COLUMN_NAME)  AS FIELD_COMMENT,
			isnull(I.IsIdentity,0) IsIdentity
FROM         INFORMATION_SCHEMA.COLUMNS C
LEFT JOIN 
	(
		SELECT syscolumns.name COLUMN_NAME, 
				sysobjects.name TABLE_NAME,
				1 IsIdentity				 
		FROM sysobjects inner join syscolumns on (sysobjects.id = syscolumns.id)
		WHERE syscolumns.status = 128
	) I ON I.COLUMN_NAME=C.COLUMN_NAME AND I.TABLE_NAME=C.TABLE_NAME
WHERE     (TABLE_SCHEMA = 'dbo');


-- dbo.ElencoTabelle source

ALTER VIEW [dbo].[ElencoTabelle]
AS
SELECT  CAST(TABLES.TABLE_SCHEMA AS VARCHAR) AS TABLE_SCHEMA , 
		CAST(TABLES.TABLE_NAME AS VARCHAR) AS TABLE_NAME, 
		CAST(TABLES.TABLE_TYPE AS VARCHAR) AS TABLE_TYPE 
FROM INFORMATION_SCHEMA.TABLES TABLES
WHERE TABLES.TABLE_SCHEMA = 'dbo' AND 
    TABLES.TABLE_NAME NOT LIKE 'SYS_%';


