-- dbo.GRD_ANA_BancaliCausali source

ALTER view  [dbo].[GRD_ANA_BancaliCausali] as
 SELECT Codice
      ,Descrizione
      ,case 
		when TipoCausale='S' THEN 'Singola'
		when TipoCausale='D' THEN 'Doppia'
	   END TipoCausale
      ,Segno1
      ,Segno2
      ,case when TipoSoggetto1='H' THEN 'Corrispondente'
		 when TipoSoggetto1='C' THEN 'Cliente'
		 when TipoSoggetto1='D' THEN 'Destinazione'
		 when TipoSoggetto1='F' THEN 'Filiale'
		 when TipoSoggetto1='V' THEN 'Vettore'
	  end TipoSoggetto1
      ,case when TipoSoggetto2='H' THEN 'Corrispondente'
		when TipoSoggetto2='C' THEN 'Cliente'
		when TipoSoggetto2='D' THEN 'Destinazione'
		when TipoSoggetto2='F' THEN 'Filiale'
		when TipoSoggetto2='V' THEN 'Vettore'
	  end TipoSoggetto2
      ,Attivo
      ,StampaBuonoBancali
      ,DatAgg
      ,UteAgg
      ,DatIns
      ,UteIns
  FROM BancaliCausali;


