-- dbo.GRD_ANA_Calendario source

ALTER VIEW [dbo].[GRD_ANA_Calendario] as
select	Data,
		CASE datepart(dw, data) 
            WHEN 1 THEN 'DOMENICA' 
			WHEN 2 THEN 'LUNEDI' 
			WHEN 3 THEN 'MARTEDI' 
			WHEN 4 THEN 'MERCOLEDI' 
			WHEN 5 THEN 'GIOVEDI' 
			WHEN 6 THEN 'VENERDI'
            WHEN 7 THEN 'SABATO' 
		END AS GIORNO,
		CASE datepart(month, data) 
            WHEN 1 THEN 'GENNAIO' 
			WHEN 2 THEN 'FEBBRAIO' 
			WHEN 3 THEN 'MARZO' 
			WHEN 4 THEN 'APRILE' 
			WHEN 5 THEN 'MAGGIO' 
			WHEN 6 THEN 'GIUGNO'
            WHEN 7 THEN 'LUGLIO' 
            WHEN 8 THEN 'AGOSTO' 
            WHEN 9 THEN 'SETTEMBRE' 
            WHEN 10 THEN 'OTTOBRE' 
            WHEN 11 THEN 'NOVEMBRE' 
            WHEN 12 THEN 'DICEMBRE' 
		END AS MESE,
		DATEPART(year,data) Anno,
case when Flag = 'F' then 'Festivo' else 'Lavorativo' end as TipoGiorno,
case when Flag = 'F' then 'STDRED' else 'STDGREEN' end as Styleset,
Null as Dummy
from Calendario;


