-- dbo.GRD_ANA_Clienti_TempiResa source

ALTER VIEW [dbo].[GRD_ANA_Clienti_TempiResa]
AS
SELECT	Id,
		Cliente,
		C.RagioneSociale as ClienteRagSoc,
		CTR.TipoServizio,
		T.Descrizione as TipoServizioDescrizione,
		TipoSpedizione,
		TS.Descrizione as TipoSpedizioneDescrizione,
		TipoMerce,
		TM.Descrizione as TipoMerceDescrizione,
		PCSPartenza,
		P.RagioneSociale as PCSPartenzaRagSoc,
		CTR.ZonaSpedizione,
		Z.Descrizione as ZonaSpedizioneDescrizione,
		GiorniPrevistaConsegna,
		GiorniUscitaMagazzino,
		Cutoff,
		CTR.Attivo
FROM	ClientiTempiResa CTR
		INNER JOIN CLIENTI C ON C.CODICE = CTR.CLIENTE
		INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = CTR.TIPOSPEDIZIONE
		INNER JOIN TIPIMERCE TM ON TM.CODICE = CTR.TIPOMERCE
		INNER JOIN PCS P ON P.CODICE = CTR.PCSPARTENZA
		INNER JOIN ZONESPEDIZIONE Z ON Z.CODICE = CTR.ZONASPEDIZIONE
		INNER JOIN TIPISERVIZI T ON T.CODICE = CTR.TIPOSERVIZIO;


