-- dbo.GRD_ANA_LocalitaZone source

ALTER VIEW [dbo].[GRD_ANA_LocalitaZone]
AS
SELECT	Id,
		IdLocalita,
		TipoMerce,
		TM.Descrizione as TipoMerceDescrizione,
		LZ.ZonaSpedizione,
		Z1.Descrizione as ZonaSpedizioneDescrizione,
		LZ.ZonaTariffaAttiva,
		Z2.Descrizione as ZonaTariffaAttivaDescrizione,
		LZ.ZonaTariffaPassiva,
		Z3.Descrizione as ZonaTariffaPassivaDescrizione,
		LZ.ZonaPartenzaAttiva,				
		Z4.Descrizione as ZonaPartenzaAttivaDescrizione
FROM	LOCALITAZONE LZ 
		INNER JOIN TIPIMERCE TM ON TM.CODICE = LZ.TIPOMERCE
		INNER JOIN ZONE Z1 ON Z1.CODICE = LZ.ZonaSpedizione
		INNER JOIN ZONE Z2 ON Z2.CODICE = LZ.ZonaTariffaAttiva
		INNER JOIN ZONE Z3 ON Z3.CODICE = LZ.ZonaTariffaPassiva
		INNER JOIN ZONE Z4 ON Z4.CODICE = LZ.ZonaPartenzaAttiva;


-- dbo.GRD_ANA_Mezzi source

ALTER VIEW [dbo].[GRD_ANA_Mezzi]
AS
SELECT M.Codice,
		right('000000'+ M.CODICE, 7) CodiceTSE,
	   M.Matricola,
       M.Descrizione,
	   M.Targa,
	   M.TipoMezzo,
	   TM.Descrizione AS DescrizioneTipoMezzo,
	   M.TipoMerce,
	   TME.Descrizione AS DescrizioneTipoMerce,
	   M.DiProprieta,
	   M.Trasportatore,
	   T.RagioneSociale AS RagioneSocialeTrasportatore,
	   M.Autista,
	   A.RagioneSociale AS RagioneSocialeAutista,
	   M.PortataPeso,
	   M.PortataVolume,
	   M.PortataMetriLineari,
	   M.PortataColli,
	   M.PortataPallet,
	   M.PortataRoll,
	   M.PortataQ1,
	   M.PortataQ2,
	   M.PortataQ3,
	   M.GradoSaturazionePeso,
	   M.GradoSaturazioneVolume,
	   M.GradoSaturazioneML,
	   M.GradoSaturazioneColli,
	   M.GradoSaturazionePallet,
	   M.GradoSaturazioneRoll,
	   M.GradoSaturazioneQ1,
	   M.GradoSaturazioneQ2,
	   M.GradoSaturazioneQ3,
	   M.PuntoPartenza,
	   PCS1.RagioneSociale AS RagioneSocialePuntoPartenza,
	   M.PuntoArrivo,
	   PCS2.RagioneSociale AS RagioneSocialePuntoArrivo,
	   M.DispDalleOre,
	   M.DispAlleOre,
	   M.TempoReimpiego,
	   M.NumMaxReimpieghi,
	   M.ClasseDiGrandezza,
	   MCG.Descrizione AS DescrizioneClasseDiGrandezza,
	   M.LunghezzaPianale,
	   M.Lunghezza,
	   M.Altezza,
	   M.Larghezza,
	   M.Tara,
	   M.Assi,
	   M.Telaio,
	   M.AnnoImmatr,
	   M.KmInizio,
	   M.KmAttuali,
	   M.DataAcquisto,
	   M.NuovoUsato,
	   M.ValoreAcquisto,
	   M.DataAlienazione,
	   M.CapacitaSerbatoio,
	   M.CavalliFiscali,
	   M.ConsumoStandard,
	   M.EmissioneCO2,
	   M.Note,
	   M.Immagine1,
	   M.Immagine1Tipo,
	   M.Immagine2,
	   M.Immagine2Tipo,
	   M.Immagine3,
	   M.Immagine3Tipo,
	   M.Attivo
  FROM Mezzi AS M
 INNER JOIN TipiMezzo AS TM ON TM.Codice=M.TipoMezzo
  LEFT JOIN TipiMerce AS TME ON TME.Codice=M.TipoMerce
  LEFT JOIN Trasportatori AS T ON T.Codice=M.Trasportatore
  LEFT JOIN Autisti AS A ON A.Codice=M.Autista
 INNER JOIN PCS AS PCS1 ON PCS1.Codice=M.PuntoPartenza
  LEFT JOIN PCS AS PCS2 ON PCS2.Codice=M.PuntoArrivo
