-- dbo.GRD_ANA_PCS source

--*************************************************************************************************************
--
-- patch sulla griglia dei PCS per provincia/nazione
--
--*************************************************************************************************************
ALTER VIEW [dbo].[GRD_ANA_PCS] AS
SELECT      P.Codice,
             P.RagioneSociale,
             P.Indirizzo,
             P.Cap,
             P.Localita,
             P.Provincia,
             P.Nazione,
             P.CodiceFiscale,
             P.PartitaIva,
             P.Telefono,
             P.Email,
             P.PuntoDiDestino,
             P.PuntoDiCarico,
             P.PuntoDiParcoVeicolare,
             P.PuntoDiDeposito,
             P.IsFiliale,        
             G.ClassificazioneLocalita,
             G.ClassificazioneCAP,
             G.ClassificazioneIndirizzo,
             G.PunteggioTotale AS Rate,
             CASE
             WHEN G.UteAgg='DSI' THEN 'N'
             WHEN G.UteAgg IS NULL THEN 'X'
             ELSE 'S'
             END AS GeocodificaManuale,
             G.UteAgg AS UtenteAggiornamento,
             G.DatAgg AS DataAggiornamento,
             G.Latitudine,
             G.Longitudine,
             Pr.Regione   
   FROM      PCS P
   LEFT OUTER JOIN PCS_Geocodifica G ON P.Codice = G.Codice
   LEFT OUTER JOIN Province Pr ON Pr.Provincia =P.Provincia And Pr.Nazione = P.Nazione
   WHERE P.PuntoDiCarico ='S' OR 
   P.PuntoDiDeposito ='S' OR
   P.PuntoDiDestino='S' OR 
   P.PuntoDiParcoVeicolare='S' OR
   P.Destinatario='S';


