-- dbo.GRD_ANA_PCS_Corrispondenti source

--************************************************************************************************************
--
-- MODIFICA VISTA PER GRIGLIA CORRISPONDENTE E RELATIVA CONFIGURAZIONE
--
--************************************************************************************************************
ALTER VIEW [dbo].[GRD_ANA_PCS_Corrispondenti] AS
 SELECT	P.Codice,
		P.RagioneSociale,
		P.Indirizzo,
		P.Cap,
		P.Localita,
		P.Provincia,
		P.Nazione,
		P.CodiceFiscale,
		P.PartitaIva,
		P.Telefono,
		P.Email,
		P.PuntoDiDestino,
		P.PuntoDiCarico,
		P.PuntoDiParcoVeicolare,
		P.PuntoDiDeposito,
		P.IsFiliale,
		P.CodiceTrasportatore,
		T.RagioneSociale as TrasportatoreRagioneSociale,
		G.ClassificazioneLocalita,
		G.ClassificazioneCAP,
		G.ClassificazioneIndirizzo,
		G.PunteggioTotale AS Rate,
		CASE
		WHEN G.UteAgg='DSI' THEN 'N'
		WHEN G.UteAgg IS NULL THEN 'X'
		ELSE 'S'
		END AS GeocodificaManuale,
		G.UteAgg AS UtenteAggiornamento,
		G.DatAgg AS DataAggiornamento,
		G.Latitudine,
		G.Longitudine,
		Pr.Regione   		
   FROM	CORRISPONDENTI P 
  INNER JOIN TRASPORTATORI T ON T.CODICE = P.CODICETRASPORTATORE
  LEFT OUTER JOIN PCS_Geocodifica G ON P.Codice = G.Codice
  LEFT OUTER JOIN Province Pr ON Pr.Provincia =P.Provincia And Pr.Nazione = P.Nazione;


