-- dbo.GRD_ANA_PCS_OrariVisita source

ALTER VIEW [dbo].[GRD_ANA_PCS_OrariVisita]
AS
SELECT	Id,
		PCS,
		TipoMerce,
		TM.Descrizione as TipoMerceDescrizione,
		TempoCaricoScarico,
		TCS.Descrizione as TempoCaricoScaricoDescrizione,
		dbo.FORMATTIME( O1.OraInizio, 'HHNN', '.') + ' - ' + dbo.FORMATTIME( O1.OraFine , 'HHNN', '.') OrarioVisita1,
		pv.GiorniValidita1,
		dbo.FORMATTIME( O2.OraInizio, 'HHNN', '.') + ' - ' + dbo.FORMATTIME( O2.OraFine , 'HHNN', '.') OrarioVisita2,
		pv.GiorniValidita2,
		dbo.FORMATTIME( O3.OraInizio, 'HHNN', '.') + ' - ' + dbo.FORMATTIME( O3.OraFine , 'HHNN', '.') OrarioVisita3,
		pv.GiorniValidita3,
		dbo.FORMATTIME( O4.OraInizio, 'HHNN', '.') + ' - ' + dbo.FORMATTIME( O4.OraFine , 'HHNN', '.') OrarioVisita4,
		pv.GiorniValidita4,
		dbo.FORMATTIME( O5.OraInizio, 'HHNN', '.') + ' - ' + dbo.FORMATTIME( O5.OraFine , 'HHNN', '.') OrarioVisita5,
		pv.GiorniValidita5 
		  
FROM	PCS_ORARIVISITA PV 
		INNER JOIN TIPIMERCE TM ON TM.CODICE = PV.TIPOMERCE
		INNER JOIN VW_TEMPICARICOSCARICO_DESC TCS ON TCS.CODICE = PV.TEMPOCARICOSCARICO		
		LEFT JOIN OrariVisita O1 ON O1.Codice =pv.OrarioVisita1 
		LEFT JOIN OrariVisita O2 ON O2 .Codice =pv.OrarioVisita2
		LEFT JOIN OrariVisita O3 ON O3 .Codice =pv.OrarioVisita3
		LEFT JOIN OrariVisita O4 ON O4 .Codice =pv.OrarioVisita4
		LEFT JOIN OrariVisita O5 ON O5 .Codice =pv.OrarioVisita5;


