-- dbo.GRD_ANA_TipiMezzo source

ALTER VIEW [dbo].[GRD_ANA_TipiMezzo]
AS
SELECT TM.Codice,
       TM.Descrizione,
	   TM.Categoria,
	   MC.Descrizione AS DescrizioneCategoria,
	   TM.PortataPeso,
	   TM.PortataVolume,
	   TM.PortataMetriLineari,
	   TM.PortataColli,
	   TM.PortataPallet,
	   TM.PortataRoll,
	   TM.PortataQ1,
	   TM.PortataQ2,
	   TM.PortataQ3,
	   TM.GradoSaturazionePeso,
	   TM.GradoSaturazioneVolume,
	   TM.GradoSaturazioneML,
	   TM.GradoSaturazioneColli,
	   TM.GradoSaturazionePallet,
	   TM.GradoSaturazioneRoll,
	   TM.GradoSaturazioneQ1,
	   TM.GradoSaturazioneQ2,
	   TM.GradoSaturazioneQ3,
	   TM.ClasseDiGrandezza,
	   MCG.Descrizione AS DescrizioneClasseDiGrandezza,
	   TM.ProfiloVelocita,
	   PV.Descrizione AS DescrizioneProfiloVelocita,
	   TM.Lunghezza,
	   TM.Altezza,
	   TM.Larghezza,
	   TM.Tara,
	   TM.Assi,
	   TM.NumMaxFermate,
	   TM.TempoReimpiego,
	   TM.NumMaxReimpieghi,
	   TM.DispDalleOre,
	   TM.DispAlleOre,
	   TM.IsDefault,
	   TM.Attivo,
	   TM.TipoMerce,
	   TME.Descrizione AS DescrizioneTipoMerce
  FROM TipiMezzo AS TM
  INNER JOIN MezziCategorie AS MC ON MC.Codice=TM.Categoria
  INNER JOIN MezziClassiGrandezza AS MCG ON MCG.Codice=TM.ClasseDiGrandezza
  INNER JOIN ProfiliVelocita AS PV ON PV.Codice=TM.ProfiloVelocita
   LEFT JOIN TipiMerce AS TME ON TME.Codice=TM.TipoMerce;


