	   T.Fax,
	   T.Riferimento,
	   T.EMail,
	   T.PartitaIva,
	   T.CodicePagamento,
	   T.CodiceIva,
	   T.Note,
	   T.ReportBordero,
	   T.Attivo,
	   T.FatturaA,	
	   T.ReportFattura,
	   T.DataPerFatturazione,
	   T.EsportazioneBolle,
	   T.CodiceFiscale,
	   T.AlboTrasportatori,	  
	   T.ZonaSpedizione,
	   T.IsDefault,
	   '<B>Ragione Sociale: </B>'+ISNULL(T.RagioneSociale,'') + '</br>' +
	   '<B>Indirizzo: </B>'+ISNULL(T.Indirizzo,'') + '</br>' +
	   '<B>CAP: </B>'+ISNULL(T.Cap,'') + '</br>' +
	   '<B>Località: </B>'+ISNULL(T.Localita,'') + '</br>' +
	   '<B>Provincia: </B>'+ISNULL(T.Provincia,'') AS ToolTip
  FROM dbo.Trasportatori AS T;


-- dbo.GRD_ANA_Trasportatori_Contatti source

ALTER VIEW [dbo].[GRD_ANA_Trasportatori_Contatti] AS
SELECT		T.Codice CodiceTrasportatore, 
			C.Id,
			C.Descrizione,
			C.TipoContatto,
			C.Telefono,
			C.Cellulare,
			C.Fax,
			C.Email,
			C.Indirizzo,
			C.NumeroCivico,
			C.Cap,
			C.Localita,
			C.Provincia,
			C.Nazione,
			C.Altro,
			C.Note			
FROM		Trasportatori T INNER JOIN	
			TrasportatoriContatti TC ON T.Codice=TC.Trasportatore INNER JOIN
			Contatti C ON TC.IdContatto=C.ID;


-- dbo.GRD_ANA_Trasportatori_Docum source

ALTER VIEW [dbo].[GRD_ANA_Trasportatori_Docum] AS
SELECT		T.Codice CodiceTrasportatore, 
			DA.Id, 
			DA.Numero, 
			DA.DataRilascio, 
			DA.TipoDocumento, 
			DA.DataInizioValidita, 
			DA.DataFineValidita, 
			DA.Attributo1, DA.Attributo2, DA.Attributo3, DA.Attributo4, DA.Attributo5, 
			DA.Attributo6, DA.Attributo7, DA.Attributo8, DA.Attributo9, DA.Attributo10, 
			DA.Immagine1, DA.Immagine1Tipo, 
			DA.Immagine2, DA.Immagine2Tipo, 
			DA.Immagine3, DA.Immagine3Tipo,
			DA.Note,
			TDA.Descrizione DescrizioneTipiDocumento
FROM		Trasportatori T INNER JOIN 
			TrasportatoriDocumenti TD ON T.Codice=TD.Trasportatore INNER JOIN
			DocumentiAnagrafiche DA ON TD.IdDocumento=DA.ID INNER JOIN
			TipiDocumentoAnagrafiche TDA ON TDA.Codice=DA.TipoDocumento;


-- dbo.GRD_ANA_Trasportatori_Eventi source

