-- dbo.GRD_CONTESTAZIONI source

ALTER VIEW [dbo].[GRD_CONTESTAZIONI] AS
SELECT	 Id
      ,TipoContestazione
	  ,T.Descrizione TipoContestazione_Descrizione 
      ,Stato
      ,TipoSoggetto
      ,Soggetto_Codice
      ,Soggetto_RagioneSociale
      ,Soggetto_Indirizzo
      ,Soggetto_Cap
      ,Soggetto_Localita
      ,Soggetto_Provincia
      ,Soggetto_Nazione
      ,Unibol
      ,CAST(DataApertura AS DATE) DataApertura 
      ,CAST(DataChiusura AS DATE) DataChiusura
      ,Riferimento1
      ,DataRiferimento1
      ,NoteRiferimento1
      ,Riferimento2
      ,DataRiferimento2
      ,NoteRiferimento2
      ,Note1
      ,Note2
      ,Note3
      ,C.DatAgg
      ,C.UteAgg
      ,C.DatIns
      ,C.UteIns,
	  CASE 
		WHEN C.stato=10 THEN 'IN CORSO' 
		WHEN C.stato=20 THEN 'TERMINATA' 
		WHEN C.stato=99 THEN 'ANNULLATA' 
		END Stato_Descrizione,
		CASE 
		WHEN C.TipoSoggetto='C' THEN 'CLIENTE' 
		WHEN C.TipoSoggetto='H' THEN 'CORRISPONDENTE'
		WHEN C.TipoSoggetto='D' THEN 'DESTINATARIO'
		WHEN C.TipoSoggetto='V' THEN 'VETTORE'		
		WHEN C.TipoSoggetto='M' THEN 'CARICATORE'		
		WHEN C.TipoSoggetto='X' THEN 'DA DEFINIRE'
		ELSE 'NON IN ANAGRAFICA'				
		END TipoSoggetto_Descrizione
FROM Contestazioni C INNER JOIN Contestazioni_Tipi T ON T.Codice=C.TipoContestazione;


