-- dbo.GRD_CTRL_FATTURE_PASSIVE source

ALTER VIEW [dbo].[GRD_CTRL_FATTURE_PASSIVE]
AS
SELECT 	T.*,
		T.Imponibile1+T.Imposta1 TotaleFattura
FROM
(
	select	IdFattura,
			TipoDocumento, 
			Numero,  DataScadenza1, DataScadenza2, DataScadenza3, Contabilizzata, 
			DataContabilizzazione, ErroreContabilizzazione, 
			UtenteDiControllo, DataDiControllo,
			C.NumeroEsterno,
			C.ID,		
			c.Sezionale,
			S.Descrizione as SezionaleDescrizione,		
			C.StatoElaborazione ,
			C.DataElaborazione ,
			C.Data, 
			C.Trasportatore, 
			T.RagioneSociale as RagioneSociale,
			C.TipoPagamento, 
			P.Descrizione as TipoPagamentoDescrizione,
			DaData, 
			AData, 
			C.Note1, C.Note2 , Note3, 
			DataOraInizioEsecuzione, 
			DataOraFineEsecuzione, Errore,
			IDFATTURAINTERNO,
			 (
				SELECT TOP 1 Imponibile 
				FROM Fatture_Passive_Iva I
				WHERE I.IdFattura=F.IdFattura 			
			) Imponibile1,
			(
				SELECT TOP 1 Aliquota
				FROM Fatture_Passive_Iva I
				WHERE I.IdFattura=F.IdFattura 			
			) Aliquota1,
			(
				SELECT TOP 1 Imposta
				FROM Fatture_Passive_Iva I
				WHERE I.IdFattura=F.IdFattura 			
			) Imposta1
		
	FROM	CTRL_Fatture_Passive_Testata C 
			LEFT JOIN Fatture_Passive_Testata F ON F.IdFattura = C.IdFatturaInterno 
			LEFT JOIN Trasportatori T on T.Codice = C.Trasportatore 
			LEFT JOIN Sezionali S on S.Codice = C.Sezionale 
			LEFT JOIN CodiciPagamento P on P.Codice = C.TipoPagamento 
) T;


