-- dbo.GRD_Contrassegni source

ALTER VIEW [dbo].[GRD_Contrassegni] AS
SELECT	C.*,  
		S.PCSDestinazione, 
		S.PCSDestinazione_Cap, 
		S.PCSDestinazione_Indirizzo, 
		S.PCSDestinazione_Localita, 
		S.PCSDestinazione_Nazione, 
		S.PCSDestinazione_Provincia, 
		S.PCSDestinazione_RagSoc,
		CL.RagioneSociale Cliente_RagioneSociale, 
		CL.Provincia Cliente_Provincia, 
		CL.Localita Cliente_Localita, 
		CL.Nazione Cliente_Nazione,     
		Cor.RagioneSociale Corrisp_RagioneSociale, 
		Cor.Provincia Corrisp_Provincia, 
		Cor.Localita Corrisp_Localita, 
		Cor.Nazione Corrisp_Nazione, 
		T.RagioneSociale Trasp_RagioneSociale,
		TI.Descrizione TipoIncasso_Descrizione  ,
		ST.Descrizione as StatoDescrizione   
FROM Contrassegni C 
INNER JOIN Spedizioni S ON S.unibol=C.UnibolApertura 
INNER JOIN Clienti CL ON CL.Codice =C.Cliente 
LEFT JOIN PCS Cor ON Cor.Codice =C.Corrispondente 
LEFT JOIN Trasportatori T ON T.Codice =C.Trasportatore 
LEFT JOIN TipiIncasso TI ON TI.Codice =C.TipoIncasso 
INNER JOIN VW_DOC_Contrassegni_Stati ST ON ST.Codice = C.Stato;


-- dbo.GRD_Contrassegni_Costi source

ALTER VIEW [dbo].[GRD_Contrassegni_Costi]
AS
SELECT	C.*, 
		V.Descrizione VOCE_Descrizione,
		CC.Descrizione CampoCalcolo_Descrizione,
		C.RecordZZ RecordZZ_Descrizione,
		C.TipoCalcolo TipoCalcolo_Descrizione,
		T.RagioneSociale Trasportatore_Descrizione
FROM Contrassegni_Costi C 
INNER JOIN Voci V ON V.Codice=C.Voce
LEFT JOIN TabCampiCalcolo CC ON CC.NomeCampo=C.CampoCalcolo 
LEFT JOIN Trasportatori T ON T.Codice=C.Trasportatore;


-- dbo.GRD_Contrassegni_Ricavi source

ALTER VIEW [dbo].[GRD_Contrassegni_Ricavi]
AS
SELECT	R.*, 
		V.Descrizione VOCE_Descrizione,
		CC.Descrizione CampoCalcolo_Descrizione,
		R.RecordZZ RecordZZ_Descrizione,
		R.TipoCalcolo TipoCalcolo_Descrizione
FROM Contrassegni_Ricavi R 
INNER JOIN Voci V ON V.Codice=R.Voce
LEFT JOIN TabCampiCalcolo CC ON CC.NomeCampo=R.CampoCalcolo;


-- dbo.GRD_Contrassegni_Rimesse source

ALTER VIEW [dbo].[GRD_Contrassegni_Rimesse]
AS
SELECT	R.Id,
		R.Stato,
		CASE WHEN R.STATO=10 THEN 'IN CORSO' WHEN R.STATO=20 THEN 'RIMESSA EFFETTUATA' END Stato_Descrizione,
		C.RagioneSociale Cliente_RagioneSociale,
		R.DataRimessa,
		(SELECT Sum(Contrassegno) FROM Contrassegni WHERE IdRimessa=R.Id) as Valore,
		R.Note1,
		R.Note2, 
		R.Note3, 
		'SELECT ''<table class="ElencoDettaglioDiGrigliaTable"><tr><td>Id</td><td>Data Creaz.</td><td>Data incasso</td><td>Importo</td></tr>'' + ' + 
		'( SELECT ''<tr><td>'' + CAST(C1.Id AS VARCHAR) + ''</td><td>'' 
			+ CONVERT(VARCHAR(10),C1.DataCreazione ,105) + ''</td><td>'' 
			+ CONVERT(VARCHAR(10),C1.DataIncasso ,105) + ''</td><td>''
			+ CAST(CAST(C1.Contrassegno AS decimal(18,2))AS VARCHAR) + ''</td></tr>''
			FROM Contrassegni C1 WHERE C1.IdRimessa=' + CAST(R.Id AS varchar) + '
			FOR XML PATH(''''), TYPE).value(''.[1]'', ''varchar(max)'')
		+ ''</table>'''  as ElencoContrassegniTooltip,
		'Vedi' as ElencoContrassegni
FROM	Contrassegni_Rimesse R LEFT JOIN CLIENTI C ON C.Codice = R.Cliente;


-- dbo.GRD_DOC_Autisti_Attivita source

ALTER VIEW [dbo].[GRD_DOC_Autisti_Attivita]
AS
SELECT	Id,
		AA.Autista,
		A.RagioneSociale AS CognomeENome,
		TipoAttivita,
		TA.Descrizione as TipoAttivitaDescrizione,
		Motrice,
		MM.Targa as TargaMotrice,				
		Rimorchio1,
		MR.Targa as TargaRimorchio,				
		Contenitore1,
		MC.Targa as TargaContenitore,	
		DataInizio,
		DataFine,
		AA.KmInizio,
		AA.KmFine,
		LocalitaInizio,
		LocalitaFine
FROM	AUTISTI_ATTIVITA AA
		INNER JOIN AUTISTI A ON A.CODICE = AA.AUTISTA
		INNER JOIN AUTISTI_TIPIATTIVITA TA ON TA.CODICE = AA.TIPOATTIVITA
		LEFT JOIN MEZZI MM ON MM.CODICE = AA.MOTRICE
		LEFT JOIN MEZZI MR ON MR.CODICE = AA.RIMORCHIO1
		LEFT JOIN MEZZI MC ON MC.CODICE = AA.CONTENITORE1;


-- dbo.GRD_DOC_Autisti_Attivita_GG source

ALTER VIEW [dbo].[GRD_DOC_Autisti_Attivita_GG]
AS
SELECT	V.AUTISTA,
		V.DATA,
		AU.RAGIONESOCIALE,		
		AI.Motrice, 
        M1.TARGA AS TARGAMOTRICE,
        AI.Rimorchio1,
        M2.TARGA AS TARGARIMORCHIO, 
		AI.DataInizio,
		AI.KmInizio,
		AI.LocalitaInizio, 
		AI.IndirizzoInizio, 		
        AI.CapInizio, 
        AI.NazioneInizio,
        AI.LatitudineInizio,
		AI.LongitudineInizio,
        AF.DataFine,
		AF.KmFine,
		AF.LocalitaFine, 
		AF.IndirizzoFine, 
        AF.CapFine, 
        AF.NazioneFine,
        AF.LatitudineFine,
		AF.LongitudineFine,
        --ISNULL(TG.MINUTI,0) AS TempoGuida,
        --ISNULL(TP.MINUTI,0) AS TempoPausa,
        --ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0) + ISNULL(TE.MINUTI,0) AS TempoCaricoScarico,
        --ISNULL(TC.MINUTI,0) AS TempoCarico,
        --ISNULL(TS.MINUTI,0) AS TempoScarico,
        --ISNULL(TE.MINUTI,0) AS TempoExtra,
        ISNULL(AF.KMFINE - AI.KMINIZIO,0) AS TotKm,
        convert(nvarchar(10), V.DATA, 112) AS DATASTRINGA,
		right(replicate('0',2) + CAST(MONTH(v.DATA) AS VARCHAR(2)),2)+ CAST(YEAR(v.DATA) AS VARCHAR(4))  AS DATASTRINGA2 ,
		AU.Trasportatore ,
		AU.Trasportatore as Trasportatore1
FROM	VW_AUTISTAGIORNO_ATT V 
		INNER JOIN AUTISTI AU ON AU.CODICE = V.AUTISTA
		INNER JOIN Autisti_Attivita AI ON AI.ID = V.IDINIZIO
		INNER JOIN Autisti_Attivita AF ON AF.ID = V.IDFINE
		LEFT JOIN MEZZI M1 ON M1.CODICE = AI.MOTRICE
		LEFT JOIN MEZZI M2 ON M2.CODICE = AI.RIMORCHIO1
		--LEFT JOIN VW_AUTISTAGIORNO_ATTIVITA_TEMPI TG ON TG.AUTISTA = V.AUTISTA AND TG.DATA = V.DATA AND TG.TIPOATTIVITA = '001'
		--LEFT JOIN VW_AUTISTAGIORNO_ATTIVITA_TEMPI TP ON TP.AUTISTA = V.AUTISTA AND TP.DATA = V.DATA AND TP.TIPOATTIVITA = '002'
		--LEFT JOIN VW_AUTISTAGIORNO_ATTIVITA_TEMPI TC ON TC.AUTISTA = V.AUTISTA AND TC.DATA = V.DATA AND TC.TIPOATTIVITA = '003'
		--LEFT JOIN VW_AUTISTAGIORNO_ATTIVITA_TEMPI TS ON TS.AUTISTA = V.AUTISTA AND TS.DATA = V.DATA AND TS.TIPOATTIVITA = '004'
		--LEFT JOIN VW_AUTISTAGIORNO_ATTIVITA_TEMPI TE ON TE.AUTISTA = V.AUTISTA AND TE.DATA = V.DATA AND TE.TIPOATTIVITA = '006';


-- dbo.GRD_DOC_MezziAnomalie source

ALTER VIEW [dbo].[GRD_DOC_MezziAnomalie]
AS
SELECT	Progressivo,
		Mezzo,
		M.Descrizione + '(' + M.Targa + ')' as MezzoDescrizione,
		M.TipoMezzo,
		TM.Descrizione as TipoMezzoDescrizione,
		MA.Autista,
		A.Ragionesociale as AutistaDescrizione,
		CausaleAnomalia,
		CMA.Descrizione as CausaleAnomaliaDescrizione,
		DataSegnalazione
FROM	MEZZIANOMALIE MA
		INNER JOIN MEZZI M ON M.CODICE = MA.MEZZO
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
		INNER JOIN AUTISTI A ON A.CODICE = MA.AUTISTA
		INNER JOIN CAUSALIMEZZIANOMALIE CMA ON CMA.CODICE = MA.CAUSALEANOMALIA;


-- dbo.GRD_DOC_Mezzi_Rifornimenti source

ALTER VIEW [dbo].[GRD_DOC_Mezzi_Rifornimenti] AS
SELECT		Id,
			R.Mezzo,
			M.Targa, 
			DataOra,
			TipoRifornimento,
			TR.Descrizione,
			R.Autista,
			A.RagioneSociale,
			Litri,
			LitriAdditivo,
			R.Localita,
			Km,
			M.Trasportatore ,
			A.Trasportatore as Trasportatore1
FROM		MEZZI_RIFORNIMENTI R 
			INNER JOIN Mezzi_TipiRifornimento TR ON TR.CODICE = R.TIPORIFORNIMENTO
			INNER JOIN Mezzi M on M.Codice = R.Mezzo 
			LEFT JOIN Autisti A on A.Codice = R.Autista;


-- dbo.GRD_DOC_Spedizioni source

ALTER VIEW [dbo].[GRD_DOC_Spedizioni] AS
   SELECT tb.descrizione AS tipobolladescrizione,
          c.ragionesociale AS clienteragionesociale,
          ts.descrizione AS tipospedizionedescrizione,
          tm.descrizione AS tipomercedescrizione,
          ISNULL (S.DATACONSEGNACONCORDATA, s.DATACONSEGNAPREVISTA1)
                                                        DATACONSEGNAPREVISTA1,
          CASE
             WHEN S.DATACONSEGNACONCORDATA IS NOT NULL
                THEN NULL
             ELSE s.DATACONSEGNAPREVISTA2
          END DATACONSEGNAPREVISTA2,
          S.UNIBOL,
          S.UNIBOLPARENT,
          S.UNIBOLMASTER,
          S.UNIBOLOBC,
          S.PROGRESSIVOCONSEGNA,
          S.BARCODE,
          S.STATO,
          S.PREBOLLA,
          S.TIPOSERVIZIO,
          S.CLIENTE,
          S.MITTENTE,
          ISNULL(S.MITTENTERAGIONESOCIALE, m.RagioneSociale) MITTENTERAGIONESOCIALE,
          S.CLIENTEFATTURAZIONE,
          S.NUMEROBOLLA,
          S.DATABOLLA,
          S.NUMEROORDINE,
          S.DATAORDINE,
          S.NUMEROORDINECLIENTE,
