          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
          Co.RagioneSociale as CorrispondenteRagSoc,
		  CO.Localita AS LocalitaCorrispondente,
		  VL.Giro,
		  VL.RiferimentoEsterno AS RiferimentoEsternoGiro
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
		  LEFT JOIN CLIENTI M ON M.CODICE = S.Mittente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN Corrispondenti Co ON S.Corrispondente = Co.Codice
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
    WHERE s.stato In (40, 48);


-- dbo.GRD_DOC_Spedizioni_Eventi source

ALTER VIEW [dbo].[GRD_DOC_Spedizioni_Eventi]
AS
SELECT	Id, 
		Unibol, 
		CodiceEvento, 
		E.Descrizione as DescrizioneEvento,
		DataOraEvento, 
		NoteInterne, 
		NoteEsterne, 
		Importato, 
		Annullato, 
		EsportatoCliente, 
		DataEsportazioneCliente, 
		EsportatoFornitore, 
        DataEsportazioneFornitore, 
        DataConsegnaConcordata, 
        OraConsegnaConcordata1, 
        OraConsegnaConcordata2, 
        Riferimento, 
        SE.Autista, 
        A.RagioneSociale as AutistaDescrizione,
        Terminale, 
        Motrice, 
        MM.Descrizione as MotriceDescrizione,
        Rimorchio1, 
        MR1.Descrizione as Rimorchio1Descrizione,
        Contenitore1, 
        MC1.Descrizione as Contenitore1Descrizione,
        Rimorchio2, 
        MR2.Descrizione as Rimorchio2Descrizione,
        Contenitore2, 
        MC2.Descrizione as Contenitore2Descrizione,
        DatiAggiuntivi, 
        Latitudine, 
        Longitudine, 
        DataValiditaGPS, 
        KmGPS, 
        KmManuali, 
        SE.Localita, 
        SE.Indirizzo, 
        SE.Cap, 
        SE.Provincia, 
        SE.Nazione,
		SE.UteIns
FROM	SPEDIZIONI_EVENTI SE
		INNER JOIN EVENTI E ON E.CODICE = SE.CODICEEVENTO
		LEFT JOIN AUTISTI A ON A.CODICE = SE.AUTISTA
		LEFT JOIN MEZZI MM ON MM.CODICE = SE.MOTRICE
		LEFT JOIN MEZZI MR1 ON MR1.CODICE = SE.RIMORCHIO1
		LEFT JOIN MEZZI MR2 ON MR1.CODICE = SE.RIMORCHIO2
		LEFT JOIN MEZZI MC1 ON MC1.CODICE = SE.CONTENITORE1
		LEFT JOIN MEZZI MC2 ON MC2.CODICE = SE.CONTENITORE2;


-- dbo.GRD_DOC_Spedizioni_Libere source

ALTER VIEW [dbo].[GRD_DOC_Spedizioni_Libere] AS
SELECT S.Unibol,
       S.Barcode,
       S.NumeroOrdine,
       S.NumeroBolla,
       S.NUMEROORDINECLIENTE,
       S.TipoSERVIZIO,
       TB.Descrizione AS TipoBollaDescrizione,          
       S.PCSPartenza,
       S.PCSPartenza_RagSoc,
       S.PCSPartenza_Localita,
       S.PCSPartenza_Indirizzo,
       S.PCSPartenza_Provincia,
       S.PCSPartenza_Nazione,
       S.PCSDestinazione,
       S.PCSDestinazione_RagSoc,
       S.PCSDestinazione_Localita,
       S.PCSDestinazione_Indirizzo,
       S.PCSDestinazione_Provincia,
       S.PCSDestinazione_Nazione,
       S.Corrispondente,
       S.Colli,
       S.Pallet,
       S.Peso,
       S.Volume,
       S.TipoSpedizione,
       S.TipoMerce,
       S.Cliente,
       S.ZonaSpedizione,
       S.DataBolla,
       S.DataOrdine,
       S.DATAORDINECLIENTE,
       S.DATACONSEGNAPREVISTA1,
       S.DATACONSEGNAPREVISTA2,
       ISNULL(S.DATACONSEGNACONCORDATA, s.DATACONSEGNAPREVISTA1) DATACONSEGNA1,
       CASE
          WHEN S.DATACONSEGNACONCORDATA IS NOT NULL
             THEN NULL
          ELSE s.DATACONSEGNAPREVISTA2
       END DATACONSEGNA2,
       DATACONSEGNACONCORDATA, 
       S.BatchId,
       S.DataSpedizione,
	   S.DestinazioneCliente,
	   CO.RagioneSociale AS RagSocCorrispondente,
	   CO.Localita AS LocalitaCorrispondente,
	   VL.Giro,
	   VL.RiferimentoEsterno AS RiferimentoEsternoGiro,
       S.FILLERALFA1,
       S.FILLERALFA2,
       S.FILLERALFA3,
       S.FILLERALFA4,
       S.FILLERALFA5,
       S.FILLERALFA6,
       S.FILLERALFA7,
       S.FILLERALFA8,
       S.FILLERALFA9,
       S.FILLERALFA10,
       S.FILLERDATA1,
       S.FILLERDATA2,
       S.FILLERDATA3,
       S.FILLERDATA4,
       S.FILLERDATA5
  FROM Spedizioni S
 INNER JOIN TIPISERVIZI TB ON TB.CODICE = S.TIPOSERVIZIO
 INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
  LEFT JOIN CLIENTI C ON C.CODICE = S.CLIENTE    
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE  
  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
WHERE IDVIAGGIO IS NULL AND s.STATO = 20;


