          S.FILLERALFA4,
          S.FILLERALFA5,
          S.FILLERALFA6,
          S.FILLERALFA7,
          S.FILLERALFA8,
          S.FILLERALFA9,
          S.FILLERALFA10,
          S.FILLERDATA1,
          S.FILLERDATA2,
          S.FILLERDATA3,
          S.FILLERDATA4,
          S.FILLERDATA5,
          S.BATCHID,
          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
          se.DataOraEvento,
          se.CodiceEvento,
          ev.TipoEvento,
          CASE
             WHEN ev.TipoEvento = 'SPEDIZIONE.ESITO.OK'
                THEN 'DOC.SPED.OK'
             WHEN ev.TipoEvento = 'SPEDIZIONE.ESITO.KO' AND s.stato <> 98
                THEN 'DOC.SPED.KO'
             WHEN ev.TipoEvento = 'SPEDIZIONE.ESITO.KO' AND s.stato = 98
                THEN 'DOC.SPED.ANN'
             ELSE ''
          END AS Styleset,
			FA.Numero AS NumeroFatturaAttiva,
	      CO.RagioneSociale AS RagSocCorrispondente,
	      CO.Localita AS LocalitaCorrispondente,
	      VL.Giro,
	      VL.RiferimentoEsterno AS RiferimentoEsternoGiro
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
		  LEFT JOIN CLIENTI M ON M.CODICE = S.Mittente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          
          LEFT JOIN Spedizioni_Eventi se
			  ON 
				se.Unibol = s.UniBol
				AND Annullato = 'N'
				AND (CodiceEvento LIKE 'ESI%' or CodiceEvento = 'ANNULLATA')
		  LEFT JOIN Eventi ev
			  ON 
				ev.Codice = se.CodiceEvento
				AND TipoEvento LIKE 'SPEDIZIONE.ESITO%'
		  LEFT JOIN FATTURE_ATTIVE_TESTATA AS FA ON FA.IDFATTURA = S.IDFATTURAATTIVA                                          
          LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
          LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
    WHERE s.stato >= 30 AND s.stato <> 99 --and s.idviaggio = 389339;


