          S.KMRICALCOLATI,
          S.DATACOMPETENZAATTIVA,
          S.DATACOMPETENZAPASSIVA,
          S.IDFATTURAATTIVA,
          S.IDFATTURAPASSIVA,
          S.IDVIAGGIO,
          S.SEQUENZAPIANIFICATA,
          S.SEQUENZAEFFETTIVA,
          S.SEQUENZAORIGINALE,
          S.FILLERALFA1,
          S.FILLERALFA2,
          S.FILLERALFA3,
          S.FILLERALFA4,
          S.FILLERALFA5,
          S.FILLERALFA6,
          S.FILLERALFA7,
          S.FILLERALFA8,
          S.FILLERALFA9,
          S.FILLERALFA10,
          S.FILLERDATA1,
          S.FILLERDATA2,
          S.FILLERDATA3,
          S.FILLERDATA4,
          S.FILLERDATA5,
          S.BATCHID,
          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
	      CO.RagioneSociale AS RagSocCorrispondente,
	      CO.Localita AS LocalitaCorrispondente,
		  T.RagioneSociale As VettoreRagioneSociale,
		  SS.Descrizione StatoDescrizione
     FROM Spedizioni S INNER JOIN TIPISERVIZI TB ON TB.CODICE = S.TIPOSERVIZIO
          INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
          LEFT JOIN CLIENTI C ON C.CODICE = S.CLIENTE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  Left Join Viaggi V On V.IdViaggio = S.IdViaggio
		  Left Join Trasportatori T On T.Codice = V.Vettore
		  Left Join VW_DOC_Spedizioni_Stati SS On SS.Codice = S.Stato
          ;


-- dbo.GRD_DOC_TARIFFECONTRATTI source

ALTER VIEW [dbo].[GRD_DOC_TARIFFECONTRATTI]
AS 
SELECT	G.Codice,
		CASE 
			WHEN AttivaPassiva='A' then 'ATTIVA'
			WHEN AttivaPassiva='P' then 'PASSIVA'			
			ELSE NULL
		END AttivaPassiva, 
		ContrattoTrasporto,
		ContrattoGiacenza,
		CASE 
			WHEN AttivaPassiva='A' THEN C.RAGIONESOCIALE
			ELSE T.RAGIONESOCIALE
		END Soggetto,
		Descrizione, 
		G.Attivo, 	
		RapportoPV,
		DataInizioValidita,
		DataFineValidita
FROM	TARIFFECONTRATTI G LEFT JOIN 
		CLIENTI C ON C.CODICE = G.CLIENTE LEFT JOIN
		TRASPORTATORI T ON T.CODICE = G.TRASPORTATORE;


-- dbo.GRD_DOC_TariffeAttive source

ALTER VIEW [dbo].[GRD_DOC_TariffeAttive] AS
SELECT TC.Codice
     , TC.Cliente AS ClienteTestata
     , C.RagioneSociale AS RagSocClienteTestata
	 , TC.Descrizione
	 , TC.DataInizioValidita
	 , TC.DataFineValidita
	 , TC.Raggruppamento
	 , TT.TipoSpedizione
	 , TT.TipoMerce
	 , TT.TipoMezzo
	 , TT.Cliente
	 , C1.RagioneSociale AS RagioneSocialeCliente
	 , TT.GruppoTariffarioPartenza
	 , GT.Descrizione AS DescrizioneGruppoTarifPartenza
	 , TT.PCSPartenza
	 , PCS.RagioneSociale AS RagSocPCSPartenza
	 , TT.MacroZonaArrivo
	 , ZM.Descrizione AS DescrizioneZMArrivo
	 , TT.ZonaArrivo
	 , Z.Descrizione AS DescrizioneZonaArrivo
	 , TT.GruppoTariffarioArrivo
	 , GT1.Descrizione AS DescrizioneGruppoTarifArrivo
	 , TT.PCSArrivo
	 , PCS1.RagioneSociale AS RagSocPCSArrivo
	 , TT.TipoDocumento
	 , TV.Voce
	 , V.Descrizione AS DescrizioneVoce
	 , TV.CampoCalcolo
	 , TV.ArrCampoCalcolo
	 , TV.ArrCampoCalcoloLimite
	 , TV.ArrCampoCalcoloOltre
	 , TV.ArrImporto
	 , TV.flgEccedenza
	 , TF.FasciaInferiore
	 , TF.FasciaSuperiore
	 , TF.Fisso
	 , TF.Variabile
	 , TF.Percentuale
	 , TT.IdTariffa
	 , TV.IdVoce
	 , TF.IdFascia
	 , CAST(TT.IdTariffa AS VARCHAR) + ' ' + CAST(TV.IdVoce AS VARCHAR) + ' ' + CAST(TF.IdFascia AS VARCHAR) AS Id
  FROM TariffeContratti TC
 INNER JOIN TariffeAttiveTestata TT ON TC.Codice=TT.Contratto 
 INNER JOIN Clienti C ON TC.Cliente=C.Codice
 INNER JOIN Clienti C1 ON TT.Cliente=C1.Codice
 INNER JOIN PCS_GruppiTariffari GT ON GT.Codice=TT.GruppoTariffarioPartenza
 INNER JOIN PCS PCS ON PCS.Codice=TT.PCSPartenza
 INNER JOIN ZoneMacro ZM ON TT.MacroZonaArrivo=ZM.Codice
 INNER JOIN Zone Z ON Z.Codice=TT.ZonaArrivo
 INNER JOIN PCS_GruppiTariffari GT1 ON GT1.Codice=TT.GruppoTariffarioArrivo
 INNER JOIN PCS PCS1 ON PCS1.Codice=TT.PCSArrivo
 INNER JOIN TariffeAttiveVoci TV ON TV.IdTariffa=TT.IdTariffa
 INNER JOIN Voci V ON V.Codice=TV.Voce
 INNER JOIN TariffeAttiveFasce TF ON TF.IdVoce=TV.IdVoce 
 WHERE TC.AttivaPassiva='A' AND TC.Attivo='S';


-- dbo.GRD_DOC_TariffePassive source

ALTER VIEW [dbo].[GRD_DOC_TariffePassive] AS
SELECT TC.Codice
     , TC.Trasportatore
     , T.RagioneSociale AS RagioneSocialeTrasportatore
	 , TC.Descrizione
	 , TC.DataInizioValidita
	 , TC.DataFineValidita
	 , TC.Raggruppamento
	 , TT.TipoSpedizione
	 , TT.TipoMerce
	 , TT.TipoMezzo
	 , TT.Cliente
	 , C.RagioneSociale AS RagioneSocialeCliente
	 , TT.GruppoTariffarioPartenza
	 , GT.Descrizione AS DescrizioneGruppoTarifPartenza
	 , TT.PCSPartenza
	 , PCS.RagioneSociale AS RagSocPCSPartenza
	 , TT.MacroZonaArrivo
	 , ZM.Descrizione AS DescrizioneZMArrivo
	 , TT.ZonaArrivo
	 , Z.Descrizione AS DescrizioneZonaArrivo
	 , TT.GruppoTariffarioArrivo
	 , GT1.Descrizione AS DescrizioneGruppoTarifArrivo
	 , TT.PCSArrivo
	 , PCS1.RagioneSociale AS RagSocPCSArrivo
	 , TT.TipoDocumento
	 , TV.Voce
	 , V.Descrizione AS DescrizioneVoce
	 , TV.CampoCalcolo
	 , TV.ArrCampoCalcolo
	 , TV.ArrCampoCalcoloLimite
	 , TV.ArrCampoCalcoloOltre
	 , TV.ArrImporto
	 , TV.flgEccedenza
	 , TF.FasciaInferiore
	 , TF.FasciaSuperiore
	 , TF.Fisso
	 , TF.Variabile
	 , TF.Percentuale
	 , TT.IdTariffa
	 , TV.IdVoce
	 , TF.IdFascia
	 , CAST(TT.IdTariffa AS VARCHAR) + ' ' + CAST(TV.IdVoce AS VARCHAR) + ' ' + CAST(TF.IdFascia AS VARCHAR) AS Id
  FROM TariffeContratti TC
 INNER JOIN TariffePassiveTestata TT ON TC.Codice=TT.Contratto
 INNER JOIN Trasportatori T ON TC.Trasportatore=T.Codice
 INNER JOIN Clienti C ON TT.Cliente=C.Codice
 INNER JOIN PCS_GruppiTariffari GT ON GT.Codice=TT.GruppoTariffarioPartenza
 INNER JOIN PCS PCS ON PCS.Codice=TT.PCSPartenza
 INNER JOIN ZoneMacro ZM ON TT.MacroZonaArrivo=ZM.Codice
 INNER JOIN Zone Z ON Z.Codice=TT.ZonaArrivo
 INNER JOIN PCS_GruppiTariffari GT1 ON GT1.Codice=TT.GruppoTariffarioArrivo
 INNER JOIN PCS PCS1 ON PCS1.Codice=TT.PCSArrivo
 INNER JOIN TariffePassiveVoci TV ON TV.IdTariffa=TT.IdTariffa
 INNER JOIN Voci V ON V.Codice=TV.Voce
 INNER JOIN TariffePassiveFasce TF ON TF.IdVoce=TV.IdVoce 
 WHERE TC.AttivaPassiva='P' AND TC.Attivo='S';


-- dbo.GRD_DOC_VIAGGI_ULTIMOEVENTO source

ALTER VIEW [dbo].[GRD_DOC_VIAGGI_ULTIMOEVENTO] 
AS
SELECT	V.IdViaggio, 	
		VE.DataOraEvento ,
		VE.CodiceEvento,
		E.Descrizione as DescrizioneEvento,
		VE.Localita,
		VE.Provincia,			
		VE.Motrice  as Motrice, 
		MM.Targa as MotriceDescrizione,
		VE.RIMORCHIO1 as Rimorchio1, 
		MR.Targa as Rimorchio1Descrizione,
		Ve.Contenitore1 as Contenitore1,
		MC.Targa as Contenitore1Descrizione,		       
        VE.AUTISTA, 
        A1.RagioneSociale as Autista1EffettivoDescrizione,
        TipoSpedizione,
        TS.Descrizione as TipoSpedizioneDescrizione,
		V.TipoMerce ,
        TM.Descrizione as TipoMerceDescrizione,
        V.Cliente, 
        C.RagioneSociale as ClienteDescrizione    ,
		MM.Trasportatore,
		A1.Trasportatore as TRasportatore1   
FROM	Viaggi V 
		INNER JOIN  VW_VIAGGI_ULTIMOEVENTO WE ON V.IdViaggio = wE.IdViaggio 
		INNER JOIN Viaggi_Eventi vE ON VE.ID = WE.ID
		INNER JOIN Eventi E ON E.CODICE = VE.CODICEEVENTO
		LEFT JOIN MEZZI MM ON MM.CODICE =  VE.Motrice
		LEFT JOIN MEZZI MR ON MR.CODICE =  VE.RIMORCHIO1
		LEFT JOIN MEZZI MC ON MC.CODICE =  Ve.Contenitore1
		LEFT JOIN AUTISTI A1 ON A1.CODICE =  VE.AUTISTA
		LEFT JOIN CLIENTI C ON C.CODICE =  V.CLIENTE
		LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE =  V.TIPOSPEDIZIONE
		LEFT JOIN TIPIMERCE TM ON TM.CODICE =  V.TipoMerce
WHERE	V.Stato = 30;


-- dbo.GRD_DOC_Viaggi source

ALTER VIEW [dbo].[GRD_DOC_Viaggi] AS
SELECT IdViaggio,
          VS.Descrizione AS Stato,
          DataPartenzaPianificata,
          DataArrivoPianificata,
          DataPartenzaEffettiva,
          DataArrivoEffettiva,
          MotriceEffettiva AS Motrice,
          MM.Targa AS MotriceDescrizione,
          Rimorchio1Effettivo AS Rimorchio1,
          MR.Targa AS Rimorchio1Descrizione,
          Contenitore1Effettivo AS Contenitore1,
          MC.Targa AS Contenitore1Descrizione,
          Vettore,
          T.RagioneSociale AS VettoreDescrizione,
          Autista1Pianificato,
          A.RagioneSociale AS Autista1PianificatoDescrizione,
          Autista1Effettivo,
          A1.RagioneSociale AS Autista1EffettivoDescrizione,
          TipoSpedizione,
          TS.Descrizione AS TipoSpedizioneDescrizione,
          V.TipoMerce,
          TM.Descrizione AS TipoMerceDescrizione,
          V.Cliente,
          C.RagioneSociale AS ClienteDescrizione,
          PCSPartenza,
          PCSArrivo,
          KmPianificati,
          KmManuali,
          KmGPS,
          A1.Trasportatore,
          MM.Trasportatore AS Trasportatore1,
          V.Terminale,
          (
          SELECT ISNULL(SUM(ISNULL(Peso,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet,
          (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
          ) Numero_Spedizioni,
          V.Sagome,
          V.PalletPassivo,
          V.VolumePassivo,
          V.PALLETEFFETTIVI,
          V.SAGOMEEFFETTIVE,
          V.VolumeEffettivo,
		  V.TipoViaggio,
          V.FILLERALFA1,
          V.FILLERALFA2,
          V.FILLERALFA3,
          V.FILLERALFA4,
          V.FILLERALFA5,
          V.FILLERALFA6,
          V.FILLERALFA7,
          V.FILLERALFA8,
          V.FILLERALFA9,
          V.FILLERALFA10,
          V.FILLERDATA1,
          V.FILLERDATA2,
          V.FILLERDATA3,
          V.FILLERDATA4,
          V.FILLERDATA5,
	V.ZonaArrivo      
     FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
          LEFT JOIN MEZZI MM ON MM.CODICE = V.MOTRICEEFFETTIVA
          LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Effettivo
          LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Effettivo
          LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
          LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
          LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
          LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
          LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
          ;


-- dbo.GRD_DOC_Viaggi_Attivi source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Attivi] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT IdViaggio,
       VS.Descrizione AS Stato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,
       PCSPartenza,
       PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,
	   V.Note1, 
	   V.Note2,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
		SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Peso,
       (
        SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Volume,
       (
        SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Colli,
       (
        SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Pallet,
       (
        SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
       ) Numero_Spedizioni    ,
       V.Sagome,
       V.PalletPassivo,
       V.VolumePassivo,
       V.PALLETEFFETTIVI,
       V.SAGOMEEFFETTIVE,
       V.VolumeEffettivo,
	   V.TipoViaggio,
       (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
       ) Num_Spedizioni_Diretta,
	   (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
       ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	V.ZonaArrivo     
     FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
          LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
          LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato
          LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato
          LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
          LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
          LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
          LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
          LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
    WHERE V.Stato<20;


-- dbo.GRD_DOC_Viaggi_Attivita source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Attivita]
AS
SELECT * FROM (
SELECT	idViaggio,
		Cast(Id as varchar(15)) as Id, 
		'SERVIZIO' as Tipo,
		Sequenza, 		
		VT.Descrizione,
		DataServizio as Data,
		Localita,
		Km
FROM	VIAGGI_SERVIZI V 
		INNER JOIN VIAGGI_TIPISERVIZI VT ON VT.CODICE = V.TIPOSERVIZIO
UNION
SELECT	IdViaggio,
		Cast(Id as varchar(15)) as Id, 
		'ISTRUZIONE' as Tipo,
		Sequenza,
		Istruzione As Descrizone,
		NULL AS Data,
		'' as Localita,
		NULL AS Km
FROM	VIAGGI_ISTRUZIONI
UNION
SELECT	IdViaggio,
		Unibol as Id,
		CASE WHEN TipoServizio = 'C' THEN 'CARICO' ELSE 'SCARICO' END as Tipo,
		CASE WHEN SequenzaEffettiva >  0 THEN SequenzaEffettiva ELSE SequenzaPianificata END AS Sequenza,
		CASE WHEN TipoServizio = 'C' THEN PCSPARTENZA_RAGSOC ELSE PCSDESTINAZIONE_RAGSOC END AS Descrizione,
		DATAORAARRIVOEFFETTIVA AS Data,
		CASE WHEN TipoServizio = 'C' THEN PCSPARTENZA_LOCALITA ELSE PCSDESTINAZIONE_LOCALITA END AS Localita,
		KmManuali as Km
FROM	SPEDIZIONI
) T;


-- dbo.GRD_DOC_Viaggi_Cert_Sped source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Cert_Sped] AS
   SELECT idviaggio,
          s.unibol,
          tiposervizio,
          tb.descrizione AS tipobolladescrizione,
          cliente,
          c.ragionesociale AS clienteragionesociale,
          mittente,
          mittenteragionesociale,
          tipospedizione,
          ts.descrizione AS tipospedizionedescrizione,
          tipomerce,
          tm.descrizione AS tipomercedescrizione,
          pcspartenza,
          pcspartenza_ragsoc,
          pcspartenza_localita,
          pcspartenza_provincia,
          pcsdestinazione,
          pcsdestinazione_ragsoc,
          pcsdestinazione_localita,
          pcsdestinazione_provincia,
          ZonaSpedizione,
		  Corrispondente,
		  CORR.RagioneSociale AS CorrispondenteRagSoc,
          colli,
          pallet,
          peso,
          volume,
          s.numeroordine,
          s.numerobolla,
          s.databolla,
          s.dataordine,
          s.campocalcolo1,
          s.campocalcolo2,
          s.campocalcolo3,
          s.campocalcolo4,
          s.campocalcolo5,
          s.campocalcolo6,
          s.campocalcolo7,
          s.campocalcolo8,
          s.campocalcolo9,
          s.campocalcolo10,
          s.sequenzapianificata,
          s.sequenzaeffettiva,
          s.sequenzaoriginale,
          s.sequenzaeffettiva AS sequenza,
          se.dataoraevento,
          se.codiceevento,
          ev.tipoevento,
          CASE
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.OK'
                THEN 'DOC.SPED.OK'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato <> 98
                THEN 'DOC.SPED.KO'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato = 98
                THEN 'DOC.SPED.ANN'
             ELSE ''
          END AS styleset,
		  s.DestinazioneCliente,
		  s.FillerAlfa1,
		  s.FillerAlfa2,
		  s.FillerAlfa3,
		  s.FillerAlfa4,
		  s.FillerAlfa5,
		  s.FillerAlfa6,
		  s.FillerAlfa7,
		  s.FillerAlfa8,
		  s.FillerAlfa9,
		  s.FillerAlfa10,
		  s.FillerData1,
		  s.FillerData2,
		  s.FillerData3,
		  s.FillerData4,
		  s.FillerData5,
		  s.KmGPS,
		  s.KmManuali,
		  s.KmPianificati,
		  s.KmRicalcolati
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN spedizioni_eventi se ON se.unibol = s.unibol AND annullato = 'N' AND codiceevento LIKE 'ESI%'
          LEFT JOIN eventi ev ON ev.codice = se.codiceevento AND tipoevento LIKE 'SPEDIZIONE.ESITO%'
		  LEFT JOIN Corrispondenti CORR ON S.Corrispondente = CORR.Codice
    WHERE s.idviaggio IS NOT NULL;


-- dbo.GRD_DOC_Viaggi_Certificati source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Certificati] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT V.IdViaggio,
       V.Stato,
       VS.Descrizione AS DescrizioneStato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,	   
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,       	   
	   ISNULL(PCSPartenzaEffettivo,PCSPartenza) PCSPartenza,
	   ISNULL(PCSArrivoEffettivo,PCSArrivo) PCSArrivo,       
	   PCSPartenza PCSPartenzaPianificato,
       PCSArrivo PCSArrivoPianificato,
	   PCSPartenzaEffettivo,
       PCSArrivoEffettivo,
	   CAST(DataPartenzaEffettiva AS DATE) DataViaggio,
       KmPianificati,
       KmManuali,
       KmGPS,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
          SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet,
          (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
          ) Numero_Spedizioni,
          V.Sagome,
          V.PalletPassivo,
          V.VolumePassivo,
          V.PALLETEFFETTIVI,
          V.SAGOMEEFFETTIVE,
          V.VolumeEffettivo,
		  V.TipoViaggio,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
		  ) Num_Spedizioni_Diretta,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
		  ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	V.ZonaArrivo
  FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
  LEFT JOIN MEZZI MM ON MM.CODICE = V.MOTRICEEFFETTIVA
  LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Effettivo
  LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Effettivo
  LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
  LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
  LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
  LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
  LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
WHERE	V.STATO=50;


-- dbo.GRD_DOC_Viaggi_Chiusi source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Chiusi] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT IdViaggio,
       Stato,
       VS.Descrizione AS DescrizioneStato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,
       PCSPartenza,
       PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
          SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet,
          (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
          ) Numero_Spedizioni,
          V.Sagome,
          V.PalletPassivo,
          V.VolumePassivo,
          V.PALLETEFFETTIVI,
          V.SAGOMEEFFETTIVE,
          V.VolumeEffettivo,
		  V.TipoViaggio,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
		  ) Num_Spedizioni_Diretta,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
		  ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	   V.ZonaArrivo,
	   V.Note1, 
	   V.Note2
  FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
  LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
  LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato 
  LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato 
  LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
  LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
  LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
  LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
  LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
WHERE	STATO =20;


