-- dbo.GRD_DOC_Viaggi_Chiusi_Sped source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Chiusi_Sped] AS
SELECT	  S.IdViaggio,
          Unibol,
          TipoSERVIZIO,
          TB.Descrizione AS TipoBollaDescrizione,
          S.Cliente,
          C.RagioneSociale AS ClienteRagioneSociale,
          Mittente,
          MittenteRagioneSociale,
          S.TipoSpedizione,
          TS.Descrizione AS TipoSpedizioneDescrizione,
          S.TipoMerce,
          TM.Descrizione AS TipoMerceDescrizione,
          S.PCSPartenza,
          PCSPartenza_RagSoc,
          PCSPartenza_Localita,
          PCSPartenza_Provincia,
          PCSDestinazione,
          PCSDestinazione_RagSoc,
          PCSDestinazione_Localita,
          PCSDestinazione_Provincia,
          ZonaSpedizione,
		  Corrispondente,
		  CORR.RagioneSociale AS CorrispondenteRagSoc,
          Colli,
          Pallet,
          Peso,
          Volume,
          S.NUMEROORDINE,
          CASE WHEN S.NumeroBolla <> S.NumeroOrdine OR S.DataBolla <> S.DataOrdine THEN S.NumeroBolla ELSE NULL END AS NumeroBolla,
          CASE WHEN S.NumeroBolla <> S.NumeroOrdine OR S.DataBolla <> S.DataOrdine THEN S.DataBolla ELSE NULL END AS DataBolla,
          S.DataOrdine,
          S.CampoCalcolo1,
          S.CampoCalcolo2,
          S.CampoCalcolo3,
          S.CampoCalcolo4,
          S.CampoCalcolo5,
          S.CampoCalcolo6,
          S.CampoCalcolo7,
          S.CampoCalcolo8,
          S.CampoCalcolo9,
          S.CampoCalcolo10,          
          S.SEQUENZAPIANIFICATA,
          S.SEQUENZAEFFETTIVA,
          S.SEQUENZAORIGINALE,
          SS.DESCRIZIONE AS StatoOBCDescrizione,
		  s.DestinazioneCliente,
		  s.FillerAlfa1,
		  s.FillerAlfa2,
		  s.FillerAlfa3,
		  s.FillerAlfa4,
		  s.FillerAlfa5,
		  s.FillerAlfa6,
		  s.FillerAlfa7,
		  s.FillerAlfa8,
		  s.FillerAlfa9,
		  s.FillerAlfa10,
		  s.FillerData1,
		  s.FillerData2,
		  s.FillerData3,
		  s.FillerData4,
		  s.FillerData5,
		  s.KmGPS,
		  s.KmManuali,
		  s.KmPianificati,
		  s.KmRicalcolati,
		  s.DataConsegnaPrevista1 DataConsegna
FROM	Spedizioni S 		
		INNER JOIN TIPISERVIZI TB ON TB.CODICE = S.TIPOSERVIZIO
		INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
		LEFT JOIN CLIENTI C ON C.CODICE = S.CLIENTE	
		LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE  
		INNER JOIN VW_DOC_Spedizioni_StatiOBC SS ON SS.CODICE = S.STATOOBC
		LEFT JOIN Corrispondenti CORR ON S.Corrispondente = CORR.Codice
WHERE	S.IDVIAGGIO IS NOT NULL;


-- dbo.GRD_DOC_Viaggi_Eventi source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Eventi]
AS
SELECT	V.Id,
		V.IdViaggio, 
		V.DAtaOraEvento,
		CASE WHEN V.AUTISTA IS NULL THEN E.Descrizione + ISNULL(' ('+ V.NOTEINTERNE + ')','') ELSE E.Descrizione END AS  CodiceEvento,
		CASE WHEN S.PCSDestinazione_RagSoc IS NOT NULL THEN S.PCSDestinazione_RagSoc 
			 WHEN VS.TIPOSERVIZIO IS NOT NULL THEN TS.DESCRIZIONE
			 ELSE '' END   AS RagSoc,
		V.Localita,
		V.Provincia,
		V.KmManuali,
		A.RagioneSociale Autista,
		V.Terminale,
		V.Motrice,
		M1.Targa MotriceDescrizione,
		V.Rimorchio1,
		M2.Targa RimorchioDescrizione,
		V.Contenitore1,
		M3.Targa ContenitoreDescrizione,
		V.UniBol ,
		V.IDSERVIZIO,
		V.IDRIFORNIMENTO,
		CASE WHEN V.UNIBOL IS NOT NULL THEN S.FILLERALFA10 
			 WHEN V.IDSERVIZIO IS NOT NULL THEN VS.VALORE5
			 WHEN V.IDRIFORNIMENTO IS NOT NULL THEN CAST(MR.LITRI AS VARCHAR) + ' LT - ' + CAST(MR.LITRIADDITIVO AS VARCHAR) + ' ADB' 
			 ELSE '' END AS Quantita,
		V.LATITUDINE,
		V.LONGITUDINE,
		CASE WHEN V.Latitudine IS NOT NULL AND V.Longitudine IS NOT NULL THEN 'S' ELSE 'N' END AS GPS,
		S.Evento_CodiceEsito AS ESITO,
		0 AS ORDERBY
FROM    Viaggi_Eventi V
		INNER JOIN EVENTI E ON V.CodiceEvento = E.Codice
		LEFT JOIN AUTISTI A ON A.Codice = V.Autista
		LEFT JOIN MEZZI M1 ON M1.Codice = V.Motrice
		LEFT JOIN MEZZI M2 ON M2.Codice = V.Rimorchio1 
		LEFT JOIN MEZZI M3 ON M3.Codice = V.Contenitore1 
		LEFT JOIN VW_SPEDIZIONI S ON S.UNIBOL = V.UNIBOL
		LEFT JOIN VIAGGI_SERVIZI VS ON VS.ID = V.IDSERVIZIO
		LEFT JOIN MEZZI_RIFORNIMENTI MR ON MR.ID = V.IDRIFORNIMENTO		
		LEFT JOIN VIAGGI_TIPISERVIZI TS ON TS.CODICE = VS.TIPOSERVIZIO;


-- dbo.GRD_DOC_Viaggi_InCorso_Sped source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_InCorso_Sped] AS
   SELECT idviaggio,
          s.unibol,
          tiposervizio,
          tb.descrizione AS tipobolladescrizione,
          cliente,
          c.ragionesociale AS clienteragionesociale,
          mittente,
          mittenteragionesociale,
          tipospedizione,
          ts.descrizione AS tipospedizionedescrizione,
          tipomerce,
          tm.descrizione AS tipomercedescrizione,
          pcspartenza,
          pcspartenza_ragsoc,
          pcspartenza_localita,
          pcspartenza_provincia,
          pcsdestinazione,
          pcsdestinazione_ragsoc,
          pcsdestinazione_localita,
          pcsdestinazione_provincia,
          ZonaSpedizione,
		  Corrispondente,
	      CORR.RagioneSociale AS CorrispondenteRagSoc,
          colli,
          pallet,
          peso,
          volume,
          s.numeroordine,
          s.numerobolla,
          s.databolla,
          s.dataordine,
          s.campocalcolo1,
          s.campocalcolo2,
          s.campocalcolo3,
          s.campocalcolo4,
          s.campocalcolo5,
          s.campocalcolo6,
          s.campocalcolo7,
          s.campocalcolo8,
          s.campocalcolo9,
          s.campocalcolo10,
          s.sequenzapianificata,
          s.sequenzaeffettiva,
          s.sequenzaoriginale,
          CASE
             WHEN S.SEQUENZAEFFETTIVA > 0
                THEN S.SEQUENZAEFFETTIVA
             ELSE S.SEQUENZAPIANIFICATA + 1000
          END AS Sequenza,
          se.dataoraevento,
          se.codiceevento,
          ev.tipoevento,
          CASE
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.OK'
                THEN 'DOC.SPED.OK'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato <> 98
                THEN 'DOC.SPED.KO'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato = 98
                THEN 'DOC.SPED.ANN'
             ELSE ''
          END AS styleset,
		  s.DestinazioneCliente,
		  s.FillerAlfa1,
		  s.FillerAlfa2,
		  s.FillerAlfa3,
		  s.FillerAlfa4,
		  s.FillerAlfa5,
		  s.FillerAlfa6,
		  s.FillerAlfa7,
		  s.FillerAlfa8,
		  s.FillerAlfa9,
		  s.FillerAlfa10,
		  s.FillerData1,
		  s.FillerData2,
		  s.FillerData3,
		  s.FillerData4,
		  s.FillerData5,
		  s.KmGPS,
		  s.KmManuali,
		  s.KmPianificati,
		  s.KmRicalcolati,
		   (SELECT SUM(SC.ImportoArrotondato) FROM Spedizioni_Costi SC WHERE SC.RecordZZ='N' AND SC.Unibol=S.Unibol) AS CostiSpedizioni,
	      (SELECT SUM(SR.ImportoArrotondato) FROM Spedizioni_Ricavi SR WHERE SR.RecordZZ='N' AND SR.Unibol=S.Unibol) AS RicaviSpedizioni
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN spedizioni_eventi se ON se.unibol = s.unibol AND annullato = 'N' AND codiceevento LIKE 'ESI%'
          LEFT JOIN eventi ev ON ev.codice = se.codiceevento AND tipoevento LIKE 'SPEDIZIONE.ESITO%'
		  LEFT JOIN Corrispondenti CORR ON S.Corrispondente = CORR.Codice
    WHERE s.idviaggio IS NOT NULL;


-- dbo.GRD_DOC_Viaggi_Incorso source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Incorso] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT IdViaggio,
       Stato,
       VS.Descrizione AS DescrizioneStato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,
       PCSPartenza,
       PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
          SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Peso,
       (
          SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Volume,
       (
          SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Colli,
       (
          SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Pallet,
       (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
       ) Numero_Spedizioni,
       (
			SELECT 
				COUNT(*) 
			FROM 
				CTE_Spedizioni S
				LEFT JOIN (Spedizioni_Eventi SE 
				INNER JOIN Eventi EV ON EV.Codice = SE.CodiceEvento AND TipoEvento LIKE 'SPEDIZIONE.ESITO%')
				ON SE.Unibol = S.unibol AND Annullato = 'N' AND CodiceEvento LIKE 'ESI%'
			WHERE 
				S.IdViaggio = V.IdViaggio AND SE.CodiceEvento IS NULL
       ) Numero_Spedizioni_DaEsitare,                   
       V.Sagome,
       V.PalletPassivo,
       V.VolumePassivo,
       V.PALLETEFFETTIVI,
       V.SAGOMEEFFETTIVE,
       V.VolumeEffettivo,
	   V.TipoViaggio,
       (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
       ) Num_Spedizioni_Diretta,
	   (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
       ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	   V.ZonaArrivo,
       V.Note1, 
	   V.Note2
  FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
  LEFT JOIN MEZZI MM ON MM.CODICE = V.MOTRICEEFFETTIVA
  LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Effettivo
  LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Effettivo
  LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
  LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
  LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
  LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
  LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
WHERE	STATO =30;


-- dbo.GRD_DOC_Viaggi_Istruzioni source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Istruzioni]
AS
SELECT	Id,
		IdViaggio, 
		Sequenza,
		Istruzione	
FROM    Viaggi_Istruzioni;


