-- dbo.GRD_DOC_Viaggi_Spedizioni source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Spedizioni] AS
SELECT IdViaggio,
       Unibol,
       TipoSERVIZIO,
       TB.Descrizione AS TipoBollaDescrizione,
       Cliente,
       C.RagioneSociale AS ClienteRagioneSociale,
       Mittente,
       MittenteRagioneSociale,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       PCSPartenza,
       PCSPartenza_RagSoc,
       PCSPartenza_Localita,
       PCSPartenza_Provincia,
       PCSDestinazione,
       PCSDestinazione_RagSoc,
       PCSDestinazione_Localita,
       PCSDestinazione_Provincia,
	   ZonaSpedizione,
       Corrispondente,
	   CORR.RagioneSociale AS CorrispondenteRagSoc,
       Colli,
       Pallet,
       Peso,
       Volume,
       S.NUMEROORDINE,
       S.NUMEROBOLLA,
       S.DataBolla,
       S.DataOrdine,
       S.CampoCalcolo1,
       S.CampoCalcolo2,
       S.CampoCalcolo3,
       S.CampoCalcolo4,
       S.CampoCalcolo5,
       S.CampoCalcolo6,
       S.CampoCalcolo7,
       S.CampoCalcolo8,
       S.CampoCalcolo9,
       S.CampoCalcolo10,          
       S.SEQUENZAPIANIFICATA,
       S.SEQUENZAEFFETTIVA,
       S.SEQUENZAORIGINALE,
	   (SELECT SUM(SC.ImportoArrotondato) FROM Spedizioni_Costi SC WHERE SC.RecordZZ='N' AND SC.Unibol=S.Unibol) AS CostiSpedizioni,
	   (SELECT SUM(SR.ImportoArrotondato) FROM Spedizioni_Ricavi SR WHERE SR.RecordZZ='N' AND SR.Unibol=S.Unibol) AS RicaviSpedizioni,
	   s.DestinazioneCliente,
	   s.FillerAlfa1,
	   s.FillerAlfa2,
	   s.FillerAlfa3,
	   s.FillerAlfa4,
	   s.FillerAlfa5,
	   s.FillerAlfa6,
	   s.FillerAlfa7,
	   s.FillerAlfa8,
	   s.FillerAlfa9,
	   s.FillerAlfa10,
	   s.FillerData1,
	   s.FillerData2,
	   s.FillerData3,
	   s.FillerData4,
	   s.FillerData5,
	   s.KmGPS,
	   s.KmManuali,
	   s.KmPianificati,
	   s.KmRicalcolati,
	   s.DataConsegnaPrevista1 DataConsegna,
	   s.NoteConsegnaPrevista, 
	   s.NoteConsegnaConcordata
  FROM Spedizioni S
 INNER JOIN TIPISERVIZI TB ON TB.CODICE = S.TIPOSERVIZIO
 INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = S.TIPOSPEDIZIONE
  LEFT JOIN CLIENTI C ON C.CODICE = S.CLIENTE	
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = S.TIPOMERCE
  LEFT JOIN Corrispondenti CORR ON S.Corrispondente = CORR.Codice
 WHERE S.IDVIAGGIO IS NOT NULL;


-- dbo.GRD_DOC_Viaggi_TROVA source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_TROVA] AS
SELECT V.IdViaggio,
	   V.Stato,
       VS.Descrizione AS StatoDescrizione,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
	   ISNULL(DataPartenzaEffettiva, DataPartenzaPianificata) DataPartenza,
	   ISNULL(DataArrivoEffettiva, DataArrivoPianificata) DataArrivo,
       MotriceEffettiva,       
       Rimorchio1Effettivo,       
       Contenitore1Effettivo,       
	   MotricePianificata ,       
       Rimorchio1Pianificato,       
       Contenitore1Pianificato,
	   ISNULL(MotriceEffettiva, MotricePianificata) Motrice,
	   ISNULL(Rimorchio1Effettivo, Rimorchio1Pianificato) Rimorchio,
	   ISNULL(Contenitore1Effettivo, Contenitore1Pianificato) Contenitore,       
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       ISNULL(Autista1Effettivo, Autista1Pianificato) Autista,
       A.RagioneSociale AS Autista1Descrizione,              
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,       
	   ISNULL(V.PCSPartenzaEffettivo, V.PCSPartenza) PCSPartenza,
	   PCS1.RagioneSociale PCSPartenzaRagSoc,
	   PCS1.Localita PCSPartenzaLocalita,
       ISNULL(V.PCSArrivoEffettivo, V.PCSArrivo) PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,       
        V.Terminale,
        (
        SELECT ISNULL(SUM(ISNULL(Peso,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
        ) Peso,
        (
        SELECT ISNULL(SUM(ISNULL(Volume,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
        ) Volume,
        (
        SELECT ISNULL(SUM(ISNULL(Colli,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
        ) Colli,
        (
        SELECT ISNULL(SUM(ISNULL(Pallet,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
        ) Pallet,
        (
        SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
        ) Numero_Spedizioni,
		 (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
       ) Num_Spedizioni_Diretta,
	   (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
       ) Num_Spedizioni_Distribuzione,
        V.Sagome,
        V.PalletPassivo,
        V.VolumePassivo,
        V.PALLETEFFETTIVI,
        V.SAGOMEEFFETTIVE,
        V.VolumeEffettivo,
		V.TipoViaggio,
        V.FILLERALFA1,
        V.FILLERALFA2,
        V.FILLERALFA3,
        V.FILLERALFA4,
        V.FILLERALFA5,
        V.FILLERALFA6,
        V.FILLERALFA7,
        V.FILLERALFA8,
        V.FILLERALFA9,
        V.FILLERALFA10,
        V.FILLERDATA1,
        V.FILLERDATA2,
        V.FILLERDATA3,
        V.FILLERDATA4,
        V.FILLERDATA5,
		V.ZonaArrivo,
		V.idViaggioHost
     FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice          
          LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
          LEFT JOIN AUTISTI A ON A.CODICE = ISNULL(V.Autista1Effettivo, V.Autista1Pianificato)
          LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
          LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
		  LEFT JOIN PCS PCS1 ON PCS1.CODICE=ISNULL(V.PCSPartenzaEffettivo, V.PCSPartenza)
          ;


-- dbo.GRD_DOC_Viaggi_Terminati source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Terminati] AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT IdViaggio,
       Stato,
       VS.Descrizione AS DescrizioneStato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
	   CAST(DataPartenzaEffettiva AS DATE) DataViaggio,
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,
       PCSPartenza,
       PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
          SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet,
          (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
          ) Numero_Spedizioni,
          V.Sagome,
          V.PalletPassivo,
          V.VolumePassivo,
          V.PALLETEFFETTIVI,
          V.SAGOMEEFFETTIVE,
          V.VolumeEffettivo,
		  V.TipoViaggio,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
		  ) Num_Spedizioni_Diretta,
		  (
			SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
		  ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	V.ZonaArrivo
  FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
  LEFT JOIN MEZZI MM ON MM.CODICE = V.MOTRICEEFFETTIVA
  LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Effettivo
  LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Effettivo
  LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
  LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
  LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
  LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
  LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
  LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
WHERE	STATO=40;


-- dbo.GRD_DOC_Viaggi_Terminati_Sped source

ALTER VIEW [dbo].[GRD_DOC_Viaggi_Terminati_Sped] AS
   SELECT idviaggio,
          s.unibol,
          tiposervizio,
          tb.descrizione AS tipobolladescrizione,
          cliente,
          c.ragionesociale AS clienteragionesociale,
          mittente,
          mittenteragionesociale,
          tipospedizione,
          ts.descrizione AS tipospedizionedescrizione,
          tipomerce,
          tm.descrizione AS tipomercedescrizione,
          pcspartenza,
          pcspartenza_ragsoc,
          pcspartenza_localita,
          pcspartenza_provincia,
          pcsdestinazione,
          pcsdestinazione_ragsoc,
          pcsdestinazione_localita,
          pcsdestinazione_provincia,
          ZonaSpedizione,
		  Corrispondente,
		  CORR.RagioneSociale AS CorrispondenteRagSoc,
          colli,
          pallet,
          peso,
          volume,
          s.numeroordine,
          s.numerobolla,
          s.databolla,
          s.dataordine,
          s.campocalcolo1,
          s.campocalcolo2,
          s.campocalcolo3,
          s.campocalcolo4,
          s.campocalcolo5,
          s.campocalcolo6,
          s.campocalcolo7,
          s.campocalcolo8,
          s.campocalcolo9,
          s.campocalcolo10,
          s.sequenzapianificata,
          s.sequenzaeffettiva,
          s.sequenzaoriginale,
          s.sequenzaeffettiva AS sequenza,
          se.dataoraevento,
          se.codiceevento,
          ev.tipoevento,
          CASE
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.OK'
                THEN 'DOC.SPED.OK'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato <> 98
                THEN 'DOC.SPED.KO'
             WHEN ev.tipoevento = 'SPEDIZIONE.ESITO.KO' AND stato = 98
                THEN 'DOC.SPED.ANN'
             ELSE ''
          END AS styleset,
		  s.DestinazioneCliente,
		  s.FillerAlfa1,
		  s.FillerAlfa2,
		  s.FillerAlfa3,
		  s.FillerAlfa4,
		  s.FillerAlfa5,
		  s.FillerAlfa6,
		  s.FillerAlfa7,
		  s.FillerAlfa8,
		  s.FillerAlfa9,
		  s.FillerAlfa10,
		  s.FillerData1,
		  s.FillerData2,
		  s.FillerData3,
		  s.FillerData4,
		  s.FillerData5,
		  s.KmGPS,
		  s.KmManuali,
		  s.KmPianificati,
		  s.KmRicalcolati,
		  (SELECT SUM(SC.ImportoArrotondato) FROM Spedizioni_Costi SC WHERE SC.RecordZZ='N' AND SC.Unibol=S.Unibol) AS CostiSpedizioni,
	      (SELECT SUM(SR.ImportoArrotondato) FROM Spedizioni_Ricavi SR WHERE SR.RecordZZ='N' AND SR.Unibol=S.Unibol) AS RicaviSpedizioni
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN spedizioni_eventi se ON se.unibol = s.unibol AND annullato = 'N' AND codiceevento LIKE 'ESI%'
          LEFT JOIN eventi ev ON ev.codice = se.codiceevento AND tipoevento LIKE 'SPEDIZIONE.ESITO%'
		  LEFT JOIN Corrispondenti CORR ON S.Corrispondente = CORR.Codice
    WHERE s.idviaggio IS NOT NULL;


