-- dbo.GRD_FAT_FattAttive_Testata source

ALTER VIEW [dbo].[GRD_FAT_FattAttive_Testata]
AS
SELECT 	T.*,
		T.Imponibile1+T.Imposta1 TotaleFattura
FROM
(
SELECT  IdFattura, 
		TipoDocumento,		
		Sezionale, 
		S.Descrizione as SezionaleDescrizione,
		Numero, 
		Data, 
		Cliente, 
		C.RagioneSociale,
		F.TipoPagamento,
		CP.Descrizione as TipoPagamentoDescrizione,  
		DataScadenza1, 
		DataScadenza2, 
		DataScadenza3, 
		Contabilizzata, 
        DataContabilizzazione, 
        ErroreContabilizzazione,
		XMLContabilizzata, 
        XMLDataContabilizzazione, 
        XMLErroreContabilizzazione,
		(
			SELECT TOP 1 Imponibile 
			FROM Fatture_Passive_Iva I
			WHERE I.IdFattura=F.IdFattura 			
        ) Imponibile1,
        (
			SELECT TOP 1 Aliquota
			FROM Fatture_Passive_Iva I
			WHERE I.IdFattura=F.IdFattura 			
        ) Aliquota1,
        (
			SELECT TOP 1 Imposta
			FROM Fatture_Passive_Iva I
			WHERE I.IdFattura=F.IdFattura 			
        ) Imposta1
FROM    Fatture_Attive_Testata F
		INNER JOIN Sezionali S ON S.Codice = F.Sezionale
		INNER JOIN Clienti C ON C.Codice = F.Cliente
		INNEr JOIN CodiciPagamento CP ON CP.Codice = F.TipoPagamento
) T;


