		INNER JOIN CodiciPagamento CP ON CP.Codice = F.TipoPagamento
) T;


-- dbo.GRD_FAT_FattureAttive_Pilota source

ALTER VIEW [dbo].[GRD_FAT_FattureAttive_Pilota]
AS
SELECT  Progressivo, 
		Cliente,
		C.RagioneSociale as ClienteRagioneSociale,	
		FatturaViaggi, 
		FatturaSpedizioni, 
		DataInizio, 
		DataFine, 
		DataDocumento, 
		Sezionale, 
		S.Descrizione as SezionaleDescrizione,
		TipoPagamento, 
		TP.Descrizione as TipoPagamentoDescrizione,
		ClienteOperativo, 
		C1.RagioneSociale as ClienteOperativoRagioneSociale,	
		Mittente, 
		C2.RagioneSociale as MittenteRagioneSociale,	
		TipoSpedizione, 
		TS.Descrizione as TipoSpedizioneDescrizione,
		TipoMerce, 
		TM.Descrizione as TipoMerceDescrizione,
		ZonaArrivo, 
		Z.Descrizione as ZonaArrivoDescrizione,
		PCSPartenza, 
		PP.RagioneSociale as PCSPartenzaRagioneSociale,	
		PCSArrivo, 
		PA.RagioneSociale as PCSArrivoRagioneSociale,	
		FiltriAggiuntivi, 
		DataOraInizioEsecuzione, 
		DataOraFineEsecuzione, 
		Errore, 
		IdFatturaGenerata,
		F.DatIns DataInserimento		
FROM    Fatture_Attive_Pilota F
		INNER JOIN CLIENTI C ON C.CODICE = F.Cliente
		INNER JOIN SEZIONALI S ON S.CODICE = F.Sezionale
		LEFT JOIN CLIENTI C1 ON C1.CODICE = F.ClienteOperativo
		LEFT JOIN CLIENTI C2 ON C2.CODICE = F.Mittente
		LEFT JOIN VW_TIPOPAGAMENTO TP ON TP.CODICE = F.TipoPagamento
		LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = F.TipoSpedizione
		LEFT JOIN TIPIMERCE TM ON TM.CODICE = F.TipoMerce
		LEFT JOIN ZONESPEDIZIONE Z ON Z.CODICE = F.ZonaArrivo
		LEFT JOIN PCS PP ON TM.CODICE = F.PCSPartenza
		LEFT JOIN PCS PA ON Z.CODICE = F.PCSArrivo;


-- dbo.GRD_FAT_FatturePassive_Pilota source

ALTER VIEW [dbo].[GRD_FAT_FatturePassive_Pilota]
AS
SELECT  Progressivo, 
		Trasportatore,
		T.RagioneSociale as TrasportatoreRagioneSociale,	
		FatturaViaggi, 
		FatturaSpedizioni, 
		DataInizio, 
		DataFine, 
		DataDocumento, 
		Sezionale, 
		S.Descrizione as SezionaleDescrizione,
		TipoPagamento, 
		TP.Descrizione as TipoPagamentoDescrizione,
		ClienteOperativo, 
		C1.RagioneSociale as ClienteOperativoRagioneSociale,	
		Mittente, 
		C2.RagioneSociale as MittenteRagioneSociale,	
		TipoSpedizione, 
		TS.Descrizione as TipoSpedizioneDescrizione,
		TipoMerce, 
		TM.Descrizione as TipoMerceDescrizione,
		ZonaArrivo, 
		Z.Descrizione as ZonaArrivoDescrizione,
		PCSPartenza, 
		PP.RagioneSociale as PCSPartenzaRagioneSociale,	
		PCSArrivo, 
		PA.RagioneSociale as PCSArrivoRagioneSociale,	
		FiltriAggiuntivi, 
		DataOraInizioEsecuzione, 
		DataOraFineEsecuzione, 
		Errore, 
		IdFatturaGenerata		,
		F.DatIns DataInserimento		
FROM    Fatture_Passive_Pilota F
		INNER JOIN TRASPORTATORI T ON T.CODICE = F.Trasportatore
		INNER JOIN SEZIONALI S ON S.CODICE = F.Sezionale
		LEFT JOIN CLIENTI C1 ON C1.CODICE = F.ClienteOperativo
		LEFT JOIN CLIENTI C2 ON C2.CODICE = F.Mittente
		LEFT JOIN VW_TIPOPAGAMENTO TP ON TP.CODICE = F.TipoPagamento
		LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = F.TipoSpedizione
		LEFT JOIN TIPIMERCE TM ON TM.CODICE = F.TipoMerce
		LEFT JOIN ZONESPEDIZIONE Z ON Z.CODICE = F.ZonaArrivo
		LEFT JOIN PCS PP ON TM.CODICE = F.PCSPartenza
		LEFT JOIN PCS PA ON Z.CODICE = F.PCSArrivo;


