-- dbo.GRD_GIRISTANDARD_DETTAGLI source

ALTER VIEW [dbo].[GRD_GIRISTANDARD_DETTAGLI] AS
SELECT G.*
     , pcs.ragionesociale
	 , pcs.indirizzo
	 , pcs.cap
	 , pcs.Localita
	 , pcs.Provincia 
	 , C.RagioneSociale AS RagSocCorrispondente
	 , C.Localita AS LocalitaCorrispondente
