-- dbo.GRD_GIRISTANDARD_TESTATA source

ALTER VIEW [dbo].[GRD_GIRISTANDARD_TESTATA]
AS
SELECT	GIRISTANDARD_TESTATA.*, 
			CASE
				WHEN GIRISTANDARD_TESTATA.GiornoPartenza = '1'
					THEN 'Lunedì'
				when GIRISTANDARD_TESTATA.GiornoPartenza = '2'
					THEN 'Martedì'
				WHEN GIRISTANDARD_TESTATA.GiornoPartenza = '3'
					THEN 'Mercoledì'
				when GIRISTANDARD_TESTATA.GiornoPartenza = '4'
					THEN 'Giovedì'
				WHEN GIRISTANDARD_TESTATA.GiornoPartenza = '5'
					THEN 'Venerdì'
				when GIRISTANDARD_TESTATA.GiornoPartenza = '6'
					THEN 'Sabato'
				when GIRISTANDARD_TESTATA.GiornoPartenza = '7'
					THEN 'Domenica'
			END DescGiornoPartenza,
			CASE
				WHEN GIRISTANDARD_TESTATA.GiornoCutOff = '1'
					THEN 'Lunedì'
				when GIRISTANDARD_TESTATA.GiornoCutOff = '2'
					THEN 'Martedì'
				WHEN GIRISTANDARD_TESTATA.GiornoCutOff = '3'
					THEN 'Mercoledì'
				when GIRISTANDARD_TESTATA.GiornoCutOff = '4'
					THEN 'Giovedì'
				WHEN GIRISTANDARD_TESTATA.GiornoCutOff = '5'
					THEN 'Venerdì'
				when GIRISTANDARD_TESTATA.GiornoCutOff = '6'
					THEN 'Sabato'
				when GIRISTANDARD_TESTATA.GiornoCutOff = '7'
					THEN 'Domenica'
			END DescGiornoCutOff, 
			(select ragionesociale from PCS p where p.Codice = GIRISTANDARD_TESTATA.depositopartenza)  rgsdepositopartenza,
			(select indirizzo from PCS p where p.Codice = GIRISTANDARD_TESTATA.depositopartenza) indirizzodepositopartenza,
			(select ragionesociale from PCS p where p.Codice = GIRISTANDARD_TESTATA.depositoarrivo) rgsdepositoarrivo,
			(select indirizzo from PCS p where p.Codice = GIRISTANDARD_TESTATA.depositoarrivo) indirizzodepositoarrivo
			  
FROM	GIRISTANDARD_TESTATA;


-- dbo.GRD_GMB_BANCALIGIACENZE source

ALTER VIEW [dbo].[GRD_GMB_BANCALIGIACENZE] AS 
SELECT	G.*,
		CASE 
		WHEN G.TipoSoggetto ='C' THEN 'Cliente'
		WHEN G.TipoSoggetto ='H' THEN 'Corrispondente'
		WHEN G.TipoSoggetto ='D' THEN 'Destinazione'
		WHEN G.TipoSoggetto ='V' THEN 'Vettore'
		WHEN G.TipoSoggetto ='F' THEN 'Filiale'
		END TipoSoggetto_descrizione,
		S.ragionesociale Soggetto_RagioneSociale,
		' ' dummy
  FROM BancaliGiacenze G
  LEFT JOIN VW_GMB_SOGGETTI S ON G.Soggetto=S.codice AND G.TipoSoggetto=S.tipoanagrafica;


-- dbo.GRD_GMB_BANCALIMOVIMENTI source

ALTER VIEW [dbo].[GRD_GMB_BANCALIMOVIMENTI] AS 
SELECT M.*,
	   CASE 
	   WHEN M.TipoSoggetto1 ='C' THEN 'Cliente'
	   WHEN M.TipoSoggetto1 ='H' THEN 'Corrispondente'
	   WHEN M.TipoSoggetto1 ='D' THEN 'Destinazione'
	   WHEN M.TipoSoggetto1 ='V' THEN 'Vettore'
	   WHEN M.TipoSoggetto1 ='F' THEN 'Filiale'
	   END TipoSoggetto1_descrizione,
	   CASE 
	   WHEN M.TipoSoggetto2 ='C' THEN 'Cliente'
	   WHEN M.TipoSoggetto2 ='H' THEN 'Corrispondente'
	   WHEN M.TipoSoggetto2 ='D' THEN 'Destinazione'
	   WHEN M.TipoSoggetto2 ='V' THEN 'Vettore'
	   WHEN M.TipoSoggetto2 ='F' THEN 'Filiale'
	   END TipoSoggetto2_descrizione,
       S1.ragionesociale Soggetto1_RagioneSociale,
       S2.ragionesociale Soggetto2_RagioneSociale,
       BC.Descrizione Causale_Descrizione      
  FROM BancaliMovimenti M LEFT JOIN VW_GMB_SOGGETTI S1 ON M.Soggetto1=S1.codice AND M.TipoSoggetto1=s1.tipoanagrafica 
  LEFT JOIN VW_GMB_SOGGETTI S2 ON M.Soggetto2=S2.codice AND M.TipoSoggetto2=s2.tipoanagrafica 
  LEFT JOIN BancaliCausali BC on BC.Codice = M.Causale;


-- dbo.GRD_GMB_ESTRATTOCONTOBANCALI source

ALTER VIEW [dbo].[GRD_GMB_ESTRATTOCONTOBANCALI] AS
SELECT	Z.*,
		S.ragionesociale Soggetto_RagioneSociale, 
		S.Localita Soggetto_Localita,
		S.Provincia Soggetto_Provincia,
		S.Cap Soggetto_Cap,
		S.Nazione Soggetto_Nazione,
		S.Indirizzo Soggetto_Indirizzo,
		M.IdRiferimento1,
		M.DataRiferimento1,
		M.IdRiferimento2,
		M.DataRiferimentO2,
		CASE 
			WHEN Z.TipoRecord='1SI' THEN 'SALDO INIZIALE'
			WHEN Z.TipoRecord='9SF' THEN 'SALDO FINALE'
			ELSE S.ragionesociale + (Z.Soggetto)
		END SoggettoCodRagSoc,
		CASE
			WHEN Z.TipoSoggettocontroparte = 'D' THEN 'DESTINAT.'
			WHEN Z.TipoSoggettocontroparte = 'F' THEN 'FILIALE'
			WHEN Z.TipoSoggettocontroparte = 'H' THEN 'CORRISP.'
			WHEN Z.TipoSoggettocontroparte = 'C' THEN 'CLIENTE'
			WHEN Z.TipoSoggettocontroparte = 'V' THEN 'VETTORE'
			ELSE ''
		END TipoSoggettoControparteDesc,
		z.Localita + ' (' + S.provincia + ')' LocalitaProvControparte,
		ISNULL(CONVERT(VARCHAR(20), Z.TipoBancale), 'TUTTI I TIPI BANCALE')  TipoBancale2
FROM ZSTAT_RPTGMB01 Z LEFT JOIN VW_GMB_SOGGETTI S ON S.tipoanagrafica=Z.TipoSoggetto AND S.codice=Z.Soggetto
LEFT JOIN BancaliMovimenti M ON M.Id=Z.IdMovimento;


-- dbo.GRD_Giacenze source

--------------------------------------------------------------------------------------------------------
--
-- C R E A Z I O N E   V I S T A   P E R   L A   G R I G L I A   D E L L E   G I A C E N Z E
--
-------------------------------------------------------------------------------------------------------- 
ALTER VIEW [dbo].[GRD_Giacenze]
AS
SELECT  Id, 
		G.Stato, 
		CASE WHEN G.Stato = 10 THEN 'IN CORSO' ELSE 'CHIUSA' END Stato_Descrizione,
		DataApertura, 
		DataChiusura, 
		GiorniGiacenza, 
		G.UnibolMaster, 
		UnibolApertura, 
		ProgressivoApertura, 
		UnibolChiusura, 
		ProgressivoChiusura, 
		G.Cliente, 
		G.ClienteFatturazione, 
		G.Corrispondente, 
		G.Trasportatore, 
		TrasportatoreFatturazione, 		
		G.IdFatturaAttiva, 
		G.IdFatturaPassiva, 		
		Note1, 
		Note2, 
		Note3, 
		G.Peso, 
		G.Colli, 
		G.Pallet, 
		G.Volume, 
		CausaleChiusura, 
		NoteChiusura,    
		S.PCSDestinazione, 
		S.PCSDestinazione_Cap, 
		S.PCSDestinazione_Indirizzo, 
		S.PCSDestinazione_Localita, 
		S.PCSDestinazione_Nazione, 
		S.PCSDestinazione_Provincia, 
		S.PCSDestinazione_RagSoc,
		CL.RagioneSociale Cliente_RagioneSociale, 
		CL.Provincia Cliente_Provincia, 
		CL.Localita Cliente_Localita, 
		CL.Nazione Cliente_Nazione,     
		Cor.RagioneSociale Corrisp_RagioneSociale, 
		Cor.Provincia Corrisp_Provincia, 
		Cor.Localita Corrisp_Localita, 
		Cor.Nazione Corrisp_Nazione, 
		T.RagioneSociale Trasp_RagioneSociale
FROM	Giacenze G
		INNER JOIN Spedizioni S ON S.unibol=G.UnibolApertura 
		INNER JOIN Clienti CL ON CL.Codice =G.Cliente 
		LEFT JOIN PCS Cor ON Cor.Codice =G.Corrispondente 
		LEFT JOIN Trasportatori T ON T.Codice =G.Trasportatore;


-- dbo.GRD_Giacenze_Costi source

--------------------------------------------------------------------------------------------------------
--
-- C R E A Z I O N E   V I S T A   P E R   L A   G R I G L I A   D E L L E   G I A C E N Z E   C O S T I
--
-------------------------------------------------------------------------------------------------------- 
ALTER VIEW  [dbo].[GRD_Giacenze_Costi]
AS
SELECT	C.*, 
		V.Descrizione VOCE_Descrizione,
		CC.Descrizione CampoCalcolo_Descrizione,
		C.RecordZZ RecordZZ_Descrizione,
		C.TipoCalcolo TipoCalcolo_Descrizione,
		T.RagioneSociale Trasportatore_Descrizione
FROM	Giacenze_Costi C 
		INNER JOIN Voci V ON V.Codice=C.Voce
		LEFT JOIN TabCampiCalcolo CC ON CC.NomeCampo=C.CampoCalcolo 
		LEFT JOIN Trasportatori T ON T.Codice=C.Trasportatore;


