-- dbo.GRD_IMP_Spedizioni_EventiEsiti source

ALTER VIEW [dbo].[GRD_IMP_Spedizioni_EventiEsiti] 
AS
SELECT  Id, 
		Unibol, 
		Cliente, 
		C.RagioneSociale as ClienteRagSoc,
		NumeroBolla, 
		DataBolla, 
		NumeroOrdine, 
		DataOrdine, 
		CodiceUDS, 
		ScopeEvento, 
		I.TipoEvento, 
		CodiceEvento, 
		E.Descrizione as CodiceEventoDescrizione,
		DataOraEvento, 
		SequenzaEffettiva, 
		NoteInterne, 
		NoteEsterne, 
		DataConsegnaConcordata, 
		OraConsegnaConcordata1, 
		OraConsegnaConcordata2, 
		I.Riferimento, 
		Autista, 
		Terminale, 
		Motrice, 
		Rimorchio1, 
		Contenitore1, 
		Rimorchio2, 
		Contenitore2, 
		DatiAggiuntivi, 
		Latitudine, 
		Longitudine, 
		DataValiditaGPS, 
		KmGPS, 
		KmManuali, 
		I.Localita, 
		I.Indirizzo, 
		I.Cap, 
		I.Provincia, 
		I.Nazione, 
		DataElaborazione, 
		StatoElaborazione
FROM    IMP_Spedizioni_Eventi I
		LEFT JOIN Clienti C ON C.Codice = I.Cliente
		LEFT JOIN Eventi E ON I.CodiceEvento = E.Codice
WHERE	ScopeEvento = '001' AND StatoElaborazione = 'X';


