		RTRIM(LTRIM(C.Descrizione)) as  CommessaDescrizione,
		M.Gruppo,
		RTRIM(LTRIM(G.Descrizione))  AS GruppoDescrizione, 
		M.DataInizio,
		M.DataFine,
		M.Descrizione,
		M.OfficinaInterna,
