          S.FILLERALFA2,
          S.FILLERALFA3,
          S.FILLERALFA4,
          S.FILLERALFA5,
          S.FILLERALFA6,
          S.FILLERALFA7,
          S.FILLERALFA8,
          S.FILLERALFA9,
          S.FILLERALFA10,
          S.FILLERDATA1,
          S.FILLERDATA2,
          S.FILLERDATA3,
          S.FILLERDATA4,
          S.FILLERDATA5,
          S.BATCHID,
          S.DATINS,
          S.UTEINS,
          S.DATAGG,
          S.UTEAGG,
          S.DATASPEDIZIONE,
          S.STATOWMS,
          S.STATOSPUNTAUSCITA,
          S.STATOOBC,
          S.BLOCCOAMMINISTRATIVO,
          S.BLOCCACOSTI,
          S.BLOCCARICAVI,
          S.IDRAGGRUPPAMENTOATTIVO,
          S.IDRAGGRUPPAMENTOPASSIVO,
          S.TIPOCONTRATTOATTIVOAPPLICATO,
          S.TIPOCONTRATTOPASSIVOAPPLICATO,
          S.ERRORETARIFFAATTIVA,
          S.ERRORETARIFFAPASSIVA,
          S.DATAESPORTAZIONECORRISPONDENTE,
		  CO.RagioneSociale AS RagSocCorrispondente,
		  CO.Localita AS LocalitaCorrispondente,
		  VL.Giro,
		  VL.RiferimentoEsterno AS RiferimentoEsternoGiro
     FROM spedizioni s INNER JOIN tipiservizi tb ON tb.codice = s.tiposervizio
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN clienti c ON c.codice = s.cliente
		  LEFT JOIN CLIENTI M ON M.CODICE = S.Mittente
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
		  LEFT JOIN Corrispondenti CO ON S.Corrispondente = CO.Codice
		  LEFT JOIN Viaggi_Linea VL ON S.IdViaggioLinea = VL.Id
    WHERE s.stato = 20 ;


-- dbo.GRD_PV_Viaggi source

ALTER VIEW [dbo].[GRD_PV_Viaggi] AS
SELECT IdViaggio,
       VS.Descrizione AS Stato,
       DataPartenzaPianificata,
       DataArrivoPianificata,
       DataPartenzaEffettiva,
       DataArrivoEffettiva,
       MotriceEffettiva AS Motrice,
       MM.Targa AS MotriceDescrizione,
       Rimorchio1Effettivo AS Rimorchio1,
       MR.Targa AS Rimorchio1Descrizione,
       Contenitore1Effettivo AS Contenitore1,
       MC.Targa AS Contenitore1Descrizione,
       Vettore,
       T.RagioneSociale AS VettoreDescrizione,
       Autista1Pianificato,
       A.RagioneSociale AS Autista1PianificatoDescrizione,
       Autista1Effettivo,
       A1.RagioneSociale AS Autista1EffettivoDescrizione,
       TipoSpedizione,
       TS.Descrizione AS TipoSpedizioneDescrizione,
       V.TipoMerce,
       TM.Descrizione AS TipoMerceDescrizione,
       V.Cliente,
       C.RagioneSociale AS ClienteDescrizione,
       PCSPartenza,
       PCSArrivo,
       KmPianificati,
       KmManuali,
       KmGPS,
	   V.Note1, 
	   V.Note2,
       A1.Trasportatore,
       MM.Trasportatore AS Trasportatore1,
       V.Terminale,
       (
		SELECT ISNULL(SUM(ISNULL(Peso,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Peso,
       (
        SELECT ISNULL(SUM(ISNULL(Volume,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Volume,
       (
        SELECT ISNULL(SUM(ISNULL(Colli,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Colli,
       (
        SELECT ISNULL(SUM(ISNULL(Pallet,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
       ) Pallet,
       (
        SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
       ) Numero_Spedizioni    ,
       V.Sagome,
       V.PalletPassivo,
       V.VolumePassivo,
       V.PALLETEFFETTIVI,
       V.SAGOMEEFFETTIVE,
       V.VolumeEffettivo,
	   V.TipoViaggio,
       (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NULL
       ) Num_Spedizioni_Diretta,
	   (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio AND S.Corrispondente IS NOT NULL
       ) Num_Spedizioni_Distribuzione,
       V.FILLERALFA1,
       V.FILLERALFA2,
       V.FILLERALFA3,
       V.FILLERALFA4,
       V.FILLERALFA5,
       V.FILLERALFA6,
       V.FILLERALFA7,
       V.FILLERALFA8,
       V.FILLERALFA9,
       V.FILLERALFA10,
       V.FILLERDATA1,
       V.FILLERDATA2,
       V.FILLERDATA3,
       V.FILLERDATA4,
       V.FILLERDATA5,
	V.ZonaArrivo,
	' ' AS DUMMY
     FROM Viaggi V INNER JOIN VW_DOC_Viaggi_Stati VS ON V.Stato = VS.Codice
          LEFT JOIN MEZZI MM ON MM.CODICE = V.MotricePianificata
          LEFT JOIN MEZZI MR ON MR.CODICE = V.Rimorchio1Pianificato
          LEFT JOIN MEZZI MC ON MC.CODICE = V.Contenitore1Pianificato
          LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE
          LEFT JOIN AUTISTI A ON A.CODICE = V.AUTISTA1PIANIFICATO
          LEFT JOIN AUTISTI A1 ON A1.CODICE = V.AUTISTA1EFFETTIVO
          LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
          LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
    WHERE V.Stato<20;


-- dbo.GRD_SML_GIRIDETTAGLI source

ALTER VIEW [dbo].[GRD_SML_GIRIDETTAGLI] AS
SELECT G.*
     , pcs.ragionesociale
	 , pcs.indirizzo
	 , pcs.cap
	 , pcs.Localita
	 , pcs.Provincia 
	 , C.RagioneSociale AS RagSocCorrispondente
	 , C.Localita AS LocalitaCorrispondente
  FROM SML_GIRIDETTAGLI G
  left join PCS on G.PCS = pcs.Codice 
  left join Corrispondenti C on G.Corrispondente = C.Codice;


-- dbo.GRD_SML_GIRITESTATA source

ALTER VIEW [dbo].[GRD_SML_GIRITESTATA]
AS
SELECT	SML_GIRITESTATA.*, 				
		(select ragionesociale from PCS p where p.Codice = SML_GIRITESTATA.depositopartenza)  rgsdepositopartenza,
		(select Localita from PCS p where p.Codice = SML_GIRITESTATA.depositopartenza) Localitadepositopartenza,
		(select ragionesociale from PCS p where p.Codice = SML_GIRITESTATA.depositoarrivo) rgsdepositoarrivo,
		(select Localita from PCS p where p.Codice = SML_GIRITESTATA.depositoarrivo) Localitadepositoarrivo,
		Codice + isnull(' - ' + Descrizione,'') DescrizioneLB
			  
FROM	SML_GIRITESTATA;


-- dbo.GRD_SML_PCS source

ALTER VIEW [dbo].[GRD_SML_PCS] AS
 SELECT	P.Codice,
		P.RagioneSociale,
		P.Indirizzo,
		P.Cap,
		P.Localita,
		P.Provincia,
		P.Nazione,
		P.CodiceFiscale,
		P.PartitaIva,
		P.Telefono,
		P.Email,
		P.Attivo	,
		P.Codice + ' - ' + P.RagioneSociale + ISNULL(' (' + P. Localita + ')', '') AS DescrizioneLB 
   FROM	PCS P
   LEFT OUTER JOIN PCS_Geocodifica G ON P.Codice = G.Codice
   WHERE P.PUNTODISIMULAZIONE = 'S';


-- dbo.GRD_SML_Sessioni source

ALTER VIEW [dbo].[GRD_SML_Sessioni] AS
