-- dbo.GRD_Spedizioni_Costi source

ALTER VIEW [dbo].[GRD_Spedizioni_Costi] AS
SELECT	SC.*, 
		V.Descrizione VOCE_Descrizione,
		CC.Descrizione CampoCalcolo_Descrizione,
		SC.RecordZZ RecordZZ_Descrizione,
		SC.TipoCalcolo TipoCalcolo_Descrizione,
		T.RagioneSociale Trasportatore_Descrizione
FROM Spedizioni_Costi SC 
INNER JOIN Voci V ON V.Codice=SC.Voce
LEFT JOIN TabCampiCalcolo CC ON CC.NomeCampo=SC.CampoCalcolo 
LEFT JOIN Trasportatori T ON T.Codice=SC.Trasportatore;


-- dbo.GRD_Spedizioni_Documenti source

