-- dbo.GRD_Spedizioni_Modello source

ALTER VIEW [dbo].[GRD_Spedizioni_Modello] AS
SELECT	S.*, 		
		C.RagioneSociale Cliente_RagioneSociale,		
		TS.Descrizione TipoSpedizione_Descrizione,		
		TM.Descrizione TipoMerce_Descrizione,		
		PCS1.RagioneSociale PCSPartenza_RagSoc,
		PCS1.Localita PCSPartenza_Localita,		
		PCS2.RagioneSociale PCSDestinazione_RagSoc,
		PCS2.Localita PCSDestinazione_Localita		
FROM Spedizioni_ModelloSettimanale S LEFT JOIN Clienti C ON C.Codice=S.Cliente
LEFT JOIN TipiSpedizione TS ON TS.Codice=S.TipoSpedizione
LEFT JOIN TipiMerce TM ON TM.Codice=S.TipoMerce 
LEFT JOIN PCS PCS1 ON PCS1.Codice=S.PCSPartenza 
LEFT JOIN PCS PCS2 ON PCS2.Codice=S.PCSDestinazione;


