/* Formatted on 2015/11/03 11:55 (Formatter Plus v4.8.8) */
ALTER VIEW [dbo].[GRD_TAR_TRA_AttiveTestata] 
AS
   SELECT T.IdTariffa,
		  T.TipoDocumento,
		  TD.Descrizione as TipoDocumentoDescrizione,
          C.Cliente AS ClienteContratto,
          CL.RagioneSociale AS ClienteContrattoDescrizione,
          T.Contratto AS Contratto,
          C.Descrizione AS ContrattoDescrizione,
          T.TipoSpedizione,
          TS.Descrizione AS TipoSpedizioneDescrizione,
          T.TipoMerce,
          TM.Descrizione AS TipoMerceDescrizione,
          T.TipoMezzo,
          T.Cliente,
          TMZ.Descrizione AS TipoMezzoDescrizione,
          T.GruppoTariffarioPartenza,
          GTP.Descrizione AS GruppoTarParDescrizione,
          T.PCSPartenza,
          PP.RagioneSociale AS PCSPartenzaDescrizione,
          T.MacroZonaArrivo,
          ZM.Descrizione AS MacroZonaArrivoDescrizione,
          T.ZonaArrivo,
          Z.Descrizione AS ZonaArrivoDescrizione,
          T.GruppoTariffarioArrivo,
          GTA.Descrizione AS GruppoTarArrDescrizione,
          T.PCSArrivo,
          PA.RagioneSociale AS PCSArrivoDescrizione,
          T.RapportoPV
     FROM TARIFFEATTIVETESTATA T 
		  INNER JOIN TARIFFECONTRATTI C ON C.CODICE = T.CONTRATTO
		  INNER JOIN TARIFFETIPIDOCUMENTO TD ON TD.CODICE = T.TIPODOCUMENTO
          INNER JOIN TIPISPEDIZIONE TS ON TS.CODICE = T.TIPOSPEDIZIONE
          INNER JOIN TIPIMERCE TM ON TM.CODICE = T.TIPOMERCE
          INNER JOIN TIPIMEZZO TMZ ON TMZ.CODICE = T.TIPOMEZZO
          INNER JOIN CLIENTI CL ON CL.CODICE = C.CLIENTE
          INNER JOIN PCS_GRUPPITARIFFARI GTP
          ON GTP.CODICE = T.GRUPPOTARIFFARIOPARTENZA
          INNER JOIN PCS PP ON PP.CODICE = T.PCSPARTENZA
          INNER JOIN ZONEMACRO ZM ON ZM.CODICE = T.MACROZONAARRIVO
          INNER JOIN ZONE Z ON Z.CODICE = T.ZONAARRIVO
          INNER JOIN PCS_GRUPPITARIFFARI GTA
          ON GTA.CODICE = T.GRUPPOTARIFFARIOARRIVO
          INNER JOIN PCS PA ON PA.CODICE = T.PCSARRIVO;


