-- dbo.GRD_TRK_MAPPA_VIAGGI source

ALTER VIEW [dbo].[GRD_TRK_MAPPA_VIAGGI] AS
   SELECT v.idviaggio,
          ISNULL(V.dataPartenzaEffettiva, V.DataPartenzaPianificata) datapartenza,
          ISNULL(V.dataArrivoEffettiva, V.DataArrivoPianificata) dataarrivo, 
		  v.datapartenzaeffettiva, 
		  v.dataarrivoeffettiva,
          ISNULL(v.MotriceEffettiva,V.MotricePianificata) AS mezzo, 
		  m.descrizione AS descrizionemezzo, 
		  m.tipomezzo,
          tm.descrizione AS descrizionetipomezzo,
          ISNULL(v.Rimorchio1Effettivo,V.Rimorchio1Pianificato) rimorchio,
		  ISNULL(v.Contenitore1Effettivo,V.Contenitore1Pianificato) Contenitore,
          m1.descrizione AS descrizionerimorchio,
          m2.descrizione AS descrizioneContenitore, 
		  ISNULL(v.Autista1Effettivo,V.Autista1Pianificato) autista,
          a.ragionesociale AS ragionesocialeautista,
          v.vettore AS trasportatore,
          t.ragionesociale AS ragionesocialetrasportatore,
          CASE WHEN V.idviaggioobc IS NOT NULL THEN 'S' ELSE 'N' END AS viaggiomanuale, 
		  v.idviaggioobc, 
		  v.terminale, 
		  v.kmpianificati,
          v.kmgps, 
		  v.kmmanuali, 
		  v.kmricalcolati, 
		  v.tipomerce, 
		  v.vettore,
          ISNULL(v.pcspartenzaeffettivo, V.PCSPartenza) pcspartenza,
          ISNULL(v.pcsarrivoeffettivo, V.PCSArrivo) pcsarrivo, 
		  vq.quantitacaricata kgcarico,
          vq.quantitascaricata kgscarico
     FROM viaggi v 
	 LEFT JOIN trasportatori t ON v.vettore = t.codice
     LEFT JOIN mezzi m ON ISNULL(v.MotriceEffettiva,V.MotricePianificata)= m.codice
     LEFT JOIN tipimezzo tm ON tm.codice = m.tipomezzo
     LEFT JOIN mezzi m1 ON ISNULL(v.Rimorchio1Effettivo,V.Rimorchio1Pianificato) = m1.codice
     LEFT JOIN mezzi m2 ON ISNULL(v.Contenitore1Effettivo,V.Contenitore1Pianificato) = m2.codice
     LEFT JOIN autisti a ON ISNULL(v.Autista1Effettivo,V.Autista1Pianificato) = a.codice
     LEFT JOIN (
					  SELECT	IdViaggio,
								SUM (CASE WHEN TipoServizio = 'C' THEN Peso ELSE 0 END ) quantitacaricata,
								SUM (CASE WHEN TipoServizio = 'C' THEN 0 ELSE Peso END ) quantitascaricata
						FROM Spedizioni
					GROUP BY IdViaggio
					) vq ON vq.IdViaggio = v.idviaggio;


-- dbo.GRD_TRK_MAPPA_VIAGGI_DETT source

ALTER VIEW [dbo].[GRD_TRK_MAPPA_VIAGGI_DETT] AS
	SELECT *
      FROM (
			 SELECT V.IdViaggio,
                    10 AS Sequenza,
                    10 AS SequenzaPrevista,
                    10 AS SequenzaEffettiva,
                    V.DataPartenzaPianificata,
                    V.DataPartenzaEffettiva,
                    NULL AS DataArrivoPianificata,
                    NULL AS DataArrivoEffettiva,
                    0 AS KmPrevisti,
                    0 AS KmEffettivi,
					0 AS KmRicalcolati,
                    0 AS KmManuali,
                    0 AS KmGps,
                    0 AS Peso,
                    0 AS Volume,
                    0 AS Colli,
					0 AS Pallet,
                    CONVERT(VARCHAR, V.IdViaggio) + '_' + ISNULL(V.PCSPartenzaEffettivo, V.PCSPartenza) AS CodicePunto,
                    'P' AS TipoPunto,
                    P.RagioneSociale RagioneSociale,
                    P.Localita Localita,
                    P.Provincia Provincia,
                    NULL AS NumeroBolla,
                    NULL AS DataBolla,
                    ISNULL(V.DataPartenzaEffettiva, V.DataPartenzaPianificata) AS DataOraEvento,
                    PG.Latitudine Latitudine,
                    PG.Longitudine Longitudine,
                    NULL AS Esito
               FROM Viaggi V 
			   LEFT JOIN PCS P ON P.Codice = ISNULL(V.PCSPartenzaEffettivo, V.PCSPartenza) 
               LEFT JOIN PCS_Geocodifica PG ON PG.Codice = P.Codice

              UNION ALL

             SELECT O.IdViaggio,
                    CASE
                       WHEN o.SequenzaEffettiva > 0 THEN o.SequenzaEffettiva + 10
                       ELSE o.SequenzaPianificata + 1000
                    END AS Sequenza,
                    o.SequenzaPianificata AS SequenzaPrevista,
                    o.SequenzaEffettiva AS SequenzaEffettiva,
                    o.DataOraPartenzaPianificata AS DataPartenzaPianificata,
                    o.DataOraPartenzaEffettiva AS DataPartenzaEffettiva,
                    O.DataOraArrivoPianificata,
                    o.Evento_DataOraEsito AS DataArrivoEffettivo,
                    o.KmPianificati AS KmPrevisti,
                    ISNULL(o.KmGPS, 0) AS KmEffettivi,
					o.KmRicalcolati AS KmRicalcolati,
                    O.KmManuali AS KmManuali,
                    o.KmGps,
                    o.Peso AS Peso,                    
                    o.Volume AS Volume,
                    o.Colli AS Colli,
					o.Pallet AS Pallet,
                    CONVERT(VARCHAR, o.IdViaggio) + '_' +
                    CASE 
                        WHEN ts.Is_Consegna = 'S' THEN O.PCSDestinazione 
                        ELSE O.PCSPartenza
                    END AS CodicePunto,
                    CASE 
                        WHEN ts.Is_Consegna = 'S' THEN 'C'
                        ELSE 'P'
                    END AS TipoPunto,
                    CASE
                       WHEN ts.Is_Consegna = 'S' THEN P.RagioneSociale
                       ELSE P1.RagioneSociale
                    END AS RagioneSociale,
                    CASE
                       WHEN ts.Is_Consegna = 'S' THEN p.Localita
                       ELSE P1.Localita
                    END AS Localita,
                    CASE
                       WHEN ts.Is_Consegna = 'S' THEN P.Provincia
                       ELSE P1.Provincia
                    END AS Provincia,
                    O.NumeroBolla AS NumeroBolla,
                    O.DataBolla AS DataBolla,
                    o.Evento_DataOraEsito AS DataEvento,
                    CASE
                       WHEN ts.Is_Consegna = 'S' THEN PG.Latitudine
                       ELSE PG1.Latitudine
                    END AS Latitudine,
                    CASE
                       WHEN ts.Is_Consegna = 'S' THEN pg.Longitudine
                       ELSE pg1.Longitudine
                    END AS Longitudine,
                    o.Evento_CodiceEsito AS Esito
               FROM vw_Spedizioni O 
			  INNER JOIN Viaggi V ON V.idviaggio = O.IdViaggio                     
               LEFT JOIN PCS P ON P.Codice = O.PCSDestinazione 
               LEFT JOIN PCS_Geocodifica PG ON PG.Codice = P.Codice
               LEFT JOIN PCS P1 ON p1.Codice = o.PCSPartenza
               LEFT JOIN PCS_Geocodifica PG1 ON PG1.Codice = P1.Codice
			  INNER JOIN TipiServizi TS ON o.TipoServizio=TS.Codice
              WHERE o.IdViaggio IS NOT NULL

              UNION ALL

             SELECT V.IdViaggio,
                    9999 AS Sequenza,
                    0 AS SequenzaPrevista,
                    0 AS SequenzaEffettiva,
					NULL AS DataPartenzaPianificata,
                    NULL AS DataPartenzaEffettiva,
                    V.DataArrivoPianificata,
                    V.DataArrivoEffettiva,
                    0 AS KmPrevisti,
                    0 AS KmEffettivi,
					V.KmRicalcolati,
                    0 KmManuali,
                    0 KmGps,
                    0 AS Peso,
                    0 AS Volume,
                    0 AS Colli,
					0 AS Pallet,
					CONVERT(VARCHAR, V.IdViaggio) + '_' + ISNULL(V.PCSArrivoEffettivo, V.PCSArrivo) AS CodicePunto,
					'P' AS TipoPunto,
					P.RagioneSociale RagioneSociale,
                    P.Localita Localita,
                    P.Provincia Provincia,
                    NULL AS NumeroBolla,
                    NULL AS DataBolla,
                    ISNULL(V.DataArrivoEffettiva, V.DataArrivoPianificata) AS DataOraEvento,
                    PG.Latitudine Latitudine,
                    PG.Longitudine Longitudine,
                    NULL AS Esito
               FROM Viaggi v 
			  INNER JOIN PCS p ON p.Codice = ISNULL(V.PCSArrivoEffettivo, V.PCSArrivo)
               LEFT JOIN PCS_Geocodifica pg ON pg.Codice = p.Codice
           ) t;


-- dbo.GRD_TrasportatoriTipiMezzo source

ALTER VIEW [dbo].[GRD_TrasportatoriTipiMezzo] AS 
SELECT	TTM.*,
		T.RagioneSociale Trasp_RagioneSociale,
		TM.Descrizione TipoMezzo_Descrizione,
		TMe.Descrizione TipoMerce_Descrizione,
		PCS1.RagioneSociale Partenza_RagioneSociale,
		PCS1.Localita Partenza_Localita,
		PCS2.RagioneSociale Arrivo_RagioneSociale,
		PCS2.Localita Arrivo_Localita
FROM Trasportatoritipimezzo TTM LEFT JOIN Trasportatori T ON T.Codice =TTM.Trasportatore 
LEFT JOIN TipiMezzo TM ON TM.Codice =TTM.TipoMezzo 
LEFT JOIN TipiMerce TMe ON TMe.Codice =TTM.TipoMerce 
LEFT JOIN PCS PCS1 ON PCS1.Codice =TTM.PuntoPartenza 
LEFT JOIN PCS PCS2 ON PCS2.Codice =TTM.PuntoArrivo;


-- dbo.GRD_Viaggi_Costi source

ALTER VIEW [dbo].[GRD_Viaggi_Costi] AS
SELECT	VC.*, 
		V.Descrizione VOCE_Descrizione,
		CC.Descrizione CampoCalcolo_Descrizione,
		VC.RecordZZ RecordZZ_Descrizione,
		VC.TipoCalcolo TipoCalcolo_Descrizione,
		T.RagioneSociale Trasportatore_Descrizione
FROM Viaggi_Costi VC 
INNER JOIN Voci V ON V.Codice=VC.Voce
LEFT JOIN TabCampiCalcolo CC ON CC.NomeCampo=VC.CampoCalcolo 
LEFT JOIN Trasportatori T ON T.Codice=VC.Trasportatore;


-- dbo.GRD_Viaggi_ModelloSettimanale source

ALTER VIEW [dbo].[GRD_Viaggi_ModelloSettimanale] AS 
SELECT	V.*, 
		TV.Descrizione TipoViaggio_Descrizione,
		T.RagioneSociale Vettore_RagioneSociale,
		TS.Descrizione TipoSpedizione_Descrizione,
		TM.Descrizione TipoMerce_Descrizione,
		P1.Localita PCSPartenza_Localita,
		P1.RagioneSociale PCSPartenza_RagioneSociale,
		P1.Provincia PCSPartenza_Provincia,
		P1.Nazione PCSPartenza_Nazione,
		P2.Localita PCSArrivo_Localita,
		P2.RagioneSociale PCSArrivo_RagioneSociale,
		P2.Provincia PCSArrivo_Provincia,
		P2.Nazione PCSArrivo_Nazione
FROM Viaggi_modellosettimanale V LEFT JOIN Viaggi_TipiViaggio TV ON TV.Codice=V.TipoViaggio 
LEFT JOIN Trasportatori T ON T.Codice =V.Vettore 
LEFT JOIN TipiSpedizione TS ON TS.Codice = V.TipoSpedizione 
LEFT JOIN TipiMerce TM ON TM.Codice = V.TipoMerce 
LEFT JOIN PCS P1 ON P1.Codice=V.PCSPartenza 
LEFT JOIN PCS P2 ON P2.Codice=V.PCSArrivo;


