-- dbo.GRD_WFI_DELSYSCHEDULER source

ALTER VIEW [dbo].[GRD_WFI_DELSYSCHEDULER]
AS
SELECT	DS.PROGRESSIVO, 
		DS.ISTANZA, 
		DS.TASK, 
		DS.APPLICAZIONE, 
		DS.DESCRIZIONE, 
		DS.SEQUENZA, 
		DS.ATTIVO, 
		DS.SCHEDULAZIONETIPO, 
		CASE 
			WHEN DS.SCHEDULAZIONETIPO = '0' THEN 'AD OGNI CICLO'
			WHEN DS.SCHEDULAZIONETIPO = '1' THEN 'UNA SOLA VOLTA'
			WHEN DS.SCHEDULAZIONETIPO = 'Z' AND DS.SCHEDULAZIONEARGOMENTO = '0' THEN 'PRIMO GIORNO DELL''ANNO'
			WHEN DS.SCHEDULAZIONETIPO = 'Z' AND DS.SCHEDULAZIONEARGOMENTO = '1' THEN 'ULTIMO GIORNO DELL''ANNO'
			WHEN DS.SCHEDULAZIONETIPO = 'X' AND DS.SCHEDULAZIONEARGOMENTO = '0' THEN 'PRIMO GIORNO DEL MESE'
			WHEN DS.SCHEDULAZIONETIPO = 'X' AND DS.SCHEDULAZIONEARGOMENTO = '1' THEN 'ULTIMO GIORNO DEL MESE'
			WHEN DS.SCHEDULAZIONETIPO = 'W' THEN 'GIORNO DELLA SETTIMANA'
			WHEN DS.SCHEDULAZIONETIPO = 'S' THEN 'OGNI N SECONDI'
			WHEN DS.SCHEDULAZIONETIPO = 'N' THEN 'OGNI N MINUTI'
			WHEN DS.SCHEDULAZIONETIPO = 'H' THEN 'OGNI N ORE'
			WHEN DS.SCHEDULAZIONETIPO = 'D' THEN 'OGNI N GIORNI'
			WHEN DS.SCHEDULAZIONETIPO = 'M' THEN 'OGNI N MESI'
			WHEN DS.SCHEDULAZIONETIPO = 'Y' THEN 'OGNI N ANNI'
			WHEN DS.SCHEDULAZIONETIPO = 'T' THEN 'UNA VOLTA AL GIORNO AD UNA CERTA ORA'
			END DescrizioneSchedulazioneTipo,
        DS.SCHEDULAZIONEARGOMENTO, 
        DS.INIZIODATA, 
        DS.INIZIOORA, 
        DS.FINEDATA, 
        DS.FINEORA, 
        DS.SECONDIDEDICATI, 
        DS.ULTIMAESECUZIONEINIZIO, 
        DS.ULTIMAESECUZIONEFINE, 
        DS.NUMEROESECUZIONI, 
        DS.NUMEROERRORI, 
        DS.ARGOMENTI, 
        DS.DatAgg, 
        DS.UteAgg, 
        DS.DatIns, 
        DS.UteIns, 
        ISNULL(DS.DESCRIZIONE, DT.DESCRIZIONE) AS DescrizioneTask ,
		'<div class=''' + case when DS.Attivo='S' AND DT.Attivo='S' THEN 'PallinoVerde' ELSE 'PallinoRosso' END + ''' title=''' + case when DS.Attivo='S' AND DT.Attivo='S' THEN 'Attivo' ELSE 'Disattivo' END + '''></div>' HtmlAttivo

FROM DELSYSCHEDULER DS 
INNER JOIN DELSYTASKS DT ON DS.TASK = DT.CODICE AND DS.APPLICAZIONE = DT.APPLICAZIONE;


-- dbo.GRD_WFI_Desktop_Tree source

ALTER VIEW [dbo].[GRD_WFI_Desktop_Tree] 
AS
   SELECT ID, configprofileid, t.voce, v.descrizione AS descrizionevoce,
          v.text AS caption,
          CASE v.tiponodo
             WHEN 'P'
                THEN 'PADRE'
             WHEN 'F'
                THEN 'FUNZIONE'
             WHEN 'N'
                THEN 'NODO'
             WHEN 'C'
                THEN 'NODO SENZA AZIONE'
             ELSE ''
          END AS tiponodo,
          parentid, t.descrizione, ordine, separa,t.visibile, t.peso
     FROM wfi_Desktop_tree t INNER JOIN wfi_menu_voci v ON v.voce = t.voce
    WHERE v.visibile = 'S';


-- dbo.GRD_WFI_FTP_FILE source

ALTER VIEW [dbo].[GRD_WFI_FTP_FILE] AS
SELECT F.Codice
     , F.Descrizione
	 , Nome
	 , FO1.Descrizione AS Sorgente
	 , FO2.Descrizione AS Destinazione
	 , RR.Descrizione AS RenameRules
	 , Semaforo
	 , FG.Descrizione AS FileGroup
	 , F.Attivo
  FROM FTPAgentFile F
  INNER JOIN FTPAgentFolders FO1 ON F.Sorgente=FO1.Codice	
  INNER JOIN FTPAgentFolders FO2 ON F.Destinazione=FO2.Codice	
   LEFT OUTER JOIN FTPAgentRenameRules RR ON F.RenameRules=RR.Codice
   LEFT OUTER JOIN FTPAgentFileGroup FG ON F.FileGroup=FG.Codice;


