-- dbo.GRD_WFI_ORGANIZ_SOGGETTI source

ALTER VIEW [dbo].[GRD_WFI_ORGANIZ_SOGGETTI]
AS
select		us.Utente, 
			us.codicesoggetto Codice, 
			o.OrganizzazioneTipoSoggetto,
			case UPPER(o.organizzazionetiposoggetto)
				when UPPER('to.destinatari') then d.ragionesociale 
				when UPPER('to.clienti') then c.ragionesociale 
				when UPPER('to.trasp') then t.ragionesociale 
				else '' end 
			as ragionesociale
from		wfi_utenti_soggetti us inner join 
			wfi_utenti o on o.codice=us.utente LEFT JOIN 
			Trasportatori T ON US.CodiceSoggetto = T.Codice LEFT JOIN				
			Destinatari d ON US.CodiceSoggetto = d.Codice LEFT JOIN				
			Clienti c ON US.CodiceSoggetto = c.Codice;


