-- dbo.IMP_SPEDIZIONI_WMS source

ALTER View [dbo].[IMP_SPEDIZIONI_WMS]
As
Select HST_ID As ID, 
		Cast(Hst_IDSessione As Varchar(60)) As IDTRASMISSIONE,
		Hst_Comando as Comando,
		Cast(HOrdTes_Ordine + '/' + HOrdTes_NumeroVersione As Varchar(30)) As NUMEROORDINE,
		Cast(Floor(Convert(Real, HOrdTes_DataOrdine)) As DateTime) As DATAORDINE,
		--SB 28/04/17
		--CAMBIATA SU INDICAZIONE DI MARANI ALTRIMENTI I TRANSITI NON ENTRANO
		--Cast(Null As Varchar(30)) As NUMEROBOLLA,
		Cast(HOrdTes_Ordine + '/' + HOrdTes_NumeroVersione As Varchar(30)) As NUMEROBOLLA, 
		--FINE SB
		Cast(Null As DATE) As DATABOLLA,
		Cast(HOrdTes_LUC_TMS_OrdineCliente As Varchar(30)) As NUMEROORDINECLIENTE,
		Cast(Null As DATE) As DATAORDINECLIENTE, 
		Cast(HOrdTes_LUC_TMS_TipoServizio As Varchar(6)) As TIPOSERVIZIO,
		Cast(HOrdTes_CommittenteOrdine As Varchar(15)) As CLIENTE,
		Cast(Null As Varchar(15)) As MITTENTE,
		Cast(Null As Varchar(60)) As MITTENTERAGIONESOCIALE,
		Cast(HOrdTes_LUC_TMS_TipoSpedizione As Varchar(6)) As TIPOSPEDIZIONE,
		Cast(Null As Varchar(6)) As TIPOSPEDIZIONEPASSIVO,
		Cast(HOrdTes_LUC_TMS_TipoMerce As Varchar(6)) As TIPOMERCE,
		Cast(ISNULL(CASE WHEN LEN(HOrdTes_LUC_TMS_PCSPartenza) = 0 THEN NULL ELSE HOrdTes_LUC_TMS_PCSPartenza END, '100004') As Varchar(15)) As PCSPARTENZA,
		Cast(Null As Varchar(60)) As PCSPARTENZAESTERNO,
		Cast('-' As Varchar(60)) As PCSPARTENZA_RAGSOC,
		Cast(Null As Varchar(60)) As PCSPARTENZA_INDIRIZZO,
		Cast(Null As Varchar(10)) As PCSPARTENZA_CAP,
		Cast(Null As Varchar(60)) As PCSPARTENZA_LOCALITA,
		Cast(Null As Varchar(3)) As PCSPARTENZA_PROVINCIA,
		Cast(Null As Varchar(6)) As PCSPARTENZA_NAZIONE,
		Cast(UPPER (HOrdTes_Destinatario) As Varchar(15)) As PCSDESTINAZIONE,
		Cast(Null As Varchar(15)) As PCSDESTINAZIONEESTERNO,
		Cast(UPPER (ISNULL(CASE WHEN LEN(HOrdTes_Dest_RagioneSociale) = 0 THEN NULL ELSE HOrdTes_Dest_RagioneSociale END,'-')) As Varchar(60)) As PCSDESTINAZIONE_RAGSOC,
		Cast(UPPER (HOrdTes_Dest_Indirizzo) As Varchar(60)) As PCSDESTINAZIONE_INDIRIZZO,
		Cast(UPPER (HOrdTes_Dest_Cap) As Varchar(10)) As PCSDESTINAZIONE_CAP,
		Cast(UPPER (HOrdTes_Dest_Localita) As Varchar(60)) As PCSDESTINAZIONE_LOCALITA,
		Cast(UPPER (HOrdTes_Dest_Provincia) As Varchar(3)) As PCSDESTINAZIONE_PROVINCIA,
		Cast(UPPER (HOrdTes_Dest_Nazione) As Varchar(3)) As PCSDESTINAZIONE_NAZIONE,
		Cast(Null As Varchar(15)) As DESTINATARIO,
		Cast(Null As Varchar(60)) As DESTINATARIOCLIENTE,
		Cast(Null As Varchar(6)) As ZONASPEDIZIONE,
		Cast(Null As Varchar(6)) As ZONAPARTENZATARIFFAATTIVA,
		Cast(Null As Varchar(6)) As ZONAARRIVOTARIFFAATTIVA,
		Cast(Null As Varchar(6)) As ZONAPARTENZATARIFFAPASSIVA,
		Cast(Null As Varchar(6)) As ZONAARRIVOTARIFFAPASSIVA,
		Cast(HOrdTes_DataConsegna As DATE) As DATACONSEGNAPREVISTA1,
		Cast(HOrdTes_DataConsegna As DATE) As DATACONSEGNAPREVISTA2,
		Cast(IsNull(HOrdTes_LUC_Incoterm + ' ' , '') + IsNull('(' + HOrdTes_LUC_Transito + ') ', '') + IsNull(HOrdTes_LUC_TMS_NoteConsegna, '') As Varchar(255)) As NOTECONSEGNAPREVISTA,
		Cast(Null As DATE) As DATARITIROPREVISTA1, Cast(Null As DATE) As DATARITIROPREVISTA2,
		Cast(Null As Varchar(255)) As NOTERITIROPREVISTO,
		Cast(Null As Varchar(15)) As CORRISPONDENTE,
		Cast(NULL As Varchar(15)) As TRASPORTATORE,
		Cast(abs(HOrdTes_LUC_TMS_Peso) As Numeric(18, 5)) As PESO, Cast(abs(HOrdTes_LUC_TMS_Colli) As Int) As COLLI,
		Cast(abs(HOrdTes_LUC_TMS_Pallet) As Int) As PALLET, Cast(abs(HOrdTes_LUC_TMS_Volume / 10000) As Numeric(18, 5)) As VOLUME,
		Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO1, Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO2,
		Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO3, Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO4,
		Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO5, Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO6,
		Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO7, Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO8,
		Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO9, Cast(Null As Numeric(18, 5)) As CAMPOCALCOLO10,
		Cast(Null As Char (1)) As FLAG1, Cast(Null As Char (1)) As FLAG2,
		Cast(Null As Char (1)) As FLAG3, Cast(Null As Char (1)) As FLAG4,
		Cast(Null As Char (1)) As FLAG5, Cast(Null As Char (1)) As FLAG6,
		Cast(Null As Char (1)) As FLAG7, Cast(Null As Char (1)) As FLAG8,
		Cast(Null As Char (1)) As FLAG9, Cast(Null As Char (1)) As FLAG10,
		Cast(Null As Numeric(18, 5)) As CONTRASSEGNO, Cast(Left(HOrdTes_LUC_TMS_Note, 1000) As Varchar(1000)) As NOTE,
		Cast(HOrdTes_LUC_BusinessUnit As Varchar(255)) As FILLERALFA1, 
		Cast(Null As Varchar(255)) As FILLERALFA2,
		Cast(HOrdTes_LUC_TMS_Commenti As Varchar(255)) As FILLERALFA3, 
		Cast(Null As Varchar(255)) As FILLERALFA4,
		Cast(HOrdTes_LUC_ClienteFatturazione As Varchar(255)) As FILLERALFA5, 
		LTRIM(RTRIM(Cast(HOrdTes_LUC_CodiceCapoGruppo As Varchar(255)))) As FILLERALFA6,
		Cast(Null As Varchar(255)) As FILLERALFA7, 
		LTRIM(RTRIM(Cast(HOrdTes_LUC_CentroDiCosto As Varchar(255)))) As FILLERALFA8,
		Cast(HOrdTes_LUC_Agente As Varchar(255)) As FILLERALFA9, 
		Cast('ALLOC' As Varchar(255)) As FILLERALFA10,
		Cast(Null As DATE) As FILLERDATA1, Cast(Null As DATE) As FILLERDATA2,
		Cast(Null As DATE) As FILLERDATA3, Cast(Null As DATE) As FILLERDATA4,
		Cast(Null As DATE) As FILLERDATA5, 
		Cast(Hst_DataInserimento As DATE) As DATINS, Cast('XXX' As Varchar(15)) As UTEINS, 
		Cast(Hst_DataInserimento As DATE) As DATAGG, Cast('XXX' As Varchar(15)) As UTEAGG, 
		HST_DATAELABORAZIONE_TMS As DATAELABORAZIONE, HST_STATORECORD_TMS As STATOELABORAZIONE, 
		Cast(HOrdTes_LUC_DataSpedizione As DATE) As DATASPEDIZIONE,
		Cast('N' As Char (1)) As BLOCCOAMMINISTRATIVO, 
		Null As STATOWMS,
		/*
		CAMPI CUSTOM
		*/
		HOrdTes_LUC_CentroDiCosto,
		HOrdTes_LUC_TipoGestione AS TIPOGESTIONE
     FROM HSTORDTESRX
    WHERE HST_STATORECORD IN ('P') and (HOrdTes_LUC_TipoGestione = 'B' OR HOrdTes_LUC_TipoGestione = 'T')
	--SB 03/05/17
	--SE ELABORATO DA TMS NON LA CERCO + per 15 minuti
	AND 
		(Hst_StatoRecord_TMS = ''
		And DateAdd(N, +15, IsNull(Hst_DataElaborazione_TMS, '19000101')) < GETDATE())
	--FINE SB;


