-- dbo.LUC_CdvItaltrade source

ALTER     VIEW [dbo].[LUC_CdvItaltrade] AS
SELECT 
    CONCAT(s.PCSDestinazione_RagSoc, ' - ',s.PCSDestinazione_Localita, ' (',PCSDestinazione_Provincia,')') as Cliente,
    rg.SDLNID as RigaOrdine,
    rg.SDLITM as Materiale,
    CONCAT((rg.SDUORG / 1000),' ',rg.SDUOM) AS Quantità,
    s.NumeroOrdine,
    s.idviaggio, 
FORMAT(
        DATEADD(
            DAY, (rg.SDPDDJ % 1000) - 1,
            DATEFROMPARTS(1900 + (rg.SDPDDJ / 1000), 1, 1)
        ),
        'dd/MM/yy'
    ) as DataConsegna,
    v.DataPartenzaPianificata
FROM spedizioni s
LEFT JOIN viaggi v on s.idviaggio = v.Idviaggio
LEFT JOIN viaggi_eventi ve 
    ON ve.idviaggio = s.idviaggio
LEFT JOIN JDEDB92.JDE_PRODUCTION.PRODDTA.F4211 AS rg
  ON RIGHT('00000000' + LEFT(LTRIM(RTRIM(s.NumeroOrdine)), 8), 8)
     = RIGHT('00000000' + CAST(CAST(rg.SDDOCO AS DECIMAL(18,0)) AS VARCHAR(8)), 8)
WHERE 
    (s.pcspartenza = 'I' and ve.CodiceEvento ='VIAINSMAN' AND cast(ve.DataOraEvento AS DATE) = CAST(GETDATE() AS DATE))
    OR (v.pcsarrivo = 'I' and ve.CodiceEvento ='VIAINI' AND cast(ve.DataOraEvento AS DATE) = CAST(GETDATE() AS DATE))
	AND rg.SDLITM like '8%';
	
