LEFT JOIN incasdb.eslucart74.dbo.rgord rg
    ON rg.OrdRig_Skid_Ordine = ts.OrdTes_SKID
WHERE 
    (v.pcspartenza = 'I' and ve.CodiceEvento ='VIAINSMAN' AND cast(ve.DataOraEvento AS DATE) = CAST(GETDATE() AS DATE))
    OR (v.pcsarrivo = 'I' and ve.CodiceEvento ='VIAINI' AND cast(ve.DataOraEvento AS DATE) = CAST(GETDATE() AS DATE));*/;


-- dbo.Nazioni source

ALTER VIEW [dbo].[Nazioni] AS
SELECT * 
FROM Localita
WHERE Localita IS NULL AND Cap IS NULL AND Provincia IS NULL AND Regione IS NULL;


-- dbo.OBC_EXP_Autisti source

ALTER VIEW [dbo].[OBC_EXP_Autisti] AS
SELECT * from Autisti;


-- dbo.OBC_EXP_CONSEGNE source

ALTER VIEW [dbo].[OBC_EXP_CONSEGNE] AS
SELECT	IdViaggio, 
		'D' TipoPCS, 
		PCSDestinazione PCS, 
		MAX(S.SequenzaPianificata) SequenzaPianificata,
		MAX(S.PCSDestinazione_RagSoc) PCS_RagSoc,
		MAX(S.PCSDestinazione_Indirizzo) PCS_Indirizzo,
		MAX(S.PCSDestinazione_Localita) PCS_Localita,
		MAX(S.PCSDestinazione_Cap) PCS_Cap,
		MAX(S.PCSDestinazione_Provincia) PCS_Provincia,
		MAX(S.PCSDestinazione_Nazione) PCS_Nazione	
FROM Spedizioni S
WHERE Corrispondente IS NULL
AND IdViaggio IS NOT NULL
GROUP BY IdViaggio, PCSDestinazione  

UNION

SELECT	IdViaggio, 
		'C' TipoPCS, 
		S.Corrispondente PCS, 
		MAX(S.SequenzaPianificata) SequenzaPianificata,
		MAX(PCS.RagioneSociale ) PCS_RagSoc,
		MAX(PCS.Indirizzo) PCS_Indirizzo,
		MAX(PCS.Localita) PCS_Localita,
		MAX(PCS.Cap) PCS_Cap,
		MAX(PCS.Provincia) PCS_Provincia,
		MAX(PCS.Nazione) PCS_Nazione	
FROM Spedizioni S INNER JOIN PCS ON S.Corrispondente =PCS.Codice 
WHERE Corrispondente IS NOT NULL
AND IdViaggio IS NOT NULL
GROUP BY IdViaggio, Corrispondente;


-- dbo.OBC_EXP_Eventi source

ALTER VIEW [dbo].[OBC_EXP_Eventi] AS
SELECT E.*		
FROM Eventi E 
WHERE E.TipoEvento='SPEDIZIONE.ESITO.KO' OR 
E.TipoEvento='UDS.ESITO.KO';


-- dbo.OBC_EXP_PCS source

ALTER VIEW [dbo].[OBC_EXP_PCS] AS
SELECT	D.*,
		S.IdViaggio 
FROM Spedizioni S INNER JOIN Destinatari D ON S.PCSDestinazione =d.Codice
WHERE IdViaggio IS NOT NULL

UNION 

SELECT	C.*,
		S.IdViaggio 
FROM Spedizioni S INNER JOIN Corrispondenti C ON S.Corrispondente =C.Codice
WHERE IdViaggio IS NOT NULL

UNION 

SELECT	PCS.*,
		V.IdViaggio 
FROM Viaggi V INNER JOIN PCS ON V.PCSPartenza = PCS.Codice
WHERE IdViaggio IS NOT NULL

UNION 

SELECT	PCS.*,
		V.IdViaggio 
FROM Viaggi V INNER JOIN PCS ON V.PCSArrivo = PCS.Codice
WHERE IdViaggio IS NOT NULL;


-- dbo.OBC_EXP_SPEDIZIONI source

ALTER VIEW [dbo].[OBC_EXP_SPEDIZIONI] AS
SELECT S.*,
	   CASE 
	   WHEN TS.Is_Ritiro='S' THEN 'R'
	   ELSE 'C'
	   END TipoServizioOBC
FROM Spedizioni S inner join TipiServizi TS ON TS.Codice=S.TipoServizio;


-- dbo.OBC_EXP_SpedizioniUds source

ALTER VIEW [dbo].[OBC_EXP_SpedizioniUds] AS
SELECT	U.*,
		S.IdViaggio  
FROM SpedizioniUds U INNER JOIN Spedizioni S ON S.UniBol=U.Unibol;


-- dbo.OBC_EXP_VIAGGI source

ALTER VIEW [dbo].[OBC_EXP_VIAGGI] AS
SELECT	V.*,	
		dbo.TRUNC(ISNULL(V.DataPartenzaPianificata, GETDATE())) DataViaggio
FROM Viaggi V  
WHERE V.Stato=20;


-- dbo.Province source

ALTER VIEW [dbo].[Province] AS
