-- dbo.RPT_KPI0001 source

ALTER VIEW [dbo].[RPT_KPI0001] AS 
 SELECT C.RagioneSociale as RagioneSocialeCliente, 
		S.UniBol, 
		S.Colli, 
		S.Pallet, 
		S.Volume, 
		S.Cliente , 
		S.Peso, 
		S.Corrispondente, 
		S.CostoViaggioRipartito, 
		Z.Descrizione as DescrizioneZona,  
		S.PCSDestinazione,  
		S.ZonaSpedizione, 
		ZM.Codice as CodiceZonaMacro, 
		ZM.Descrizione as DescrizioneZonaMacro, 
		ISNULL (
				(	SELECT     SUM(ImportoArrotondato) 
                              FROM         dbo.Spedizioni_Costi C
                              WHERE     (Unibol = S.UniBol) AND (RecordZZ = 'N')
				), 0) AS TotaleCosti, 
		ISNULL (
				(	SELECT     SUM(ImportoArrotondato) 
                              FROM         dbo.Spedizioni_Ricavi R
                              WHERE     (Unibol = S.UniBol) AND (RecordZZ = 'N')
				), 0) AS TotaleRicavi, 
		S.IdViaggio,
        S.DataBolla
 FROM   Spedizioni S INNER JOIN Clienti C ON S.Cliente = C.Codice
INNER JOIN ZoneSpedizione Z ON S.ZonaSpedizione=Z.Codice
LEFT JOIN ZoneMacro ZM ON Z.CodiceZonaMacro=ZM.Codice;


-- dbo.RPT_KPI0002 source

ALTER VIEW [dbo].[RPT_KPI0002]
AS
SELECT     	S.UniBol, 
			S.DataBolla, 
			S.PCSDestinazione, 
			S.PCSDestinazione_RagSoc, 
			S.PCSDestinazione_Indirizzo, 
			S.PCSDestinazione_Cap, 
			S.PCSDestinazione_Localita, 
            S.PCSDestinazione_Provincia, 
            S.PCSDestinazione_Nazione, 
            R.Descrizione AS DescrizioneRegione, 
            P.Descrizione AS DescrizioneProvincia, 
            N.Descrizione AS DescrizioneNazione, 
            S.Corrispondente, 
            S.Peso, 
            S.Colli, 
            S.Pallet, 
            S.Volume, 
            S.TassatoPassivo, 
            S.CostoViaggioRipartito, 
            S.RicavoViaggioRipartito, 
            ISNULL (
            		(
            			SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         Spedizioni_Costi AS C
                              WHERE     (Unibol = S.UniBol) AND (RecordZZ = 'N')
					), 0) AS TotaleCosti, 
			ISNULL (
					(
						SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         Spedizioni_Ricavi AS R
                              WHERE     (Unibol = S.UniBol) AND (RecordZZ = 'N')
					), 0) AS TotaleRicavi, 
			S.IdViaggio, 
			P.Provincia, 
			R.Regione, 
            N.Nazione, 
            V.Vettore, 
            V.DataPartenzaEffettiva
                      
FROM Viaggi V INNER JOIN Spedizioni S ON V.IdViaggio = S.IdViaggio 
LEFT JOIN Province P ON P.Provincia = S.PCSDestinazione_Provincia
LEFT JOIN Regioni R ON R.Regione = P.Regione 
LEFT JOIN Nazioni N ON N.Nazione = P.Nazione;


-- dbo.RPT_KPI0003 source

ALTER VIEW [dbo].[RPT_KPI0003]  AS 
SELECT 	T.RAGIONESOCIALE AS RAGIONESOCIALEVETTORE, 
 		S.UNIBOL, 
		S.COLLI, 
		S.PALLET, 
		S.VOLUME, 
		S.CLIENTE , 
		S.PESO, 
		S.CORRISPONDENTE, 
		S.COSTOVIAGGIORIPARTITO, 
		ZONE.DESCRIZIONE AS DESCRIZIONEZONA,  
		S.PCSDESTINAZIONE,  
		S.ZonaArrivoTariffaPassiva, 
		ZONEMACRO.CODICE AS CODICEZONAMACRO, 
		ZONEMACRO.DESCRIZIONE AS DESCRIZIONEZONAMACRO, 
		ISNULL(
				(
					SELECT     SUM(IMPORTOARROTONDATO) 
					FROM         SPEDIZIONI_COSTI C
                    WHERE     (UNIBOL = S.UNIBOL) AND (RECORDZZ = 'N')
				), 0) AS TOTALECOSTI, 
		ISNULL(
				(
					SELECT     SUM(IMPORTOARROTONDATO) 
                    FROM         SPEDIZIONI_RICAVI R
                    WHERE     (UNIBOL = S.UNIBOL) AND (RECORDZZ = 'N')
				), 0) AS TOTALERICAVI, 
		S.IDVIAGGIO ,
        S.DATABOLLA, 
        v.Vettore 
 FROM  SPEDIZIONI S
 INNER JOIN VIAGGI V ON V.IDVIAGGIO=S.IDVIAGGIO
 INNER JOIN TRASPORTATORI T ON V.VETTORE =T.CODICE 
 LEFT JOIN ZONETARIFFAPASSIVA ZONE ON S.ZonaArrivoTariffaPassiva=ZONE.CODICE
 LEFT JOIN ZONEMACRO ZONEMACRO ON ZONE.CODICEZONAMACRO=ZONEMACRO.CODICE;


-- dbo.RPT_KPI0004 source

ALTER VIEW [dbo].[RPT_KPI0004]
AS
SELECT     	S.UniBol, 
			S.DataBolla, 
			S.PCSDestinazione, 
			S.PCSDestinazione_RagSoc, 
            S.PCSDestinazione_Indirizzo, 
            S.PCSDestinazione_Cap, 
            S.PCSDestinazione_Localita, 
            S.PCSDestinazione_Provincia, 
            S.PCSDestinazione_Nazione, 
            P.Descrizione AS DescrizioneProvincia, 
            S.Corrispondente, 
            S.Peso, 
            S.Colli, 
            S.Pallet, 
            S.Volume, 
            S.IdViaggio, 
            P.Provincia, 
            V.Vettore, 
            V.DataPartenzaEffettiva, 
            S.Cliente, 
            C.RagioneSociale, 
            R.Regione
                      
FROM Viaggi V INNER JOIN Spedizioni S ON V.IdViaggio = S.IdViaggio 
INNER JOIN Clienti C ON S.Cliente = C.Codice 
LEFT JOIN Province P ON P.Provincia = S.PCSDestinazione_Provincia
LEFT JOIN Regioni R ON R.Regione = P.Regione 
LEFT JOIN Nazioni N ON N.Nazione = P.Nazione;


-- dbo.RPT_KPI0005 source

ALTER VIEW [dbo].[RPT_KPI0005]
AS
SELECT     	S.DataConsegnaPrevista1 AS DataPrevista1, 
			S.DataConsegnaPrevista2, 
			T.DataEsito, 
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S') = 0 THEN 1 ELSE 0 END AS Giorno0, 
            CASE WHEN ABS(dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S')) = 1 THEN 1 ELSE 0 END AS Giorno1, 
            CASE WHEN ABS(dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S')) = 2 THEN 1 ELSE 0 END AS Giorno2, 
            CASE WHEN ABS(dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S')) = 3 THEN 1 ELSE 0 END AS Giorno3, 
			CASE WHEN ABS(dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S')) > 3 THEN 1 ELSE 0 END AS Giorno4, 
			S.UniBol, 
			P.Descrizione AS DescrizioneProvincia, 
			P.Regione, 
			C.RagioneSociale, 
			S.Cliente, 
            S.PCSDestinazione_Provincia, 
            S.DataBolla, 
            P.Provincia, 
            CASE WHEN DataConsegnaConcordata IS NULL THEN DATEDIFF(d, DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1)) ELSE 0 END AS GGCONTRATTO, 
            dbo.TRUNC(S.DatIns) AS DATAACQUISIZIONE, 
            R.Descrizione AS DescrizioneRegione
FROM Spedizioni S INNER JOIN Clienti C ON C.Codice = S.Cliente 
INNER JOIN	(
				SELECT  Spedizioni_Eventi.Unibol, 
						MAX(dbo.TRUNC(Spedizioni_Eventi.DataOraEvento)) AS DataEsito
                FROM    Spedizioni_Eventi INNER JOIN Eventi ON Spedizioni_Eventi.CodiceEvento = Eventi.Codice AND Eventi.TipoEvento LIKE 'SPEDIZIONE.ESITO%'
                GROUP BY Spedizioni_Eventi.Unibol
            ) T ON T.Unibol = S.UniBol AND S.DataConsegnaPrevista1 IS NOT NULL
LEFT JOIN Province P ON P.Provincia = S.PCSDestinazione_Provincia
LEFT JOIN Regioni R ON R.Regione = P.Regione;


-- dbo.RPT_KPI0006 source

ALTER VIEW [dbo].[RPT_KPI0006] AS
SELECT     	S.DataConsegnaPrevista1 AS DataPrevista1, 
			S.DataConsegnaPrevista2, 
			T.DataEsito, 
			dbo.TRUNC(S.DatIns) AS DATAACQUISIZIONE, 
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK(dbo.TRUNC(S.DatIns) , dataesito,'S') <1 then 1 else 0 end as Giorno0,
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK(dbo.TRUNC(S.DatIns) , dataesito,'S') = 1 then 1 else 0 end as Giorno1,
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK(dbo.TRUNC(S.DatIns) , dataesito,'S') =2 then 1 else 0 end as Giorno2,
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK(dbo.TRUNC(S.DatIns) , dataesito,'S') =3 then 1 else 0 end as Giorno3,
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK(dbo.TRUNC(S.DatIns) , dataesito,'S') >3 then 1 else 0 end as Giorno4,
			CASE WHEN dbo.DATEDIFF_CALENDAR_IFWORK_SLA(DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1), dataesito, 'S') = 0 THEN 1 ELSE 0 END AS OnTime, 
			S.UniBol, 
			P.Descrizione AS DescrizioneProvincia, 
			P.Regione, 
			C.RagioneSociale, 
			S.Cliente, 
			S.PCSDestinazione_Provincia, 
			S.DataBolla, 
			P.Provincia, 
			CASE WHEN DataConsegnaConcordata IS NULL THEN DATEDIFF(d, DataConsegnaPrevista1, isnull(DataConsegnaPrevista2, DataConsegnaPrevista1)) ELSE 0 END AS GGCONTRATTO, 
			R.Descrizione AS DescrizioneRegione
FROM Spedizioni S INNER JOIN Clienti C ON C.Codice = S.Cliente 
INNER JOIN	(
				SELECT  Spedizioni_Eventi.Unibol, 
						MAX(dbo.TRUNC(Spedizioni_Eventi.DataOraEvento)) AS DataEsito
                FROM    Spedizioni_Eventi INNER JOIN Eventi ON Spedizioni_Eventi.CodiceEvento = Eventi.Codice AND Eventi.TipoEvento LIKE 'SPEDIZIONE.ESITO%'
                GROUP BY Spedizioni_Eventi.Unibol
            ) T ON T.Unibol = S.UniBol AND S.DataConsegnaPrevista1 IS NOT NULL
LEFT JOIN Province P ON P.Provincia = S.PCSDestinazione_Provincia
LEFT JOIN Regioni R ON R.Regione = P.Regione;


-- dbo.RPT_RIFORNIMENTI source

ALTER  VIEW [dbo].[RPT_RIFORNIMENTI]
as
SELECT DataOra,  

		Autista, 
