-- dbo.RPT_RIMESSA_01 source

ALTER VIEW [dbo].[RPT_RIMESSA_01] AS 
SELECT	R.Id IDRimessa,
		R.DataRimessa,
		R.Cliente,
		R.Stato StatoRimessa,
		R.Note1 Note1_Rimessa,
		 R.Note2 Note2_Rimessa,
		 R.Note3 Note3_Rimessa,
		 R.DataConferma DataConferma_Rimessa,
		 CL.RagioneSociale Cliente_RagioneSociale,
		 CL.Indirizzo Cliente_Indirizzo,
		 CL.Cap Cliente_Cap,
		 CL.Localita Cliente_Localita,
		 Cl.Provincia Cliente_Provincia,
		 CL.Nazione Cliente_Nazione,
		 C.unibolMaster, 
		 C.DataCreazione Contra_DataCreazione,
		 C.DataIncasso Contra_DataIncasso,
		 C.Contrassegno Contra_Valore,
		 C.Id Contra_Id,
		 C.DataEsito Contra_DataEsito,
		 C.CausaleEsito Contra_CausaleEsito,
		 C.NoteIncasso Contra_NoteIncasso,
		 C.NoteEsito Contra_NoteEsito,
		 S.PCSDestinazione Sped_PCSDestinazione,
		 S.PCSDestinazione_Cap Sped_PCSDestinazione_Cap,
		 S.PCSDestinazione_Indirizzo  Sped_PCSDestinazione_Indirizzo,
		 S.PCSDestinazione_Localita Sped_PCSDestinazione_Localita,
		 S.PCSDestinazione_Nazione Sped_PCSDestinazione_Nazione,
		 S.PCSDestinazione_Provincia Sped_PCSDestinazione_Prov,
		 S.PCSDestinazione_RagSoc Sped_PCSDestinazione_RagSoc,
		 S.NumeroBolla Sped_NumeroBolla,
		 S.DataBolla Sped_DataBolla,
		 S.NumeroOrdine Sped_NumeroOrdine,
		 S.DataOrdine Sped_DataOrdine,
		 TI.Descrizione TipoIncasso_Descrizione,
		 ISNULL(S.MittenteRagioneSociale, Mitt.RagioneSociale) MittenteRagioneSociale    

FROM Contrassegni_Rimesse R LEFT JOIN Clienti CL ON CL.Codice =R.Cliente
LEFT JOIN Contrassegni C ON C.IdRimessa =R.Id 
LEFT JOIN Spedizioni S ON S.UniBol =C.UnibolMaster 
LEFT JOIN Clienti Mitt ON mitt.Codice =S.Mittente 
LEFT JOIN TIPIINCASSO TI ON TI.Codice=C.TipoIncasso;


-- dbo.RPT_SPEDIZIONI source

ALTER VIEW [dbo].[RPT_SPEDIZIONI]
AS
SELECT	TIPOServizio AS TIPO,  
		V.autista1Effettivo as AUTISTA ,
		DBO.TRUNC(DataOraArrivoEffettiva) AS DATA,	
		DataOraArrivoEffettiva as DataOra,			
		CASE WHEN S.TIPOSPEDIZIONE = '002' THEN CampoCalcolo3 ELSE S.PESO  END AS VALORE1, 
		CASE WHEN S.TIPOSPEDIZIONE = '002' THEN CampoCalcolo4 ELSE NULL END AS VALORE2, 
		'' AS VALORE3,
		CASE WHEN S.TIPOSPEDIZIONE = '002' THEN (SELECT DESCRIZIONE FROM TABCAMPICALCOLO WHERE NOMECAMPO = 'CampoCalcolo3')  
			 ELSE (SELECT DESCRIZIONE FROM TABCAMPICALCOLO WHERE NOMECAMPO = 'Peso') END AS LABELVALORE1, 
		CASE WHEN S.TIPOSPEDIZIONE = '002' THEN (SELECT DESCRIZIONE FROM TABCAMPICALCOLO WHERE NOMECAMPO = 'CampoCalcolo4')  
			 ELSE '' END AS LABELVALORE2, 		
		S.KMMANUALI KM,
		CASE WHEN TIPOServizio = 'C' 
		THEN ISNULL(PCSPartenza_RagSoc,'') 
		ELSE ISNULL(PCSDestinazione_RagSoc,'')  
		END AS RAGIONESOCIALE,
		CASE WHEN TIPOServizio = 'C' 
		THEN  ISNULL(PCSPartenza_Localita,'') 
		ELSE ISNULL( PCSDestinazione_Localita,'')
		END AS LOCALITA,
		CASE WHEN TIPOServizio = 'C' 
		THEN ISNULL(PCSPartenza_Provincia ,'') 
		ELSE ISNULL(PCSDestinazione_Provincia,'') 
		END AS PROVINCIA,		
		V.TIPOSPEDIZIONE,
		CASE WHEN S.TIPOSPEDIZIONE = '002' AND S.NUMEROBOLLA LIKE 'S%' THEN CampoCalcolo3 ELSE 0 END AS BOMBOLESIAD,
		CASE WHEN S.TIPOSPEDIZIONE = '002' AND S.NUMEROBOLLA NOT LIKE 'S%' THEN CampoCalcolo3 ELSE 0 END AS BOMBOLERIVOIRA,
		CASE WHEN S.TIPOSPEDIZIONE = '002'  THEN CampoCalcolo4 ELSE 0 END AS BOMBOLEVUOTE,
		SequenzaEffettiva AS SEQUENZA,
		S.IDVIAGGIO 
FROM    SPEDIZIONI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO 
UNION	
SELECT	'E' AS TIPO,  
		V.autista1Effettivo as AUTISTA ,
		DBO.TRUNC(DataServizio) AS DATA,	
		DataServizio AS DataOra,			
		NULL AS VALORE1, 
		NULL AS VALORE2, 
				CAST(CAST(ISNULL(QUANTITA1,0) AS int) AS VARCHAR(15)) + ' '+ RIGHT(T.DESCRIZIONE, 5) AS VALORE3, 
		NULL AS LABELVALORE1, 
		NULL AS LABELVALORE2, 		
		S.KM,
		T.DESCRIZIONE AS RAGIONESOCIALE,
		LOCALITA,
		PROVINCIA,		
		V.TIPOSPEDIZIONE,
		NULL AS BOMBOLESIAD,
		NULL AS BOMBOLERIVOIRA,
		NULL AS BOMBOLEVUOTE,
		Sequenza,
		S.IDVIAGGIO
FROM    VIAGGI_SERVIZI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO 
		INNER JOIN VIAGGI_TIPISERVIZI T ON T.CODICE = S.TIPOSERVIZIO;


-- dbo.RPT_SPEDIZIONI_STAT source

