AS
SELECT     UniBol, UnibolParent, UnibolMaster, UnibolOBC, ProgressivoConsegna, Barcode, Stato, StatoOBC, Prebolla, TipoServizio, Cliente, Mittente, MittenteRagioneSociale, 
                      ClienteFatturazione, NumeroBolla, DataBolla, NumeroOrdine, DataOrdine, NumeroOrdineCliente, DataOrdineCliente, TipoSpedizione, TipoSpedizionePassivo, 
                      TipoMerce, PCSPartenza, PCSPartenza_RagSoc, PCSPartenza_Indirizzo, PCSPartenza_Cap, PCSPartenza_Localita, PCSPartenza_Provincia, PCSPartenza_Nazione, 
                      PCSDestinazione, PCSDestinazione_RagSoc, PCSDestinazione_Indirizzo, PCSDestinazione_Cap, PCSDestinazione_Localita, PCSDestinazione_Provincia, 
                      PCSDestinazione_Nazione, DestinazioneCliente, Destinatario, DestinatarioCliente, ZonaSpedizione, ZonaPartenzaTariffaAttiva, ZonaArrivoTariffaAttiva, 
                      ZonaPartenzaTariffaPassiva, ZonaArrivoTariffaPassiva, DataConsegnaPrevista1, DataConsegnaPrevista2, NoteConsegnaPrevista, DataConsegnaConcordata, 
                      OraConsegnaConcordata1, OraConsegnaConcordata2, NoteConsegnaConcordata, RiferimentoConsegnaConcordata, CausaleConsegnaConcordata, DataRitiroPrevista1,
                       DataRitiroPrevista2, NoteRitiroPrevisto, OraRitiroConcordata1, OraRitiroConcordata2, NoteRitiroConcordata, RiferimentoRitiroConcordata, CausaleRitiroConcordata, 
                      Corrispondente, Trasportatore, Peso, Colli, Pallet, Volume, CampoCalcolo1, CampoCalcolo2, CampoCalcolo3, CampoCalcolo4, CampoCalcolo5, CampoCalcolo6, 
                      CampoCalcolo7, CampoCalcolo8, CampoCalcolo9, CampoCalcolo10, Flag1, Flag2, Flag3, Flag4, Flag5, Flag6, Flag7, Flag8, Flag9, Flag10, Contrassegno, 
                      TassatoAttivo, TassatoPassivo, Note, DataOraPartenzaPianificata, DataOraPartenzaEffettiva, DataOraArrivoPianificata, DataOraArrivoEffettiva, KmPianificati, KmGPS, 
                      KmManuali, KmRicalcolati, DataCompetenzaAttiva, DataCompetenzaPassiva, IdFatturaAttiva, IdFatturaPassiva, IdViaggio, SequenzaPianificata, SequenzaEffettiva, 
                      SequenzaOriginale, FillerAlfa1, FillerAlfa2, FillerAlfa3, FillerAlfa4, FillerAlfa5, FillerAlfa6, FillerAlfa7, FillerAlfa8, FillerAlfa9, FillerAlfa10, FillerData1, FillerData2, 
                      FillerData3, FillerData4, FillerData5, BatchId, DataSpedizione, StatoWMS, StatoSpuntaUscita, BloccoAmministrativo, DatIns, UteIns, DatAgg, UteAgg, BloccaCosti, 
                      BloccaRicavi, IdRaggruppamentoAttivo, IdRaggruppamentoPassivo, TipoContrattoAttivoApplicato, TipoContrattoPassivoApplicato, ErroreTariffaAttiva, 
                      ErroreTariffaPassiva, DataEsportazioneCorrispondente, CostoViaggioRipartito, RicavoViaggioRipartito, IdViaggioLinea, DataOraPartenzaRicalcolata, 
                      DataOraArrivoRicalcolata, ISNULL
                          ((SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         dbo.Spedizioni_Costi AS C
                              WHERE     (Unibol = SP.UniBol) AND (RecordZZ = 'N')), 0) AS TotaleCosti, ISNULL
                          ((SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         dbo.Spedizioni_Ricavi AS R
                              WHERE     (Unibol = SP.UniBol) AND (RecordZZ = 'N')), 0) AS TotaleRicavi, CAST(IdViaggio AS varchar(15)) AS Annbor
FROM         dbo.Spedizioni AS SP;


-- dbo.RPT_SUB_FATT_ATT_01 source

ALTER VIEW [dbo].[RPT_SUB_FATT_ATT_01] 
AS
SELECT	T.IDFATTURA,		
		CI1.CODICE AS CODICEIVATOT,
		CI1.DESCRIZIONE AS DESCRIZIONEIVATOT,
		I.IMPONIBILE,
		I.ALIQUOTA,
		I.IMPOSTA,
		I.IMPOSTA + I.IMPONIBILE AS TOTALEIVA
FROM	FATTURE_ATTIVE_TESTATA T 		
		INNER JOIN FATTURE_ATTIVE_IVA I ON I.IDFATTURA = T.IDFATTURA 
		INNER JOIN CODICIIVA CI1 ON CI1.CODICE = I.CODICEIVA;


-- dbo.RPT_SUB_FATT_PAS_01 source

ALTER VIEW [dbo].[RPT_SUB_FATT_PAS_01] 
AS
SELECT	T.IDFATTURA,		
		CI1.CODICE AS CODICEIVATOT,
		CI1.DESCRIZIONE AS DESCRIZIONEIVATOT,
