-- dbo.RPT_VIAGGIO_01 source

ALTER VIEW [dbo].[RPT_VIAGGIO_01] AS

SELECT 
	V.IdViaggio,
	'*' + cast(V.IdViaggio as varchar) + '*' BarcodeViaggio, 
	case  SequenzaEffettiva When 0 then SequenzaPianificata else SequenzaEffettiva end as Sequenza,
	IsNull(IsNull(DataPartenzaEffettiva,DataPartenzaPianificata),getdate()) as DataPartenza,
	T.RagioneSociale as T_RagioneSociale, T.Indirizzo as T_Indirizzo, T.Localita as T_Localita, T.Provincia as T_Provincia,
	T.PartitaIva as T_PartitaIva, T.AlboTrasportatori as T_Albo,
	--V.PcsPartenza, V.PcsArrivo,
	Pcs_VPart.Localita as V_PartLoc ,Pcs_VPart.Provincia  as V_PartProv,
	Pcs_VArr.Localita as V_ArrLoc ,Pcs_VArr.Provincia  as V_ArrProv,
	isNull(Me.Descrizione,Mp.Descrizione) as V_MezzoDescrizione,
	isNull(Me.Targa,Mp.Targa) as V_MezzoTarga,
	S.UniBol,S.NumeroBolla,S.DataBolla,S.NumeroOrdine,
	isNull(S.DataConsegnaConcordata,S.DataConsegnaPrevista1) as DataConsegna,
	C.RagioneSociale as ClienteRagSoc,
	S.PCSDestinazione_RagSoc as Destinatario,
	S.PCSDestinazione_Indirizzo as Indirizzo,S.PCSDestinazione_Localita as Localita, S.PCSDestinazione_Provincia as Provincia,
	S.Colli,S.peso,S.Volume,S.Pallet,
	S.Corrispondente,
	Corrisp.ragionesociale as C_RagioneSociale,Corrisp.Indirizzo as C_Indirizzo, Corrisp.Localita as C_Localita, Corrisp.Provincia as C_Provincia

FROM Viaggi V
	left Join Trasportatori T on V.Vettore = T.Codice
	left Join Pcs Pcs_VPart on V.PcsPartenza = Pcs_VPart.Codice
	left Join Pcs Pcs_VArr on V.PcsArrivo = Pcs_VArr.Codice
	left join Mezzi Me on V.MotriceEffettiva = Me.Codice
	left join Mezzi Mp on V.MotricePianificata = Mp.Codice
	Join Spedizioni S on V.IdViaggio = S.IdViaggio
	Join Clienti C on S.Cliente = C.Codice

	left Join Pcs Corrisp on S.Corrispondente = Corrisp.Codice;


-- dbo.RPT_VIAGGIO_02 source

ALTER VIEW [dbo].[RPT_VIAGGIO_02] AS

SELECT 
	V.IdViaggio,
	'*' + cast(V.IdViaggio as varchar) + '.' +S.Corrispondente  +  '*' BarcodeViaggio, 
	case  SequenzaEffettiva When 0 then SequenzaPianificata else SequenzaEffettiva end as Sequenza,
	IsNull(IsNull(DataPartenzaEffettiva,DataPartenzaPianificata),getdate()) as DataPartenza,
	T.RagioneSociale as T_RagioneSociale, T.Indirizzo as T_Indirizzo, T.Localita as T_Localita, T.Provincia as T_Provincia,
	T.PartitaIva as T_PartitaIva, T.AlboTrasportatori as T_Albo,
	--V.PcsPartenza, V.PcsArrivo,
	Pcs_VPart.Localita as V_PartLoc ,Pcs_VPart.Provincia  as V_PartProv,
	Pcs_VArr.Localita as V_ArrLoc ,Pcs_VArr.Provincia  as V_ArrProv,
	isNull(Me.Descrizione,Mp.Descrizione) as V_MezzoDescrizione,
	isNull(Me.Targa,Mp.Targa) as V_MezzoTarga,
	S.UniBol,S.NumeroBolla,S.DataBolla,S.NumeroOrdine,
	isNull(S.DataConsegnaConcordata,S.DataConsegnaPrevista1) as DataConsegna,
	C.RagioneSociale as ClienteRagSoc,
	S.PCSDestinazione_RagSoc as Destinatario,
	S.PCSDestinazione_Indirizzo as Indirizzo,S.PCSDestinazione_Localita as Localita, S.PCSDestinazione_Provincia as Provincia,
	S.Colli,S.peso,S.Volume,S.Pallet,
	S.Corrispondente,
	Corrisp.ragionesociale as C_RagioneSociale,Corrisp.Indirizzo as C_Indirizzo, Corrisp.Localita as C_Localita, 
	Corrisp.Provincia as C_Provincia, Corrisp.PartitaIva as C_PartitaIva

FROM Viaggi V
	left Join Trasportatori T on V.Vettore = T.Codice
	left Join Pcs Pcs_VPart on V.PcsPartenza = Pcs_VPart.Codice
	left Join Pcs Pcs_VArr on V.PcsArrivo = Pcs_VArr.Codice
	left join Mezzi Me on V.MotriceEffettiva = Me.Codice
	left join Mezzi Mp on V.MotricePianificata = Mp.Codice
	Join Spedizioni S on V.IdViaggio = S.IdViaggio
	Join Clienti C on S.Cliente = C.Codice
	left Join Pcs Corrisp on S.Corrispondente = Corrisp.Codice
	Where isNull(S.Corrispondente,'') <> '';


-- dbo.RPT_VIAGGI_STAT source

ALTER VIEW [dbo].[RPT_VIAGGI_STAT]

AS
WITH CTE_Spedizioni AS (
  SELECT S.*, 
    CASE when TS.Is_Consegna ='S' THEN +1 WHEN TS.Is_ritiro ='S' THEN -1 ELSE 0 END SEGNO
    FROM Spedizioni S LEFT join TipiServizi TS ON S.Tiposervizio=TS.Codice        
    )
SELECT     IdViaggio, Stato, TipoViaggio, DataPartenzaPianificata, DataArrivoPianificata, DataPartenzaEffettiva, DataArrivoEffettiva, MotricePianificata, Rimorchio1Pianificato, 
                      Contenitore1Pianificato, Rimorchio2Pianificato, Contenitore2Pianificato, MotriceEffettiva, Rimorchio1Effettivo, Contenitore1Effettivo, Rimorchio2Effettivo, 
                      Contenitore2Effettivo, TipoUnitaViaggiante, Vettore, Autista1Pianificato, Autista1Effettivo, Autista2Effettivo, TipoSpedizione, TipoMerce, ZonaPartenza, ZonaArrivo, 
                      Cliente, TipoSpedizioneAttiva, ZonaPartenzaTariffaAttiva, ZonaArrivoTariffaAttiva, PCSPartenza, PCSArrivo, PCSPartenzaEffettivo, PCSArrivoEffettivo, 
                      IdFatturaPassiva, TassatoPassivo, KmPianificati, KmManuali, KmGPS, KmRicalcolati, PesoPassivo, ColliPassivo, PalletPassivo, VolumePassivo, 
                      CampoCalcolo1Passivo, CampoCalcolo2Passivo, CampoCalcolo3Passivo, CampoCalcolo4Passivo, CampoCalcolo5Passivo, CampoCalcolo6Passivo, 
                      CampoCalcolo7Passivo, CampoCalcolo8Passivo, CampoCalcolo9Passivo, CampoCalcolo10Passivo, PesoAttivo, ColliAttivo, PalletAttivo, VolumeAttivo, 
                      CampoCalcolo1Attivo, CampoCalcolo2Attivo, CampoCalcolo3Attivo, CampoCalcolo4Attivo, CampoCalcolo5Attivo, CampoCalcolo6Attivo, CampoCalcolo7Attivo, 
                      CampoCalcolo8Attivo, CampoCalcolo9Attivo, CampoCalcolo10Attivo, Sagome, Flag1, Flag2, Flag3, Flag4, Flag5, Flag6, Flag7, Flag8, Flag9, Flag10, Note1, Note2, 
                      DatIns, UteIns, DatAgg, UteAgg, Terminale, IdViaggioOBC, IdViaggioHost, FlagViaggioSospeso, TassatoAttivo, IdFatturaAttiva, BloccaCosti, BloccaRicavi, 
                      IdRaggruppamentoAttivo, IdRaggruppamentoPassivo, TipoContrattoAttivoApplicato, TipoContrattoPassivoApplicato, ErroreTariffaAttiva, ErroreTariffaPassiva, 
                      KmCertificati, DataPartenzaRicalcolata, DataArrivoRicalcolata, MinutiGuidaPianificati, MinutiGuidaEffettivi, SagomeEffettive, NoteInizioViaggio, NoteFineViaggio, 
                      VolumeEffettivo, PalletEffettivi, MinutiGuidaRicalcolati, CAST(IdViaggio AS VARCHAR(15)) AS ANNBOR, ISNULL
                          ((SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         dbo.Viaggi_Costi AS C
                              WHERE     (IdViaggio = V.IdViaggio) AND (RecordZZ = 'N')), 0) AS TotaleCosti, ISNULL
                          ((SELECT     SUM(ImportoArrotondato) AS Expr1
                              FROM         dbo.Viaggi_Ricavi AS R
                              WHERE     (IdViaggio = V.IdViaggio) AND (RecordZZ = 'N')), 0) AS TotaleRicavi, ISNULL
                          ((SELECT     COUNT(UniBol) AS Expr1
                              FROM         dbo.Spedizioni
                              WHERE     (IdViaggio = V.IdViaggio)), 0) AS TotaleSpedizioni, 0 AS TotaleConsegne,
                                        (
                                        SELECT ISNULL(SUM(ISNULL(Peso*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet*Segno,0)),0) FROM CTE_Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet
FROM         dbo.Viaggi AS V;


-- dbo.RPT_Viaggi source

ALTER VIEW [dbo].[RPT_Viaggi]
AS
SELECT     dbo.Viaggi.IdViaggio, dbo.Viaggi.Stato, dbo.Viaggi.DataArrivoEffettiva, dbo.Viaggi.MotriceEffettiva, ISNULL(dbo.Viaggi.Rimorchio1Effettivo, 
                      dbo.Viaggi.Contenitore1Effettivo) AS Cisterna, dbo.Viaggi.Vettore, dbo.Viaggi.Autista1Effettivo, dbo.Viaggi.Autista2Effettivo, dbo.Viaggi.TipoSpedizione, 
                      dbo.Viaggi.TipoMerce, Viaggi_Eventi_1.DataOraEvento AS DataOraInizio, dbo.Viaggi_Eventi.DataOraEvento AS DataOrafine, 
                      Viaggi_Eventi_1.Localita AS localitapartenza, Viaggi_Eventi_1.Provincia AS PROVINCIAPARTENZA, dbo.Viaggi_Eventi.Localita AS LOCALITAARRIVO, 
                      dbo.Viaggi_Eventi.Provincia AS PROVINCIAARRIVO, dbo.TipiSpedizione.Descrizione AS DescrizioneTipoSpedizione, 
                      dbo.TipiMerce.Descrizione AS DescrizioneTipoMerce, CASE WHEN rimorchio1effettivo IS NOT NULL 
                      THEN Mezzi_1.Targa ELSE dbo.Mezzi.Targa END AS TargaCisterna, ISNULL(dbo.VW_SPEDIZIONI_PRIMOSCARICO.DATAPRIMOSCARICO, 
                      dbo.TRUNC(Viaggi_Eventi_1.DataOraEvento)) AS DATARIF, dbo.TipiMezzo.Descrizione AS DescrizioneTIPOMEZZO, Mezzi_1.Descrizione AS DESCRIZIONECISTERNA, 
                      Autisti_1.RagioneSociale AS RagioneSocialeAutista2, dbo.Autisti.RagioneSociale AS RagioneSocialeAutista1, dbo.Viaggi.KmGPS, dbo.Viaggi.KmManuali, 
                      dbo.VW_VIAGGI_PRIMOEVENTO_MEZZO.KMMANUALI AS KMINIZIO, dbo.VW_VIAGGI_ULTIMOEVENTO_MEZZO.KMMANUALI AS KMFINE, 
                      ISNULL(dbo.VW_SPEDIZIONI_VIAGGI_MEZZI_S.SERVIZI, 0) AS SCARICHI
FROM         dbo.Viaggi INNER JOIN
                      dbo.VW_VIAGGI_PRIMOEVENTO_MEZZO ON dbo.Viaggi.IdViaggio = dbo.VW_VIAGGI_PRIMOEVENTO_MEZZO.IDVIAGGIO INNER JOIN
                      dbo.VW_VIAGGI_ULTIMOEVENTO_MEZZO ON dbo.Viaggi.IdViaggio = dbo.VW_VIAGGI_ULTIMOEVENTO_MEZZO.IDVIAGGIO INNER JOIN
                      dbo.Viaggi_Eventi AS Viaggi_Eventi_1 ON dbo.VW_VIAGGI_PRIMOEVENTO_MEZZO.ID = Viaggi_Eventi_1.Id INNER JOIN
                      dbo.Viaggi_Eventi ON dbo.VW_VIAGGI_ULTIMOEVENTO_MEZZO.ID = dbo.Viaggi_Eventi.Id left JOIN
                      dbo.TipiMerce ON dbo.Viaggi.TipoMerce = dbo.TipiMerce.Codice INNER JOIN
                      dbo.Mezzi AS Mezzi_1 ON dbo.Viaggi.Rimorchio1Effettivo = Mezzi_1.Codice INNER JOIN
                      dbo.TipiSpedizione ON dbo.Viaggi.TipoSpedizione = dbo.TipiSpedizione.Codice INNER JOIN
                      dbo.TipiMezzo ON Mezzi_1.TipoMezzo = dbo.TipiMezzo.Codice LEFT OUTER JOIN
                      dbo.VW_SPEDIZIONI_VIAGGI_MEZZI_S ON dbo.Viaggi.IdViaggio = dbo.VW_SPEDIZIONI_VIAGGI_MEZZI_S.IDVIAGGIO LEFT OUTER JOIN
                      dbo.Autisti ON dbo.Viaggi.Autista1Effettivo = dbo.Autisti.Codice LEFT OUTER JOIN
                      dbo.Autisti AS Autisti_1 ON dbo.Viaggi.Autista2Effettivo = Autisti_1.Codice LEFT OUTER JOIN
                      dbo.Mezzi ON dbo.Viaggi.Contenitore1Effettivo = dbo.Mezzi.Codice LEFT OUTER JOIN
                      dbo.VW_SPEDIZIONI_PRIMOSCARICO ON dbo.Viaggi.IdViaggio = dbo.VW_SPEDIZIONI_PRIMOSCARICO.IDVIAGGIO
WHERE     (dbo.Viaggi.DataArrivoEffettiva IS NOT NULL) AND (dbo.Viaggi.MotriceEffettiva IS NOT NULL);


-- dbo.Regioni source

ALTER VIEW [dbo].[Regioni] AS
SELECT * 
FROM Localita
WHERE Localita IS NULL AND Cap IS NULL AND Provincia IS NULL AND Regione IS NOT NULL;


-- dbo.Sessioni source

ALTER VIEW [dbo].[Sessioni] as 
SELECT *, HostName Host_Name
FROM Master..SysProcesses;


-- dbo.TAR_ATT_COD_Document source

ALTER VIEW [dbo].[TAR_ATT_COD_Document]
AS
SELECT	
		/*
			Estremi del documento
		*/
		C.Id							ID,
		C.Id							IDContrassegno,
		'CONTRASSEGNO'					TipoDocumento,
		DBO.TRUNC(C.DataCreazione)		DataDocumento,
		/*
			Id Sottodocumenti
		*/
		C.ID						IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		C.Cliente						SoggettoAttivo,
		C.ClienteFatturazione 			SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		NULL							SoggettoPassivo,
		NULL							SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo Mezzo
		*/
		'*ALL'							TipoMezzo,
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		'*ALL'							Cliente,
		/*
			Date di competenza
		*/
		C.DataCompetenzaAttiva			DataCompetenzaAttiva,
		C.DataCompetenzaPassiva			DataCompetenzaPassiva,
		'DataIncasso'					CampoDataCompetenzaAttiva,
		'DataIncasso'					CampoDataCompetenzaPassiva,		
		/*
			Campi di valorizzazione
		*/
		S.Peso							Peso,		
		S.Colli							Colli,
		S.Pallet						Pallet,
		S.Volume						Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,	
		C.Contrassegno					Contrassegno,
		S.CampoCalcolo1					CampoCalcolo1,
		S.CampoCalcolo2					CampoCalcolo2,
		S.CampoCalcolo3					CampoCalcolo3,
		S.CampoCalcolo4					CampoCalcolo4,
		S.CampoCalcolo5					CampoCalcolo5,
		S.CampoCalcolo6					CampoCalcolo6,
		S.CampoCalcolo7					CampoCalcolo7,
		S.CampoCalcolo8					CampoCalcolo8,
		S.CampoCalcolo9					CampoCalcolo9,
		S.CampoCalcolo10				CampoCalcolo10,	   
		1								Forfait,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN C.BloccaRicavi='S' THEN 'N'
			WHEN C.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'N'		
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END						CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (C.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'		
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'S'	
			WHEN (C.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,			
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN S.BloccaCosti='S' THEN 'N'
			WHEN S.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (C.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (C.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		C.UnibolApertura,		
		C.UnibolChiusura,		
		C.UnibolMaster,			
		C.DataCreazione,	
		C.DataEsito,
		C.CausaleEsito,
		C.DataIncasso,
		C.IdRimessa,
		C.TipoIncasso, 
		S.ProgressivoConsegna,
		S.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		C.FillerAlfa1,
		C.FillerAlfa2,
		C.FillerAlfa3,
		C.FillerAlfa4,
		C.FillerAlfa5,
		C.FillerAlfa6,
		C.FillerAlfa7,
		C.FillerAlfa8,
		C.FillerAlfa9,
		C.FillerAlfa10,						
		C.BloccaRicavi,		
		C.BloccaCosti,										
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro		
		
FROM	Contrassegni  C
		INNER JOIN VW_Spedizioni S ON C.UnibolMaster = S.unibol
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN Clienti CL ON CL.Codice=S.Cliente 	      
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio;


-- dbo.TAR_ATT_ShippingDocument source

ALTER VIEW [dbo].[TAR_ATT_ShippingDocument]
AS
SELECT	
		/*
			Estremi del documento
		*/
		S.Unibol						ID,
		'SPEDIZIONE'					TipoDocumento,
		DBO.TRUNC(S.DATINS)				DataDocumento,
		/*
			Id Sottodocumenti
		*/
		S.Unibol						IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		S.Cliente						SoggettoAttivo,
		CL.FatturaA						SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		NULL							SoggettoPassivo,
		NULL							SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo Mezzo
		*/
		'*ALL'							TipoMezzo,
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		'*ALL'							Cliente,
		/*
			Date di competenza
		*/
		S.DataCompetenzaAttiva			DataCompetenzaAttiva,
		S.DataCompetenzaPassiva			DataCompetenzaPassiva,
		ISNULL(CL.DatFat,'DataBolla')	CampoDataCompetenzaAttiva,
		NULL							CampoDataCompetenzaPassiva,
		
		/*
			Campi di valorizzazione
		*/
		S.Peso							Peso,		
		S.Colli							Colli,
		S.Pallet						Pallet,
		S.Volume						Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,	
		S.Contrassegno					Contrassegno,
		S.CampoCalcolo1					CampoCalcolo1,
		S.CampoCalcolo2					CampoCalcolo2,
		S.CampoCalcolo3					CampoCalcolo3,
		S.CampoCalcolo4					CampoCalcolo4,
		S.CampoCalcolo5					CampoCalcolo5,
		S.CampoCalcolo6					CampoCalcolo6,
		S.CampoCalcolo7					CampoCalcolo7,
		S.CampoCalcolo8					CampoCalcolo8,
		S.CampoCalcolo9					CampoCalcolo9,
		S.CampoCalcolo10				CampoCalcolo10,	   
		1								Forfait,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN S.BloccaRicavi='S' THEN 'N'
			WHEN S.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'N'		
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END						CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (S.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'		
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'S'	
			WHEN (S.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,			
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN S.BloccaCosti='S' THEN 'N'
			WHEN S.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (S.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (S.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		S.Unibol,
		S.UnibolParent,
		S.UnibolMaster,		
		S.Barcode,
		S.ProgressivoConsegna,
		S.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		S.FillerAlfa1,
		S.FillerAlfa2,
		S.FillerAlfa3,
		S.FillerAlfa4,
		S.FillerAlfa5,
		S.FillerAlfa6,
		S.FillerAlfa7,
		S.FillerAlfa8,
		S.FillerAlfa9,
		S.FillerAlfa10,
		S.FillerData1,
		S.FillerData2,
		S.FillerData3,
		S.FillerData4,
		S.FillerData5,
		S.BatchID,
		S.DataSpedizione,
		S.StatoWMS,
		S.StatoSpuntaUscita,
		S.BloccoAmministrativo,
		S.BloccaRicavi,		
		S.BloccaCosti,								
		S.Evento_CodiceEsito,
		S.Evento_DataOraEsito,
		S.Evento_NoteInterne,
		S.Evento_NoteEsterne,
		S.Evento_TipoEsito,
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro,
		dbo.trunc(ISNULL(V.DataPartenzaEffettiva, V.DataPartenzaPianificata)) DataViaggio  				
		
FROM	VW_SPEDIZIONI S
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN Clienti CL ON CL.Codice=S.Cliente 	      
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio;


-- dbo.TAR_ATT_Stock_Document source

ALTER  VIEW [dbo].[TAR_ATT_Stock_Document]
AS
SELECT	
		/*
			Estremi del documento
		*/
		G.Id							ID,
		G.Id							IDGiacenza,
		'GIACENZA_ATTIVA'				TipoDocumento,
		dbo.trunc(G.DataApertura)		DataDocumento,
		/*
			Id Sottodocumenti
		*/
		G.ID							IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		G.Cliente						SoggettoAttivo,
		G.ClienteFatturazione 			SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		NULL							SoggettoPassivo,
		NULL							SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo Mezzo
		*/
		'*ALL'							TipoMezzo,
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		'*ALL'							Cliente,
		/*
			Date di competenza
		*/
		G.DataCompetenzaAttiva			DataCompetenzaAttiva,
		G.DataCompetenzaPassiva			DataCompetenzaPassiva,
		'DataChiusura'					CampoDataCompetenzaAttiva,
		'DataChiusura'					CampoDataCompetenzaPassiva,		
		/*
			Campi di valorizzazione
		*/
		ISNULL(G.Peso, S.Peso)			Peso,		
		ISNULL(G.Colli, S.Colli)		Colli,
		ISNULL(G.Pallet, S.Pallet)		Pallet,
		ISNULL(G.Volume,S.Volume)		Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,	
		S.Contrassegno					Contrassegno,
		ISNULL(G.CampoCalcolo1,S.CampoCalcolo1)		CampoCalcolo1,
		ISNULL(G.CampoCalcolo2,S.CampoCalcolo2)		CampoCalcolo2,
		ISNULL(G.CampoCalcolo3,S.CampoCalcolo3)		CampoCalcolo3,
		ISNULL(G.CampoCalcolo4,S.CampoCalcolo4)		CampoCalcolo4,
		ISNULL(G.CampoCalcolo5,S.CampoCalcolo5)		CampoCalcolo5,
		ISNULL(G.CampoCalcolo6,S.CampoCalcolo6)		CampoCalcolo6,
		ISNULL(G.CampoCalcolo7,S.CampoCalcolo7)		CampoCalcolo7,
		ISNULL(G.CampoCalcolo8,S.CampoCalcolo8)		CampoCalcolo8,
		ISNULL(G.CampoCalcolo9,S.CampoCalcolo9)		CampoCalcolo9,
		ISNULL(G.CampoCalcolo10,S.CampoCalcolo10)	CampoCalcolo10,	   
		1								Forfait,
		G.GiorniGiacenza				DurataServizio,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN G.BloccaRicavi='S' THEN 'N'
			WHEN G.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END						CalcolaTariffaAttiva,
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE
			WHEN (G.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'			
			WHEN (G.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN G.BloccaCosti='S' THEN 'N'
			WHEN G.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (G.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (G.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		G.UnibolApertura,		
		G.UnibolChiusura,		
		G.UnibolMaster,			
		G.DataApertura,											
		G.DataChiusura,												
		G.ProgressivoApertura,		
		G.ProgressivoChiusura ,
		G.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		G.FillerAlfa1,
		G.FillerAlfa2,
		G.FillerAlfa3,
		G.FillerAlfa4,
		G.FillerAlfa5,
		G.FillerAlfa6,
		G.FillerAlfa7,
		G.FillerAlfa8,
		G.FillerAlfa9,
		G.FillerAlfa10,						
		G.BloccaRicavi,		
		G.BloccaCosti,	
		G.Flag1, 									
		G.Flag2,
		G.Flag3,
		G.Flag4,
		G.Flag5,
		G.Flag6,
		G.Flag7,
		G.Flag8,
		G.Flag9,
		G.Flag10,
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro		
		
FROM	Giacenze G
		INNER JOIN VW_Spedizioni S ON G.UnibolApertura = S.unibol
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN Clienti CL ON CL.Codice=S.Cliente 	      
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio;


-- dbo.TAR_ATT_TourDocument source

ALTER VIEW [dbo].[TAR_ATT_TourDocument]
AS
SELECT	
		/*
			Estremi del documento
		*/
		V.IdViaggio						ID,
		'VIAGGIO'						TipoDocumento,
		dbo.TRUNC(V.DATINS)				DataDocumento,
		/*
			Id Sottodocumenti
		*/
		V.IdViaggio						IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		V.Cliente						SoggettoAttivo,
		CL.FatturaA						SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		NULL							SoggettoPassivo,
		NULL							SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		ISNULL(ISNULL(V.TipoSpedizioneAttiva,V.TipoSpedizione),'*ALL')		TipoSpedizioneAttivo,
		ISNULL(ISNULL(V.TipoSpedizione,V.TipoSpedizioneAttiva),'*ALL')		TipoSpedizionePassivo,
		/*
			Tipo mezzo
		*/
		M.TipoMezzo										TipoMezzo, 
		/*
			Zona Partenza Attiva
		*/
		ISNULL(V.ZonaPartenzaTariffaAttiva,'*ALL')		ZonaPartenzaAttiva,		
		ISNULL(ZPA.CodiceZonaMacro,'*ALL')				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		ISNULL(V.ZonaArrivoTariffaAttiva,'*ALL')		ZonaArrivoAttiva,		
		ISNULL(ZAA.CodiceZonaMacro	,'*ALL')			ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		V.ZonaPartenza							ZonaPartenzaPassiva,				
		NULL									ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		ISNULL(V.ZonaArrivo,'*ALL')							ZonaArrivoPassiva,		
		ISNULL(ZAP.CodiceZonaMacro	,'*ALL')				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		ISNULL(ISNULL(V.PCSPartenzaEffettivo,V.PCSPartenza),'*ALL')	PCSPartenza,
		ISNULL(PP.GruppoTariffa,'*ALL')								GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		ISNULL(ISNULL(V.PCSArrivoEffettivo,V.PCSArrivo),'*ALL')	PCSArrivo,
		ISNULL(PA.GruppoTariffa,'*ALL')							GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		V.Cliente						Cliente,
		/*
			Date di competenza
		*/
		V.DataCompetenzaAttiva 			DataCompetenzaAttiva,
		V.DataCompetenzaPassiva			DataCompetenzaPassiva,
		/*
			modificabile per impianto: ADESSO SCELTA DATAPARTENZAEFFETTIVA
		*/
		'DATAPARTENZAEFFETTIVA'			CampoDataCompetenzaAttiva,
		'DATAPARTENZAEFFETTIVA'         CampoDataCompetenzaPassiva,
		
		/*
			Campi di valorizzazione
		*/
		ISNULL(ISNULL(V.PesoAttivo, S.Peso),0)			Peso,		
		ISNULL(ISNULL(V.ColliAttivo, S.Colli),0)		Colli,
		ISNULL(ISNULL(V.PalletAttivo, S.pallet),0)		Pallet,
		ISNULL(ISNULL(V.VolumeAttivo, S.Volume),0)		Volume,		
		V.TassatoAttivo									TassatoAttivo,		
		V.TassatoPassivo								TassatoPassivo,		
		ISNULL(S.Contrassegno,0)						Contrassegno,

		ISNULL(ISNULL(V.CampoCalcolo1Attivo,S.CampoCalcolo1),0)			CampoCalcolo1,
		ISNULL(ISNULL(V.CampoCalcolo2Attivo,S.CampoCalcolo2),0)			CampoCalcolo2,
		ISNULL(ISNULL(V.CampoCalcolo3Attivo,S.CampoCalcolo3),0)			CampoCalcolo3,
		ISNULL(ISNULL(V.CampoCalcolo4Attivo,S.CampoCalcolo4),0)			CampoCalcolo4,
		ISNULL(ISNULL(V.CampoCalcolo5Attivo,S.CampoCalcolo5),0)			CampoCalcolo5,
		ISNULL(ISNULL(V.CampoCalcolo6Attivo,S.CampoCalcolo6),0)			CampoCalcolo6,
		ISNULL(ISNULL(V.CampoCalcolo7Attivo,S.CampoCalcolo7),0)			CampoCalcolo7,
		ISNULL(ISNULL(V.CampoCalcolo8Attivo,S.CampoCalcolo8),0)			CampoCalcolo8,
		ISNULL(ISNULL(V.CampoCalcolo9Attivo,S.CampoCalcolo9),0)			CampoCalcolo9,
		ISNULL(ISNULL(V.CampoCalcolo10Attivo,S.CampoCalcolo10),0)		CampoCalcolo10,	   

		ISNULL(S.CampoCalcolo1,0)										SpedizioniCampoCalcolo1,
		ISNULL(S.CampoCalcolo2,0)										SpedizioniCampoCalcolo2,
		ISNULL(S.CampoCalcolo3,0)										SpedizioniCampoCalcolo3,
		ISNULL(S.CampoCalcolo4,0)										SpedizioniCampoCalcolo4,
		ISNULL(S.CampoCalcolo5,0)										SpedizioniCampoCalcolo5,
		ISNULL(S.CampoCalcolo6,0)										SpedizioniCampoCalcolo6,
		ISNULL(S.CampoCalcolo7,0)										SpedizioniCampoCalcolo7,
		ISNULL(S.CampoCalcolo8,0)										SpedizioniCampoCalcolo8,
		ISNULL(S.CampoCalcolo9,0)										SpedizioniCampoCalcolo9,
		ISNULL(S.CampoCalcolo10,0)										SpedizioniCampoCalcolo10,	   

		ISNULL(V.CampoCalcolo1Attivo,0)									ViaggioCampoCalcolo1,
		ISNULL(V.CampoCalcolo2Attivo,0)									ViaggioCampoCalcolo2,
		ISNULL(V.CampoCalcolo3Attivo,0)									ViaggioCampoCalcolo3,
		ISNULL(V.CampoCalcolo4Attivo,0)									ViaggioCampoCalcolo4,
		ISNULL(V.CampoCalcolo5Attivo,0)									ViaggioCampoCalcolo5,
		ISNULL(V.CampoCalcolo6Attivo,0)									ViaggioCampoCalcolo6,
		ISNULL(V.CampoCalcolo7Attivo,0)									ViaggioCampoCalcolo7,
		ISNULL(V.CampoCalcolo8Attivo,0)									ViaggioCampoCalcolo8,
		ISNULL(V.CampoCalcolo9Attivo,0)									ViaggioCampoCalcolo9,
		ISNULL(V.CampoCalcolo10Attivo,0)								ViaggioCampoCalcolo10,	   

		1																Forfait,
		ISNULL(S.NumeroSpedizioni,0)									NumeroSpedizioni,
		ISNULL(S.NumeroConsegne,0)										NumeroConsegne,
		ISNULL(S.NumeroPCSPart,0)										NumeroPCSPart,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 		
			WHEN V.BLOCCARICAVI = 'S' THEN 'N'	
			WHEN V.CLIENTE IS NULL THEN 'N'
			WHEN V.IdFatturaAttiva IS NOT NULL THEN 'N'	
			WHEN TV.TariffaAttiva = 'N' THEN 'N'										
		ELSE 'S' END							CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (V.IdFatturaAttiva IS NULL AND TV.TariffaAttiva='N') THEN 'S'								
		ELSE 'N' END							CancellaRicavi,			
		'S'								AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 		
			WHEN V.BLOCCACOSTI = 'S' THEN 'N'	
			WHEN V.VETTORE IS NULL THEN 'N'
			WHEN V.IdFatturaPassiva IS NOT NULL THEN 'N'											
		ELSE 'S' END								CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (V.IdFatturaPassiva IS NULL AND TV.TariffaPassiva='N') THEN 'S'								
		ELSE 'N' END		CancellaCosti,
		'N'		AccreditaCosti,		
		/*
			Abilita Raggruppamento
		*/
		'N'			RaggruppataAttiva,
		'N'			RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		V.IdViaggio,
		V.Stato,
		V.TipoViaggio,		
		V.DataPartenzaPianificata,
		V.DataArrivoPianificata,
		V.DataPartenzaEffettiva,
		V.DataArrivoEffettiva,
		V.MotricePianificata,
		V.Rimorchio1Pianificato,
		V.Contenitore1Pianificato,	
		V.Rimorchio2Pianificato,
		V.Contenitore2Pianificato,				
		V.MotriceEffettiva,
		V.Rimorchio1Effettivo,
		V.Contenitore1Effettivo,	
		V.Rimorchio2Effettivo,
		V.Contenitore2Effettivo,	
		V.TipoUnitaViaggiante,		
		V.Vettore,
		V.TipoSpedizione,
		V.TipoMerce,
		V.ZonaPartenza,
		V.ZonaArrivo,
		V.TipoSpedizioneAttiva,
		V.KmPianificati,
		V.KmManuali,
		V.KmGPS,
		V.KmRicalcolati,
		V.IdFatturaAttiva,
		V.IdFatturaPassiva,
		V.Sagome,
		V.Flag1,
		V.Flag2,
		V.Flag3,
		V.Flag4,
		V.Flag5,
		V.Flag6,
		V.Flag7,
		V.Flag8,
		V.Flag9,
		V.Flag10,
		V.Note1,
		V.Note2,
		V.BloccaRicavi,
		V.BloccaCosti	
						
FROM	Viaggi V
		INNER JOIN Viaggi_TipiViaggio TV ON TV.Codice = V.TipoViaggio
		LEFT JOIN PCS PP ON PP.Codice = ISNULL(V.PCSPartenzaEffettivo,V.PCSPartenza)
		LEFT JOIN PCS PA ON PA.Codice = ISNULL(V.PCSArrivoEffettivo,V.PCSArrivo)		
		LEFT JOIN Zone ZPA ON ZPA.Codice = V.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = V.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = V.ZonaArrivo 
		LEFT JOIN Clienti CL ON CL.Codice=V.Cliente 	      
		LEFT JOIN Mezzi M ON M.Codice =ISNULL(V.MotriceEffettiva, V.MotricePianificata )
		OUTER APPLY dbo.GetViaggioSommatorie(V.IDVIAGGIO) S;


-- dbo.TAR_PAS_COD_Document source

ALTER VIEW [dbo].[TAR_PAS_COD_Document]
AS
SELECT	
		/*
			Estremi del documento
		*/
		C.Id							ID,
		C.Id							IDContrassegno,
		'CONTRASSEGNO'					TipoDocumento,
		DBO.TRUNC(C.DataCreazione)		DataDocumento,
		/*
			Id Sottodocumenti
		*/
		C.ID							IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		C.Cliente						SoggettoAttivo,
		C.ClienteFatturazione 			SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		C.Trasportatore					SoggettoPassivo,
		C.TrasportatoreFatturazione		SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo Mezzo
		*/
		'*ALL'							TipoMezzo,
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		C.Cliente						Cliente,
		/*
			Date di competenza
		*/
		C.DataCompetenzaAttiva			DataCompetenzaAttiva,
		C.DataCompetenzaPassiva			DataCompetenzaPassiva,
		'DataIncasso'					CampoDataCompetenzaAttiva,
		'DataIncasso'					CampoDataCompetenzaPassiva,		
		/*
			Campi di valorizzazione
		*/
		S.Peso							Peso,		
		S.Colli							Colli,
		S.Pallet						Pallet,
		S.Volume						Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,	
		C.Contrassegno					Contrassegno,
		S.CampoCalcolo1					CampoCalcolo1,
		S.CampoCalcolo2					CampoCalcolo2,
		S.CampoCalcolo3					CampoCalcolo3,
		S.CampoCalcolo4					CampoCalcolo4,
		S.CampoCalcolo5					CampoCalcolo5,
		S.CampoCalcolo6					CampoCalcolo6,
		S.CampoCalcolo7					CampoCalcolo7,
		S.CampoCalcolo8					CampoCalcolo8,
		S.CampoCalcolo9					CampoCalcolo9,
		S.CampoCalcolo10				CampoCalcolo10,	   
		1								Forfait,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN C.BloccaRicavi='S' THEN 'N'
			WHEN C.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'N'		
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END						CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (C.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'		
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'S'	
			WHEN (C.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,			
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN C.BloccaCosti='S' THEN 'N'
			WHEN C.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (C.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (C.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		C.UnibolApertura,		
		C.UnibolChiusura,		
		C.UnibolMaster,			
		C.DataCreazione,	
		C.DataEsito,
		C.CausaleEsito,
		C.DataIncasso,
		C.IdRimessa,
		C.TipoIncasso, 
		S.ProgressivoConsegna,
		S.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		C.FillerAlfa1,
		C.FillerAlfa2,
		C.FillerAlfa3,
		C.FillerAlfa4,
		C.FillerAlfa5,
		C.FillerAlfa6,
		C.FillerAlfa7,
		C.FillerAlfa8,
		C.FillerAlfa9,
		C.FillerAlfa10,						
		C.BloccaRicavi,		
		C.BloccaCosti,										
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro		
		
FROM	Contrassegni  C
		INNER JOIN VW_Spedizioni S ON C.UnibolMaster = S.unibol
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio;


-- dbo.TAR_PAS_ShippingDocument source

ALTER VIEW [dbo].[TAR_PAS_ShippingDocument]
AS
SELECT	
		/*
			Estremi del documento
		*/
		S.Unibol						ID,
		'SPEDIZIONE'					TipoDocumento,
		DBO.TRUNC(S.DATINS)				DataDocumento,
		/*
			Id Sottodocumenti
		*/
		S.Unibol						IDSottoDocumenti,
		/*
			Soggetto attivo (NULLO sono nella passiva)
		*/
		NULL							SoggettoAttivo,
		NULL							SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo 
		*/
		S.TRASPORTATORE					SoggettoPassivo,
		TR.FATTURAA						SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo mezzo
		*/
		ISNULL(M.TipoMezzo,'*ALL')		TipoMezzo, 
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		S.Cliente						Cliente,
		/*
			Date di competenza
		*/
		S.DataCompetenzaAttiva			DataCompetenzaAttiva,
		S.DataCompetenzaPassiva			DataCompetenzaPassiva,
		NULL							CampoDataCompetenzaAttiva,
		ISNULL(TR.DataPerFatturazione,'DataBolla')	CampoDataCompetenzaPassiva,
		
		/*
			Campi di valorizzazione
		*/
		S.Peso							Peso,		
		S.Colli							Colli,
		S.Pallet						Pallet,
		S.Volume						Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,		
		S.Contrassegno					Contrassegno,
		S.CampoCalcolo1					CampoCalcolo1,
		S.CampoCalcolo2					CampoCalcolo2,
		S.CampoCalcolo3					CampoCalcolo3,
		S.CampoCalcolo4					CampoCalcolo4,
		S.CampoCalcolo5					CampoCalcolo5,
		S.CampoCalcolo6					CampoCalcolo6,
		S.CampoCalcolo7					CampoCalcolo7,
		S.CampoCalcolo8					CampoCalcolo8,
		S.CampoCalcolo9					CampoCalcolo9,
		S.CampoCalcolo10				CampoCalcolo10,	   
		1								Forfait,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN S.BloccaRicavi='S' THEN 'N'
			WHEN S.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'N'		
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (S.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'		
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'S'	
			WHEN (S.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,	
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN S.BloccaCosti='S' THEN 'N'
			WHEN S.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (S.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (S.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		S.Unibol,
		S.UnibolParent,
		S.UnibolMaster,		
		S.Barcode,
		S.ProgressivoConsegna,
		S.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		S.FillerAlfa1,
		S.FillerAlfa2,
		S.FillerAlfa3,
		S.FillerAlfa4,
		S.FillerAlfa5,
		S.FillerAlfa6,
		S.FillerAlfa7,
		S.FillerAlfa8,
		S.FillerAlfa9,
		S.FillerAlfa10,
		S.FillerData1,
		S.FillerData2,
		S.FillerData3,
		S.FillerData4,
		S.FillerData5,
		S.BatchID,
		S.DataSpedizione,
		S.StatoWMS,
		S.StatoSpuntaUscita,
		S.BloccoAmministrativo,
		S.BloccaRicavi,		
		S.BloccaCosti,								
		S.Evento_CodiceEsito,
		S.Evento_DataOraEsito,
		S.Evento_NoteInterne,
		S.Evento_NoteEsterne,
		S.Evento_TipoEsito,
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro,
		dbo.trunc(ISNULL(V.DataPartenzaEffettiva, V.DataPartenzaPianificata)) DataViaggio  				
		
FROM	VW_SPEDIZIONI S
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN Trasportatori TR ON TR.Codice=S.Trasportatore 	      
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio
		LEFT JOIN Mezzi M ON M.Codice =ISNULL(V.MotriceEffettiva, V.MotricePianificata );


-- dbo.TAR_PAS_ShippingDocument2 source

ALTER VIEW [dbo].[TAR_PAS_ShippingDocument2]
AS
SELECT	
		/*
			Estremi del documento
		*/
		S.Unibol						ID,
		'SPEDIZIONE'					TipoDocumento,
		DBO.TRUNC(S.DATINS)				DataDocumento,
		/*
			Id Sottodocumenti
		*/
		S.Unibol						IDSottoDocumenti,
		/*
			Soggetto attivo (NULLO sono nella passiva)
		*/
		NULL							SoggettoAttivo,
		NULL							SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo 
		*/
		S.Vettore						SoggettoPassivo,
		TR.FATTURAA						SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo mezzo
		*/
		ISNULL(M.TipoMezzo,'*ALL')		TipoMezzo, 
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		S.Cliente						Cliente,
		/*
			Date di competenza
		*/
		S.DataCompetenzaAttiva			DataCompetenzaAttiva,
		S.DataCompetenzaPassiva			DataCompetenzaPassiva,
		NULL							CampoDataCompetenzaAttiva,
		ISNULL(TR.DataPerFatturazione,'DataBolla')	CampoDataCompetenzaPassiva,
		
		/*
			Campi di valorizzazione
		*/
		S.Peso							Peso,		
		S.Colli							Colli,
		S.Pallet						Pallet,
		S.Volume						Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,		
		S.Contrassegno					Contrassegno,
		S.CampoCalcolo1					CampoCalcolo1,
		S.CampoCalcolo2					CampoCalcolo2,
		S.CampoCalcolo3					CampoCalcolo3,
		S.CampoCalcolo4					CampoCalcolo4,
		S.CampoCalcolo5					CampoCalcolo5,
		S.CampoCalcolo6					CampoCalcolo6,
		S.CampoCalcolo7					CampoCalcolo7,
		S.CampoCalcolo8					CampoCalcolo8,
		S.CampoCalcolo9					CampoCalcolo9,
		S.CampoCalcolo10				CampoCalcolo10,	   
		1								Forfait,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN S.BloccaRicavi='S' THEN 'N'
			WHEN S.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'N'		
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (S.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'		
			WHEN S.IDVIAGGIO IS NOT NULL AND S.CLIENTE = V.CLIENTE THEN 'S'	
			WHEN (S.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,	
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN S.BloccaCosti='S' THEN 'N'
			WHEN S.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (S.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (S.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		S.Unibol,
		S.UnibolParent,
		S.UnibolMaster,		
		S.Barcode,
		S.ProgressivoConsegna,
		S.Stato,				
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.Vettore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		S.FillerAlfa1,
		S.FillerAlfa2,
		S.FillerAlfa3,
		S.FillerAlfa4,
		S.FillerAlfa5,
		S.FillerAlfa6,
		S.FillerAlfa7,
		S.FillerAlfa8,
		S.FillerAlfa9,
		S.FillerAlfa10,
		S.FillerData1,
		S.FillerData2,
		S.FillerData3,
		S.FillerData4,
		S.FillerData5,
		S.BatchID,
		S.DataSpedizione,
		S.StatoWMS,
		S.StatoSpuntaUscita,
		S.BloccoAmministrativo,
		S.BloccaRicavi,		
		S.BloccaCosti,								
		S.Evento_CodiceEsito,
		S.Evento_DataOraEsito,
		S.Evento_NoteInterne,
		S.Evento_NoteEsterne,
		S.Evento_TipoEsito,
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro		
		
FROM	VW_SPEDIZIONI S
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN Trasportatori TR ON TR.Codice=S.Vettore 	      
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio
		LEFT JOIN Mezzi M ON M.Codice =ISNULL(V.MotriceEffettiva, V.MotricePianificata );


-- dbo.TAR_PAS_Stock_Document source

ALTER VIEW [dbo].[TAR_PAS_Stock_Document]
AS
SELECT	
		G.Id							ID,
		G.Id							IDGiacenza,
		'GIACENZA_PASSIVA'				TipoDocumento,
		dbo.trunc(G.DataApertura)		DataDocumento,
		/*
			Id Sottodocumenti
		*/
		G.ID							IDSottoDocumenti,
		/*
			Soggetto attivo 
		*/
		G.Cliente						SoggettoAttivo,
		G.ClienteFatturazione 			SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo (NULLO sono nella attiva)
		*/
		G.Trasportatore					SoggettoPassivo,
		G.TrasportatoreFatturazione		SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		S.TipoSpedizione				TipoSpedizioneAttivo,
		ISNULL(S.TipoSpedizionePassivo,S.TipoSpedizione)		TipoSpedizionePassivo,
		/*
			Tipo Mezzo
		*/
		'*ALL'							TipoMezzo,
		/*
			Zona Partenza Attiva
		*/
		S.ZonaPartenzaTariffaAttiva		ZonaPartenzaAttiva,		
		ZPA.CodiceZonaMacro				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		S.ZonaArrivoTariffaAttiva		ZonaArrivoAttiva,		
		ZAA.CodiceZonaMacro				ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		S.ZonaPartenzaTariffaPassiva	ZonaPartenzaPassiva,				
		NULL							ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		S.ZonaArrivoTariffaPassiva		ZonaArrivoPassiva,		
		ZAP.CodiceZonaMacro				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		S.PCSPartenza					PCSPartenza,
		PP.GruppoTariffa				GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		S.PCSDestinazione				PCSArrivo,
		PA.GruppoTariffa				GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		G.Cliente						Cliente,
		/*
			Date di competenza
		*/
		G.DataCompetenzaAttiva			DataCompetenzaAttiva,
		G.DataCompetenzaPassiva			DataCompetenzaPassiva,
		'DataChiusura'					CampoDataCompetenzaAttiva,
		'DataChiusura'					CampoDataCompetenzaPassiva,		
		/*
			Campi di valorizzazione
		*/
		ISNULL(G.Peso, S.Peso)			Peso,		
		ISNULL(G.Colli, S.Colli)		Colli,
		ISNULL(G.Pallet, S.Pallet)		Pallet,
		ISNULL(G.Volume,S.Volume)		Volume,		
		S.TassatoAttivo					TassatoAttivo,
		S.TassatoAttivo					TassatoAttivoSomma,
		S.TassatoPassivo				TassatoPassivo,
		S.TassatoPassivo				TassatoPassivoSomma,	
		S.Contrassegno					Contrassegno,
		ISNULL(G.CampoCalcolo1,S.CampoCalcolo1)		CampoCalcolo1,
		ISNULL(G.CampoCalcolo2,S.CampoCalcolo2)		CampoCalcolo2,
		ISNULL(G.CampoCalcolo3,S.CampoCalcolo3)		CampoCalcolo3,
		ISNULL(G.CampoCalcolo4,S.CampoCalcolo4)		CampoCalcolo4,
		ISNULL(G.CampoCalcolo5,S.CampoCalcolo5)		CampoCalcolo5,
		ISNULL(G.CampoCalcolo6,S.CampoCalcolo6)		CampoCalcolo6,
		ISNULL(G.CampoCalcolo7,S.CampoCalcolo7)		CampoCalcolo7,
		ISNULL(G.CampoCalcolo8,S.CampoCalcolo8)		CampoCalcolo8,
		ISNULL(G.CampoCalcolo9,S.CampoCalcolo9)		CampoCalcolo9,
		ISNULL(G.CampoCalcolo10,S.CampoCalcolo10)	CampoCalcolo10,	   
		1								Forfait,
		G.GiorniGiacenza				DurataServizio,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 
			WHEN G.BloccaRicavi='S' THEN 'N'
			WHEN G.IdFatturaAttiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaAttiva='N' THEN 'N'			
			WHEN ISNULL(S.Evento_AddebitaRicavi,'S')='N' THEN 'N'
		ELSE 'S' END						CalcolaTariffaAttiva,	
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE
			WHEN (G.IdFatturaAttiva IS NULL AND TS.TariffaAttiva='N') THEN 'S'			
			WHEN (G.IdFatturaAttiva IS NULL AND ISNULL(S.Evento_AddebitaRicavi,'S')='N') THEN 'S'
		ELSE 'N' END							CancellaRicavi,
		ISNULL(S.Evento_AddebitaRicavi,'S') AddebitaRicavi,		
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 
			WHEN G.BloccaCosti='S' THEN 'N'
			WHEN G.IdFatturaPassiva IS NOT NULL THEN 'N'
			WHEN TS.TariffaPassiva='N' THEN 'N'							
			WHEN ISNULL(S.Evento_AccreditaCosti,'S')='N' THEN 'N'
		ELSE 'S' END							CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (G.IdFatturaPassiva IS NULL AND TS.TariffaPassiva='N') THEN 'S'					
			WHEN (G.IdFatturaPassiva IS NULL AND ISNULL(S.Evento_AccreditaCosti,'S')='N') THEN 'S'
		ELSE 'N' END CancellaCosti,		
		ISNULL(S.Evento_AccreditaCosti,'S') AccreditaCosti,
		/*
			Abilita Raggruppamento
		*/
		TS.RaggruppataAttiva,
		TS.RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		G.UnibolApertura,		
		G.UnibolChiusura,		
		G.UnibolMaster,			
		G.DataApertura,											
		G.DataChiusura,												
		G.ProgressivoApertura,		
		G.ProgressivoChiusura ,
		G.Stato,								
		S.Note,
		S.Prebolla,
		S.TipoServizio,		
		S.Mittente,
		S.MittenteRagioneSociale,
		S.ClienteFatturazione,
		S.NumeroBolla,
		S.DataBolla,
		S.NumeroOrdine,
		S.DataOrdine,
		S.NumeroOrdineCliente,
		S.DataOrdineCliente,
		S.TipoSpedizione,
		S.TipoMerce,		
		S.PCSDestinazione,
		S.PCSDestinazione_RagSoc,
		S.PCSDestinazione_Indirizzo,
		S.PCSDestinazione_Cap,
		S.PCSDestinazione_Localita,
		S.PCSDestinazione_Provincia,
		S.PCSDestinazione_Nazione,
		S.DestinazioneCliente,
		S.Destinatario,
		S.DestinatarioCliente,
		S.ZonaSpedizione,
		S.ZonaPartenzaTariffaAttiva,
		S.ZonaArrivoTariffaAttiva,
		S.ZonaPartenzaTariffaPassiva,
		S.ZonaArrivoTariffaPassiva,
		S.DataConsegnaPrevista1,
		S.DataConsegnaPrevista2,
		S.NoteConsegnaPrevista,
		S.DataConsegnaConcordata,
		S.OraConsegnaConcordata1,
		S.OraConsegnaConcordata2,
		S.NoteConsegnaConcordata,
		S.CausaleConsegnaConcordata,
		S.Corrispondente,
		S.Trasportatore,
		S.DataOraPartenzaPianificata,
		S.DataOraPartenzaEffettiva,
		S.DataOraArrivoPianificata,
		S.DataOraArrivoEffettiva,
		S.KmPianificati,
		S.KmGPS,
		S.KmManuali,
		S.KmRicalcolati,
		S.IdFatturaAttiva,
		S.IdFatturaPassiva,
		S.IdViaggio,
		G.FillerAlfa1,
		G.FillerAlfa2,
		G.FillerAlfa3,
		G.FillerAlfa4,
		G.FillerAlfa5,
		G.FillerAlfa6,
		G.FillerAlfa7,
		G.FillerAlfa8,
		G.FillerAlfa9,
		G.FillerAlfa10,						
		G.BloccaRicavi,		
		G.BloccaCosti,	
		G.Flag1, 									
		G.Flag2,
		G.Flag3,
		G.Flag4,
		G.Flag5,
		G.Flag6,
		G.Flag7,
		G.Flag8,
		G.Flag9,
		G.Flag10,
		TS.TransitoDeposito, 
		TS.Is_Consegna,
		TS.Is_AB,
		TS.Is_Reso,
		TS.Is_Ritiro		
		
FROM	Giacenze  G
		INNER JOIN VW_Spedizioni S ON G.UnibolApertura = S.unibol
		INNER JOIN PCS PP ON PP.Codice = S.PCSPartenza
		INNER JOIN PCS PA ON PA.Codice = S.PCSDestinazione
		LEFT JOIN Zone ZPA ON ZPA.Codice = S.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = S.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = S.ZonaArrivoTariffaPassiva 
		LEFT JOIN TipiServizi TS ON TS.Codice=S.TipoServizio
		LEFT JOIN Viaggi V ON V.IdViaggio = S.IdViaggio;


-- dbo.TAR_PAS_TourDocument source

ALTER VIEW [dbo].[TAR_PAS_TourDocument]
AS
SELECT	
		/*
			Estremi del documento
		*/
		V.IdViaggio						ID,
		'VIAGGIO'						TipoDocumento,
		dbo.TRUNC(V.DATINS)				DataDocumento,
		/*
			Id Sottodocumenti
		*/
		V.IdViaggio						IDSottoDocumenti,
		/*
			Soggetto attivo (NULLO sono nella passiva)
		*/
		NULL						SoggettoAttivo,
		NULL						SoggettoFatturazioneAttiva,
		/*
			Soggetto Passivo
		*/
		V.Vettore					SoggettoPassivo,
		TR.FatturaA					SoggettoFatturazionePassiva,						
		/*
			Tipo Spedizione
		*/
		ISNULL(ISNULL(V.TipoSpedizioneAttiva,V.TipoSpedizione),'*ALL')		TipoSpedizioneAttivo,
		ISNULL(ISNULL(V.TipoSpedizione,V.TipoSpedizioneAttiva),'*ALL')		TipoSpedizionePassivo,
		/*
			Tipo mezzo
		*/
		ISNULL(M.TipoMezzo,'*ALL')						TipoMezzo, 
		/*
			Zona Partenza Attiva
		*/
		ISNULL(V.ZonaPartenzaTariffaAttiva,'*ALL')		ZonaPartenzaAttiva,		
		ISNULL(ZPA.CodiceZonaMacro,'*ALL')				ZonaPartenzaAttivaMacro,
		/*
			Zona Arrivo Attiva
		*/
		ISNULL(V.ZonaArrivoTariffaAttiva,'*ALL')		ZonaArrivoAttiva,		
		ISNULL(ZAA.CodiceZonaMacro	,'*ALL')			ZonaArrivoAttivaMacro,						
		/*
			Zona Partenza Passiva
		*/
		V.ZonaPartenza							ZonaPartenzaPassiva,				
		NULL									ZonaPartenzaPassivaMacro,								
		/*
			Zona Arrivo Passiva
		*/										
		ISNULL(V.ZonaArrivo,'*ALL')							ZonaArrivoPassiva,		
		ISNULL(ZAP.CodiceZonaMacro	,'*ALL')				ZonaArrivoPassivaMacro,														
		/*
			Partenza
		*/
		ISNULL(ISNULL(V.PCSPartenzaEffettivo,V.PCSPartenza),'*ALL')	PCSPartenza,
		ISNULL(PP.GruppoTariffa,'*ALL')								GruppoTariffarioPartenza,
		/*
			Destinazione
		*/
		ISNULL(ISNULL(V.PCSArrivoEffettivo,V.PCSArrivo),'*ALL')	PCSArrivo,
		ISNULL(PA.GruppoTariffa,'*ALL')							GruppoTariffarioArrivo,
		/*
			Cliente
		*/
		V.Cliente						Cliente,
		/*
			Date di competenza
		*/
		V.DataCompetenzaAttiva 			DataCompetenzaAttiva,
		V.DataCompetenzaPassiva			DataCompetenzaPassiva,
		/*
			modificabile per impianto: ADESSO SCELTA DATAPARTENZAEFFETTIVA
		*/				
		ISNULL(TR.DataPerFatturazioneViaggi,'DATAPARTENZAEFFETTIVA')	CampoDataCompetenzaAttiva,
		ISNULL(TR.DataPerFatturazioneViaggi,'DATAPARTENZAEFFETTIVA')	CampoDataCompetenzaPassiva,		
		/*
			Campi di valorizzazione
		*/
		ISNULL(ISNULL(V.PesoPassivo, S.Peso),0)			Peso,		
		ISNULL(ISNULL(V.ColliPassivo, S.Colli),0)		Colli,
		ISNULL(ISNULL(V.PalletPassivo, S.pallet),0)		Pallet,
		ISNULL(ISNULL(V.VolumePassivo, S.Volume),0)		Volume,		
		V.TassatoAttivo									TassatoAttivo,		
		V.TassatoPassivo								TassatoPassivo,		
		ISNULL(S.Contrassegno,0)						Contrassegno,

		ISNULL(ISNULL(V.CampoCalcolo1Passivo,S.CampoCalcolo1),0)			CampoCalcolo1,
		ISNULL(ISNULL(V.CampoCalcolo2Passivo,S.CampoCalcolo2),0)			CampoCalcolo2,
		ISNULL(ISNULL(V.CampoCalcolo3Passivo,S.CampoCalcolo3),0)			CampoCalcolo3,
		ISNULL(ISNULL(V.CampoCalcolo4Passivo,S.CampoCalcolo4),0)			CampoCalcolo4,
		ISNULL(ISNULL(V.CampoCalcolo5Passivo,S.CampoCalcolo5),0)			CampoCalcolo5,
		ISNULL(ISNULL(V.CampoCalcolo6Passivo,S.CampoCalcolo6),0)			CampoCalcolo6,
		ISNULL(ISNULL(V.CampoCalcolo7Passivo,S.CampoCalcolo7),0)			CampoCalcolo7,
		ISNULL(ISNULL(V.CampoCalcolo8Passivo,S.CampoCalcolo8),0)			CampoCalcolo8,
		ISNULL(ISNULL(V.CampoCalcolo9Passivo,S.CampoCalcolo9),0)			CampoCalcolo9,
		ISNULL(ISNULL(V.CampoCalcolo10Passivo,S.CampoCalcolo10),0)			CampoCalcolo10,	   

		ISNULL(S.CampoCalcolo1,0)										SpedizioniCampoCalcolo1,
		ISNULL(S.CampoCalcolo2,0)										SpedizioniCampoCalcolo2,
		ISNULL(S.CampoCalcolo3,0)										SpedizioniCampoCalcolo3,
		ISNULL(S.CampoCalcolo4,0)										SpedizioniCampoCalcolo4,
		ISNULL(S.CampoCalcolo5,0)										SpedizioniCampoCalcolo5,
		ISNULL(S.CampoCalcolo6,0)										SpedizioniCampoCalcolo6,
		ISNULL(S.CampoCalcolo7,0)										SpedizioniCampoCalcolo7,
		ISNULL(S.CampoCalcolo8,0)										SpedizioniCampoCalcolo8,
		ISNULL(S.CampoCalcolo9,0)										SpedizioniCampoCalcolo9,
		ISNULL(S.CampoCalcolo10,0)										SpedizioniCampoCalcolo10,	   

		ISNULL(V.CampoCalcolo1Passivo,0)								ViaggioCampoCalcolo1,
		ISNULL(V.CampoCalcolo2Passivo,0)								ViaggioCampoCalcolo2,
		ISNULL(V.CampoCalcolo3Passivo,0)								ViaggioCampoCalcolo3,
		ISNULL(V.CampoCalcolo4Passivo,0)								ViaggioCampoCalcolo4,
		ISNULL(V.CampoCalcolo5Passivo,0)								ViaggioCampoCalcolo5,
		ISNULL(V.CampoCalcolo6Passivo,0)								ViaggioCampoCalcolo6,
		ISNULL(V.CampoCalcolo7Passivo,0)								ViaggioCampoCalcolo7,
		ISNULL(V.CampoCalcolo8Passivo,0)								ViaggioCampoCalcolo8,
		ISNULL(V.CampoCalcolo9Passivo,0)								ViaggioCampoCalcolo9,
		ISNULL(V.CampoCalcolo10Passivo,0)								ViaggioCampoCalcolo10,	   

		1																Forfait,
		ISNULL(S.NumeroSpedizioni,0)									NumeroSpedizioni,
		ISNULL(S.NumeroConsegne,0)										NumeroConsegne,
		ISNULL(S.NumeroPCSPart,0)										NumeroPCSPart,
		/*
		 campo per inibizione calcolo tariffa Attiva
		*/
		CASE 		
			WHEN V.BLOCCARICAVI = 'S' THEN 'N'	
			WHEN V.CLIENTE IS NULL THEN 'N'
			WHEN V.IdFatturaAttiva IS NOT NULL THEN 'N'	
			WHEN TV.TariffaAttiva = 'N' THEN 'N'										
		ELSE 'S' END							CalcolaTariffaAttiva,		
		/*
		 campo per cancellazione Ricavi (valido so se CalcolaTariffaAttiva='N')
		*/
		CASE 			
			WHEN (V.IdFatturaAttiva IS NULL AND TV.TariffaAttiva='N') THEN 'S'								
		ELSE 'N' END							CancellaRicavi,			
		'S'								AddebitaRicavi,
		/*
		 campo per inibizione calcolo tariffa Passiva
		*/
		CASE 		
			WHEN V.BLOCCACOSTI = 'S' THEN 'N'	
			WHEN V.VETTORE IS NULL THEN 'N'
			WHEN V.IdFatturaPassiva IS NOT NULL THEN 'N'											
		ELSE 'S' END								CalcolaTariffaPassiva,		
		/*
		 campo per cancellazione costi
		*/
		CASE 			
			WHEN (V.IdFatturaPassiva IS NULL AND TV.TariffaPassiva='N') THEN 'S'								
		ELSE 'N' END		CancellaCosti,
		'S'		AccreditaCosti,		
		/*
			Abilita Raggruppamento
		*/
		'N'			RaggruppataAttiva,
		'N'			RaggruppataPassiva,			
		/*
			Altri campi
		*/					
		V.IdViaggio,
		V.Stato,
		V.TipoViaggio,		
		V.DataPartenzaPianificata,
		V.DataArrivoPianificata,
		V.DataPartenzaEffettiva,
		V.DataArrivoEffettiva,
		V.MotricePianificata,
		V.Rimorchio1Pianificato,
		V.Contenitore1Pianificato,	
		V.Rimorchio2Pianificato,
		V.Contenitore2Pianificato,				
		V.MotriceEffettiva,
		V.Rimorchio1Effettivo,
		V.Contenitore1Effettivo,	
		V.Rimorchio2Effettivo,
		V.Contenitore2Effettivo,	
		V.TipoUnitaViaggiante,		
		V.Vettore,
		V.TipoSpedizione,
		V.TipoMerce,
		V.ZonaPartenza,
		V.ZonaArrivo,
		V.TipoSpedizioneAttiva,
		V.KmPianificati,
		V.KmManuali,
		V.KmGPS,
		V.KmRicalcolati,
		V.IdFatturaAttiva,
		V.IdFatturaPassiva,
		V.Sagome,
		V.Flag1,
		V.Flag2,
		V.Flag3,
		V.Flag4,
		V.Flag5,
		V.Flag6,
		V.Flag7,
		V.Flag8,
		V.Flag9,
		V.Flag10,
		V.Note1,
		V.Note2,
		V.BloccaRicavi,
		V.BloccaCosti
FROM	Viaggi V
		INNER JOIN Viaggi_TipiViaggio TV ON TV.Codice = V.TipoViaggio
		LEFT JOIN PCS PP ON PP.Codice = ISNULL(V.PCSPartenzaEffettivo,V.PCSPartenza)
		LEFT JOIN PCS PA ON PA.Codice = ISNULL(V.PCSArrivoEffettivo,V.PCSArrivo)		
		LEFT JOIN Zone ZPA ON ZPA.Codice = V.ZonaPartenzaTariffaAttiva
		LEFT JOIN Zone ZAA ON ZAA.Codice = V.ZonaArrivoTariffaAttiva     
		LEFT JOIN Zone ZAP ON ZAP.Codice = V.ZonaArrivo 
		LEFT JOIN Trasportatori TR ON TR.Codice=V.Vettore 	 
		LEFT JOIN Mezzi M ON M.Codice =ISNULL(V.MotriceEffettiva, V.MotricePianificata )     
		OUTER APPLY dbo.GetViaggioSommatorie(V.IDVIAGGIO) S --ON S.IdViaggio = V.IdViaggio;


