-- dbo.TAR_TariffeAttiveRaggruVoci source

ALTER VIEW [dbo].[TAR_TariffeAttiveRaggruVoci] AS
SELECT	T.IdTariffa,
		T.Contratto,
		T.TipoSpedizione, 
		T.TipoMerce, 
		T.TipoMezzo,
		T.Cliente, 
		T.GruppoTariffarioPartenza,
		T.PCSPartenza,
		T.MacroZonaArrivo,
		T.ZonaArrivo,
		T.GruppoTariffarioArrivo,
		T.PCSArrivo,
		T.DataInizioValidita, 
		T.DataFineValidita, 
		T.RapportoPV, 		
		V.IdVoce,
		V.Voce,		
		V.CampoCalcolo,
		V.ArrCampoCalcolo,
		V.ArrCampoCalcoloLimite,
		V.ArrCampoCalcoloOltre,
		V.ArrImporto,
		V.flgEccedenza,
		Voci.Descrizione			Voce_Descrizione,
		CASE 
		WHEN Voci.FlagNolo='N' THEN 'N' 
		ELSE 'S' END				Voce_FlagNolo,		
		Voci.FlagNolo				Voce_TipoFlagNolo,
		Voci.Riconsegna				Voce_Riconsegna,
		VA.Codice					Voce_Applicabilita,
		Voci.Reso					Voce_Reso,
		Voci.TipoVoce				Voce_TipoVoce, 
		CASE 
		WHEN Voci.TipoVoce = 'S' THEN -1 
		ELSE 1 END					Voce_TipoVoceSegno,
		Voci.Viaggio				Voce_Viaggio, 
		Voci.Spedizione				Voce_Spedizione, 
		Voci.Giacenza				Voce_Giacenza,
		VA.Descrizione				VoceApplicabilita_Descrizione,
		VA.Tabella					VoceApplicabilita_Tabella,
		VA.Campo					VoceApplicabilita_Campo,
		VA.TipoCampo				VoceApplicabilita_TipoCampo,
		VA.Operatore				VoceApplicabilita_Operatore,
		VA.Valore					VoceApplicabilita_Valore,
		VA.TipoApplicabilita		VoceApplicabilita_Tipo,
		CV.TipoRipartizione			TipoRipartizione,
		T.Peso
FROM	TAR_TariffeAttiveTestata T 
		LEFT JOIN TariffeAttiveVoci V ON T.IdTariffa=V.IdTariffa 
		LEFT JOIN Voci ON VOCI.Codice=V.Voce AND Voci.Attivo='S'
		LEFT JOIN VociApplicabilita VA ON VA.Codice=ISNULL(V.Applicabilita, Voci.Applicabilita) AND VA.Attivo='S'
		INNER JOIN TariffeContrattiVoci CV ON (CV.Contratto=T.Contratto AND CV.Voce=V.Voce)
WHERE	V.Voce IS NOT NULL;


-- dbo.TAR_TariffeAttiveTestata source

ALTER VIEW [dbo].[TAR_TariffeAttiveTestata] AS
SELECT		T.IdTariffa,
			T.Contratto,
			T.TipoDocumento,
			T.TipoSpedizione, 
			T.TipoMerce, 
			T.TipoMezzo,
			T.Cliente, 
			T.GruppoTariffarioPartenza,
			T.PCSPartenza,
			T.MacroZonaArrivo,
			T.ZonaArrivo,
			T.GruppoTariffarioArrivo,
			T.PCSArrivo,
			C.DataInizioValidita DataInizioValidita,
			C.DataFineValidita DataFineValidita,
			ISNULL(T.RapportoPV, C.RapportoPV) RapportoPV,			
			C.ArrotondamentoImporti,
			C.TassazioneRiconsegne, 
			C.PercentualeRiconsegne,
			C.TassazioneResi,
			C.PercentualeResi,			
			(CASE WHEN T.TipoDocumento='*ALL' THEN 0 ELSE 1 END )*5000000000 +
			(CASE WHEN T.PCSArrivo='*ALL' THEN 0 ELSE 1 END )*1000000000 +
			(CASE WHEN T.GruppoTariffarioArrivo='*ALL' THEN 0 ELSE 1 END )*100000000 +
			(CASE WHEN T.ZonaArrivo='*ALL' THEN 0 ELSE 1 END )*10000000 +
			(CASE WHEN T.MacroZonaArrivo='*ALL' THEN 0 ELSE 1 END )*1000000 +
			(CASE WHEN T.PCSPartenza='*ALL' THEN 0 ELSE 1 END )*100000 +
			(CASE WHEN T.GruppoTariffarioPartenza='*ALL' THEN 0 ELSE 1 END )*10000 +
			(CASE WHEN T.Cliente='*ALL' THEN 0 ELSE 1 END )*1000 +
			(CASE WHEN T.TipoMezzo='*ALL' THEN 0 ELSE 1 END )*100 +
			(CASE WHEN T.TipoMerce='*ALL' THEN 0 ELSE 1 END )*10 +
			(CASE WHEN T.TipoSpedizione='*ALL' THEN 0 ELSE 1 END )*1 Peso
FROM		TariffeAttiveTestata T 
			INNER JOIN TariffeContratti C ON T.Contratto=C.Codice;


