ALTER VIEW [dbo].[VW_ANA_CONTESTAZIONI_SOGGETTI]  AS
	SELECT  codice, 
			ragionesociale,
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'D' AS TipoSoggetto, 
			Attivo
    FROM Destinatari      
		 
	UNION
	
	SELECT codice, 
			ragionesociale, 
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'H' AS TipoSoggetto, 			
			Attivo
    FROM Corrispondenti     
     
	UNION
	
	SELECT  codice, 
			ragionesociale, 
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'C' AS TipoSoggetto, 			
			Attivo
     FROM clienti	 
	 
   UNION
   
   SELECT	codice, 
			ragionesociale, 			
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'V' AS TipoSoggetto, 			
			Attivo
     FROM trasportatori

	UNION

	 SELECT	codice, 
			ragionesociale, 			
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'M' AS TipoSoggetto, 			
			Attivo
     FROM Caricatori;


-- dbo.VW_AUTISTAGIORNO_ATT source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT]
AS
SELECT      p.AUTISTA,
            p.DATA, 
            MIN(P.ID) IDINIZIO,
            MAX(u.ID) AS IDFINE
FROM	VW_AUTISTI_ATT_PRIMAGG P 
        INNER JOIN VW_AUTISTI_ATT_ULTIMAGG U ON U.AUTISTA = p.AUTISTA AND U.DATA = p.DATA
GROUP BY p.AUTISTA,p.DATA;


-- dbo.VW_AUTISTAGIORNO_ATT_DETT source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT_DETT]
AS
SELECT	V.AUTISTA,
		V.DATA,
		AU.RAGIONESOCIALE,		
		AI.Motrice, 
        M1.TARGA AS TARGAMOTRICE,
        AI.Rimorchio1,
        M2.TARGA AS TARGARIMORCHIO, 
		AI.DataInizio,
		AI.KmInizio,
		AI.LocalitaInizio, 
		AI.IndirizzoInizio, 
        AI.CapInizio, 
        AI.NazioneInizio,
        AF.DataFine,
		AF.KmFine,
		AF.LocalitaFine, 
		AF.IndirizzoFine, 
        AF.CapFine, 
        AF.NazioneFine,
        ISNULL(TG.MINUTI,0) AS TempoGuida,
        ISNULL(TG.TEMPO,0) AS TempoGuida2,       
        ISNULL(TP.MINUTI,0) AS TempoPausa,
        ISNULL(TP.TEMPO,0) AS TempoPausa2,     
        ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0) AS TempoCaricoScarico,
        --ISNULL(TS.TEMPO,0) AS TempoCaricoScarico2,    
		CASE WHEN  (ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0))  / 60 = 0 THEN '' ELSE CAST( (ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0)) / 60 AS VARCHAR(5))+':' END +  
		CASE WHEN  (ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0))  / 60 > 0 THEN REPLACE(STR( (ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0)) % 60, 2), SPACE(1), '0') ELSE CAST( (ISNULL(TC.MINUTI,0) + ISNULL(TS.MINUTI,0))  % 60 AS VARCHAR(5)) end AS TempoCaricoScarico2,
        ISNULL(AF.KMFINE - AI.KMINIZIO,0) AS TotKm,
        AI.ProvinciaInizio AS ProvinciaInizio, 
		AF.ProvinciaFine AS  ProvinciaFine
FROM	VW_AUTISTAGIORNO_ATT V 
		INNER JOIN AUTISTI AU ON AU.CODICE = V.AUTISTA
		INNER JOIN Autisti_Attivita AI ON AI.ID = V.IDINIZIO
		INNER JOIN Autisti_Attivita AF ON AF.ID = V.IDFINE
		LEFT JOIN MEZZI M1 ON M1.CODICE = AI.MOTRICE
		LEFT JOIN MEZZI M2 ON M2.CODICE = AI.RIMORCHIO1
		LEFT JOIN VW_AUTISTAGIORNO_ATT_TEMPI TG ON TG.AUTISTA = V.AUTISTA AND TG.DATA = V.DATA AND TG.TIPOATTIVITA = '001'
		LEFT JOIN VW_AUTISTAGIORNO_ATT_TEMPI TP ON TP.AUTISTA = V.AUTISTA AND TP.DATA = V.DATA AND TP.TIPOATTIVITA = '002'
		LEFT JOIN VW_AUTISTAGIORNO_ATT_TEMPI TC ON TC.AUTISTA = V.AUTISTA AND TC.DATA = V.DATA AND TC.TIPOATTIVITA = '003'
		LEFT JOIN VW_AUTISTAGIORNO_ATT_TEMPI TS ON TS.AUTISTA = V.AUTISTA AND TS.DATA = V.DATA AND TS.TIPOATTIVITA = '004'
		LEFT JOIN VW_AUTISTAGIORNO_ATT_TEMPI TE ON TE.AUTISTA = V.AUTISTA AND TE.DATA = V.DATA AND TE.TIPOATTIVITA = '006';


-- dbo.VW_AUTISTAGIORNO_ATT_MEZZO source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT_MEZZO]
AS
SELECT      A.AUTISTA,
            A.DATA, 
            (P.ID) IDINIZIO,
            (U.ID) AS IDFINE, 
            A.MOTRICE AS MEZZO
FROM	VW_AUTISTA_GIORNO_MEZZO  A 
		INNER JOIN VW_AUTISTI_ATT_PRIMAGG_MEZZO P ON P.AUTISTA = A.AUTISTA AND P.DATA = A.DATA  and p.motrice =a.motrice
        INNER JOIN VW_AUTISTI_ATT_ULTIMAGG_MEZZO U ON U.AUTISTA = A.AUTISTA AND U.DATA = A.DATA and u.motrice =a.motrice
        -- where a.autista ='100068'
  --and A.DATA = '20150129'
GROUP BY A.AUTISTA,A.DATA, A.MOTRICE, p.id, u.id;


-- dbo.VW_AUTISTAGIORNO_ATT_TEMPI source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT_TEMPI]
AS
SELECT	AUTISTA,
		DATA,
		TIPOATTIVITA,		
		SUM(TOTALE) AS MINUTI,
		SUM(TOTALE) % 60 AS TOTMINUTI,
		SUM(TOTALE) / 60 AS TOTORE,
		CASE WHEN SUM(TOTALE) / 60 = 0 THEN '' ELSE CAST(SUM(TOTALE) / 60 AS VARCHAR(5))+':' END +  
		CASE WHEN SUM(TOTALE) / 60 > 0 THEN REPLACE(STR(SUM(TOTALE) % 60, 2), SPACE(1), '0') ELSE CAST(SUM(TOTALE) % 60 AS VARCHAR(5)) END AS TEMPO
FROM	(
		SELECT	AUTISTA,
				DBO.TRUNC(DATAINIZIO) AS DATA,
				TIPOATTIVITA,		
				DATEDIFF(minute,DATAINIZIO,DATAFINE) AS TOTALE 
		FROM	AUTISTI_ATTIVITA
		) 
		T
		INNER JOIN AUTISTI_TIPIATTIVITA AT ON AT.CODICE = T.TIPOATTIVITA
GROUP BY AUTISTA,DATA,TIPOATTIVITA;


-- dbo.VW_AUTISTAGIORNO_ATT_TEMPI_MZ source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT_TEMPI_MZ]
AS
SELECT	AUTISTA,
		DATA,
		TIPOATTIVITA,	MOTRICE	,
		SUM(TOTALE) AS MINUTI,
		SUM(TOTALE) % 60 AS TOTMINUTI,
		SUM(TOTALE) / 60 AS TOTORE,
		CASE WHEN SUM(TOTALE) / 60 = 0 THEN '' ELSE CAST(SUM(TOTALE) / 60 AS VARCHAR(5))+':' END +  
		CASE WHEN SUM(TOTALE) / 60 > 0 THEN REPLACE(STR(SUM(TOTALE) % 60, 2), SPACE(1), '0') ELSE CAST(SUM(TOTALE) % 60 AS VARCHAR(5)) END
		 AS TEMPO
FROM	(
		SELECT	AUTISTA,
				DBO.TRUNC(DATAINIZIO) AS DATA,
				TIPOATTIVITA,	MOTRICE,	
				DATEDIFF(minute,DATAINIZIO,DATAFINE) AS TOTALE 
		FROM	AUTISTI_ATTIVITA
		) 
		T
		INNER JOIN AUTISTI_TIPIATTIVITA AT ON AT.CODICE = T.TIPOATTIVITA
GROUP BY AUTISTA,DATA,TIPOATTIVITA,MOTRICE;


-- dbo.VW_AUTISTAGIORNO_ATT_VIAGGIO source

ALTER VIEW [dbo].[VW_AUTISTAGIORNO_ATT_VIAGGIO]
AS
SELECT      A.AUTISTA,
            A.DATA, 
            (P.ID) IDINIZIO,
            (U.ID) AS IDFINE, 
            A.IDVIAGGIO AS IDVIAGGIO
FROM	VW_AUTISTA_GIORNO_VIAGGIO  A 
		INNER JOIN VW_AUTISTI_ATT_PRIMAGG_VIAGGIO P ON P.AUTISTA = A.AUTISTA AND P.DATA = A.DATA  and p.IDVIAGGIO =a.IDVIAGGIO
        INNER JOIN VW_AUTISTI_ATT_ULTIMAGG_VIAGGIO U ON U.AUTISTA = A.AUTISTA AND U.DATA = A.DATA and u.IDVIAGGIO =a.IDVIAGGIO
        -- where a.autista ='100068'
  --and A.DATA = '20150129'
GROUP BY A.AUTISTA,A.DATA, A.IDVIAGGIO, p.id, u.id;


