-- dbo.VW_AUTISTI_ATT_PRIMAGG source

ALTER VIEW [dbo].[VW_AUTISTI_ATT_PRIMAGG]
AS
SELECT ID,AUTISTA,DATA FROM 
(
      SELECT      A.Id,
                  A.AUTISTA,
                  DBO.TRUNC(A.DATAINIZIO) DATA, 
                  ROW_NUMBER() OVER(PARTITION BY AUTISTA, DBO.TRUNC(DATAINIZIO) ORDER BY DATAINIZIO) AS RN 
      FROM  AUTISTI_ATTIVITA A 
      WHERE TIPOATTIVITA <> '005'
)T WHERE RN= 1;


