-- dbo.VW_AUTISTI_CALENDARIO source

ALTER VIEW [dbo].[VW_AUTISTI_CALENDARIO] 
AS  
SELECT	CODICE, 
		RAGIONESOCIALE, 
		DATA, 
		FLAG  
FROM	AUTISTI CROSS JOIN CALENDARIO
WHERE	YEAR(DATA) > 2013;


-- dbo.VW_CLIENTI_FATTURAZIONE source

ALTER VIEW [dbo].[VW_CLIENTI_FATTURAZIONE] AS 
SELECT DISTINCT C1.CODICE AS CODICE, 				
				Case When C1.Attivo = 'N' Then '*** ATTENZIONE: BLOCCO AMMINISTRATIVO *** ' Else '' End + RTRIM(LTRIM(C1.RagioneSociale)) + ' (' + C1.CODICE + ')' as descrizione, 
				C1.RAGIONESOCIALE, 
				C1.Localita,
				C1.Indirizzo,
				C1.Provincia,
				C1.Nazione,
				C1.Cap,
				C1.RAGIONESOCIALE as orderfield
FROM			CLIENTI C1 
				INNER JOIN CLIENTI C2 ON C1.CODICE = C2.FATTURAA
WHERE			C1.CODICE <> '*ALL';


-- dbo.VW_CONSEGNE_EFFETTUATE source

ALTER VIEW [dbo].[VW_CONSEGNE_EFFETTUATE]
AS
SELECT	IDVIAGGIO,PCSDESTINAZIONE,'S' AS ESITO
FROM	SPEDIZIONI 
WHERE	IDVIAGGIO IS NOT NULL 
		AND STATO >= 50
GROUP BY IDVIAGGIO,PCSDESTINAZIONE;


