-- dbo.VW_Controllo_BolleRicevute source

ALTER VIEW [dbo].[VW_Controllo_BolleRicevute] as
select Stato,idviaggio, Numeroordine, numerobolla, databolla, pcspartenza as CodiceMittente, pcspartenza_ragsoc as Mittente, pcsdestinazione_ragsoc as Destinatario, Filleralfa1 as BU, Filleralfa6, Filleralfa7, filleralfa8 as CdC, Filleralfa9, Filleralfa10
	   from spedizioni
       where numerobolla not like '%/%'
       and idviaggio is null
-- and stato >30
-- and stato <> 99
and MONTH(databolla)=MONTH(getdate())
and YEAR(databolla)=YEAR(getdate());


-- dbo.VW_Controllo_ErroriBolle source

ALTER   VIEW [dbo].[VW_Controllo_ErroriBolle] as
SELECT
    Stato, 
    IdViaggio, 
    Numeroordine, 
    numerobolla, 
    databolla, 
    pcspartenza AS CodiceMittente, 
    pcspartenza_ragsoc AS Mittente, 
    pcsdestinazione_ragsoc AS Destinatario, 
    Filleralfa1 AS BU, 
    Filleralfa6, 
    Filleralfa7, 
    filleralfa8 AS CdC, 
    Filleralfa9, 
    Filleralfa10,
    CASE 
        WHEN databolla >= DATEADD(month, DATEDIFF(month, 0, GETDATE()) - 1, 0)
         AND databolla <  DATEADD(month, DATEDIFF(month, 0, GETDATE()), 0)
            THEN 'Mese precedente'
        WHEN databolla >= DATEADD(month, DATEDIFF(month, 0, GETDATE()), 0)
         AND databolla <  DATEADD(month, DATEDIFF(month, 0, GETDATE()) + 1, 0)
            THEN 'Mese corrente'
        ELSE 'Fuori periodo'
    END AS Periodo
FROM spedizioni
WHERE (Numeroordine NOT LIKE '%/%' OR Numeroordine = numerobolla)
  AND Stato > 30 
  AND Stato <> 99
  -- filtro che prende sia mese precedente che mese corrente
  AND databolla >= DATEADD(month, DATEDIFF(month, 0, GETDATE()) - 1, 0)  -- 1° giorno mese precedente
  AND databolla <  DATEADD(month, DATEDIFF(month, 0, GETDATE()) + 1, 0)  -- 1° giorno mese prossimo
  AND TipoSpedizione <>'EXW';


