-- dbo.VW_DELSYTASKS_TRIGGERS source

ALTER VIEW [dbo].[VW_DELSYTASKS_TRIGGERS]                                                     
AS
    SELECT TR.PROGRESSIVO,
          ISNULL(ISNULL(TR.ISTANZA, TSK.Istanza_Default),'MAIN') ISTANZA,
          TR.TASK,
          TR.APPLICAZIONE,
          TR.ATTIVO,
          TR.DATARICHIESTA,
          TR.DATAELABORAZIONE,
          RTRIM(LTRIM (TR.ARGOMENTI + ISNULL (TSK.ARGOMENTI, ' '))) ARGOMENTI,
          TR.RISULTATO,
          TR.DATAGG,
          TR.UTEAGG,
          TR.DATINS,
          TR.UTEINS,
          TSK.CLASSNAME CLASSNAME,
          ISNULL (TSK.DESCRIZIONE, TSK.CODICE) DESCRIZIONE
     FROM DELSYTASKS_TRIGGERS TR INNER JOIN DELSYTASKS TSK
          ON TSK.APPLICAZIONE = TR.APPLICAZIONE AND TSK.codice = TR.TASK;


-- dbo.VW_DELSY_MONITORGIRI source

ALTER VIEW [dbo].[VW_DELSY_MONITORGIRI]
AS
SELECT	DATApartenza AS DATA,	  	   	
	   	CAST(ISNULL(STATO_15, 0) AS INTEGER) IN_CORSO,
		CAST(ISNULL(STATO_20, 0) AS INTEGER) TERMINATI,			   
		CAST(ISNULL(STATO_15, 0)  + ISNULL(STATO_20, 0)  AS INTEGER) TOTALE, 
		--CAST(ISNULL(TERM, 0) AS INTEGER) TERM,
		CAST(ISNULL(TERM, 0) AS INTEGER) TERM
FROM
(
	SELECT TOP 100 percent DBO.TRUNC(DataPartenzaEffettiva) AS DATApartenza, 		   		   
		   (
			SELECT COUNT(DataPartenzaEffettiva)
			FROM VIAGGI V		
			WHERE V.Stato =30 AND Terminale IS NOT NULL and FlagViaggioSospeso = 'N' 
			  AND DBO.TRUNC(T1.DataPartenzaEffettiva)=DBO.TRUNC(V.DataPartenzaEffettiva)			  
			GROUP BY DBO.TRUNC(DataPartenzaEffettiva)
		   ) STATO_15,
		   (
		   SELECT COUNT(DataArrivoEffettiva  )
			FROM VIAGGI V		
			WHERE V.Stato =40 AND  DBO.TRUNC(T1.DataPartenzaEffettiva)=DBO.TRUNC(V.DataArrivoEffettiva )			  

			GROUP BY DBO.TRUNC(DataArrivoEffettiva )
		   ) STATO_20,		  		  		   
		   --(
		 --  SELECT COUNT(distinct Terminale)
			--FROM Viaggi  V		
			--WHERE V.stato in (30,40)
			--  AND DBO.TRUNC(T1.DataPartenzaEffettiva)=DBO.TRUNC(V.DataPartenzaEffettiva)			
			--GROUP BY DBO.TRUNC(DataPartenzaEffettiva)
		 --  ) TERM,
		   (
		   SELECT COUNT(distinct Autista1Effettivo )
			FROM Viaggi v 	
			WHERE  DBO.TRUNC(T1.DataPartenzaEffettiva)=DBO.TRUNC(v.DataPartenzaEffettiva) 
				   OR DBO.TRUNC(T1.DataPartenzaEffettiva)=DBO.TRUNC(v.DataArrivoEffettiva)			
			--GROUP BY DBO.TRUNC(a.datainizio)
		   ) TERM
		   
	FROM VIAGGI T1
	GROUP BY DBO.TRUNC(T1.DataPartenzaEffettiva )
	 
) T --ORDER BY DBO.TRUNC(DATApartenza) DESC;


