-- dbo.VW_DOC_VIAGGI_MASSIVO source

ALTER VIEW [dbo].[VW_DOC_VIAGGI_MASSIVO]
AS
SELECT	IDVIAGGIO, 
		DATAPARTENZAEFFETTIVA AS DATAPARTENZAEFFETTIVA, 
        ISNULL(V.MOTRICEEFFETTIVA,'') + ISNULL(' (' + M1.TARGA + ')','') AS MOTRICE,
        ISNULL(V.RIMORCHIO1EFFETTIVO,'') + ISNULL(' (' + M2.TARGA  + ')','') AS RIMORCHIO,
        ISNULL(TS.DESCRIZIONE,'') + ISNULL(' (' + TS.CODICE+ ')','')  AS TIPOSPEDIZIONE,
        ISNULL(TM.DESCRIZIONE,'') + ISNULL(' (' + TM.CODICE + ')','') AS TIPOMERCE,
        ISNULL(V.PCSPARTENZAEFFETTIVO,'') AS PCSPARTENZA,
        ISNULL(V.PCSARRIVOEFFETTIVO,'') AS PCSARRIVO,
        V.KMRICALCOLATI 
FROM	VIAGGI V 
		LEFT JOIN MEZZI M1 ON M1.CODICE = V.MOTRICEEFFETTIVA 
		LEFT JOIN MEZZI M2 ON M2.CODICE = V.RIMORCHIO1EFFETTIVO 
		LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = ISNULL(V.TIPOSPEDIZIONEATTIVA,TIPOSPEDIZIONE) 
		LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TIPOMERCE 
WHERE	V.STATO = 40;


