-- dbo.VW_DSISCHEDULER source

ALTER VIEW [dbo].[VW_DSISCHEDULER] AS
SELECT 
	D.PROGRESSIVO AS PROGRESSIVO,
	D.ISTANZA AS ISTANZA,
	D.TASK AS TASK,
	D.SEQUENZA AS SEQUENZA,
	D.ATTIVO AS ATTIVO,
	D.SCHEDULAZIONETIPO AS SCHEDULAZIONETIPO,
	D.SCHEDULAZIONEARGOMENTO AS SCHEDULAZIONEARGOMENTO,
	D.INIZIODATA AS INIZIODATA,
	D.INIZIOORA AS INIZIOORA,
	D.FINEDATA AS FINEDATA,
	D.FINEORA AS FINEORA,
	D.SECONDIDEDICATI AS SECONDIDEDICATI,
	D.ULTIMAESECUZIONEINIZIO AS ULTIMAESECUZIONEINIZIO,
	D.ULTIMAESECUZIONEFINE AS ULTIMAESECUZIONEFINE,
	D.NUMEROESECUZIONI AS NUMEROESECUZIONI,
	D.NUMEROERRORI AS NUMEROERRORI,
	ISNULL(D.ARGOMENTI, T.ARGOMENTI) AS ARGOMENTI,
	ISNULL(T.CLASSNAME, T.CODICE) AS CLASSNAME,
	ISNULL(D.DESCRIZIONE, '(' + T.DESCRIZIONE + ')') AS DESCRIZIONE,
	T.DESCRIZIONE AS DESCRIZIONEGENERICA,
	GETDATE() AS DATAORACORRENTE
FROM 
	DelsySCHEDULER D
	INNER JOIN DelsyTASKS T ON T.CODICE = D.TASK AND T.APPLICAZIONE=D.APPLICAZIONE
WHERE
	T.ATTIVO = 'S' AND 
	D.ATTIVO = 'S' AND 
	T.APPLICAZIONE='DSI' AND
	(D.INIZIODATA IS NULL OR D.INIZIODATA <= CONVERT(CHAR(8), GETDATE(), 112)) AND 
	(D.FINEDATA IS NULL OR D.FINEDATA >= CONVERT(CHAR(8), GETDATE(), 112)) AND 
	(CONVERT (INTEGER, D.INIZIOORA) <= DATEPART(hh, GETDATE()) * 10000 + DATEPART(mi, GETDATE()) * 100 + DATEPART(ss, GETDATE())) AND 
	(CONVERT (INTEGER, D.FINEORA) >= DATEPART(hh, GETDATE()) * 10000 + DATEPART(mi, GETDATE()) * 100 + DATEPART(ss, GETDATE()));


-- dbo.VW_DSI_LAST_EXEC_TASK source

ALTER VIEW [dbo].[VW_DSI_LAST_EXEC_TASK] AS 
SELECT 
	S.TASK, 
	S.DESCRIZIONE,
	S.ISTANZA,
	S.ARGOMENTI,
	U.RISULTATO,
	U.INIZIO,
	U.FINE
FROM 
	VW_DSI_LAST_EXEC_TASK_BASE B 
	INNER JOIN DelsyTasksEsecuzioni U 
		ON U.PROGRESSIVO = B.PROGRESSIVO
	INNER JOIN DelsyScheduler S 
		ON S.PROGRESSIVO = B.PROGRESSIVOSCHEDULER;


