		CAST(NULL AS VARCHAR(255)) FillerAlfa2,
		CAST(NULL AS VARCHAR(255)) FillerAlfa3,
		CAST(NULL AS VARCHAR(255)) FillerAlfa4,
		CAST(NULL AS VARCHAR(255)) FillerAlfa5,
		CAST(NULL AS VARCHAR(255)) FillerAlfa6,
		CAST(NULL AS VARCHAR(255)) FillerAlfa7,
		CAST(NULL AS VARCHAR(255)) FillerAlfa8,
		CAST(NULL AS VARCHAR(255)) FillerAlfa9,
