		Cliente,		
		Trasportatore,
		Autista,
		M.TipoMerce,
		M.PortataPeso,
		M.PortataVolume,
		M.PortataColli,
		M.PortataPallet,
		KmAttuali
FROM	Mezzi M	
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
		INNER JOIN MEZZICATEGORIE C ON C.CODICE = TM.CATEGORIA
WHERE	M.ATTIVO = 'S' AND CONMOTORE = 'S';


