-- dbo.VW_FGL_Viaggi source

ALTER VIEW [dbo].[VW_FGL_Viaggi]
AS
SELECT	  IdViaggio,
		  ISNULL(DataArrivoEffettiva,ISNULL(DataPartenzaEffettiva,DataPartenzaPianificata)) as DataRiferimento,
          Stato,
          TipoViaggio,
          DataPartenzaPianificata,
          DataArrivoPianificata,
          DataPartenzaEffettiva,
          DataArrivoEffettiva,
          MotricePianificata,          
          Rimorchio1Pianificato,    
          Rimorchio2Pianificato,         
          Contenitore1Pianificato,  
          Contenitore2Pianificato,   
          Autista1Pianificato,               
          MotriceEffettiva,          
          Rimorchio1Effettivo,    
          Rimorchio2Effettivo,         
          Contenitore1Effettivo,  
          Contenitore2Effettivo,  
          Autista1Effettivo,      
          Autista2Effettivo,
          Vettore,
          T.RagioneSociale AS Vettore_RagSoc,         
          TipoSpedizione,
          TS.Descrizione AS TipoSpedizione_Descrizione,
          V.TipoMerce,
          TM.Descrizione AS TipoMerce_Descrizione,
          V.Cliente,
          C.RagioneSociale AS Cliente_RagSoc,
          PCSPartenza,
          PP.RagioneSociale PCSPARTENZA_RAGSOC,
          PP.Indirizzo PCSPARTENZA_INDIRIZZO,
          PP.Cap PCSPARTENZA_CAP,
          PP.Localita PCSPARTENZA_LOCALITA,
          PP.Provincia PCSPARTENZA_PROVINCIA,
          PP.Nazione PCSPARTENZA_NAZIONE,
          PCSArrivo,
          PA.RagioneSociale PCSARRIVO_RAGSOC,
          PA.Indirizzo PCSARRIVO_INDIRIZZO,
          PA.Cap PCSARRIVO_CAP,
          PA.Localita PCSARRIVO_LOCALITA,
          PA.Provincia PCSARRIVO_PROVINCIA,
          PA.Nazione PCSARRIVO_NAZIONE,
          PCSPartenzaEffettivo,
          PP.RagioneSociale PCSPARTENZAEffettivo_RAGSOC,
          PP.Indirizzo PCSPARTENZAEffettivo_INDIRIZZO,
          PP.Cap PCSPARTENZAEffettivo_CAP,
          PP.Localita PCSPARTENZAEffettivo_LOCALITA,
          PP.Provincia PCSPARTENZAEffettivo_PROVINCIA,
          PP.Nazione PCSPARTENZAEffettivo_NAZIONE,
          PCSArrivoEffettivo,
          PA.RagioneSociale PCSARRIVOEffettivo_RAGSOC,
          PA.Indirizzo PCSARRIVOEffettivo_INDIRIZZO,
          PA.Cap PCSARRIVOEffettivo_CAP,
          PA.Localita PCSARRIVOEffettivo_LOCALITA,
          PA.Provincia PCSARRIVOEffettivo_PROVINCIA,
          PA.Nazione PCSARRIVOEffettivo_NAZIONE,
          KmPianificati,
          KmManuali,
          KmGPS,          
          Terminale,
          (
          SELECT ISNULL(SUM(ISNULL(Peso,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Peso,
          (
          SELECT ISNULL(SUM(ISNULL(Volume,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Volume,
          (
          SELECT ISNULL(SUM(ISNULL(Colli,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Colli,
          (
          SELECT ISNULL(SUM(ISNULL(Pallet,0)),0) FROM Spedizioni S WHERE S.IdViaggio=V.IdViaggio
          ) Pallet,
          (
          SELECT COUNT(*) FROM Spedizioni S WHERE S.IdViaggio = V.IdViaggio
          ) NumeroSpedizioni,          
          FlagViaggioSospeso
FROM	  Viaggi V 
          LEFT JOIN TRASPORTATORI T ON T.CODICE = V.VETTORE         
          LEFT JOIN CLIENTI C ON C.CODICE = V.CLIENTE
          LEFT JOIN TIPISPEDIZIONE TS ON TS.CODICE = V.TIPOSPEDIZIONE
          LEFT JOIN TIPIMERCE TM ON TM.CODICE = V.TipoMerce
          LEFT JOIN PCS PP ON PP.CODICE = V.PCSPARTENZA
          LEFT JOIN PCS PA ON PA.CODICE = V.PCSARRIVO
WHERE	  STATO > 10 AND STATO < 50;


-- dbo.VW_FILTRO_AUTISTIATTIVITA source

ALTER VIEW [dbo].[VW_FILTRO_AUTISTIATTIVITA]
AS
SELECT	codice, descrizione, codice AS orderfield, visibile
FROM	(SELECT '1' AS codice, 'GIORNO CORRENTE' AS descrizione,
                  'S' AS visibile             
           UNION
           SELECT '10' AS codice, 'ULTIMI 10 GIORNI' AS descrizione,
                  'S' AS visibile
             
           UNION
           SELECT '20' AS codice, 'ULTIMI 20 GIORNI' AS descrizione,
                  'S' AS visibile
            
           UNION
           SELECT '30' AS codice, 'ULTIMI 30 GIORNI' AS descrizione,
                  'S' AS visibile
            
           UNION
           SELECT '40' AS codice, 'MESE CORRENTE' AS descrizione,
                  'S' AS visibile
            
           UNION
           SELECT '50' AS codice, 'DA DATA - A DATA' AS descrizione,
                  'S' AS visibile
        )T;


-- dbo.VW_FLGECCEDENZA source

ALTER VIEW [dbo].[VW_FLGECCEDENZA] AS
SELECT  'N' AS CODICE, 
		'FASCIA SINGOLA' AS DESCRIZIONE,
		'S' ISDEFAULT,
		1 AS ORDERFIELD
UNION
SELECT  'S' AS CODICE, 
		'ECCEDENZE' AS DESCRIZIONE,
		'N' ISDEFAULT,
		2 AS ORDERFIELD
UNION
SELECT  '+' AS CODICE, 
		'COMPENSAZIONE POSITIVA (CONVENIENZA CLIENTE)' AS DESCRIZIONE,
		'N' ISDEFAULT,
		3 AS ORDERFIELD
UNION
SELECT  '-' AS CODICE, 
		'COMPENSAZIONE NEGATIVA (CONVENIENZA TRASPORTATORE)' AS DESCRIZIONE,
		'N' ISDEFAULT,
		4 AS ORDERFIELD;


-- dbo.VW_GMB_SOGGETTI source

ALTER VIEW [dbo].[VW_GMB_SOGGETTI]  AS
	SELECT  codice, 
			ragionesociale,
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'D' AS tipoanagrafica, 
			Attivo
    FROM Destinatari  
    WHERE Attivo='S'
	
	UNION
	
	SELECT  codice, 
			ragionesociale, 
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'F' AS tipoanagrafica, 
			Attivo
    FROM Filiali 
    WHERE Attivo='S'
     
	UNION
	
	SELECT codice, 
			ragionesociale, 
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'H' AS tipoanagrafica, 			
			Attivo
    FROM Corrispondenti 
    WHERE Attivo='S'
     
	UNION
	
	SELECT  codice, 
			ragionesociale, 
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'C' AS tipoanagrafica, 			
			Attivo
     FROM clienti
	 WHERE Attivo='S' 
	 
   UNION
   
   SELECT	codice, 
			ragionesociale, 			
			Localita, 
			provincia, 
			Nazione,
			Cap,
			indirizzo,
			'V' AS tipoanagrafica, 			
			Attivo
     FROM trasportatori;


