-- dbo.VW_MEZZI_TA source

ALTER VIEW [dbo].[VW_MEZZI_TA] AS
   SELECT m.Codice, 
		  m.Descrizione, 
		  m.Targa, 
		  m.TipoMezzo,
		  tm.Descrizione DescrizioneTipoMezzo,
		  m.TipoMerce,
		  m.KmInizio, 
		  m.Autista,
          m.Trasportatore, 
		  ISNULL(m.PortataPeso, tm.PortataPeso) PortataPeso,
          ISNULL(m.PortataVolume, tm.PortataVolume) PortataVolume,
          ISNULL(m.PortataMetriLineari, tm.PortataMetriLineari) PortataMetriLineari,
          ISNULL(m.PortataColli, tm.PortataColli) PortataColli,
          ISNULL(m.PortataPallet, tm.PortataPallet) PortataPallet,
          ISNULL(m.PortataRoll, tm.PortataRoll) PortataRoll,
          ISNULL(m.PortataQ1, tm.PortataQ1) PortataQ1,
          ISNULL(m.PortataQ2, tm.PortataQ2) PortataQ2,
          ISNULL(m.PortataQ3, tm.PortataQ3) PortataQ3,
          ISNULL(m.GradoSaturazionePeso, tm.GradoSaturazionePeso) GradoSaturazionePeso,
          ISNULL(m.GradoSaturazioneVolume, tm.GradoSaturazioneVolume) GradoSaturazioneVolume,
		  ISNULL(m.GradoSaturazioneML, tm.GradoSaturazioneML) GradoSaturazioneML,
          ISNULL(m.GradoSaturazioneColli, tm.GradoSaturazioneColli) GradoSaturazioneColli,
          ISNULL(m.GradoSaturazionePallet, tm.GradoSaturazionePallet) GradoSaturazionePallet,
          ISNULL(m.GradoSaturazioneRoll, tm.GradoSaturazioneRoll) GradoSaturazioneRoll,
          ISNULL(m.GradoSaturazioneQ1, tm.GradoSaturazioneQ1) GradoSaturazioneQ1,
		  ISNULL(m.GradoSaturazioneQ2, tm.GradoSaturazioneQ2) GradoSaturazioneQ2,
          ISNULL(m.GradoSaturazioneQ3, tm.GradoSaturazioneQ3) GradoSaturazioneQ3,
          ISNULL(m.TempoReimpiego, tm.TempoReimpiego) TempoReimpiego,
          ISNULL(m.NumMaxReimpieghi, tm.NumMaxReimpieghi) NumMaxReimpieghi,
		  ISNULL(m.ClasseDiGrandezza, tm.ClasseDiGrandezza) ClasseDiGrandezza, 
		  ISNULL(m.Lunghezza, tm.Lunghezza) Lunghezza,
          ISNULL(m.Larghezza, tm.Larghezza) Larghezza,
		  ISNULL(m.Altezza, tm.Altezza) Altezza,
		  m.EmissioneCO2, 
		  ISNULL(m.Tara, tm.Tara) Tara,
		  ISNULL(m.Assi, tm.Assi) Assi,
		  m.Note,
          m.Telaio, 
		  m.Attivo, 
		  m.PuntoPartenza, 
		  m.PuntoArrivo, 
		  m.DispDalleOre,
          m.DispAlleOre, 
          mc.Contenitore,
          mc.ConMotore Trattore,
          CASE
             WHEN mc.ConMotore = 'N' AND mc.Trainato = 'S' THEN 'S'
             ELSE 'N'
          END Semirimorchio,
		  pv.SuffissoFile,
          pv.IdDima
     FROM Mezzi m 
	INNER JOIN TipiMezzo tm ON tm.Codice = m.TipoMezzo
	INNER JOIN MezziCategorie mc ON tm.Categoria = mc.Codice
	INNER JOIN ProfiliVelocita pv ON tm.ProfiloVelocita = pv.Codice;


-- dbo.VW_PCS_ACQUISITI source

--
--
-- INTRODUZIONE DEL MECCANISMO *ALL IN IMP SPEDIZIONI SU AGGANCCIO PCS_ACQUISITI (ATTIVAZIONE DEL MECCANISMO TRAMITE UN PARAMETRO DI INGRESSO AL TASK)
--
--
ALTER VIEW VW_PCS_ACQUISITI AS
SELECT 
	CASE WHEN T.Cliente='*ALL' THEN 0 ELSE 10 END + 
	CASE WHEN T.CodiceEsterno='*ALL' THEN 0 ELSE 1 END Peso,
	T.* 
FROM PCS_Acquisiti T;


-- dbo.VW_PCS_RECUPERA source

ALTER VIEW [dbo].[VW_PCS_RECUPERA]
AS
SELECT	P.Codice, 
		P.RagioneSociale, 
		ISNULL(P.Indirizzo,'') Indirizzo ,		
		ISNULL(P.Cap, '') Cap ,
		ISNULL(P.Localita, '') Localita ,
		ISNULL(P.Provincia, '') Provincia, 
		ISNULL(P.Nazione, '') Nazione ,
		ISNULL(Latitudine, '') Latitudine ,
		ISNULL(Longitudine, '') Longitudine, 		
		'C' AS  Tipologia ,
		ISNULL(A.CLIENTE,'*ALL') Cliente,
		Note
FROM	PCS	P
		LEFT JOIN PCS_GEOCODIFICA PG ON PG.CODICE = P.CODICE
		LEFT JOIN PCS_ACQUISITI A ON  P.CODICE = A.CODICEINTERNO
WHERE	P.PUNTODICARICO = 'S'
UNION ALL
SELECT	P.Codice, 
		P.RagioneSociale, 
		ISNULL(P.Indirizzo,'') Indirizzo ,		
		ISNULL(P.Cap, '') Cap ,
		ISNULL(P.Localita, '') Localita ,
		ISNULL(P.Provincia, '') Provincia, 
		ISNULL(P.Nazione, '') Nazione ,
		ISNULL(Latitudine, '') Latitudine ,
		ISNULL(Longitudine, '') Longitudine, 		
		'S' AS Tipologia ,
		ISNULL(A.CLIENTE,'*ALL') Cliente ,
		Note
FROM	PCS	P
		LEFT JOIN PCS_GEOCODIFICA PG ON PG.CODICE = P.CODICE
		LEFT JOIN PCS_ACQUISITI A ON  P.CODICE = A.CODICEINTERNO
WHERE	P.PUNTODIDESTINO = 'S';


