ALTER VIEW [dbo].[VW_PV_Spedizioni] 
AS
   SELECT unibol, unibolparent, unibolmaster, progressivoconsegna, barcode,
          prebolla, tiposervizio, cliente,
          c.ragionesociale AS clienteragionesociale, mittente,
          m.ragionesociale AS mittenteragionesociale2, mittenteragionesociale,
          numerobolla, databolla, numeroordine, dataordine,
          numeroordinecliente, dataordinecliente, tipospedizione,
          ts.descrizione AS iipospedizionidescrizione, tipomerce,
          tm.descrizione AS tipomercedescrizione, pcspartenza,
          pcspartenza_ragsoc, pcspartenza_indirizzo, pcspartenza_cap,
          pcspartenza_localita, pcspartenza_provincia, pcspartenza_nazione,
          pcsdestinazione, pcsdestinazione_ragsoc, pcsdestinazione_indirizzo,
          pcsdestinazione_cap, pcsdestinazione_localita,
          pcsdestinazione_provincia, pcsdestinazione_nazione,
          s.zonaspedizione, z.descrizione AS zonaspedizionedescrizione,
          dataconsegnaprevista1, dataconsegnaprevista2,
          dataconsegnaconcordata, oraconsegnaconcordata1,
          oraconsegnaconcordata2, dataritiroprevista1, dataritiroprevista2,
          oraritiroconcordata1, oraritiroconcordata2, corrispondente,
          co.ragionesociale AS corrispondenteragionesociale, trasportatore,
          t.ragionesociale AS trasportatoreragionesociale, s.peso, s.colli,
          s.pallet, s.volume, s.campocalcolo1, s.campocalcolo2,
          s.campocalcolo3, s.campocalcolo4, s.campocalcolo5, s.campocalcolo6,
          s.campocalcolo7, s.campocalcolo8, s.campocalcolo9, s.campocalcolo10,
          contrassegno, s.note, datacompetenzaattiva, batchid, dataspedizione,
          ISNULL (zm.codice, '*XXX*') AS macrozonaspedizione,
          ISNULL (zm.descrizione,'NON DEFINITA') AS macrozonaspedizionedescrizione, 
		  s.FillerAlfa1,s.FillerAlfa2,s.FillerAlfa3,
		  s.FillerAlfa4,s.FillerAlfa5,s.FillerAlfa6,
		  s.FillerAlfa7,s.FillerAlfa8,s.FillerAlfa9,s.FillerAlfa10,
		  S.FLAG1, S.FLAG2, S.FLAG3, S.FLAG4, S.FLAG5,
          S.FLAG6, S.FLAG7, S.FLAG8, S.FLAG9, S.FLAG10
     FROM spedizioni s INNER JOIN clienti c ON c.codice = s.cliente
          LEFT JOIN clienti m ON m.codice = s.mittente
          INNER JOIN tipispedizione ts ON ts.codice = s.tipospedizione
          LEFT JOIN tipimerce tm ON tm.codice = s.tipomerce
          LEFT JOIN corrispondenti co ON co.codice = s.corrispondente
          LEFT JOIN trasportatori t ON t.codice = s.trasportatore
          INNER JOIN zonespedizione z ON z.codice = s.zonaspedizione
          LEFT JOIN zonemacro zm ON zm.codice = z.codicezonamacro
    WHERE s.stato = 20 AND idviaggio IS NULL;


