-- dbo.VW_SPEDIZIONI source

ALTER VIEW [dbo].[VW_SPEDIZIONI] AS
SELECT	S1.*,
		E.TipoEvento Evento_TipoEsito,
		E.BuonFine Evento_BuonFine,
		E.GeneraRiconsegna Evento_GeneraRiconsegna,
		E.AddebitaRicavi Evento_AddebitaRicavi,
		E.AccreditaCosti Evento_AccreditaCosti,
		E.CreaGiacenza Evento_CreaGiacenza,
		E.CreaContestazione Evento_CreaContestazione,
		(
		SELECT Unibol_Spedizione
		FROM Spedizioni_SubSpedizioni 
		WHERE Unibol_SubSpedizione=S1.UniBol  
		) UnibolSpedizioneCompleta,
		(
		SELECT COUNT(*)
		FROM Spedizioni_SubSpedizioni 
		WHERE Unibol_Spedizione=S1.UniBol  
		) CountOfSubSpedizioni
FROM (
	select	S.*, 
			SE.CodiceEvento Evento_CodiceEsito,
			SE.DataOraEvento Evento_DataOraEsito,		
			SE.NoteInterne Evento_NoteInterne,
			SE.NoteEsterne Evento_NoteEsterne,
			SE.Importato Evento_Importato,
			SE.Annullato Evento_Annullato,
			SE.EsportatoCliente Evento_EsportatoCliente,
			SE.DataEsportazioneCliente Evento_DataEsportazioneCliente,
			SE.EsportatoFornitore Evento_EsportatoFornitore,
			SE.DataEsportazioneFornitore Evento_DataEsportazioneForn
	from Spedizioni S 
	OUTER APPLY dbo.getSpedizioneEvento(null, '001', S.UNIBOL) SE
) S1 LEFT JOIN Eventi E ON Evento_CodiceEsito=E.Codice;


-- dbo.VW_SPEDIZIONI_DATA source

ALTER view [dbo].[VW_SPEDIZIONI_DATA]
AS
SELECT	V.Autista1Effettivo  as AUTISTASERVIZIO ,
		DBO.TRUNC(DataOraArrivoEffettiva) AS DATASERVIZIO,	
		COUNT(1) AS SERVIZI
FROM    SPEDIZIONI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO
GROUP BY DBO.TRUNC(DataOraArrivoEffettiva), V.Autista1Effettivo;


-- dbo.VW_SPEDIZIONI_DATA_MEZZI source

ALTER VIEW [dbo].[VW_SPEDIZIONI_DATA_MEZZI]
AS
SELECT	V.Autista1Effettivo  as AUTISTASERVIZIO ,
		DBO.TRUNC(DataOraArrivoEffettiva) AS DATASERVIZIO,	MotriceEffettiva AS MOTRICESERVIZIO,
		COUNT(1) AS SERVIZI
FROM    SPEDIZIONI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO
GROUP BY DBO.TRUNC(DataOraArrivoEffettiva), V.Autista1Effettivo, MotriceEffettiva;


