-- dbo.VW_SPEDIZIONI_DATA_VIAGGIO_C source

ALTER VIEW [dbo].[VW_SPEDIZIONI_DATA_VIAGGIO_C]
AS
SELECT	V.Autista1Effettivo  as AUTISTASERVIZIO ,
		DBO.TRUNC(DataOraArrivoEffettiva) AS DATASERVIZIO,	V.IDVIAGGIO AS IDVIAGGIO,
