-- dbo.VW_SPEDIZIONI_ESITO source

ALTER VIEW [dbo].[VW_SPEDIZIONI_ESITO] 
AS
SELECT UNIBOL,CODICEEVENTO FROM SPEDIZIONI_EVENTI 
WHERE ID IN (
SELECT	MAX(ID)
FROM	SPEDIZIONI_EVENTI S 
		INNER JOIN EVENTI E ON E.CODICE = S.CODICEEVENTO 
		INNER JOIN EVENTI_TIPI T ON E.TIPOEVENTO = T.CODICE
WHERE	T.SCOPE = '001'
GROUP BY UNIBOL);


-- dbo.VW_SPEDIZIONI_PRIMOSCARICO source

ALTER VIEW [dbo].[VW_SPEDIZIONI_PRIMOSCARICO]
AS
SELECT IDVIAGGIO,DATAPRIMOSCARICO FROM 
(
      SELECT      S.IdViaggio ,
                  DBO.TRUNC(S.DataOraArrivoEffettiva)  DATAPRIMOSCARICO, 
                  ROW_NUMBER() OVER(PARTITION BY S.idviaggio ORDER BY DataOraArrivoEffettiva DESC) AS RN 
FROM    SPEDIZIONI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO
WHERE TIPOSERVIZIO ='S'		
)T WHERE RN= 1;


-- dbo.VW_SPEDIZIONI_VIAGGI_MEZZI_S source

ALTER VIEW [dbo].[VW_SPEDIZIONI_VIAGGI_MEZZI_S]
AS
SELECT	V.IDVIAGGIO as IDVIAGGIO ,
		MotriceEffettiva AS MOTRICESERVIZIO,
		COUNT(1) AS SERVIZI
FROM    SPEDIZIONI S 
		INNER JOIN VIAGGI V on V.IDVIAGGIO = S.IDVIAGGIO
		AND TIPOSERVIZIO='S'
GROUP BY V.IDVIAGGIO, MotriceEffettiva;


-- dbo.VW_TEMPICARICOSCARICO_DESC source

ALTER VIEW [dbo].[VW_TEMPICARICOSCARICO_DESC] AS 
SELECT 
	TCS.Codice,
	TCS.Descrizione + ' (' + TCS.Codice + ') - ' + 
	CASE WHEN TempoFisso <> '' THEN 'Tempo fisso:' + TempoFisso ELSE '' END + 
	CASE WHEN TempoFisso <> '' AND TempoVariabile <> '' THEN ' e ' ELSE '' END +
	CASE WHEN TempoVariabile <> '' AND Quantita <> 0 THEN 'Tempo variabile:' + TempoVariabile + ' per ogni ' + CAST(Quantita AS VARCHAR) + ' ' + ISNULL(U.Descrizione, TCS.CodiceUDM) ELSE '' END AS Descrizione
FROM	
	(SELECT 
		Codice,
		Descrizione,
		dbo.HumanReadableTimeInterval(TempoFisso) AS TempoFisso,
		dbo.HumanReadableTimeInterval(TempoVariabile) AS TempoVariabile,
		CodiceUDM,
		Quantita
	FROM 
		TEMPICARICOSCARICO) TCS
	LEFT JOIN UnitaDiMisura U ON U.Codice = TCS.CodiceUDM;


