		'S'  AS Attivo
FROM	CLIENTITIPISPEDIZIONE 
WHERE	CLIENTE <> '*ALL';


-- dbo.VW_TERM_CausaliAnomalieMezzo source

ALTER VIEW [dbo].[VW_TERM_CausaliAnomalieMezzo]
AS
SELECT	CODICE,
		DESCRIZIONE,
		'S' as Motrice,
		'S' as Rimorchio,
		'S' as Tank,
		Attivo
FROM	CausaliMezziAnomalie;


-- dbo.VW_TERM_MEZZI source

ALTER VIEW [dbo].[VW_TERM_MEZZI]
AS
SELECT	M.Codice, 
		ISNULL(Cliente,'') Cliente,
		ISNULL(M.Descrizione,'') Descrizione, 
		ISNULL(Targa, '') Targa, 
		CASE WHEN CONMOTORE = 'S' THEN 'M' 
			 WHEN CONMOTORE = 'N' AND TARGATO = 'S' THEN 'R'
			 ELSE 'T' END AS TipoMezzo, 
		ISNULL(ISNULL(M.TipoMerce,TM.TipoMerce), '') TipoMerce, 				
		CASE WHEN PUOTRAINARE = 'S' AND CONTENITORE = 'N' THEN 'S' 
			 ELSE 'N' END AS Rimorchio, 	
		CASE WHEN ACCETTACONTENITORE = 'S' AND CONTENITORE = 'N' THEN 'S'
			 ELSE 'N' END AS Tank,	
		KmAttuali as Km,
		M.Attivo
FROM	Mezzi M	
		INNER JOIN TIPIMEZZO TM ON TM.CODICE = M.TIPOMEZZO
		INNER JOIN MEZZICATEGORIE C ON C.CODICE = TM.CATEGORIA;


-- dbo.VW_TERM_OBC_TipoServizioInfo source

ALTER VIEW  [dbo].[VW_TERM_OBC_TipoServizioInfo]
AS
SELECT	Progressivo,
