		ISNULL(Servizio,'') Servizio,
        ISNULL(Cliente,'*ALL') Cliente,
        Descrizione,
        TipoDato,
        Sequenza ,
		Attivo,
		isnull(UnitaMisura,'') UnitaMisura ,
		Raggruppato
FROM	OBC_TipoServiziInfo;


-- dbo.VW_TERM_PCS source

ALTER VIEW [dbo].[VW_TERM_PCS]
AS
SELECT	P.Codice, 
		RagioneSociale, 
		ISNULL(Indirizzo,'') Indirizzo ,		
		ISNULL(Cap, '') Cap ,
		ISNULL(Localita, '') Localita ,
		ISNULL(Provincia, '') Provincia, 
		ISNULL(Nazione, '') Nazione ,
		ISNULL(Latitudine, '') Latitudine ,
		ISNULL(Longitudine, '') Longitudine, 		
		'C' AS  Tipologia ,
		ISNULL('','') Cliente ,
		Note
FROM	PCS	P
		LEFT JOIN PCS_GEOCODIFICA PG ON PG.CODICE = P.CODICE
WHERE	PUNTODICARICO = 'S'
UNION ALL
SELECT	P.Codice, 
		RagioneSociale, 
		ISNULL(Indirizzo,'') Indirizzo ,		
		ISNULL(Cap, '') Cap ,
		ISNULL(Localita, '') Localita ,
		ISNULL(Provincia, '') Provincia, 
		ISNULL(Nazione, '') Nazione ,
		ISNULL(Latitudine, '') Latitudine ,
		ISNULL(Longitudine, '') Longitudine, 		
		'S' AS Tipologia ,
		ISNULL('','') Cliente ,
		Note
FROM	PCS	P
		LEFT JOIN PCS_GEOCODIFICA PG ON PG.CODICE = P.CODICE
WHERE	PUNTODIDESTINO = 'S';


-- dbo.VW_TERM_SPEDIZIONI source

ALTER VIEW [dbo].[VW_TERM_SPEDIZIONI]
AS
SELECT	S.IdViaggio, 
		Unibol, 
		TipoServizio TipoBolla, 
		ISNULL(S.Cliente, '') Cliente,
		ISNULL(NumeroOrdine, '') NumeroBolla,
		DataBolla,		
		CASE WHEN TIPOSERVIZIO = 'C' THEN ISNULL(PCSDestinazione, '') ELSE ISNULL(S.PCSPartenza,'') END PCS_Partenza,
		ISNULL(PCSDestinazione, '') PCS_Arrivo,	
		S.KmManuali,
		ISNULL(PCSDestinazione_Localita,'') as Localita,	
		CASE WHEN DATAORAARRIVOEFFETTIVA IS NOT NULL THEN 'OK' ELSE '' END AS CodiceEsito,
		SequenzaEffettiva AS SEQUENZA,
		SEQUENZAPIANIFICATA + 1000 AS SEQUENZAPianificata,
		DATAORAARRIVOEFFETTIVA as DATAESITO,
		ISNULL(NOTE,'') as NOTE,
		UNIBOLOBC
FROM	SPEDIZIONI S INNER JOIN VIAGGI V ON S.IDVIAGGIO = V.IDVIAGGIO
WHERE	S.IDVIAGGIO IS NOT NULL
		AND V.STATO < 40 AND V.STATO >=20;


