-- dbo.VW_TERM_VIAGGI source

ALTER VIEW [dbo].[VW_TERM_VIAGGI]
AS

SELECT	IdViaggio, 
		ISNULL(TipoSpedizione,'') AS TipoSpedizione, 
		ISNULL(Cliente ,'') AS Cliente,
		ISNULL(TipoMerce, '') TipoMerce,
		ISNULL(ISNULL(MOTRICEEFFETTIVA, MOTRICEPIANIFICATA),'')  AS Motrice,
		ISNULL(ISNULL(Rimorchio1EFFETTIVO,Rimorchio1Pianificato),'')  AS Rimorchio,
		ISNULL(ISNULL(CONTENITORE1EFFETTIVO,CONTENITORE1Pianificato),'')  AS Tank,		
		ISNULL(Terminale,'') AS Terminale,
		Stato,
		S.DESCRIZIONE,
		CASE WHEN v.STAtO = 20 THEN 'CENTRALE' ELSE 'SOSPESO' END AS StatoDescrizione,
		ISNULL(DataPartenzaEffettiva,DataPartenzaPianificata) AS DataPartenza,
		iSNULL(NOTE1,'') AS NOTE
FROM	Viaggi V
		INNER JOIN VW_DOC_Viaggi_Stati S ON S.CODICE = V.STATO
WHERE	(STATO = 30 AND FLAGVIAGGIOSOSPESO = 'S' AND DBO.TRUNC(DataPartenzaEffettiva) >= (GETDATE() - 8) ) 
		OR (STATO = 20)
		AND CLIENTE IS NOT NULL;


