-- dbo.VW_TERM_VIAGGI_TIPISERVIZI source

ALTER VIEW [dbo].[VW_TERM_VIAGGI_TIPISERVIZI]
AS
SELECT	CODICE,		
		V.DESCRIZIONE,
		'E' TIPO,
		V.Attivo,
		3 SEQUENZA	,
		ISNULL(Cliente,'*ALL') as Cliente 
FROM	VIAGGI_TIPISERVIZI V LEFT JOIN
		OBC_TipoServiziInfo O ON V.Codice = O.Servizio 		
UNION 
SELECT	'SPED_CARICO' CODICE,
		'CARICO' DESCRIZIONE,
		'C' TIPO,
		'S' attivo,
		1 SEQUENZA,
		'*ALL' AS Cliente
UNION 
SELECT	'SPED_SCARICO' CODICE,
		'SCARICO' DESCRIZIONE,
		'S' TIPO,
		'S' attivo,
		2 SEQUENZA,
		'*ALL' AS Cliente;


