-- dbo.VW_TRASPORTATORI_FATTURAZIONE source

ALTER VIEW [dbo].[VW_TRASPORTATORI_FATTURAZIONE] AS 
SELECT DISTINCT T1.CODICE AS CODICE, 				
				Case When T1.Attivo = 'N' Then '*** ATTENZIONE: BLOCCO AMMINISTRATIVO *** ' Else '' End + RTRIM(LTRIM(T1.RagioneSociale)) + ' (' + T1.CODICE + ')' as descrizione, 
				T1.RAGIONESOCIALE, 
				T1.Localita,
				T1.Indirizzo,
				T1.Provincia,
				T1.Nazione,
				T1.Cap,
				T1.RAGIONESOCIALE as orderfield
FROM			TRASPORTATORI T1 
				INNER JOIN TRASPORTATORI T2 ON T1.CODICE = T2.FATTURAA
WHERE			T1.CODICE <> '*ALL';


-- dbo.VW_TRK_MAPPA_PUNTIVIAGGIO source

ALTER VIEW [dbo].[VW_TRK_MAPPA_PUNTIVIAGGIO] AS
   SELECT *
     FROM (
			SELECT v.IdViaggio, 
				   0 AS SequenzaCalcolata, 
				   ISNULL(v.PCSPartenzaEffettivo, v.PCSPartenza) AS ID,
				   '2' AS Tipologia, 
				   pg.Latitudine,
				   pg.Longitudine,
				   p.RagioneSociale + ' (' + p.Codice + ')' AS Tooltip,
				   p.RagioneSociale + ' - ' + p.Localita + ' - ' + p.Indirizzo AS Descrizione,
				   0 AS FixTooltip,
				   '' AS ColoreFixTooltip,
				   0 AS Sequenza,
				   'OK' AS Esito, 
				   NULL AS CodiceEsito
              FROM Viaggi v 
			  LEFT JOIN PCS p ON p.Codice = ISNULL(v.PCSPartenzaEffettivo, v.PCSPartenza)
              LEFT JOIN PCS_Geocodifica pg ON pg.Codice = p.Codice

             UNION ALL

			SELECT v.IdViaggio,
				   CASE
					   WHEN o.SequenzaEffettiva = 0 THEN 200 + o.SequenzaPianificata
					   ELSE o.SequenzaEffettiva
                   END AS SequenzaCalcolata,
				   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN O.PCSDestinazione 
                        ELSE O.PCSPartenza
                   END AS ID,
                   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN '1'
						WHEN ts.Is_Ritiro = 'S' THEN '2'
                        ELSE '999'
                   END AS Tipologia,
				   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN pg.Latitudine
						WHEN ts.Is_Ritiro = 'S' THEN pg1.Latitudine
                        ELSE ''
                   END AS Latitudine,
				   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN pg.Longitudine
						WHEN ts.Is_Ritiro = 'S' THEN pg1.Longitudine
                        ELSE ''
                   END AS Longitudine,
				   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN p.RagioneSociale + ' (' + p.Codice + ')'
						WHEN ts.Is_Ritiro = 'S' THEN p1.RagioneSociale + ' (' + p1.Codice + ')'
                        ELSE ''
                   END AS Tooltip,
                   CASE 
                        WHEN ts.Is_Consegna = 'S' THEN p.RagioneSociale + ' - ' + p.Localita + ' - ' + p.Indirizzo
						WHEN ts.Is_Ritiro = 'S' THEN p1.RagioneSociale + ' - ' + p1.Localita + ' - ' + p1.Indirizzo
                        ELSE ''
                   END AS Descrizione,
                   o.SequenzaEffettiva AS FixTooltip, 
				   '' AS ColoreFixTooltip,
                   CASE
                       WHEN sequenzaeffettiva = 0 THEN 200 + sequenzapianificata
                       ELSE sequenzaeffettiva
                   END AS Sequenza,
                   CASE
					   WHEN o.Evento_BuonFine = 'N' THEN 'KO_CONSEGNA'
                       WHEN o.Evento_BuonFine = 'X' THEN 'KO_NOCONSEGNA'
					   WHEN o.Evento_BuonFine = 'P' THEN 'PARZ_CONSEGNA'
                       ELSE 'OK'
                   END Esito,
                   Evento_CodiceEsito AS CodiceEsito
              FROM vw_Spedizioni o 
			 INNER JOIN Viaggi v ON o.IdViaggio = v.IdViaggio
              LEFT JOIN PCS p ON p.Codice = o.PCSDestinazione
              LEFT JOIN PCS_Geocodifica pg ON pg.Codice = p.Codice
              LEFT JOIN PCS p1 ON p1.Codice = o.PCSPartenza
              LEFT JOIN PCS_Geocodifica pg1 ON pg1.Codice = p1.Codice
			 INNER JOIN TipiServizi TS ON o.TipoServizio=TS.Codice

			 UNION ALL

            SELECT v.IdViaggio,
			       1000 AS SequenzaCalcolata,
				   ISNULL(v.PCSPartenzaEffettivo, v.PCSPartenza) AS ID,
				   '2' AS Tipologia,
				   pg.Latitudine,
				   pg.Longitudine,
				   p.RagioneSociale + ' (' + p.Codice + ')' AS Tooltip,
				   p.RagioneSociale + ' - ' + p.Localita + ' - ' + p.Indirizzo AS Descrizione,
				   0 AS FixTooltip, 
				   '' AS ColoreFixTooltip,
				   1000 AS Sequenza,
				   'OK' AS Esito, 
				   NULL AS CodiceEsito
              FROM Viaggi v 
			 INNER JOIN PCS p ON p.Codice = ISNULL(v.PCSArrivoEffettivo, v.PCSArrivo)
              LEFT JOIN PCS_Geocodifica pg ON pg.Codice = p.Codice
          ) t;


-- dbo.VW_TRK_Mappa_Viaggi source

ALTER VIEW [dbo].[VW_TRK_Mappa_Viaggi] AS
   SELECT v.IdViaggio,
          dbo.TRUNC (isnull (datapartenzaeffettiva, datapartenzapianificata)) AS DataPartenza,
          TipoMerce, 
		  Terminale, 
		  Stato, 
		  ISNULL (motriceeffettiva, motricepianificata) Trattore,
          ISNULL (Contenitore1Effettivo, Contenitore1Pianificato) AS Mezzo,
          (SELECT MAX (ZonaSpedizione)
             FROM PCS_Zone
            WHERE v.TipoMerce = PCS_Zone.TipoMerce
              AND ISNULL(v.PCSPartenzaEffettivo, V.PCSPartenza) = PCS_Zone.PCS) ZonaSpedizionePartenza,
          (SELECT MAX (ZonaSpedizione)
             FROM PCS_Zone
            WHERE v.TipoMerce = PCS_Zone.TipoMerce
              AND ISNULL(v.PCSArrivoEffettivo, V.PCSArrivo) = PCS_Zone.PCS) ZonaSpedizioneArrivo,
          CAST(NULL AS VARCHAR(1000)) NoteCertificazione
     FROM Viaggi v;


-- dbo.VW_VIAGGIO_MEZZI_TA source

ALTER VIEW [dbo].[VW_VIAGGIO_MEZZI_TA] AS
 SELECT X.IdViaggio
      , X.Trattore 
	  , tratt.Descrizione DescrizioneTrattore
	  , tratt.PortataPeso PortataPesoTrattore
	  , tratt.Tara TaraTrattore
	  , tratt.Larghezza LarghezzaTrattore
	  , tratt.Lunghezza LunghezzaTrattore
	  , tratt.Altezza AltezzaTrattore
	  , tratt.SuffissoFile SuffissoFileTrattore
	  , tratt.IdDima IdDimaTrattore
	  , X.Semirimorchio 
	  , sem.Descrizione DescrizioneSemirimorchio
	  , sem.PortataPeso PortataPesoSemirimorchio
	  , sem.Tara TaraSemirimorchio
	  , sem.Larghezza LarghezzaSemirimorchio
	  , sem.Lunghezza LunghezzaSemirimorchio
	  , sem.Altezza AltezzaSemirimorchio
	  , sem.SuffissoFile SuffissoFileSemirimorchio
	  , sem.IdDima IdDimaSemirimorchio
	  , X.Contenitore
	  , cont.Descrizione DescrizioneContenitore
	  , cont.PortataPeso PortataPesoContenitore
	  , cont.Tara TaraContenitore
	  , cont.Larghezza LarghezzaContenitore
	  , cont.Lunghezza LunghezzaContenitore
	  , cont.Altezza AltezzaContenitore
	  , cont.SuffissoFile SuffissoFileContenitore
	  , cont.IdDima IdDimaContenitore
	  , tm.ADR
   FROM (  
   SELECT v.IdViaggio,
		  CASE
			WHEN v.Stato>=40 THEN ISNULL(v.MotriceEffettiva, v.MotricePianificata)
			ELSE v.MotricePianificata
		  END AS Trattore,
          CASE
			WHEN v.Stato>=40 THEN ISNULL(v.Rimorchio1Effettivo, v.Rimorchio1Pianificato)
			ELSE v.Rimorchio1Pianificato
		  END AS Semirimorchio,
		  CASE
			WHEN v.Stato>=40 THEN ISNULL(v.Contenitore1Effettivo, v.Contenitore1Pianificato)
			ELSE v.Contenitore1Pianificato
		  END AS Contenitore,
		  V.TipoMerce
     FROM Viaggi v) X
	LEFT OUTER JOIN VW_MEZZI_TA tratt ON tratt.Codice=x.Trattore
	LEFT OUTER JOIN VW_MEZZI_TA sem ON sem.Codice=x.Semirimorchio
	LEFT OUTER JOIN VW_MEZZI_TA cont ON cont.Codice=x.Contenitore
	LEFT OUTER JOIN TipiMerce tm ON tm.Codice=X.TipoMerce;


-- dbo.VW_VIAGGI_PRIMOEVENTO_MEZZO source

ALTER VIEW [dbo].[VW_VIAGGI_PRIMOEVENTO_MEZZO]
AS
SELECT ID,IDVIAGGIO,DATA, MOTRICE, KMMANUALI FROM 
(
      SELECT      VE.Id,
                  VE.IdViaggio ,
                  VE.DataOraEvento  DATA, 
                  MOTRICE, VE.KMMANUALI,
                  ROW_NUMBER() OVER(PARTITION BY VE.idviaggio ORDER BY DataOraEvento ) AS RN 
      FROM  VIAGGI_EVENTI VE 
			INNER JOIN VIAGGI V ON V.IDVIAGGIO = VE.IdViaggio 
      WHERE V.STATO > 30
)T WHERE RN= 1;


-- dbo.VW_VIAGGI_ULTIMOEVENTO source

ALTER VIEW [dbo].[VW_VIAGGI_ULTIMOEVENTO]
AS
SELECT ID,IDVIAGGIO,DATA FROM 
(
      SELECT      VE.Id,
                  VE.IdViaggio ,
                  VE.DataOraEvento  DATA, 
                  ROW_NUMBER() OVER(PARTITION BY VE.idviaggio ORDER BY DataOraEvento DESC) AS RN 
      FROM  VIAGGI_EVENTI VE 
			INNER JOIN VIAGGI V ON V.IDVIAGGIO = VE.IdViaggio 
      WHERE V.STATO = 30
)T WHERE RN= 1;


-- dbo.VW_VIAGGI_ULTIMOEVENTO_MEZZO source

ALTER VIEW [dbo].[VW_VIAGGI_ULTIMOEVENTO_MEZZO]
AS
SELECT ID,IDVIAGGIO,DATA, MOTRICE, KMMANUALI FROM 
(
      SELECT      VE.Id,
                  VE.IdViaggio ,
                  VE.DataOraEvento  DATA, 
                  MOTRICE,VE.KMMANUALI,
                  ROW_NUMBER() OVER(PARTITION BY VE.idviaggio ORDER BY DataOraEvento DESC) AS RN 
      FROM  VIAGGI_EVENTI VE 
			INNER JOIN VIAGGI V ON V.IDVIAGGIO = VE.IdViaggio 
      WHERE V.STATO > 30
)T WHERE RN= 1;


