-- dbo.VW_WFI_Soggetti source

ALTER VIEW [dbo].[VW_WFI_Soggetti] AS
SELECT * 
FROM
(
	select	Codice,
			RagioneSociale Descrizione,
			'TO.DESTINATARI' TipoSoggetto
	FROM Destinatari 
	UNION ALL
	select	Codice,
			RagioneSociale Descrizione,
			'TO.CLIENTI' TipoSoggetto
	FROM Clienti
	UNION ALL
	select	Codice,
			RagioneSociale Descrizione,
			'TO.TRASP' TipoSoggetto
	FROM Trasportatori
) S;


-- dbo.VW_WFI_StampeAutomatiche source

ALTER VIEW [dbo].[VW_WFI_StampeAutomatiche] AS
SELECT 
		CASE 
			WHEN S.NomRep <>'*ALL' THEN 900
			ELSE 100 
		END +
		CASE 
			WHEN S.Utente='XXX' THEN 50
			WHEN U.Tipo='U' THEN 90
			WHEN U.Tipo='G' THEN 80
			WHEN U.Tipo='O' THEN 70			
			WHEN U.Tipo='T' THEN 60
			ELSE 10
		END Peso,
		S.*
FROM WFI_TabRep_StampeAutomatiche S
LEFT JOIN WFI_Utenti U ON U.Codice=S.Utente
WHERE S.Attivo='S';


