-- dbo.VW_WMS_VIAGGI source

ALTER VIEW [dbo].[VW_WMS_VIAGGI] AS
SELECT V.*, ISNULL(M.ALTEZZA,0) AltezzaMezzo, dbo.trunc(ISNULL(ISNULL(DataPartenzaEffettiva, DataPartenzaPianificata), GETDATE())) DataRiferimento 
FROM Viaggi V LEFT JOIN Mezzi M ON ISNULL(V.RIMORCHIO1EFFETTIVO, V.Rimorchio1Pianificato)=M.CODICE;


-- dbo.WFI_FUNCTIONLIST source

ALTER VIEW [dbo].[WFI_FUNCTIONLIST] AS
SELECT	CODICE,
		MAX(DESCRIZIONE) DESCRIZIONE,
		MAX(FUNZIONE) FUNZIONE,
		MAX(TOOLTIP) TOOLTIP,
		MAX(SEARCHTAG) SEARCHTAG,
		MAX(ACTIONCODE) ACTIONCODE,
		UTENTE
FROM
(
	SELECT	'MENU.' + VV.VOCE	CODICE, 
			VV.TEXT				DESCRIZIONE, 
			VV.FUNZIONE			FUNZIONE, 
			VV.TOOLTIP			TOOLTIP,
			VV.SEARCHTAG		SEARCHTAG,			
			VV.ACTIONCODE		ACTIONCODE,			
			UU.UTENTE			UTENTE
	FROM WFI_MENU_UTENTE UU INNER JOIN WFI_MENU_VOCI VV ON UU.VOCE = VV.VOCE 
	WHERE UU.VISIBILE='S' 
	AND VV.VISIBILE='S'  
	AND VV.TIPONODO in ('N', 'F')
	and VV.FUNZIONE is not null
) T
GROUP BY CODICE, UTENTE;


-- dbo.WFI_FUNCTIONLIST_V2 source

ALTER VIEW [dbo].[WFI_FUNCTIONLIST_V2] AS
SELECT	CODICE,
		MAX(DESCRIZIONE) DESCRIZIONE,
		MAX(FUNZIONE) FUNZIONE,
		MAX(TOOLTIP) TOOLTIP,
		MAX(SEARCHTAG) SEARCHTAG,
		MAX(ACTIONCODE) ACTIONCODE,
		ConfigProfileId
FROM
(
	SELECT	'MENU.' + VV.VOCE	CODICE, 
			VV.TEXT				DESCRIZIONE, 
			VV.FUNZIONE			FUNZIONE, 
			VV.TOOLTIP			TOOLTIP,
			VV.SEARCHTAG		SEARCHTAG,			
			VV.ACTIONCODE		ACTIONCODE,			
			UU.ConfigProfileId	ConfigProfileId
	FROM WFI_MENU_TREE UU INNER JOIN WFI_MENU_VOCI VV ON UU.VOCE = VV.VOCE 
	WHERE UU.VISIBILE='S' 
	AND VV.VISIBILE='S'  
	AND VV.TIPONODO in ('N', 'F')
	and VV.FUNZIONE is not null
) T
GROUP BY CODICE, ConfigProfileId;


-- dbo.WFI_Filiali source

ALTER VIEW [dbo].[WFI_Filiali] AS 
SELECT T.Codice Codice,
	MAX(T.Descrizione ) Descrizione,
	MAX(T.Attivo ) Attivo,
	MAX(IsDefault) IsDefault  
FROM 
(
	SELECT	Codice, 
			RagioneSociale Descrizione, 
			Attivo, 
			IsDefault  
	FROM Filiali
	UNION
	SELECT	'XXX', 
			'FILIALE MASTER' Descrizione, 
			'S' Attivo,
			'N' IsDefault  
) T
GROUP BY T.CODICE;


-- dbo.WFI_PARAMETRICA source

ALTER VIEW [dbo].[WFI_PARAMETRICA] AS
SELECT * FROM Parametrica;


-- dbo.WSCApiUtenti source

ALTER VIEW [dbo].[WSCApiUtenti] AS
SELECT	CODICE, 
		DESCRIZIONE, 
		CODICE as Password, 
		'U' Tipo, 
		Attivo, 
		GETDATE()+100 ScadenzaPassword,
		'API.TERM' Gruppo,
		NULL Organizzazione

from Terminali

UNION 

SELECT 'API.TERM' Codice,
		'Gruppo Terminali' Descrizione,
		Null [Password],
		'G' Tipo,
		'S' Attivo,
		GETDATE()+100 ScadenzaPassword,
		Null Gruppo,
		'API.ORG' Organizzazione;


